INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4944, 55, 43, N'هَٰذِهِ جَهَنَّمُ الَّتِي يُكَذِّبُ بِهَا الْمُجْرِمُونَ', N'This is Hell the sinners called a lie. ', N'یہ ہے وہ جہنم جسے مجرم جھٹلاتے ہیں،', N'Inilah neraka Jahannam yang didustakan oleh orang-orang berdosa.', N'یہی وہ جہنم ہے جسے گنہگار لوگ جھٹلاتے تھے ')
