INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4945, 55, 44, N'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ', N'They will go round and around between it and boiling water. ', N'پھیرے کریں گے اس میں اور انتہا کے جلتے کھولتے پانی میں', N'Mereka berkeliling di antaranya dan di antara air mendidih yang memuncak panasnya.', N'وہ دوزخ اور کھولتے ہوئے گرم پانی کے درمیان گھومتے پھریں گے ')
