INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4959, 55, 58, N'كَأَنَّهُنَّ الْيَاقُوتُ وَالْمَرْجَانُ', N'As though rubies and pearls. ', N'گویا وہ لعل اور یاقوت اور مونگا ہیں', N'Seakan-akan bidadari itu permata yakut dan marjan.', N'گویا وہ یاقوت اور مرجان ہیں ')
