INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4960, 55, 59, N'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', N'Which of the favours of your Lord will then both of you deny? ', N'تو اپنے رب کی کونسی نعمت جھٹلاؤ گے،', N'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?', N'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟ ')
