INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4961, 55, 60, N'هَلْ جَزَاءُ الْإِحْسَانِ إِلَّا الْإِحْسَانُ', N'Should the reward of goodness be aught else but goodness? -- ', N'نیکی کا بدلہ کیا ہے مگر نیکی', N'Tidak ada balasan kebaikan kecuali kebaikan (pula).', N'نیکی کا بدلہ نیکی کے سوا کچھ نہیں ہے ')
GO
INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4962, 55, 61, N'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', N'How many favours of your Lord will then both of you deny? -- ', N'تو اپنے رب کی کونسی نعمت جھٹلاؤ گے،', N'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?', N'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟ ')
