INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4963, 55, 62, N'وَمِنْ دُونِهِمَا جَنَّتَانِ', N'And besides these two other gardens -- ', N'اور ان کے سوا دو جنتیں اور ہیں', N'Dan selain dari dua surga itu ada dua surga lagi', N'اور ان باغوں کے علاوہ دو باغ اور ہیں ')
GO
