INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4965, 55, 64, N'مُدْهَامَّتَانِ', N'Of darkest verdant green -- ', N'نہایت سبزی سے سیاہی کی جھلک دے رہی ہیں،', N'Kedua surga itu (kelihatan) hijau tua warnanya.', N'دونوں خوب گہرے سبز ')
GO
