INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4967, 55, 66, N'فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ', N'With two fountains gushing constantly, -- ', N'ان میں دو چشمے ہیں چھلکتے ہوئے،', N'Di dalam kedua surga itu ada dua buah mata air yang memancar.', N'ان میں دو چشمے ابل رہے ہیں ')
GO
