INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4969, 55, 68, N'فِيهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ', N'With fruits in them, and dates and pomegranates -- ', N'ان میں میوے اور کھجوریں اور انار ہیں،', N'Di dalam keduanya (ada macam-macam) buah-buahan dan kurma serta delima.', N'ان میں میوے اور کھجوریں اور انار ہیں ')
GO
