INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4971, 55, 70, N'فِيهِنَّ خَيْرَاتٌ حِسَانٌ', N'In them good and comely maidens -- ', N'ان میں عورتیں ہیں عادت کی نیک صورت کی اچھی', N'Di dalam surga itu ada bidadari-bidadari yang baik-baik lagi cantik-cantik.', N'ان میں نیک سیرت (اور) خوبصورت عورتیں ہیں ')
GO
INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4972, 55, 71, N'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', N'How many favours of your Lord will you then deny? -- ', N'تو اپنے رب کی کونسی نعمت جھٹلاؤ گے،', N'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?', N'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟ ')
