INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4973, 55, 72, N'حُورٌ مَقْصُورَاتٌ فِي الْخِيَامِ', N'Houris cloistered in pavilions -- ', N'حوریں ہیں خیموں میں پردہ نشین', N'(Bidadari-bidadari) yang jelita, putih bersih, dipingit dalam rumah.', N'(وہ) حوریں (ہیں جو) خیموں میں مستور (ہیں) ')
GO
INSERT [dbo].[Quran] ([ID], [ChapterID], [VerseID], [AyahText], [EnglishTranslation], [UrduTranslation], [IndonasianTranslation], [UrduTranJalandhry]) VALUES (4974, 55, 73, N'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', N'How many favours of your Lord will you then deny? -- ', N'تو اپنے رب کی کونسی نعمت جھٹلاؤ گے،', N'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?', N'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟ ')
