INSERT [dbo].[QuranUrdu] ([Id], [SuraID], [VerseID], [AyahText]) VALUES (755, 5, 86, N'اور جن لوگوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہ جہنمی ہیں ')
