INSERT [dbo].[QuranUrdu] ([Id], [SuraID], [VerseID], [AyahText]) VALUES (791, 6, 2, N'وہی تو ہے جس نے تم کو مٹی سے پیدا کیا پھر (مرنے کا) ایک وقت مقرر کر دیا اور ایک مدت اس کے ہاں اور مقرر ہے پھر بھی تم (اے کافرو خدا کے بارے میں) شک کرتے ہو ')
GO
INSERT [dbo].[QuranUrdu] ([Id], [SuraID], [VerseID], [AyahText]) VALUES (792, 6, 3, N'اور آسمانوں اور زمین میں وہی (ایک) خدا ہے تمہاری پوشیدہ اور ظاہر سب باتیں جانتا ہے اور تم جو عمل کرتے ہو سب سے واقف ہے ')
GO
INSERT [dbo].[QuranUrdu] ([Id], [SuraID], [VerseID], [AyahText]) VALUES (793, 6, 4, N'اور خدا کی نشانیوں میں سے کوئی نشانی ان لوگوں کے پاس نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں ')
