INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1, 1, 1, N'اللہ کے نام سے شروع جو بہت مہربان رحمت والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2, 1, 2, N'سب خوبیاں اللہ کو جو مالک سارے جہان والوں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3, 1, 3, N'بہت مہربان رحمت والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4, 1, 4, N'روز جزا کا مالک،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5, 1, 5, N'ہم تجھی کو پوجیں اور تجھی سے مدد چاہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (6, 1, 6, N'ہم کو سیدھا راستہ چلا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (7, 1, 7, N'راستہ ان کا جن پر تو نے احسان کیا، نہ ان کا جن پر غضب ہوا اور نہ بہکے ہوؤں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (8, 2, 1, N'الم')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (9, 2, 2, N'وہ بلند رتبہ کتاب (قرآن) کوئی شک کی جگہ نہیں، اس میں ہدایت ہے ڈر والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (10, 2, 3, N'وہ جو بے دیکھے ایمان لائیں اور نماز قائم رکھیں اور ہماری دی ہوئی روزی میں سے ہماری میں اٹھائیں-')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (11, 2, 4, N'اور وہ کہ ایمان لائیں اس پر جو اے محبوب تمہاری طرف اترا اور جو تم سے پہلے اترا اور آخرت پر یقین رکھیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (12, 2, 5, N'وہی لوگ اپنے رب کی طرف سے ہدایت پر ہیں اور وہی مراد کو پہنچنے والے۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (13, 2, 6, N'بیشک وہ جن کی قسمت میں کفر ہے ا نہیں برابر ہے، چاہے تم انہیں ڈراؤ، یا نہ ڈراؤ، وہ ایمان لانے کے نہیں۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (14, 2, 7, N'اللہ نے ان کے دلوں پر اور کانوں پر مہر کردی اور ان کی آنکھوں پر گھٹاٹوپ ہے، اور ان کے لئے بڑا عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (15, 2, 8, N'اور کچھ لوگ کہتے ہیں کہ ہم اللہ اور پچھلے دن پر ایمان لائے اور وہ ایمان والے نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (16, 2, 9, N'فریب دیا چاہتے ہیں اللہ اور ایمان والوں کو اور حقیقت میں فریب نہیں دیتے مگر اپنی جانوں کو اور انہیں شعور نہیں۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (17, 2, 10, N'ان کے دلوں میں بیماری ہے تو اللہ نے ان کی بیماری اور بڑھائی اور ان کے لئے دردناک عذاب ہے، بدلا ان کے جھوٹ کا -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (18, 2, 11, N'اوران سے کہا جائے زمین میں فساد نہ کرو، تو کہتے ہیں ہم تو سنوارنے والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (19, 2, 12, N'سنتا ہے وہی فسادی ہیں مگر انہیں شعور نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (20, 2, 13, N'اور جب ان سے کہا جائے ایمان لاؤ جیسے اور لوگ ایمان لائے تو کہیں کیا ہم احمقوں کی طرح ایمان لے آئیں سنتا ہے وہی احمق ہیں مگر جانتے نہیں -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (21, 2, 14, N'اور جب ایمان والوں سے ملیں تو کہیں ہم ایمان لائے اور جب اپنے شیطانوں کے پاس اکیلے ہوں تو کہیں ہم تمہارے ساتھ ہیں، ہم تو یونہی ہنسی کرتے ہیں-')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (22, 2, 15, N'اللہ ان سے استہزاء فرماتا ہے (جیسا کہ اس کی شان کے لائق ہے) اور انہیں ڈھیل دیتا ہے کہ اپنی سرکشی میں بھٹکتے رہیں۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (23, 2, 16, N'یہ لوگ جنہوں نے ہدایت کے بدلے گمراہی خریدی تو ان کا سودا کچھ نفع نہ لایا اور وہ سودے کی راہ جانتے ہی نہ تھے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (24, 2, 17, N'ان کی کہاوت اس طرح ہے جس نے آگ روشن کی۔ تو جب اس سے آس پاس سب جگمگا اٹھا اللہ ان کا نور لے گیا اور انہیں اندھیریوں میں چھوڑ دیا کہ کچھ نہیں سوجھتا -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (25, 2, 18, N'بہرے، گونگے، ندھے تو وہ پھر آ نے والے نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (26, 2, 19, N'یا جیسے آسمان سے اترتا پانی کہ ان میں اندھیریاں ہیں اور گرج اور چمک اپنے کانوں میں انگلیاں ٹھونس رہے ہیں، کڑک کے سبب، موت کے ڈر سے اور اللہ کافروں کو، گھیرے ہوئے ہے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (27, 2, 20, N'بجلی یوں معلوم ہوتی ہے کہ ان کی نگاہیں اچک لے جائے گی جب کچھ چمک ہوئی اس میں چلنے لگے اور جب اندھیرا ہوا کھڑے رہ گئے اور اللہ چاہتا تو ان کے کان اور آنکھیں لے جاتا بیشک اللہ سب کچھ کرسکتا ہے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (28, 2, 21, N'اے لوگو! اپنے رب کو پوجو جس نے تمہیں اور تم سے اگلوں کو پیدا کیا، یہ امید کرتے ہوئے، کہ تمہیں پرہیزگاری ملے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (29, 2, 22, N'جس نے تمہارے لئے زمین کو بچھونا اور آسمان کو عمارت بنایا اور آسمان سے پانی اتارا تو اس سے کچھ پھل نکالے تمہارے کھانے کو۔ تو اللہ کے لئے جان بوجھ کر برابر والے نہ ٹھہراؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (30, 2, 23, N'اور اگر تمہیں کچھ شک ہو اس میں جو ہم نے اپنے (اس خاص) بندے پر اتارا تو اس جیسی ایک سورت تو لے آؤ اور اللہ کے سوا، اپنے سب حمایتیوں کو بلالو، اگر تم سچے ہو۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (31, 2, 24, N'پھر اگر نہ لا سکو اور ہم فرمائے دیتے ہیں کہ ہر گز نہ لا سکو گے تو ڈرو اس آگ سے، جس کا ایندھن آدمی اور پتھر ہیں تیار رکھی ہے کافروں کے لئے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (32, 2, 25, N'اور خوشخبری دے، انہیں جو ایمان لائے اور اچھے کام کئے، کہ ان کے لئے باغ ہیں، جن کے نیچے نہریں رواں جب انہیں ان باغوں سے کوئی پھل کھانے کو دیا جائے گا، (صورت دیکھ کر) کہیں گے، یہ تو وہی رزق ہے جو ہمیں پہلے ملا تھا اور وہ (صورت میں) ملتا جلتا انہیں دیا گیا اور ان کے لئے ان باغوں میں ستھری بیبیاں ہیں اور وہ ان میں ہمیشہ رہیں گے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (33, 2, 26, N'بیشک اللہ اس سے حیا نہیں فرماتا کہ مثال سمجھانے کو کیسی ہی چیز کا ذکر فرمائے مچھر ہو یا اس سے بڑھ کر تو وہ جو ایمان لائے، وہ تو جانتے ہیں کہ یہ ان کے رب کی طرف سے حق ہے رہے کافر، وہ کہتے ہیں ایسی کہاوت میں اللہ کا کیا مقصُود ہے، اللہ بہتیروں کو اس سے گمراہ کرتا ہے اور بہتیروں کو ہدایت فرماتا ہے اور اس سے انہیں گمراہ کرتا ہے جو بے حکم ہیں-')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (34, 2, 27, N'وہ جو اللہ کے عہد کو توڑ دیتے ہیں پکا ہونے کے بعد، اور کاٹتے ہیں اس چیز کو جس کے جوڑنے کا خدا نے حکم دیا ہے اور زمین میں فساد پھیلاتے ہیں وہی نقصان میں ہیں۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (35, 2, 28, N'بھلا تم کیونکر خدا کے منکر ہو گے، حالانکہ تم مردہ تھے اس نے تمہیں جِلایا پھر تمہیں مارے گا پھر تمہیں جِلائے گا پھر اسی کی طرف پلٹ کر جاؤ گے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (36, 2, 29, N'وہی ہے جس نے تمہارے لئے بنایا جو کچھ زمین میں ہے۔ پھر آسمان کی طرف استوا (قصد) فرمایا تو ٹھیک سات آسمان بنائے وہ سب کچھ جانتا ہے -')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (37, 2, 30, N'اور یاد کرو جب تمہارے رب نے فرشتوں سے فرمایا، میں زمین میں اپنا نائب بنانے والا ہوں بولے کیا ایسے کو نائب کرے گا جو اس میں فساد پھیلائے گا اور خونریزیاں کرے گا اور ہم تجھے سراہتے ہوئے، تیری تسبیح کرتے اور تیری پاکی بولتے ہیں، فرمایا مجھے معلوم ہے جو تم نہیں جانتے-')
GO
