INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (70, 2, 63, N'اور جب ہم نے تم سے عہد لیا اور تم پر طور کو اونچا کیا لو جو کچھ ہم تم کو دیتے ہیں زور سے اور اس کے مضمون یاد کرو اس امید پر کہ تمہیں پرہیزگاری ملے-')
