INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (71, 2, 64, N'پھر اس کے بعد تم پھر گئے تو اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی تو تم ٹوٹے والوں میں ہو جاتے -')
