INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (150, 2, 143, N'اور بات یوں ہی ہے کہ ہم نے تمہیں کیا سب امتوں میں افضل، کہ تم لوگوں پر گواہ ہو اور یہ رسول تمہارے نگہبان و گواہ اور اے محبوب! تم پہلے جس قبلہ پر تھے ہم نے وہ اسی لئے مقرر کیا تھا کہ دیکھیں کون رسول کی پیروی کرتا ہے اور کون الٹے پاؤں پھر جاتا ہے۔ اور بیشک یہ بھاری تھی مگر ان پر، جنہیں اللہ نے ہدایت کی اور اللہ کی شان نہیں کہ تمہارا ایمان اکارت کرے بیشک اللہ آدمیوں پر بہت مہربان، رحم والا ہے۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (151, 2, 144, N'ہم دیکھ رہے ہیں بار بار تمہارا آسمان کی طرف منہ کرنا تو ضرور ہم تمہیں پھیردیں گے اس قبلہ کی طرف جس میں تمہاری خوشی ہے ابھی اپنا منہ پھیر دو مسجد حرام کی طرف اور اے مسلمانو! تم جہاں کہیں ہو اپنا منہ اسی کی طرف کرو اور وہ جنہیں کتاب ملی ہے ضرور جانتے کہ یہ انکے رب کی طرف سے حق ہے اور اللہ ان کے کوتکوں (اعمال) سے بے خبر نہیں-')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (152, 2, 145, N'اور اگر تم ان کتابیوں کے پاس ہر نشانی لے کر آ ؤ وہ تمہارے قبلہ کی پیروی نہ کریں گے اور نہ تم ان کے قبلہ کی پیروی کرو اور وہ آپس میں بھی ایک دوسرے کے قبلہ کے تابع نہیں اور (اے سننے والے کسے باشد) اگر تو ان کی خواہشوں پر چلا بعد اس کے کہ تجھے علم مل چکا تو اس وقت تو ضرور ستم گر ہوگا۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (153, 2, 146, N'جنہیں ہم نے کتاب عطا فرمائی وہ اس نبی کو ایسا پہچانتے ہیں جیسے آدمی اپنے بیٹوں کو پہچانتا ہے اور بیشک ان میں ایک گروہ جان بوجھ کر حق چھپاتے ہیں -')
GO
