INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (185, 2, 178, N'اے ایمان والوں تم پر فرض ہے کہ جو ناحق مارے جائیں ان کے خون کا بدلہ لو آزاد کے بدلے آزاد اور غلام کے بدلے غلام اور عورت کے بدلے عورت تو جس کے لئے اس کے بھائی کی طرف سے کچھ معافی ہوئی۔ تو بھلائی سے تقا ضا ہو اور اچھی طرح ادا، یہ تمہارے رب کی طرف سے تمہارا بوجھ پر ہلکا کرنا ہے اور تم پر رحمت تو اس کے بعد جو زیادتی کرے اس کے لئے دردناک عذاب ہے')
