INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (186, 2, 179, N'اور خون کا بدلہ لینے میں تمہاری زندگی ہے اے عقل مندو کہ تم کہیں بچو،')
