INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (187, 2, 180, N'تم پر فرض ہوا کہ جب تم میں کسی کو موت آئے اگر کچھ مال چھوڑے تو وصیت کرجائے اپنے ماں باپ اور قریب کے رشتہ داروں کے لئے موافق دستور یہ واجب ہے پرہیزگاروں پر،')
