INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (188, 2, 181, N'تو جو وصیت کو سن سنا کر بدل دے اس کا گناہ انہیں بدلنے والوں پر ہے بیشک اللہ سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (189, 2, 182, N'پھر جسے اندیشہ ہوا کہ وصیت کرنے والے نے کچھ بے انصافی یا گناہ کیا تو اس نے ان میں صلح کرادی اس پر کچھ گناہ نہیں بیشک اللہ بخشنے والا مہربان ہے')
