INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (191, 2, 184, N'گنتی کے دن ہیں تو تم میں جو کوئی بیمار یا سفر میں ہو تو اتنے روزے اور دنوں میں اور جنہیں اس کی طاقت نہ ہو وہ بدلہ دیں ایک مسکین کا کھانا پھر جو اپنی طرف سے نیکی زیادہ کرے تو وہ اس کے لئے بہتر ہے اور روزہ رکھنا تمہارے لئے زیادہ بھلا ہے اگر تم جانو')
