INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (192, 2, 185, N'رمضان کا مہینہ جس میں قرآن اترا لوگوں کے لئے ہدایت اور رہنمائی اور فیصلہ کی روشن باتیں تو تم میں جو کوئی یہ مہینہ پائے، ضرور اس کے روزے رکھے اور جو بیمار یا سفر میں ہو تو اتنے روزے اور دنوں میں اللہ تم پر آسانی چاہتا ہے اور تم پر دشواری نہیں چاہتا اور اس لئے کہ تم گنتی پوری کرو اور اللہ کی بڑائی بولو اس پر کہ اس نے تمہیں ہدایت کی اور کہیں تم حق گزار ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (193, 2, 186, N'اور اے محبوب جب تم سے میرے بندے مجھے پوچھیں تو میں نزدیک ہوں دعا قبول کرتا ہوں پکارنے والے کی جب مجھے پکارے تو انہیں چاہئے میرا حکم مانیں اور مجھ پر ایمان لائیں کہ کہیں راہ پائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (194, 2, 187, N'روزہ کی راتوں میں اپنی عورتوں کے پاس جانا تمہارے لئے حلال ہوا وہ تمہاری لباس ہیں اور تم ان کے لباس، اللہ نے جانا کہ تم اپنی جانوں کو خیانت میں ڈالتے تھے تو اس نے تمہاری توبہ قبول کی اور تمہیں معاف فرمایا تو اب ان سے صحبت کرو اور طلب کرو جو اللہ نے تمہارے نصیب میں لکھا ہو اور کھاؤ اور پیئو یہاں تک کہ تمہارے لئے ظاہر ہوجائے سفیدی کا ڈورا سیاہی کے ڈورے سے (پوپھٹ کر) پھر رات آنے تک روزے پورے کرو اور عورتوں کو ہاتھ نہ لگاؤ جب تم مسجدوں میں اعتکاف سے ہو یہ اللہ کی حدیں ہیں ان کے پاس نہ جاؤ اللہ یوں ہی بیان کرتا ہے لوگوں سے اپنی آیتیں کہ کہیں انہیں پرہیزگاری ملے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (195, 2, 188, N'اور آپس میں ایک دوسرے کا مال ناحق نہ کھاؤ اور نہ حاکموں کے پاس ان کا مقدمہ اس لئے پہنچاؤ کہ لوگوں کا کچھ مال ناجائز طور پر کھاؤ جان بوجھ کر،')
