INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (196, 2, 189, N'تم سے نئے چاند کو پوچھتے ہیں تم فرمادو وہ وقت کی علامتیں ہیں لوگوں اور حج کے لئے اور یہ کچھ بھلائی نہیں کہ گھروں میں پچھیت (پچھلی دیوار) توڑ کر آ ؤ ہاں بھلائی تو پرہیزگاری ہے، اور گھروں میں دروازوں سے آ ؤ اور اللہ سے ڈرتے رہو اس امید پر کہ فلاح پاؤ')
