INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (198, 2, 191, N'اور کافروں کو جہاں پاؤ مارو اور انہیں نکال دو جہاں سے انہوں نے تمہیں نکا لا تھا اور ان کا فساد تو قتل سے بھی سخت ہے اور مسجد حرام کے پاس ان سے نہ لڑو جب تک وہ تم سے وہاں نہ لڑیں اور اگر تم سے لڑیں تو انہیں قتل کرو کافروں کی یہی سزا ہے،')
