INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (200, 2, 193, N'اور ان سے لڑو یہاں تک کہ کوئی فتنہ نہ رہے اور ایک اللہ کی پوجا ہو پھر اگر وہ باز آئیں تو زیادتی نہیں مگر ظالموں پر،')
