INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (202, 2, 195, N'اور اللہ کی راہ میں خرچ کرو اور اپنے ہاتھوں، ہلاکت میں نہ پڑو اور بھلائی والے ہو جاؤ بیشک بھلائی والے اللہ کے محبوب ہیں،')
