INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (203, 2, 196, N'اور حج اور عمرہ اللہ کے لئے پورا کرو پھر اگر تم روکے جاؤ تو قربانی بھیجو جو میسر آئے اور اپنے سر نہ منڈاؤ جب تک قربانی اپنے ٹھکانے نہ پہنچ جائے پھر جو تم میں بیمار ہو یا اس کے سر میں کچھ تکلیف ہے تو بدلے دے روزے یا خیرات یا قربانی، پھر جب تم اطمینان سے ہو تو جو حج سے عمرہ ملانے کا فائدہ اٹھائے اس پر قربانی ہے جیسی میسر آئے پھر جسے مقدور نہ ہو تو تین روزے حج کے دنوں میں رکھے اور سات جب اپنے گھر پلٹ کر جاؤ یہ پورے دس ہوئے یہ حکم اس کے لئے ہے جو مکہ کا رہنے والا نہ ہو اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ کا عذاب سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (204, 2, 197, N'حج کے کئی مہینہ ہیں جانے ہوئے تو جو ان میں حج کی نیت کرے تو نہ عورتوں کے سامنے صحبت کا تذکرہ ہو نہ کوئی گناہ، نہ کسی سے جھگڑا حج کے وقت تک اور تم جو بھلائی کرو اللہ اسے جانتا ہے اور توشہ ساتھ لو کہ سب سے بہتر توشہ پرہیزگاری ہے اور مجھ سے ڈرتے رہو اے عقل والو، ف۳۷۸)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (205, 2, 198, N'تم پر کچھ گناہ نہیں کہ اپنے رب کا فضل تلاش کرو، تو جب عرفات سے پلٹو تو اللہ کی یاد کرو مشعر حرام کے پاس اور اس کا ذکر کرو جیسے اس نے تمہیں ہدایت فرمائی اور بیشک اس سے پہلے تم بہکے ہوئے تھے، ف۳۸۳)')
