INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (207, 2, 200, N'پھر جب اپنے حج کے کام پورے کرچکو تو اللہ کا ذکر کرو جیسے اپنے باپ دادا کا ذکر کرتے تھے بلکہ اس سے زیادہ اور کوئی آدمی یوں کہتا ہے کہ اے رب ہمارے ہمیں دنیا میں دے اور آخرت میں اس کا کچھ حصہ نہیں،')
