INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (210, 2, 203, N'اور اللہ کی یاد کرو گنے ہوئے دنوں میں تو جلدی کرکے دو دن میں چلا جائے اس پر کچھ گنا نہیں اور جو رہ جائے تو اس پر گناہ نہیں پرہیزگار کے لئے اور اللہ سے ڈرتے رہو اور جان رکھو کہ تمہیں اسی کی طرف اٹھنا ہے،')
