INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (211, 2, 204, N'اور بعض آدمی وہ ہیں کہ دنیا کی زندگی میں اس کی بات تجھے بھلی لگے اور اپنے دل کی بات پر اللہ کو گواہ لائے اور وہ سب سے بڑا جھگڑالو ہے،')
