INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (212, 2, 205, N'اور جب پیٹھ پھیرے تو زمین میں فساد ڈالتا پھرے اور کھیتی اور جانیں تباہ کرے اور اللہ فسادسے راضی نہیں')
