INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (214, 2, 207, N'اور کوئی آدمی اپنی جان بیچتا ہے اللہ کی مرضی چاہنے میں اور اللہ بندوں پر مہربان ہے،')
