INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (217, 2, 210, N'کاہے کے انتظار میں ہیں مگر یہی کہ اللہ کا عذاب آئے چھائے ہوئے بادلوں میں اور فرشتے اتریں اور کام ہوچکے اور سب کاموں کی رجوع اللہ کی طرف ہے،')
