INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (218, 2, 211, N'بنی اسرائیل سے پوچھو ہم نے کتنی روشن نشانیاں انہیں دیں اور جو اللہ کی آئی ہوئی نعمت کو بدل دے تو بیشک اللہ کا عذاب سخت ہے،')
