INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (219, 2, 212, N'کافروں کی نگاہ میں دنیا کی زندگی آراستہ کی گئی اور مسلمانوں سے ہنستے ہیں اور ڈر والے ان سے اوپر ہوں گے قیامت کے دن اور خدا جسے چاہے بے گنتی دے،')
