INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (220, 2, 213, N'لوگ ایک دین پر تھے پھر اللہ نے انبیاء بھیجے خوشخبری دیتے اور ڈر سناتے اور ان کے ساتھ سچی کتاب اتاری کہ وہ لوگوں میں ان کے اختلافوں کا فیصلہ کردے اور کتاب میں اختلاف اُنہیں نے ڈالا جن کو دی گئی تھی بعداس کے کہ ان کے پاس روشن حکم آچکے آپس میں سرکشی سے تو اللہ نے ایمان والوں کو وہ حق بات سوجھا دی جس میں جھگڑ رہے تھے اپنے حکم سے، اور اللہ جسے چاہے سیدھی راہ دکھائے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (221, 2, 214, N'کیا اس گمان میں ہو کہ جنت میں چلے جاؤ گے اور ابھی تم پر اگلوں کی سی روداد (حالت) نہ آئی پہنچی انہیں سختی اور شدت اور ہلا ہلا ڈالے گئے یہاں تک کہ کہہ اٹھا رسول اور اس کے ساتھ ایمان والے کب آئے گی اللہ کی مدد سن لو بیشک اللہ کی مدد قریب ہے،')
