INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (222, 2, 215, N'تم سے پوچھتے ہیں کیا خرچ کریں، تم فرماؤ جو کچھ مال نیکی میں خرچ کرو تو و ہ ماں باپ اور قریب کے رشتہ داروں اور یتیموں اور محتاجوں اور راہ گیر کے لئے ہے اور جو بھلائی کرو بیشک اللہ اسے جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (223, 2, 216, N'تم پر فرض ہوا خدا کی راہ میں لڑنا اور وہ تمہیں ناگوار ہے اور قریب ہے کہ کوئی بات تمہیں بری لگے اور وہ تمہارے حق میں بہتر ہو اور قریب ہے کہ کوئی بات تمہیں پسند آئے اور وہ تمہارے حق میں بری ہو اور اللہ جانتا ہے اور تم نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (224, 2, 217, N'تم سے پوچھتے ہیں ماہ حرام میں لڑنے کا حکم تم فرماؤ اس میں لڑنا بڑا گناہ ہے اور اللہ کی راہ سے روکنا اور اس پر ایمان نہ لانا اور مسجد حرام سے روکنا، اور اس کے بسنے والوں کو نکال دینا اللہ کے نزدیک یہ گناہ اس سے بھی بڑے ہیں اور ان کا فساد قتل سے سخت تر ہے اور ہمیشہ تم سے لڑتے رہیں گے یہاں تک کہ تمہیں تمہارے دین سے پھیردیں اگر بن پڑے اور تم میں جو کوئی اپنے دین سے پھرے پھر کافر ہوکر مرے تو ان لوگوں کا کیا اکارت گیا دنیا میں اور آخرت میں اور وہ دوزخ والے ہیں انہیں اس میں ہمیشہ رہنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (225, 2, 218, N'وه جو ایمان لائے اور وہ جنہوں نے اللہ کے لئے اپنے گھر بار چھوڑے اور اللہ کی راہ میں لڑے وہ رحمت الٰہی کے امیداور ہیں، اور اللہ بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (226, 2, 219, N'تم سے شراب اور جوئے کا حکم پوچھتے ہیں، تم فرمادو کہ ان دونوں میں بڑا گناہ ہے اور لوگوں کے کچھ دنیوی نفع بھی اور ان کا گناہ ان کے نفع سے بڑا ہے تم سے پوچھتے ہیں کیا خرچ کریں تم فرماؤ جو فاضل بچے اسی طرح اللہ تم سے آیتیں بیان فرماتا ہے کہ کہیں تم دنیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (227, 2, 220, N'اور ا ٓ خرت کے کام سوچ کر کرو اور تم سے یتیموں کا مسئلہ پوچھتے ہیں تم فرماؤ ان کا بھلا کرنا بہتر ہے اور اگر اپنا ان کا خرچ ملالو تو وہ تمہارے بھائی ہیں اور خدا خوب جانتا ہے بگاڑنے والے کو سنوارنے والے سے، اور اللہ چاہتا ہے تو تمہیں مشقت میں ڈالتا، بیشک اللہ زبردست حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (228, 2, 221, N'اور شرک والی عورتوں سے نکاح نہ کرو جب تک مسلمان نہ ہوجائیں اور بیشک مسلمان لونڈی مشرکہ سے اچھی ہے اگرچہ وہ تمہیں بھاتی ہو اور مشرکوں کے نکاح میں نہ دو جب تک وہ ایمان نہ لائیں اور بیشک مسلمان غلام مشرک سے اچھا ہے اگرچہ وہ تمہیں بھاتا ہو، وہ دوزخ کی طرف بلاتے ہیں اور اللہ جنت اور بخشش کی طرف بلاتا ہے اپنے حکم سے اور اپنی آیتیں لوگوں کے لئے بیان کرتا ہے کہ کہیں وہ نصیحت مانیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (229, 2, 222, N'اور تم سے پوچھتے ہیں حیض کا حکم تم فرماؤ وہ ناپاکی ہے تو عورتوں سے الگ رہو حیض کے دنوں اور ان سے نزدیکی نہ کرو جب تک پاک نہ ہولیں پھر جب پاک ہوجائیں تو ان کے پاس جاؤ جہاں سے تمہیں اللہ نے حکم دیا، بیشک اللہ پسند کرتا ہے بہت توبہ کرنے والوں کو اور پسند رکھتا ہے سھتروں کو،')
