INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (230, 2, 223, N'تمہاری عورتیں تمہارے لئے کھیتیاں ہیں، تو آؤ اپنی کھیتیوں میں جس طرح چاہو اور اپنے بھلے کا کام پہلے کرو اور اللہ سے ڈرتے رہو اور جان رکھو کہ تمہیں اس سے ملنا ہے اور اے محبوب بشارت دو ایمان والوں کو،')
