INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (232, 2, 225, N'اور تمہیں نہیں پکڑ تا ان قسموں میں جو بے ارادہ زبان سے نکل جائے ہاں اس پر گرفت فرماتا ہے جو کام تمہارے دلوں نے کئے اور اللہ بخشنے والا حلم والا ہے،')
