INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (235, 2, 228, N'اور طلاق والیاں اپنی جانوں کو روکے رہیں تین حیض تک اور انہیں حلال نہیں کہ چھپائیں وہ جو اللہ نے ان کے پیٹ میں پیدا کیا اگر اللہ اور قیامت پر ایمان رکھتی ہیں اور ان کے شوہروں کو اس مدت کے اندر ان کے پھیر لینے کا حق پہنچتا ہے اگر ملاپ چاہیں اور عورتوں کا بھی حق ایسا ہی ہے جیسا ان پر ہے شرع کے موافق اور مردوں کو ان پر فضیلت ہے، اور اللہ غالب حکمت والا ہے،')
