INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (236, 2, 229, N'یہ طلاق دو بار تک ہے پھر بھلائی کے ساتھ روک لینا ہے یا نکوئی (اچھے سلوک) کے ساتھ چھوڑ دینا ہے اور تمہیں روا نہیں کہ جو کچھ عورتوں کو دیا اس میں سے کچھ واپس لو مگر جب دونوں کو اندیشہ ہو کہ اللہ کی حدیں قائم نہ کریں گے پھر اگر تمہیں خوف ہو کہ وہ دونوں ٹھیک انہیں حدوں پر نہ رہیں گے تو ان پر کچھ گناہ نہیں اس میں جو بدلہ دے کر عورت چھٹی لے، یہ اللہ کی حدیں ہیں ان سے آگے نہ بڑھو اور جو اللہ کی حدوں سے آگے بڑھے تو وہی لوگ ظالم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (237, 2, 230, N'پھر اگر تیسری طلاق اسے دی تو اب وہ عورت اسے حلال نہ ہوگی جب تک دوسرے خاوند کے پاس نہ رہے، پھر وہ دوسرا اگر اسے طلاق دے دے تو ان دونوں پر گناہ نہیں کہ پھر آپس میں مل جائیں اگر سمجھتے ہوں کہ اللہ کی حدیں نباہیں گے، اور یہ اللہ کی حدیں ہیں جنہیں بیان کرتا ہے دانش مندوں کے لئے،')
