INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (238, 2, 231, N'اور جب تم عورتوں کو طلاق دو اور ان کی میعاد آلگے تو اس وقت تک یا بھلائی کے ساتھ روک لو یا نکوئی (اچھے سلوک) کے ساتھ چھوڑ دو اور انہیں ضرر دینے کے لئے روکنا نہ ہو کہ حد سے بڑھو اور جو ایسا کرے وہ اپنا ہی نقصان کرتا ہے اور اللہ کی آیتوں کو ٹھٹھا نہ بنالو اور یاد کرو اللہ کا احسان جو تم پر ہے اور و ہ جو تم پر کتاب اور حکمت اتاری تمہیں نصیحت دینے کو اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ سب کچھ جانتا ہے')
