INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (239, 2, 232, N'اور جب تم عورتوں کو طلاق دو اور ان کی میعاد پوری ہوجائے تو اے عورتوں کے والِیو انہیں نہ روکو اس سے کہ اپنے شوہروں سے نکاح کرلیں جب کہ آپس میں موافق شرع رضا مند ہوجائیں یہ نصیحت اسے دی جاتی ہے جو تم میں سے اللہ اور قیامت پر ایمان رکھتا ہو یہ تمہارے لئے زیادہ ستھرا اور پاکیزہ ہے اور اللہ جانتا ہے اور تم نہیں جانتے،')
