INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (253, 2, 246, N'اے محبوب! کیا تم نے نہ دیکھا بنی اسرائیل کے ایک گروہ کو جو موسیٰ کے بعد ہوا جب اپنے ایک پیغمبر سے بولے ہمارے لیے کھڑا کردو ایک بادشاہ کہ ہم خدا کی راہ میں لڑیں، نبی نے فرمایا کیا تمہارے انداز ایسے ہیں کہ تم پر جہاد فرض کیا جائے تو پھر نہ کرو، بولے ہمیں کیا ہوا کہ ہم اللہ کی راہ میں نہ لڑیں حالانکہ ہم نکالے گئے ہیں اپنے وطن اور اپنی اولاد سے تو پھر جب ان پر جہاد فرض کیا گیا منہ پھیر گئے مگر ان میں کے تھوڑے اور اللہ خوب جانتا ہے ظالموں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (254, 2, 247, N'اور ان سے ان کے نبی نے فرمایا بیشک اللہ نے طالوت کو تمہارا بادشاہ بنا کر بھیجا ہے بولے اسے ہم پر بادشاہی کیونکر ہوگی اور ہم اس سے زیادہ سلطنت کے مستحق ہیں اور اسے مال میں بھی وسعت نہیں دی گئی فرمایا اسے اللہ نے تم پر چن لیا اور اسے علم اور جسم میں کشادگی زیادہ دی اور اللہ اپنا ملک جسے چاہ ے دے اور اللہ وسعت والا علم والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (255, 2, 248, N'اور ان سے ان کے نبی نے فرمایا اس کی بادشاہی کی نشانی یہ ہے کہ آئے تمہارے پاس تابوت جس میں تمہارے رب کی طرف سے دلوں کا چین ہے اور کچھ بچی ہوئی چیزیں معزز موسی ٰ او ر معزز ہارون کے ترکہ کی اٹھاتے لائیں گے اسے فرشتے، بیشک اس میں بڑی نشانی ہے تمہارے لئے اگر ایمان رکھتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (256, 2, 249, N'پھر جب طالوت لشکروں کو لے کر شہر سے جدا ہوا بولا بیشک اللہ تمہیں ایک نہر سے آزمانے والا ہے تو جو اس کا پانی پئے وہ میرا نہیں اور جو نہ پیئے وہ میرا ہے مگر وہ جو ایک چلُو اپنے ہاتھ سے لے لے تو سب نے اس سے پیا مگر تھوڑوں نے پھر جب طالوت اور اس کے ساتھ کے مسلمان نہر کے پار گئے بولے ہم میں آج طاقت نہیں جالوت اور اس کے لشکروں کی بولے وہ جنہیں اللہ سے ملنے کا یقین تھا کہ بارہا کم جماعت غالب آئی ہے زیادہ گروہ پر اللہ کے حکم سے، اور اللہ صابروں کے ساتھ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (257, 2, 250, N'پھر جب سامنے آئے جالوت اور اس کے لشکروں کے عرض کی اے رب ہمارے ہم پر صبر انڈیل اور ہمارے پاؤں جمے رکھ کافر لوگوں پرہماری مدد کر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (258, 2, 251, N'تو انہوں نے ان کو بھگا دیا اللہ کے حکم سے، اور قتل کیا داؤد نے جالوت کو اور اللہ نے اسے سلطنت اور حکمت عطا فرمائی اور اسے جو چاہا سکھایا اور اگر اللہ لوگوں میں بعض سے بعض کو دفع نہ کرے تو ضرور زمین تباہ ہوجائے مگر اللہ سارے جہان پر فضل کرنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (259, 2, 252, N'یہ اللہ کی آیتیں ہیں کہ ہم اے محبوب تم پر ٹھیک ٹھیک پڑھتے ہیں، اور تم بےشک رسولوں میں ہو۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (260, 2, 253, N'یہ رسول ہیں کہ ہم نے ان میں ایک کو دوسرے پر افضل کیا ان میں کسی سے اللہ نے کلام فرمایا اور کوئی وہ ہے جسے سب پر درجوں بلند کیا اور ہم نے مریم کے بیٹے عیسیٰ کو کھلی نشانیاں دیں اور پاکیزہ روح سے اس کی مدد کی اور اللہ چاہتا تو ان کے بعد والے آپس میں نہ لڑتے نہ اس کے کہ ان کے پاس کھلی نشانیاں آچکیں لیکن وہ مختلف ہوگئے ان میں کوئی ایمان پر رہا اور کوئی کافر ہوگیا اور اللہ چاہتا تو وہ نہ لڑتے مگر اللہ جو چاہے کرے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (261, 2, 254, N'اے ایمان والو! اللہ کی راہ میں ہمارے دیئے میں سے خرچ کرو وہ دن آنے سے پہلے جس میں نہ خرید و فروخت ہے اور نہ کافروں کے لئے دوستی اور نہ شفاعت، اور کافر خود ہی ظالم ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (262, 2, 255, N'اللہ ہے جس کے سوا کوئی معبود نہیں وہ آپ زندہ اور اوروں کا قائم رکھنے والا اسے نہ اونگھ آئے نہ نیند اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں وہ کون ہے جو اس کے یہاں سفارش کرے بغیر اس کے حکم کے جانتا ہے جو کچھ ان کے آگے ہے اور جو کچھ ان کے پیچھے اور وہ نہیں پاتے اس کے علم میں سے مگر جتنا وہ چاہے اس کی کرسی میں سمائے ہوئے آسمان اور زمین اور اسے بھاری نہیں ان کی نگہبانی اور وہی ہے بلند بڑائی والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (263, 2, 256, N'کچھ زبردستی نہیں دین میں بیشک خوب جدا ہوگئی ہے نیک راہ گمراہی سے تو جو شیطان کو نہ مانے اور اللہ پر ایمان لائے اس نے بڑی محکم گرہ تھامی جسے کبھی کھلنا نہیں، اور اللہ سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (264, 2, 257, N'اللہ والی ہے مسلمانوں کا انہیں اندھیریوں سے نور کی طرف نکلتا ہے، اور کافروں کے حمایتی شیطان ہیں وہ انہیں نور سے اندھیریوں کی طرف نکالتے ہیں یہی لوگ دوزخ والے ہیں انہیں ہمیشہ اس میں رہنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (265, 2, 258, N'اے محبوب! کیا تم نے نہ دیکھا تھا اسے جو ابراہیم سے جھگڑا اس کے رب کے بارے میں اس پر کہ اللہ نے اسے بادشاہی دی جبکہ ابراہیم نے کہا کہ میرا رب وہ ہے جو جِلاتا اور مارتا ہے بولا میں جِلاتا اور مارتا ہوں ابراہیم نے فرمایا تو اللہ سورج کو لاتا ہے پورب (مشرق) سے تو اس کو پچھم (مغرب) سے لے آ تو ہوش اڑ گئے کافروں کے، اور اللہ راہ نہیں دکھاتا ظالموں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (266, 2, 259, N'یا اس کی طرح جو گزرا ایک بستی پر اور وہ ڈھئی (مسمار ہوئی) پڑی تھی اپنی چھتوں پر بولا اسے کیونکر جِلائے گا اللہ اس کی موت کے بعد تو اللہ نے اسے مردہ رکھا سو برس پھر زندہ کردیا، فرمایا تو یہاں کتنا ٹھہرا، عرض کی دن بھر ٹھہرا ہوں گا یا کچھ کم، فرمایا نہیں تجھے سو برس گزر گئے اور اپنے کھانے اور پانی کو دیکھ کہ اب تک بو نہ لایا اور اپنے گدھے کو دیکھ کہ جس کی ہڈیاں تک سلامت نہ رہیں اور یہ اس لئے کہ تجھے ہم لوگوں کے واسطے نشانی کریں اور ان ہڈیوں کو دیکھ کیونکر ہم انہیں اٹھان دیتے پھر انہیں گوشت پہناتے ہیں جب یہ معاملہ اس پر ظاہر ہوگیا بولا میں خوب جانتا ہوں کہ اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (267, 2, 260, N'اور جب عرض کی ابراہیم نے اے رب میرے مجھے دکھا دے تو کیونکر مردے جِلائے گا فرمایا کیا تجھے یقین نہیں عرض کی یقین کیوں نہیں مگر یہ چاہتا ہوں کہ میرے دل کو قرار آجائے فرمایا تو اچھا، چار پرندے لے کر اپنے ساتھ ہلالے پھر ان کا ایک ایک ٹکڑا ہر پہاڑ پر رکھ دے پھر انہیں بلا وہ تیرے پاس چلے آئیں گے پاؤں سے دوڑتے اور جان رکھ کہ اللہ غالب حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (268, 2, 261, N'ان کی کہاوت جو اپنے مال اللہ کی راہ میں خرچ کرتے ہیں اس دانہ کی طرح جس نے اگائیں سات بالیں ہر بال میں سو دانے اور اللہ اس سے بھی زیادہ بڑھائے جس کے لئے چاہے اور اللہ وسعت والا علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (269, 2, 262, N'وہ جو اپنے مال اللہ کی راہ میں خرچ کرتے ہیں پھر دیئے پیچھے نہ احسان رکھیں نہ تکلیف دیں ان کا نیگ (انعام) ان کے رب کے پاس ہے اور انہیں نہ کچھ اندیشہ ہو نہ کچھ غم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (270, 2, 263, N'اچھی بات کہنا اور درگزر کرنا اس خیرات سے بہتر ہے جس کے بعد ستانا ہو اور اللہ بے پراہ حلم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (271, 2, 264, N'اے ایمان والوں اپنے صدقے باطل نہ کردو احسان رکھ کر اور ایذا دے کر اس کی طرح جو اپنا مال لوگوں کے دکھاوے کے لئے خرچ کرے اور اللہ اور قیامت پر ایمان نہ لائے، تو اس کی کہاوت ایسی ہے جیسے ایک چٹان کہ اس پر مٹی ہے اب اس پر زور کا پانی پڑا جس نے اسے نرا پتھر کر چھوڑا اپنی کمائی سے کسی چیز پر قابو نہ پائیں گے، اور اللہ کافروں کو راہ نہیں دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (272, 2, 265, N'اور ان کی کہاوت جو اپنے مال اللہ کی رضا چاہنے میں خرچ کرتے ہیں اور اپنے دل جمانے کو اس باغ کی سی ہے جو بھوڑ (رتیلی زمین) پر ہو اس پر زور کا پانی پڑا تو دُونے میوے لایا پھر اگر زور کا مینھ اسے نہ پہنچے تو اوس کافی ہے اور اللہ تمہارے کام دیکھ رہا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (273, 2, 266, N'کیا تم میں کوئی اسے پسند رکھے گا کہ اس کے پاس ایک باغ ہو کھجوروں اور انگوروں کا جس کے نیچے ندیاں بہتیں اس کے لئے اس میں ہر قسم کے پھلوں سے ہے اور اسے بڑھاپا آیا اور اس کے ناتوان بچے ہیں تو آیا اس پر ایک بگولا جس میں آگ تھی تو جل گیا ایسا ہی بیان کرتا ہے اللہ تم سے اپنی آیتیں کہ کہیں تم دھیان لگاؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (274, 2, 267, N'اے ایمان والو! اپنی پاک کمائیوں میں سے کچھ دو اور اس میں سے جو ہم نے تمہارے لئے زمین سے نکالا اور خاص ناقص کا ارادہ نہ کرو کہ دو تو اس میں سے اور تمہیں ملے تو نہ لوگے جب تک اس میں چشم پوشی نہ کرو اور جان رکھو کہ اللہ بے پروانہ سراہا گیا ہے۔')
