INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (275, 2, 268, N'شیطان تمہیں اندیشہ دلاتا ہے محتاجی کا اور حکم دیتا ہے بے حیائی کا اور اللہ تم سے وعدہ فرماتا ہے بخشش اور فضل کا اور اللہ وسعت و الا علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (276, 2, 269, N'اللہ حکمت دیتا ہے جسے چاہے اور جسے حکمت ملی اسے بہت بھلائی ملی، اور نصیحت نہیں مانتے مگر عقل والے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (277, 2, 270, N'اور تم جو خرچ کرو یا منت مانو اللہ کو اس کی خبر ہے اور ظالموں کا کوئی مددگار نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (278, 2, 271, N'اگر خیرات اعلانیہ دو تو وہ کیا ہی اچھی بات ہے اور اگر چھپا کر فقیروں کو دو یہ تمہارے لئے سب سے بہتر ہے اور اسمیں تمہارے کچھ گناہ گھٹیں گے، اور اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (279, 2, 272, N'انہیں راہ دینا تمہارے ذمہ لازم نہیں، ہاں اللہ راہ دیتا ہے جسے چاہتا ہے، اور تم جو اچھی چیز دو تو تمہارا ہی بھلا ہے اور تمہیں خرچ کرنا مناسب نہیں مگر اللہ کی مرضی چاہنے کے لئے، اور جو مال دو تمہیں پورا ملے گا اور نقصان نہ دیئے جاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (280, 2, 273, N'ان فقیروں کے لئے جو راہ خدا میں روکے گئے زمین میں چل نہیں سکتے نادان انہیں تونگر سمجھے بچنے کے سبب تو انہیں ان کی صورت سے پہچان لے گا لوگوں سے سوال نہیں کرتے کہ گڑ گڑانا پڑے اور تم جو خیرات کرو اللہ اسے جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (281, 2, 274, N'وہ جو اپنے مال خیرات کرتے ہیں رات میں اور دن میں چھپے اور ظاہر ان کے لئے ان کا نیگ (انعام، حصہ) ہے ان کے رب کے پاس ان کو نہ کچھ اندیشہ ہو نہ کچھ غم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (282, 2, 275, N'وہ جو سود کھاتے ہیں قیامت کے دن نہ کھڑے ہوں گے مگر، جیسے کھڑا ہوتا ہے وہ جسے آسیب نے چھو کر مخبوط بنادیا ہو اس لئے کہ انہوں نے کہا بیع بھی تو سود ہی کے مانند ہے، اور اللہ نے حلال کیا بیع کو اور حرام کیا سود، تو جسے اس کے رب کے پاس سے نصیحت آئی اور وہ باز رہا تو اسے حلال ہے جو پہلے لے چکا، اور اس کا کام خدا کے سپرد ہے اور جو اب ایسی حرکت کرے گا تو وہ دوزخی ہے وہ اس میں مدتو ں رہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (283, 2, 276, N'اللہ ہلاک کرتا ہے سود کو اور بڑھاتا ہے خیرات کو اور اللہ کو پسند نہیں آتا کوئی ناشکرا بڑا گنہگار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (284, 2, 277, N'بیشک وہ جو ایمان لائے اور اچھے کام کئے اور نماز قائم کی اور زکوٰة دی ان کا نیگ (انعام) ان کے رب کے پاس ہے، اور نہ انہیں کچھ اندیشہ ہو، نہ کچھ غم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (285, 2, 278, N'اے ایمان والو! اللہ سے ڈرو اور چھوڑ دو جو باقی رہ گیا ہے سود اگر مسلمان ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (286, 2, 279, N'پھر اگر ایسا نہ کرو تو یقین کرلو اللہ اور اللہ کے رسول سے لڑائی کا اور اگر تم توبہ کرو تو اپنا اصل مال لے لو نہ تم کسی کو نقصان پہچاؤ نہ تمہیں نقصان ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (287, 2, 280, N'اور اگر قرضدار تنگی والا ہے تو اسے مہلت دو آسانی تک، اور قرض اس پر بالکل چھوڑ دینا تمہارے لئے اور بھلا ہے اگر جانو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (288, 2, 281, N'اور ڈرو اس دن سے جس میں اللہ کی طرف پھرو گے، اور ہر جان کو اس کی کمائی پوری بھردی جائے گی اور ان پر ظلم نہ ہوگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (289, 2, 282, N'اے ایمان والو! جب تم ایک مقرر مدت تک کسی دین کا لین دین کرو تو اسے لکھ لو اور چاہئے کہ تمہارے درمیان کوئی لکھنے والا ٹھیک ٹھیک لکھے اور لکھنے والا لکھنے سے انکار نہ کرے جیسا کہ اسے اللہ نے سکھایا ہے تو اسے لکھ دینا چاہئے اور جس بات پر حق آتا ہے وہ لکھا تا جائے اور اللہ سے ڈرے جو اس کا رب ہے اور حق میں سے کچھ رکھ نہ چھوڑے پھر جس پر حق آتا ہے اگر بے عقل یا ناتواں ہو یا لکھا نہ سکے تو اس کا ولی انصاف سے لکھائے، اور دو گواہ کرلو اپنے مردوں میں سے پھر اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں ایسے گواہ جن کو پسند کرو کہ کہیں ان میں ایک عورت بھولے تو اس کو دوسری یاد دلادے، اور گواہ جب بلائے جائیں تو آنے سے انکار نہ کریں اور اسے بھاری نہ جانو کہ دین چھوٹا ہو یا بڑا اس کی میعاد تک لکھت کرلو یہ اللہ کے نزدیک زیادہ انصاف کی بات ہے اس میں گواہی خوب ٹھیک رہے گی اور یہ اس سے قریب ہے کہ تمہیں شبہ نہ پڑے مگر یہ کہ کوئی سردست کا سودا دست بدست ہو تو اس کے نہ لکھنے کا تم پر گناہ نہیں اور جب خرید و فروخت کرو تو گواہ کرلو اور نہ کسی لکھنے والے کو ضَرر دیا جائے، نہ گواہ کو (یا، نہ لکھنے والا ضَرر دے نہ گواہ) اور جو تم ایسا کرو تو یہ تمہارا فسق ہوگا، اور اللہ سے ڈرو اور اللہ تمہیں سکھاتا ہے، اور اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (290, 2, 283, N'اور اگر تم سفر میں ہو اور لکھنے والا نہ پاؤ تو گِرو (رہن) ہو قبضہ میں دیا ہوا اور اگر تم ایک کو دوسرے پر اطمینان ہو تو وہ جسے اس نے امین سمجھا تھا اپنی امانت ادا کردے اور اللہ سے ڈرے جو اس کا رب ہے اور گواہی نہ چھپاؤ اور جو گواہی چھپائے گا تو اندر سے اسکا دل گنہگار ہے اور اللہ تمہارے کاموں کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (291, 2, 284, N'اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور اگر تم ظاہر کرو جو کچھ تمہارے جی میں ہے یا چھپاؤ اللہ تم سے اس کا حساب لے گا تو جسے چاہے گا بخشے گا اور جسے چاہے گا سزادے گا اور اللہ ہر چیز پر قادر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (292, 2, 285, N'سب نے مانا اللہ اور اس کے فرشتوں اور اس کی کتابوں اور اس کے رسولوں کو یہ کہتے ہوئے کہ ہم اس کے کسی رسول پر ایمان لانے میں فرق نہیں کرتے اور عرض کی کہ ہم نے سنا اور مانا تیری معافی ہو اے رب ہمارے! اور تیری ہی طرف پھرنا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (293, 2, 286, N'اللہ کسی جان پر بوجھ نہیں ڈالتا مگر اس کی طاقت بھر، اس کا فائدہ ہے جو اچھا کمایا اور اس کا نقصان ہے جو برائی کمائی اے رب ہمارے! ہمیں نہ پکڑ اگر ہم بھولیں یا چوُکیں اے رب ہمارے! اور ہم پر بھاری بوجھ نہ رکھ جیسا تو نے ہم سے اگلوں پر رکھا تھا، اے رب ہمارے! اور ہم پر وہ بوجھ نہ ڈال جس کی ہمیں سہار (برداشت) نہ ہو اور ہمیں معاف فرمادے اور بخش دے اور ہم پر مہر کر تو ہمارا مولیٰ ہے۔ تو کافروں پر ہمیں مدد دے۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (294, 3, 1, N'الم،')
