INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (295, 3, 2, N'اللہ ہے جس کے سوا کسی کی پوجا نہیں آپ زندہ اور ونکا قائم رکھنے والا،')
