INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (296, 3, 3, N'اس نے تم پر یہ سچی کتاب اتاری اگلی کتابوں کی تصدیق فرماتی اور اس نے اس سے پہلے توریت اور انجیل اتاری،')
