INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (297, 3, 4, N'لوگوں کو راہ دکھاتی اور فیصلہ اتارا، بیشک وہ جو اللہ کی آیتوں سے منکر ہوئے ان کے لئے سخت عذاب ہے اور اللہ غالب بدلہ لینے والا ہے،')
