INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (299, 3, 6, N'وہی ہے کہ تمہاری تصویر بناتا ہے ماؤں کے پیٹ میں جیسی چاہے اس کے سوا کسی کی عبادت نہیں عزت والا حکمت والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (300, 3, 7, N'وہی ہے جس نے تم پر یہ کتاب اتاری اس کی کچھ آیتیں صاف معنی رکھتی ہیں وہ کتاب کی اصل ہیں اور دوسری وہ ہیں جن کے معنی میں اشتباہ ہے وہ جن کے دلوں میں کجی ہے وہ اشتباہ والی کے پیچھے پڑتے ہیں گمراہی چاہنے اور اس کا پہلو ڈھونڈنے کو اور اس کا ٹھیک پہلو اللہ ہی کو معلوم ہے اور پختہ علم والے کہتے ہیں ہم اس پر ایمان لائے سب ہمارے رب کے پاس سے ہے اور نصیحت نہیں مانتے مگر عقل والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (301, 3, 8, N'اے رب ہمارے دل ٹیڑھے نہ کر بعد اس کے کہ تو نے ہمیں ہدایت دی اور ہمیں اپنے پاس سے رحمت عطا کر بیشک تو ہے بڑا دینے والا،')
