INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (304, 3, 11, N'جیسے فرعون والوں اور ان سے اگلوں کا طریقہ، انہوں نے ہماری آیتیں جھٹلائیں تو اللہ نے ان کے گناہوں پر ان کو پکڑا اور اللہ کا عذاب سخت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (305, 3, 12, N'فرمادو، کافروں سے کوئی دم جاتا ہے کہ تم مغلوب ہوگے اور دوزخ کی طرف ہانکے جاؤ گے اور وہ بہت ہی برا بچھونا،')
