INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (306, 3, 13, N'بیشک تمہارے لئے نشانی تھی دو گروہوں میں جو آپس میں بھڑ پڑے ایک جتھا اللہ کی راہ میں لڑتا اور دوسرا کافر کہ انہیں آنکھوں دیکھا اپنے سے دونا سمجھیں، اور اللہ اپنی مدد سے زور دیتا ہے جسے چاہتا ہے بیشک اس میں عقلمندوں کے لئے ضرور دیکھ کر سیکھنا ہے،')
