INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (307, 3, 14, N'لوگوں کے لئے آراستہ کی گئی ان خواہشوں کی محبت عورتوں اور بیٹے اور تلے اوپر سونے چاندے کے ڈھیر اور نشان کئے ہوئے گھوڑے اور چوپائے اور کھیتی یہ جیتی دنیا کی پونجی ہے اور اللہ ہے جس کے پاس اچھا ٹھکانا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (308, 3, 15, N'تم فرماؤ کیا میں تمہیں اس سے بہتر چیز بتادوں پرہیزگاروں کے لئے ان کے رب کے پاس جنتیں ہیں جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے اور ستھری بیبیاں اور اللہ کی خوشنودی اور اللہ بندوں کو دیکھتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (309, 3, 16, N'وہ جو کہتے ہیں ے رب ہمارے! ہم ایمان لائے تو ہمارے گناہ معاف کر اور ہمیں دوزخ کے عذاب سے بچالے،')
