INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (310, 3, 17, N'صبر والے اور سچے اور ادب والے اور راہِ خدا میں خرچنے والے اور پچھلے پہر سے معافی مانگنے والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (311, 3, 18, N'اور اللہ نے گواہی دی کہ اس کے سوا کوئی معبود نہیں اور فرشتوں نے اور عالموں نے انصاف سے قائم ہوکر اس کے سوا کسی کی عبادت نہیں عزت والا حکمت والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (312, 3, 19, N'بیشک اللہ کے یہاں اسلام ہی دین ہے اور پھوٹ میں نہ پڑے کتابی مگر اس کے کہ انہیں علم آچکا اپنے دلو ں کی جلن سے اور جو اللہ کی آیتوں کا منکر ہو تو بیشک اللہ جلد حساب لینے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (313, 3, 20, N'پھر اے محبوب! اگر وہ تم سے حجت کریں تو فرمادو میں اپنا منہ اللہ کے حضور جھکائے ہوں اور جومیرے پیرو ہوئے اور کتابیوں اور اَن پڑھوں سے فرماؤ کیا تم نے گردن رکھی پس اگر وہ گردن رکھیں جب تو راہ پاگئے اور اگر منہ پھیریں تو تم پر تو یہی حکم پہنچادینا ہے اور اللہ بندوں کو کو دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (314, 3, 21, N'وہ جو اللہ کی آیتوں سے منکر ہوتے اور پیغمبروں کو ناحق شہید کرتے اور انصاف کا حکم کرنے والوں کو قتل کرتے ہیں انہیں خوشخبری دو درناک عذاب کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (315, 3, 22, N'یہ ہیں وہ جنکے اعمال اکارت گئے دنیا و آخرت میں اور ان کا کوئی مددگار نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (316, 3, 23, N'کیا تم نے انہیں دیکھا جنہیں کتاب کا ایک حصہ ملا کتاب اللہ کی طرف بلائے جاتے ہیں کہ وہ ان کا فیصلہ کرے پھر ان میں کا ایک گروہ اس سے روگرداں ہوکر پھر جاتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (317, 3, 24, N'یہ جرأت انہیں اس لئے ہوئی کہ وہ کہتے ہیں ہرگز ہمیں آگ نہ چھوئے گی مگر گنتی کے دنوں اور ان کے دین میں انہیں فریب دیا اس جھوٹ نے جو باندھتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (318, 3, 25, N'تو کیسی ہوگی جب ہم انہیں اکٹھا کریں گے اس دن کے لئے جس میں شک نہیں اور ہر جان کو اس کی کمائی پوری بھر (بالکل پوری) دی جائے گی اور ان پر ظلم نہ ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (319, 3, 26, N'یوں عرض کر، اے اللہ! ملک کے مالک تو جسے چاہے سلطنت دے اور جس سے چاہے چھین لے، اور جسے چاہے عزت دے اور جسے چاہے ذلت دے، ساری بھلائی تیرے ہی ہاتھ ہے، بیشک تو سب کچھ کرسکتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (320, 3, 27, N'تو دن کا حصّہ رات میں ڈالے اور رات کا حصہ دن میں ڈالے اور مردہ سے زندہ نکالے اور زندہ سے مردہ نکالے اور جسے چاہے بے گنتی دے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (321, 3, 28, N'مسلمان کافروں کو اپنا دوست نہ بنالیں مسلمانوں کے سوا اور جو ایسا کرے گا اسے اللہ سے کچھ علاقہ نہ رہا مگر یہ کہ تم ان سے کچھ ڈرو اور اللہ تمہیں اپنے غضب سے ڈراتا ہے اور اللہ ہی کی طرف پھرنا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (322, 3, 29, N'تم فرمادو کہ اگر تم اپنے جی کی بات چھپاؤ یا ظاہر کرو اللہ کو سب معلوم ہے، اور جانتا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور ہر چیز پر اللہ کا قابو ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (323, 3, 30, N'جس دن ہر جان نے جو بھلا کیا حاضر پائے گی اور جو برا کام کیا، امید کرے گی کاش مجھ میں اور اس میں دور کا فاصلہ ہوتا اور اللہ تمہیں اپنے عذاب سے ڈراتا ہے، اور اللہ بندوں پر مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (324, 3, 31, N'اے محبوب! تم فرمادو کہ لوگو اگر تم اللہ کو دوست رکھتے ہو تو میرے فرمانبردار ہوجاؤ اللہ تمہیں دوست رکھے گا اور تمہارے گناہ بخش دے گا اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (325, 3, 32, N'تم فرمادو کہ حکم مانو اللہ اور رسول کا پھر اگر وہ منہ پھیریں تو اللہ کو خوش نہیں آتے کافر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (326, 3, 33, N'بیشک اللہ نے چن لیا آدم اور نوح اور ابراہیم کی آ ل اولاد اور عمران کی آ ل کو سارے جہاں سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (327, 3, 34, N'یہ ایک نسل ہے ایک دوسرے سے اور اللہ سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (328, 3, 35, N'جب عمران کی بی بی نے عرض کی اے رب میرے! میں تیرے لئے منت مانتی ہو جو میرے پیٹ میں ہے کہ خالص تیری ہی خدمت میں رہے تو تو مجھ سے قبول کرلے بیشک تو ہی سنتا جانتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (329, 3, 36, N'پھر جب اسے جنا بولی، اے رب میرے! یہ تو میں نے لڑکی جنی اور اللہ جو خوب معلوم ہے جو کچھ وہ جنی، اور وہ لڑکا جو اس نے مانگا اس لڑکی سا نہیں اور میں نے اس کا نام مریم رکھا اور میں اسے اور اس کی اولاد کو تیری پناہ میں دیتی ہوں راندے ہوئے شیطان سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (330, 3, 37, N'تو اسے اس کے رب نے اچھی طرح قبول کیا اور اسے اچھا پروان چڑھایا اور اسے زکریا کی نگہبانی میں دیا، جب زکریا اس کے پاس اس کی نماز پڑھنے کی جگہ جاتے اس کے پاس نیا رزق پاتے کہا اے مریم! یہ تیرے پاس کہاں سے آیا، بولیں وہ اللہ کے پاس سے ہے، بیشک اللہ جسے چاہے بے گنتی دے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (331, 3, 38, N'یہاں پکارا زکریا اپنے رب کو بولا اے رب! میرے مجھے اپنے پاس سے دے ستھری اولاد، بیشک تو ہی ہے دعا سننے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (332, 3, 39, N'تو فرشتوں نے اسے آواز دی اور وہ اپنی نماز کی جگہ کھڑا نماز پڑھ رہا تھا بیشک اللہ آپ کو مژدہ دیتا ہے یحییٰ کا جو اللہ کی طرف کے ایک کلمہ کی تصدیق کرے گا اور سردار اور ہمیشہ کے لیے عورتوں سے بچنے والا اور نبی ہمارے خاصوں میں سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (333, 3, 40, N'بولا اے میرے رب میرے لڑکا کہاں سے ہوگا مجھے تو پہنچ گیا بڑھا پا اور میری عورت بانجھ فرمایا اللہ یوں ہی کرتا ہے جو چاہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (334, 3, 41, N'عرض کی اے میرے رب میرے لئے کوئی نشانی کردے فرمایا تیری نشانی یہ ہے کہ تین دن تو لوگوں سے بات نہ کرے مگر اشارہ سے اور اپنے رب کی بہت یاد کر اور کچھ دن رہے اور تڑکے اس کی پاکی بول،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (335, 3, 42, N'اور جب فرشتوں نے کہا، اے مریم، بیشک اللہ نے تجھے چن لیا اور خوب ستھرا کیا اور آج سارے جہاں کی عورتوں سے تجھے پسند کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (336, 3, 43, N'اے مریم اپنے رب کے حضور ادب سے کھڑی ہو اور اس کے لئے سجدہ کر اور رکوع والوں کے ساتھ رکوع کر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (337, 3, 44, N'یہ غیب کی خبریں ہیں کہ ہم خفیہ طور پر تمہیں بتاتے ہیں اور تم ان کے پاس نہ تھے جب وہ اپنی قلموں سے قرعہ ڈالتے تھے کہ مریم کس کی پرورش میں رہیں اور تم ان کے پاس نہ تھے جب وہ جھگڑ رہے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (338, 3, 45, N'اور یاد کرو جب فرشتو ں نے مریم سے کہا، اے مریم! اللہ تجھے بشارت دیتا ہے اپنے پاس سے ایک کلمہ کی جس کا نام ہے مسیح عیسیٰ مریم کا بیٹا رُو دار (باعزت) ہوگا دنیا اور آخرت میں اور قرب والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (339, 3, 46, N'اور لوگوں سے بات کرے گا پالنے میں اور پکی عمر میں اور خاصوں میں ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (340, 3, 47, N'بولی اے میرے رب! میرے بچہ کہاں سے ہوگا مجھے تو کسی شخص نے ہاتھ نہ لگایا فرمایا اللہ یوں ہی پیدا کرتا ہے جو چاہے جب، کسی کام کا حکم فرمائے تو اس سے یہی کہتا ہے کہ ہوجا وہ فوراً ہوجاتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (341, 3, 48, N'اور اللہ سکھائے گا کتاب اور حکمت اور توریت اور انجیل،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (342, 3, 49, N'اور رسول ہوگا بنی اسرائیل کی طرف، یہ فرماتا ہو کہ میں تمہارے پاس ایک نشانی لایا ہوں تمہارے رب کی طرف سے کہ میں تمہارے لئے مٹی سے پرند کی سی مور ت بناتا ہوں پھر اس میں پھونک مارتا ہوں تو وہ فوراً پرند ہوجاتی ہے اللہ کے حکم سے اور میں شفا دیتا ہوں مادر زاد اندھے اور سفید داغ والے کو اور میں مُردے جلاتا ہوں اللہ کے حکم سے اور تمہیں بتاتا ہوں جو تم کھاتے اور جو اپنے گھروں میں جمع کر رکھتے ہو، بیشک ان باتوں میں تمہارے لئے بڑی نشانی ہے اگر تم ایمان رکھتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (343, 3, 50, N'اور تصدیق کرتا آیا ہوں اپنے سے پہلے کتاب توریت کی اور اس لئے کہ حلال کروں تمہارے لئے کچھ وہ چیزیں جو تم پر حرام تھیں اور میں تمہارے پاس پاس تمہارے رب کی طرف سے نشانی لایا ہوں، تو اللہ سے ڈرو اور میرا حکم مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (344, 3, 51, N'بیشک میرا تمہارا سب کا رب اللہ ہے تو اسی کو پوجو یہ ہے سیدھا راستہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (345, 3, 52, N'پھر جب عیسیٰ نے ان سے کفر پایا بولا کون میرے مددگار ہوتے ہیں اللہ کی طرف، حواریوں نے کہا ہم دینِ خدا کے مددگار ہیں ہم اللہ پر ایمان لائے، اور آپ گواہ ہوجائیں کہ ہم مسلمان ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (346, 3, 53, N'اے رب ہمارے! ہم اس پر ایمان لائے جو تو نے اتارا اور رسول کے تابع ہوئے تو ہمیں حق پر گواہی دینے والوں میں لکھ لے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (347, 3, 54, N'اور کافروں نے مکر کیا اور اللہ نے ان کے ہلاک کی خفیہ تدبیر فرمائی اور اللہ سب سے بہتر چھپی تدبیر والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (348, 3, 55, N'یاد کرو جب اللہ نے فرمایا اے عیسیٰ میں تجھے پوری عمر تک پہنچاؤں گا اور تجھے اپنی طرف اٹھالوں گا اور تجھے کافروں سے پاک کردوں گا اور تیرے پیروؤں کو قیامت تک تیرے منکروں پر غلبہ دوں گا پھر تم سب میری طرف پلٹ کر آؤ گے تو میں تم میں فیصلہ فرمادوں گا جس بات میں جھگڑتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (349, 3, 56, N'تو وہ جو کافر ہوئے میں انہیں دنیاو آخرت میں سخت عذاب کروں گا، اور انکا کوئی مددگار نہ ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (350, 3, 57, N'اور وہ جو ایمان لائے اور اچھے کام کئے اللہ ان کا نیگ (انعام) انہیں بھرپور دے گا اور ظالم اللہ کو نہیں بھاتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (351, 3, 58, N'یہ ہم تم پر پڑھتے ہیں کچھ آیتیں اور حکمت والی نصیحت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (352, 3, 59, N'عیسیٰ کی کہاوت اللہ کے نزدیک آدم کی طرح ہے اسے مٹی سے بنایا پھر فرمایا ہوجا وہ فوراً ہوجاتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (353, 3, 60, N'اے سننے والے! یہ تیرے رب کی طرف سے حق ہے تو شک والوں میں نہ ہونا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (354, 3, 61, N'پھر اے محبوب! جو تم سے عیسیٰ کے بارے میں حجت کریں بعد اس کے کہ تمہیں علم آچکا تو ان سے فرما دو آ ؤ ہم بلائیں اپنے بیٹے اور تمہارے بیٹے اور اپنی عورتیں اور تمہاری عورتیں اور اپنی جانیں اور تمہاری جانیں، پھر مباہلہ کریں تو جھوٹوں پر اللہ کی لعنت ڈالیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (355, 3, 62, N'یہی بیشک سچا بیان ہے اور اللہ کے سوا کوئی معبود نہیں اور بیشک اللہ ہی غالب ہے حکمت والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (356, 3, 63, N'پھر اگر وہ منہ پھیریں تو اللہ فسادیوں کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (357, 3, 64, N'تم فرماؤ، اے کتابیو! ایسے کلمہ کی طرف آؤ جو ہم میں تم میں یکساں ہے یہ کہ عبادت نہ کریں مگر خدا کی اور اس کا شریک کسی کو نہ کریں اور ہم میں کوئی ایک دوسرے کو رب نہ بنالے اللہ کے سوا پھر اگر وہ نہ مانیں تو کہہ دو تم گواہ رہو کہ ہم مسلمان ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (358, 3, 65, N'اے کتاب والو! ابراہیم کے باب میں کیوں جھگڑتے ہو توریت و انجیل تو نہ اتری مگر ان کے بعد تو کیا تمہیں عقل نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (359, 3, 66, N'سنتے ہو یہ جو تم ہو اس میں جھگڑے جس کا تمہیں علم تھا تو اس میں کیوں جھگڑتے ہو جس کا تمہیں علم ہی نہیں اور اللہ جانتا ہے اور تم نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (360, 3, 67, N'ابراہیم نہ یہودی تھے نہ نصرانی بلکہ ہر باطل سے جدا مسلمان تھے، اور مشرکوں سے نہ تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (361, 3, 68, N'بیشک سب لوگوں سے ابراہیم کے زیادہ حق دار وہ تھے جو ان کے پیرو ہوئے اور یہ نبی اور ایمان والے اور ایمان والوں کا ولی اللہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (362, 3, 69, N'کتابیوں کا ایک گروہ دل سے چاہتا ہے کہ کسی طرح تمہیں گمراہ کردیں، اور وہ اپنے ہی آپ کو گمراہ کرتے ہیں اور انہیں شعور نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (363, 3, 70, N'اے کتابیو! اللہ کی آیتوں سے کیوں کفر کرتے ہو حالانکہ تم خود گواہی ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (364, 3, 71, N'اے کتابیو! حق میں باطل کیوں ملاتے ہو اور حق کیوں چھپاتے ہو حالانکہ تمہیں خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (365, 3, 72, N'اور کتابیوں کا ایک گروہ بولا وہ جو ایمان والوں پر اترا صبح کو اس پر ایمان لاؤ اور شام کو منکر ہوجاؤ شاید وہ پھر جائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (366, 3, 73, N'اور یقین نہ لاؤ مگر اس کا جو تمہارے دین کا پیرو ہو تم فرمادو کہ اللہ ہی کی ہدایت ہدایت ہے (یقین کا ہے کا نہ لاؤ) اس کا کہ کسی کو ملے جیسا تمہیں ملا یا کوئی تم پر حجت لاسکے تمہارے رب کے پاس تم فرمادو کہ فضل تو اللہ ہی کے ہاتھ ہے جسے چاہے دے، اور اللہ وسعت والا علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (367, 3, 74, N'اپنی رحمت سے خاص کرتا ہے جسے چاہے اور اللہ بڑے فضل والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (368, 3, 75, N'اور کتابیوں میں کوئی وہ ہے کہ اگر تو اس کے پاس ایک ڈھیر امانت رکھے تو وہ تجھے ادا کردے گا اور ان میں کوئی وہ ہے کہ اگر ایک اشرفی اس کے پاس امانت رکھے تو وہ تجھے پھیر کر نہ دے گا مگر جب تک تو اس کے سر پر کھڑا رہے یہ اس لئے کہ وہ کہتے ہیں کہ اَن پڑھوں کے معاملہ میں ہم پر کوئی مؤاخذہ نہیں اور اللہ پر جان بوجھ کر جھوٹ باندھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (369, 3, 76, N'ہاں کیوں نہیں جس نے اپنا عہد پورا کیا اور پرہیزگاری کی اور بیشک پرہیزگار اللہ کو خوش آتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (370, 3, 77, N'جو اللہ کے عہد اور اپنی قسموں کے بدلے ذلیل دام لیتے ہیں آخرت میں ان کا کچھ حصہ نہیں اور اللہ نہ ان سے بات کرے نہ ان کی طرف نظر فرمائے قیامت کے دن اور نہ انہیں پاک کرے، اور ان کے لئے دردناک عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (371, 3, 78, N'اور ان میں کچھ وہ ہیں جو زبان پھیر کر کتاب میں میل (ملاوٹ) کرتے ہیں کہ تم سمجھو یہ بھی کتاب میں ہے اور وہ کتاب میں نہیں، اور وہ کہتے ہیں یہ اللہ کے پاس سے ہے اور وہ اللہ کے پاس سے نہیں، اور اللہ پر دیدہ و دانستہ جھوٹ باندھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (372, 3, 79, N'کسی آدمی کا یہ حق نہیں کہ اللہ اسے کتاب اور حکم و پیغمبری دے پھر وہ لوگوں سے کہے کہ اللہ کو چھوڑ کر میرے بندے ہوجاؤ ہاں یہ کہے گا کہ اللہ والے ہوجاؤ اس سبب سے کہ تم کتاب سکھاتے ہو اور اس سے کہ تم درس کرتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (373, 3, 80, N'اور نہ تمہیں یہ حکم دے گا کہ فرشتوں اور پیغمبروں کو خدا ٹھیرالو، کیا تمہیں کفر کا حکم دے گا بعد اس کے کہ تم مسلمان ہولیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (374, 3, 81, N'اور یاد کرو جب اللہ نے پیغمبروں سے ان کا عہد لیا جو میں تم کو کتاب اور حکمت دوں پھر تشریف لائے تمہارے پاس وہ رسول کہ تمہاری کتابوں کی تصدیق فرمائے تو تم ضرور ضرور اس پر ایمان لانا اور ضرور ضرور اس کی مدد کرنا، فرمایا کیوں تم نے اقرار کیا اور اس پر میرا بھاری ذمہ لیا؟ سب نے عرض کی، ہم نے اقرار کیا، فرمایا تو ایک دوسرے پر گواہ ہوجاؤ اور میں آپ تمہارے ساتھ گواہوں میں ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (375, 3, 82, N'تو جو کوئی اس کے بعد پھرے تو وہی لوگ فاسق ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (376, 3, 83, N'تو کیا اللہ کے دین کے سوا اور دین چاہتے ہیں اور اسی کے حضور گردن رکھے ہیں جو کوئی آسمانوں اور زمین میں ہیں خوشی سے سے مجبوری سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (377, 3, 84, N'اور اُسی کی طرف پھیریں گے، یوں کہو کہ ہم ایمان لائے اللہ پر اور اس پر جو ہماری طرف اترا اور جو اترا ابراہیم اور اسماعیل اور اسحاق اور یعقوب اور ان کے بیٹوں پر اور جو کچھ ملا موسیٰ اور عیسیٰ اور انبیاء کو ان کے رب سے، ہم ان میں کسی پر ایمان میں فرق نہیں کرتے اور ہم اسی کے حضور گردن جھکائے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (378, 3, 85, N'اور جو اسلام کے سوا کوئی دین چاہے گا وہ ہرگز اس سے قبول نہ کیا جائے گا اور وہ آخرت میں زیاں کاروں سے ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (379, 3, 86, N'کیونکر اللہ ایسی قوم کی ہدایت چاہے جو ایمان لاکر کافر ہوگئے اور گواہی دے چکے تھے کہ رسول سچا ہے اور انہیں کھلی نشانیاں آچکی تھیں اور اللہ ظالموں کو ہدایت نہیں کرتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (380, 3, 87, N'ان کا بدلہ یہ ہے کہ ان پر لعنت ہے اللہ اور فرشتوں اور آدمیوں کی سب کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (381, 3, 88, N'ہمیشہ اس میں رہیں، نہ ان پر سے عذاب ہلکا ہو اور نہ انہیں مہلت دی جائے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (382, 3, 89, N'مگر جنہوں نے اس کے بعد توبہ کی اور آپا سنبھالا تو ضرور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (383, 3, 90, N'بیشک وہ جو ایمان لاکر کافر ہوئے پھر اور کفر میں بڑھے ان کی توبہ ہرگز قبول نہ ہوگی اور وہی ہیں بہکے ہوئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (384, 3, 91, N'وہ جو کافر ہوئے اور کافر ہی مرے ان میں کسی سے زمین بھر سونا ہرگز قبول نہ کیا جائے گا اگرچہ اپنی خلاصی کو دے، ان کے لئے دردناک عذاب ہے اور ان کا کوئی یار نہیں۔')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (385, 3, 92, N'تم ہرگز بھلائی کو نہ پہنچو گے جب تک راہِ خدا میں اپنی پیاری چیز نہ خرچ کرو اور تم جو کچھ خرچ کرو اللہ کو معلوم ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (386, 3, 93, N'سب کھانے بنی اسرائیل کو حلال تھے مگر وہ جو یعقوبؑ نے اپنے اوپر حرام کرلیا تھا توریت اترنے سے پہلے تم فرماؤ توریت لاکر پڑھو اگر سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (387, 3, 94, N'تو اس کے بعد جو اللہ پر جھوٹ باندھے تو وہی ظالم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (388, 3, 95, N'تم فرماؤ اللہ سچا ہے، تو ابراہیم کے دین پر چلو جو ہر باطل سے جدا تھے اور شرک والوں میں نہ تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (389, 3, 96, N'بیشک سب میں پہلا گھر جو لوگوں کی عبادت کو مقرر ہوا وہ ہے جو مکہ میں ہے برکت والا اور سارے جہان کا راہنما')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (390, 3, 97, N'اس میں کھلی نشانیاں ہیں ابراہیم کے کھڑے ہونے کی جگہ اور جو اس میں آئے امان میں ہو اور اللہ کے لئے لوگوں پر اس گھر کا حج کرنا ہے جو اس تک چل سکے اور جو منکر ہو تو اللہ سارے جہان سے بے پرواہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (391, 3, 98, N'تم فرماؤ اے کتابیو! اللہ کی آیتیں کیوں نہیں مانتے اور تمہارے کام اللہ سامنے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (392, 3, 99, N'تم فرماؤ اے کتابیو! کیوں اللہ کی راہ سے روکتے ہو اسے جو ایمان لائے اسے ٹیڑھا کیا چاہتے ہو اور تم خود اس پر گواہ ہو اور اللہ تمہارے کوتکوں (برے اعمال، کرتوت) سے بے خبر نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (393, 3, 100, N'اے ایمان والو! اگر تم کچھ کتابیوں کے کہے پر چلے تو وہ تمہارے ایمان کے بعد کافر کر چھوڑیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (394, 3, 101, N'اور تم کیوں کر کفر کروگے تم پر اللہ کی آیتیں پڑھی جاتی ہیں اور تم میں اس کا رسول تشریف لایا اور جس نے اللہ کا سہارا لیا تو ضرور وہ سیدھی راہ دکھایا گیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (395, 3, 102, N'اے ایمان والو! اللہ سے ڈرو جیسا اس سے ڈرنے کا حق ہے اور ہرگز نہ مرنا مگر مسلمان،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (396, 3, 103, N'اور اللہ کی رسی مضبوط تھام لو سب مل کر اور آپس میں پھٹ نہ جانا (فرقوں میں نہ بٹ جانا) اور اللہ کا احسان اپنے اوپر یاد کرو جب تم میں بیر تھا اس نے تمہارے دلوں میں ملاپ کردیا تو اس کے فضل سے تم آپس میں بھائی ہوگئے اور تم ایک غار دوزخ کے کنارے پر تھے تو اس نے تمہیں اس سے بچادیا اللہ تم سے یوں ہی اپنی آیتیں بیان فرماتا ہے کہ کہیں تم ہدایت پاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (397, 3, 104, N'اور تم میں ایک گروہ ایسا ہونا چاہئے کہ بھلائی کی طرف بلائیں اور اچھی بات کا حکم دیں اور بری سے منع کریں اور یہی لوگ مراد کو پہنچے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (398, 3, 105, N'اور ان جیسے نہ ہونا جو آپس میں پھٹ گئے اور ان میں پھوٹ پڑگئی بعد اس کے کہ روشن نشانیاں انہیں آچکی تھیں اور ان کے لیے بڑا عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (399, 3, 106, N'جس دن کچھ منہ اونجالے ہوں گے اور کچھ منہ کالے تو وہ جن کے منہ کالے ہوئے کیا تم ایمان لاکر کافر ہوئے تو اب عذاب چکھو اپنے کفر کا بدلہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (400, 3, 107, N'اور وہ جن کے منہ اونجالے ہوئے وہ اللہ کی رحمت میں ہیں وہ ہمیشہ اس میں رہیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (401, 3, 108, N'یہ اللہ کی آیتیں ہیں کہ ہم ٹھیک ٹھیک تم پر پڑھتے ہیں، اور اللہ جہاں والوں پر ظلم نہیں چاہتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (402, 3, 109, N'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور اللہ ہی کی طرف سب کاموں کی رجوع ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (403, 3, 110, N'تم بہتر ہو ان امتوں میں جو لوگوں میں ظاہر ہوئیں بھلائی کا حکم دیتے ہو اور برائی سے منع کرتے ہو اور اللہ پر ایمان رکھتے ہو، اور اگر کتابی ایمان لاتے تو ان کا بھلا تھا، ان میں کچھ مسلمان ہیں اور زیادہ کافر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (404, 3, 111, N'وہ تمہارے کچھ نہ بگاڑیں گے مگر یہی ستانا اور اگر تم سے لڑیں تو تمہارے سامنے سے پیٹھ پھیر جائیں گے پھر ان کی مدد نہ ہوگی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (405, 3, 112, N'ان پر جمادی گئی خواری جہاں ہوں امان نہ پائیں مگر اللہ کی ڈور اور آدمیوں کی ڈور سے اور غضب الٰہی کے سزاوار ہوئے اور ان پر جمادی گئی محتاجی یہ اس لئے کہ وہ اللہ کی آیتوں سے کفر کرتے اور پیغمبروں کو ناحق شہید کرتے، یہ اس لئے کہ نا فرمانبردار اور سرکش تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (406, 3, 113, N'سب ایک سے نہیں کتابیوں میں کچھ وہ ہیں کہ حق پر قائم ہیں اللہ کی آیتیں پڑھتے ہیں رات کی گھڑیوں میں اور سجدہ کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (407, 3, 114, N'اللہ اور پچھلے دن پر ایمان لاتے ہیں اور بھلائی کا حکم دیتے اور برائی سے منع کرتے ہیں اور نیک کاموں پر دوڑتے ہیں، اور یہ لوگ لائق ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (408, 3, 115, N'اور وہ جو بھلائی کریں ان کا حق نہ مارا جائے گا اور اللہ کو معلوم ہیں ڈر والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (409, 3, 116, N'وہ جو کافر ہوئے ان کے مال اور اولاد ان کو اللہ سے کچھ نہ بچالیں گے اور وہ جہنمی ہیں ان کو ہمیشہ اس میں رہنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (410, 3, 117, N'کہاوت اس کی جو اس دنیا میں زندگی میں خرچ کرتے ہیں اس ہوا کی سی ہے جس میں پالا ہو وہ ایک ایسی قوم کی کھیتی پر پڑی جو اپنا ہی برا کرتے تھے تو اسے بالکل مارگئی اور اللہ نے ان پر ظلم نہ کیا ہاں وہ خود اپنی جانوں پر ظلم کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (411, 3, 118, N'اے ایمان والو! غیروں کو اپنا راز دار نہ بناؤ وہ تمہاری برائی میں کمی نہیں کرتے ان کی آرزو ہے، جتنی ایذا پہنچے بیَر ان کی باتوں سے جھلک اٹھا اور وہ جو سینے میں چھپائے ہیں اور بڑا ہے، ہم نے نشانیاں تمہیں کھول کر سنادیں اگر تمہیں عقل ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (412, 3, 119, N'سنتے ہو یہ جو تم ہو تم تو انہیں چاہتے ہو اور وہ تمہیں نہیں چاہتے اور حال یہ کہ تم سب کتابوں پر ایمان لاتے ہو اور وہ جب تم سے ملتے ہیں کہتے ہیں ہم ایمان لائے اور اکیلے ہوں تو تم پر انگلیاں چبائیں غصہ سے تم فرمادو کہ مرجاؤ اپنی گھٹن (قلبی جلن) میں اللہ خوب جانتا ہے دلوں کی بات،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (413, 3, 120, N'تمہیں کوئی بھلائی پہنچے تو انہیں برا لگے اور تم کہ برائی پہنچے تو اس پر خوش ہوں، اور اگر تم صبر اور پرہیزگاری کیے رہو تو ان کا داؤ تمہارا کچھ نہ بگاڑے گا، بیشک ان کے سب کام خدا کے گھیرے میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (414, 3, 121, N'اور یاد کرو اے محبوب! جب تم صبح کو اپنے دولت خانہ سے برآمد ہوئے مسلمانوں کو لڑائی کے مور چوں پر قائم کرتے اور اللہ سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (415, 3, 122, N'جب تم میں کے دو گروہوں کا ارادہ ہوا کہ نامردی کرجائیں اور اللہ ان کا سنبھالنے والا ہے اور مسلمانوں کو اللہ ہی پر بھروسہ چاہئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (416, 3, 123, N'اور بیشک اللہ نے بدر میں تمہاری مدد کی جب تم بالکل بے سر و سامان تھے تو اللہ سے ڈرو کہیں تم شکر گزار ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (417, 3, 124, N'جب اے محبوب تم مسلمانوں سے فرماتے تھے کیا تمہیں یہ کافی نہیں کہ تمہارا رب تمہاری مدد کرے تین ہزار فرشتہ اتار کر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (418, 3, 125, N'ہا ں کیوں نہیں اگر تم صبرو تقویٰ کرو اور کافر اسی دم تم پر آپڑیں تو تمہارا رب تمہاری مدد کو پانچ ہزار فرشتے نشان والے بھیجے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (419, 3, 126, N'اور یہ فتح اللہ نے نہ کی مگر تمہاری خوشی کے لئے اور اسی لئے کہ اس سے تمہارے دلوں کو چین ملے اور مدد نہیں مگر اللہ غالب حکمت والے کے پاس سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (420, 3, 127, N'اس لئے کہ کافروں کا ایک حصہ کاٹ دے یا انہیں ذلیل کرے کہ نامراد پھر جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (421, 3, 128, N'یہ بات تمہارے ہاتھ نہیں یا انہیں توبہ کی توفیق دے یا ان پر عذاب کرے کہ وہ ظالم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (422, 3, 129, N'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے جسے چاہے بخشے اور جسے چاہے عذاب کرے، اور اللہ بخشنے والا مہربان،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (423, 3, 130, N'اے ایمان والوں سود دونا دون نہ کھاؤ اللہ سے ڈرو اس امید پر کہ تمہیں فلاح ملے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (424, 3, 131, N'اور اس آگ سے بچو جو کافروں کے لئے تیار رکھی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (425, 3, 132, N'اور اللہ و رسول کے فرمانبردار رہو اس امید پر کہ تم رحم کیے جاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (426, 3, 133, N'اور دوڑو اپنے رب کی بخشش اور ایسی جنت کی طرف جس کی چوڑان میں سب آسمان و زمین پرہیزگاروں کے لئے تیار کر رکھی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (427, 3, 134, N'وہ جو اللہ کے راہ میں خرچ کرتے ہیں خوشی میں اور رنج میں اور غصہ پینے والے اور لوگوں سے درگزر کرنے والے، اور نیک لوگ اللہ کے محبوب ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (428, 3, 135, N'اور وہ کہ جب کوئی بے حیائی یا اپنی جانوں پر ظلم کریں اللہ کو یاد کرکے اپنے گناہوں کی معافی چاہیں اور گناہ کون بخشے سوا اللہ کے، اور اپنے کیے پر جان بوجھ کر اڑ نہ جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (429, 3, 136, N'ایسوں کو بدلہ ان کے رب کی بخشش اور جنتیں ہیں جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں اور کامیوں (نیک لوگوں) کا اچھا نیگ (انعام، حصہ) ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (430, 3, 137, N'تم سے پہلے کچھ طریقے برتاؤ میں آچکے ہیں تو زمین میں چل کر دیکھو کیسا انجام ہوا جھٹلانے والوں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (431, 3, 138, N'یہ لوگوں کو بتانا اور راہ دکھانا اور پرہیزگاروں کو نصیحت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (432, 3, 139, N'اور نہ سستی کرو اور نہ غم کھاؤ تم ہی غالب آؤ گے اگر ایمان رکھتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (433, 3, 140, N'اگر تمہیں کوئی تکلیف پہنچی تو وہ لوگ بھی ویسی ہی تکلیف پاچکے ہیں اور یہ دن ہیں جن میں ہم نے لوگوں کے لیے باریاں رکھی ہیں اور اس لئے کہ اللہ پہچان کرادے ایمان والوں کی اور تم میں سے کچھ لوگوں کو شہادت کا مرتبہ دے اور اللہ دوست نہیں رکھتا ظالموں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (434, 3, 141, N'اور اس لئے کہ اللہ مسلمانوں کا نکھار کردے اور کافروں کو مٹادے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (435, 3, 142, N'کیا اس گمان میں ہو کہ جنت میں چلے جاؤ گے اور ابھی اللہ نے تمہارے غازیوں کا امتحان نہ لیا اور نہ صبر والوں آزمائش کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (436, 3, 143, N'اور تم تو موت کی تمنا کیا کرتے تھے اس کے ملنے سے پہلے تو اب وہ تمہیں نظر آئی آنکھوں کے سامنے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (437, 3, 144, N'اور محمد تو ایک رسول ان سے پہلے اور رسول ہوچکے تو کیا اگر وہ انتقال فرمائیں یا شہید ہوں تو تم الٹے پاؤں پھر جاؤں گے اور جو الٹے پاؤں پھرے گا اللہ کا کچھ نقصان نہ کرے گا، اور عنقریب اللہ شکر والوں کو صلہ دے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (438, 3, 145, N'اور کوئی جان بے حکم خدا مر نہیں سکتی سب کا وقت لکھا رکھا ہے اور دنیا کا انعام چاہے ۰ف۲۶۱) ہم اس میں سے اسے دیں اور جو آخرت کا انعام چاہے ہم اس میں سے اسے دیں اور قریب ہے کہ ہم شکر والوں کو صلہ عطا کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (439, 3, 146, N'اور کتنے ہی انبیاء نے جہاد کیا ان کے ساتھ بہت خدا والے تھے، تو نہ سست پڑے ان مصیبتوں سے جو اللہ کی راہ میں انہیں پہنچیں اور نہ کمزور ہوئے اور نہ دبے اور صبر والے اللہ کو محبوب ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (440, 3, 147, N'اور وہ کچھ بھی نہ کہتے تھے سوا اس دعا کے کہ اے ہمارے رب بخش دے ہمارے گناہ اور جو زیادتیاں ہم نے اپنے کام کیں اور ہمارے قدم جما دے اور ہمیں ان کافر لوگوں پر مدد دے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (441, 3, 148, N'تو اللہ نے انہیں دنیا کا انعام دیا اور آخرت کے ثواب کی خوبی اور نیکی والے اللہ کو پیارے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (442, 3, 149, N'اے ایمان والو! اگر تم کافروں کے کہے پر چلے تو وہ تمہیں الٹے پاؤں لوٹادیں گے پھر ٹوٹا کھا کے پلٹ جاؤ گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (443, 3, 150, N'بلکہ اللہ تمہارا مولا ہے اور وہ سب سے بہتر مددگار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (444, 3, 151, N'کوئی دم جاتا ہے کہ ہم کافروں کے دلوں میں رعب ڈالیں گے کہ انہوں نے اللہ کا شریک ٹھہرایا جس پر اس نے کوئی سمجھ نہ اتاری اور ان کا ٹھکانا دوزخ ہے، اور کیا برا ٹھکانا ناانصافوں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (445, 3, 152, N'اور بیشک اللہ نے تمہیں سچ کر دکھایا اپنا وعدہ جب کہ تم اس کے حکم سے کافروں کو قتل کرتے تھے یہاں تک کہ جب تم نے بزدلی کی اور حکم میں جھگڑا ڈالا اور نافرمانی کی بعد اس کے کہ اللہ تمہیں دکھا چکا تمہاری خوشی کی بات تم میں کوئی دنیا چاہتا تھا اور تم میں کوئی آخرت چاہتا تھا پھر تمہارا منہ ان سے پھیردیا کہ تمہیں آزمائے اور بیشک اس نے تمہیں معاف کردیا، اور اللہ مسلمانوں پر فضل کرتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (446, 3, 153, N'جب تم منہ اٹھائے چلے جاتے تھے اور پیٹھ پھیر کر کسی کو نہ دیکھتے اور دوسری جماعت میں ہمارے رسول تمہیں پکار رہے تھے تو تمہیں غم کا بدلہ غم دیا اور معافی اس لئے سنائی کہ جو ہاتھ سے گیا اور جو افتاد پڑی اس کا رنج نہ کرو اور اللہ کوتمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (447, 3, 154, N'پھر تم پر غم کے بعد چین کی نیند اتاری کہ تمہاری ایک جماعت کو گھیرے تھی اور ایک گروہ کو اپنی جان کی پڑی تھی اللہ پر بے جا گمان کرتے تھے جاہلیت کے سے گمان، کہتے کیا اس کام میں کچھ ہمارا بھی اختیار ہے تم فرمادو کہ اختیار تو سارا اللہ کا ہے اپنے دلوں میں چھپاتے ہیں جو تم پر ظاہر نہیں کرتے کہتے ہیں، ہمارا کچھ بس ہوتا تو ہم یہاں نہ مارے جاتے، تم فرمادو کہ اگر تم اپنے گھروں میں ہوتے جب بھی جن کا مارا جانا لکھا جاچکا تھا اپنی قتل گاہوں تک نکل آتے اور اس لئے کہ اللہ تمہارے سینوں کی بات آزمائے اور جو کچھ تمہارے دلو ں میں ہے اسے کھول دے اور اللہ دلوں کی بات جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (448, 3, 155, N'بیشک وہ جو تم میں سے پھرگئے جس دن دونوں فوجیں ملی تھیں انہیں شیطان ہی نے لغزش دی ان کے بعض اعمال کے باعث اور بیشک اللہ نے انہیں معاف فرمادیا، بیشک اللہ بخشنے والا حلم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (449, 3, 156, N'اے ایمان والو! ان کافروں کی طرح نہ ہونا جنہوں نے اپنے بھائیوں کی نسبت کہا کہ جب وہ سفر یا جہاد کو گئے کہ ہمارے پاس ہوتے تو نہ مرتے اور نہ مارے جاتے اس لئے اللہ ان کے دلوں میں اس کا افسوس رکھے، اور اللہ جِلاتا اور مارتا ہے اور اللہ تمہارے کام دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (450, 3, 157, N'اور بیشک اگر تم اللہ کی راہ میں مارے جاؤ یا مرجاؤ تو اللہ کی بخشش اور رحمت ان کے سارے دھن دولت سے بہتر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (451, 3, 158, N'اور اگر تم مرو یا مارے جاؤ تو اللہ کی طرف اٹھنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (452, 3, 159, N'تو کیسی کچھ اللہ کی مہربانی ہے کہ اے محبوب! تم ان کے لئے نرم دل ہوئے اور اگر تند مزاج سخت دل ہوتے تو وہ ضرور تمہارے گرد سے پریشان ہوجاتے تو تم انہیں معاف فرماؤ او ر ان کی شفاعت کرو اور کاموں میں ان سے مشورہ لو اور جو کسی بات کا ارادہ پکا کرلو تو اللہ پر بھروسہ کرو بیشک توکل والے اللہ کو پیارے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (453, 3, 160, N'اگر اللہ تمہاری مدد کرے تو کوئی تم پر غالب نہیں آسکتا اور اگر وہ تمہیں چھوڑ دے تو ایسا کون ہے جو پھر تمہاری مدد کرے اور مسلمانوں کو اللہ ہی پر بھروسہ چاہئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (454, 3, 161, N'اور کسی نبی پر یہ گمان نہیں ہوسکتا کہ وہ کچھ چھپا رکھے اور جو چھپا رکھے وہ قیامت کے دن اپنی چھپائی چیز لے کر آئے گا پھر ہر جان کو ان کی کمائی بھرپور دی جائے گی اور ان پر ظلم نہ ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (455, 3, 162, N'تو کیا جو اللہ کی مرضی پر چلا وہ اس جیسا ہوگا جس نے اللہ کا غضب اوڑھا اور اس کا ٹھکانا جہنم ہے، اور کیا بری جگہ پلٹنے کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (456, 3, 163, N'وہ اللہ کے یہاں درجہ درجہ ہیں اور اللہ ان کے کام دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (457, 3, 164, N'بیشک اللہ کا بڑا احسان ہوا مسلمانوں پر کہ ان میں انہیں میں سے ایک رسول بھیجا جو ان پر اس کی آیتیں پڑھتا ہے اور انہیں پاک کرتا ہے اور انہیں کتاب و حکمت سکھاتا ہے اور وہ ضرور اس سے پہلے کھلی گمراہی میں تھے')
