INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (458, 3, 165, N'کیا جب تمہیں کوئی مصیبت پہنچے کہ اس سے دونی تم پہنچا چکے ہو تو کہنے لگو کہ یہ کہاں سے آئی تم فرمادو کہ وہ تمہاری ہی طرف سے آئی بیشک اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (459, 3, 166, N'اور وہ مصیبت جو تم پر آئی جس دن دونوں فوجیں ملی تھیں وہ اللہ کے حکم سے تھی اور اس لئے کہ پہچان کرادے ایمان والوں کی،')
