INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (460, 3, 167, N'اور اس لئے کہ پہچان کرادے، ان کی جو منافق ہوئے اور ان سے کہا گیا کہ ا ٓؤ اللہ کی راہ میں لڑو یا دشمن کو ہٹاؤ بولے اگر ہم لڑائی ہوتی جانتے تو ضرو ر تمہارا ساتھ دیتے، اور اس دن ظاہری ایمان کی بہ نسبت کھلے کفر سے زیادہ قریب ہیں، اپنے منہ سے کہتے ہیں جو ان کے دل میں نہیں اور اللہ کو معلوم ہے جو چھپارہے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (461, 3, 168, N'وہ جنہوں نے اپنے بھائیوں کے بارے میں کہا اور آپ بیٹھ رہے کہ وہ ہمارا کہا مانتے تو نہ مارے جاتے تم فرمادو تو اپنی ہی موت ٹال دو اگر سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (462, 3, 169, N'اور جو اللہ کی راہ میں مارے گئے ہر گز انہیں مردہ نہ خیال کرنا، بلکہ وہ اپنے رب کے پاس زندہ ہیں روزی پاتے ہیں')
