INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (463, 3, 170, N'شاد ہیں اس پر جو اللہ نے انہیں اپنے فضل سے دیا اور خوشیاں منارہے ہیں اپنے پچھلوں کی جو ابھی ان سے نہ ملے کہ ان پر نہ کچھ اندیشہ ہے اور نہ کچھ غم،')
