INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (464, 3, 171, N'خوشیاں مناتے ہیں اللہ کی نعمت اور فضل کی اور یہ کہ اللہ ضائع نہیں کرتا اجر مسلمانوں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (465, 3, 172, N'وہ جو اللہ و رسول کے بلانے پر حاضر ہوئے بعد اس کے کہ انہیں زخم پہنچ چکا تھا ان کے نکوکاروں اور پرہیزگاروں کے لئے بڑا ثواب ہے،')
