INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (466, 3, 173, N'وہ جن سے لوگوں نے کہا کہ لوگوں نے تمہارے لئے جتھا جوڑا تو ان س ے ڈرو تو ان کا ایمان اور زائد ہوا اور بولے اللہ ہم کو بس ہے اور کیا اچھا کارساز')
