INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (467, 3, 174, N'تو پلٹے اللہ کے احسان اور فضل سے کہ انہیں کوئی برائی نہ پہنچی اور اللہ کی خوشی پر چلے اور اللہ بڑے فضل والا ہے')
