INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (468, 3, 175, N'وہ تو شیطان ہی ہے کہ اپنے دوستوں سے دھمکاتا ہے تو ان سے نہ ڈرو اور مجھ سے ڈرو اگر ایمان رکھتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (469, 3, 176, N'اور اے محبوب! تم ان کا کچھ غم نہ کرو جو کفر پر دوڑتے ہیں وہ اللہ کا کچھ بگاڑیں گے اور اللہ چاہتا ہے کہ آخرت میں ان کا کوئی حصہ نہ رکھے اور ان کے لئے بڑا عذاب ہے،')
