INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (470, 3, 177, N'وہ جنہوں نے ایمان کے بدلے کفر مول لیا اللہ کا کچھ نہ بگاڑیں گے اور ان کے لئے دردناک عذاب ہے،')
