INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (471, 3, 178, N'اور ہرگز کافر اس گمان میں نہ رہیں کہ وہ جو ہم انہیں ڈھیل دیتے ہیں کچھ ان کے لئے بھلا ہے، ہم تو اسی لئے انہیں ڈھیل دیتے ہیں کہ اور گناہ میں بڑھیں اور ان کے لئے ذلت کا عذاب ہے،')
