INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (472, 3, 179, N'اللہ مسلمانوں کو اس حال پر چھوڑنے کا نہیں جس پر تم ہو جب تک جدا نہ کردے گندے کو ستھرے سے اور اللہ کی شان یہ نہیں کہ اے عام لوگو! تمہیں غیب کا علم دے دے ہاں اللہ چن لیتا ہے اپنے رسولوں سے جسے چاہے تو ایمان لاؤ اللہ اور اس کے رسولوں پر اور اگر ایمان لاؤ اور پرہیزگاری کرو تو تمہارے لئے بڑا ثواب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (473, 3, 180, N'اور جو بخل کرتے ہیں اس چیز میں جو اللہ نے انہیں اپنے فضل سے دی ہرگز اسے اپنے لئے اچھا نہ سمجھیں بلکہ وہ ان کے لئے برا ہے، عنقریب وہ جس میں بخل کیا تھا قیامت کے دن ان کے گلے کا طوق ہوگا اور اللہ ہی وارث ہے آسمانوں اور زمین کا اور اللہ تمہارے کاموں سے خبردار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (474, 3, 181, N'بیشک اللہ نے سنا جنہوں نے کہا کہ اللہ محتاج ہے اور ہم غنی اور ہم غنی اب ہم لکھ رکھیں گے ان کا کہا اور انبیاء کو ان کا ناحق شہید کرنا اور فرمائیں گے کہ چکھو آگ کا عذاب،')
