INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (475, 3, 182, N'یہ بدلا ہے اس کا جو تمہارے ہاتھوں نے آگے بھیجا اور اللہ بندوں پر ظلم نہیں کرتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (476, 3, 183, N'وہ جو کہتے ہیں اللہ نے ہم سے اقرار کر لیا ہے کہ ہم کسی رسول پر ایمان نہ لائیں جب تک ایسی قربانی کا حکم نہ لائے جس آ گ کھائے تم فرمادو مجھ سے پہلے بہت رسول تمہارے پاس کھلی نشانیاں اور یہ حکم لے کر آئے جو تم کہتے ہو پھر تم نے انہیں کیوں شہید کیا اگر سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (477, 3, 184, N'تو اے محبوب! اگر وہ تمہاری تکذیب کرتے ہیں تو تم سے اگلے رسولوں کی بھی تکذیب کی گئی ہے جو صاف نشانیاں اور صحیفے اور چمکتی کتاب لے کر آئے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (478, 3, 185, N'ہر جان کو موت چکھنی ہے، اور تمہارے بدلے تو قیامت ہی کو پورے ملیں گے، جو آگ سے بچا کر جنت میں داخل کیا گیا وہ مراد کو پہنچا، اور دنیا کی زندگی تو یہی دھوکے کا مال ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (479, 3, 186, N'بیشک ضرور تمہاری آزمائش ہوگی تمہارے مال اور تمہاری جانوں میں اور بیشک ضرور تم اگلے کتاب والوں اور مشرکوں سے بہت کچھ برا سنو گے اور اگر تم صبر کرو اور بچتے رہو تو یہ بڑی ہمت کا کام ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (480, 3, 187, N'اور یاد کرو جب اللہ نے عہد لیا ان سے جنہیں کتاب عطا فرمائی کہ تم ضرور اسے لوگوں سے بیان کردینا اور نہ چھپانا تو انہوں نے اسے اپنی پیٹھ کے پیچھے پھینک دیا اور اس کے بدلے ذلیل دام حاصل کیے تو کتنی بری خریداری ہے')
