INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (481, 3, 188, N'ہر گز نہ سمجھنا انہیں جو خوش ہوتے ہیں اپنے کیے پر اور چاہتے ہیں کہ بے کیے ان کی تعریف ہو ایسوں کو ہرگز عذاب سے دور نہ جاننا اور ان کے لیے دردناک عذاب ہے')
