INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (482, 3, 189, N'اور اللہ ہی کے لئے ہے آسمانوں اور زمین کی بادشاہی اور اللہ ہر چیز پر قادر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (483, 3, 190, N'بیشک آسمانوں اور زمین کی پیدائش اور رات اور دن کی باہم بدلیوں میں نشانیاں ہیں عقلمندوں کے لئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (484, 3, 191, N'جو اللہ کی یاد کرت ہیں کھڑے اور بیٹھے اور کروٹ پر لیٹے اور آسمانوں اور زمین کی پیدائش میں غور کرتے ہیں اے رب ہمارے! تو نے یہ بیکار نہ بنایا پاکی ہے تجھے تو ہمیں دوزخ کے عذاب سے بچالے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (485, 3, 192, N'اے رب ہمارے! بیشک جسے تو دوزخ میں لے جائے اسے ضرور تو نے رسوائی دی اور ظالموں کا کوئی مددگار نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (486, 3, 193, N'اے رب ہمارے ہم نے ایک منادی کو سنا کہ ایمان کے لئے ندا فرماتا ہے کہ اپنے رب پر ایمان لاؤ تو ہم ایمان لائے اے رب ہمارے تو ہمارے گنا بخش دے اور ہماری برائیاں محو فرمادے اور ہماری موت اچھوں کے ساتھ کر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (487, 3, 194, N'اے رب ہمارے! اور ہمیں دے وہ جس کا تو نے ہم سے وعدہ کیا ہے اپنے رسولوں کی معرفت اور ہمیں قیامت کے دن رسوانہ کر، بیشک تو وعدہ خلاف نہیں کرتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (488, 3, 195, N'تو ان کی دعا سن لی ان کے رب نے کہ میں تم میں کام والے کی محنت اکارت نہیں کرتا مرد ہو یا عورت تم آپس میں ایک ہو تو وہ جنہوں نے ہجرت کی اور اپنے گھروں سے نکالے گئے اور میری راہ میں ستائے گئے اور لڑے اور مارے گء ے میں ضرور ان کے سب گناہ اتار دوں گا اور ضرور انہیں باغوں میں لے جاؤں گا جن کے نیچے نہریں رواں اللہ کے پاس کا ثواب، اور اللہ ہی کے پاس اچھا ثواب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (489, 3, 196, N'اے سننے والے! کافروں کا شہروں میں اہلے گہلے پھرنا ہرگز تجھے دھوکا نہ دے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (490, 3, 197, N'تھوڑا برتنا، ان کا ٹھکانا دوزخ ہے، اور کیا ہی برا بچھونا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (491, 3, 198, N'لیکن وہ جو اپنے رب سے ڈرتے ہیں ان کے لئے جنتیں ہیں جن کے نیچے نہریں بہیں ہمیشہ ان میں رہیں اللہ کی طرف کی، مہمانی اور جو اللہ پاس ہے وہ نیکوں کے لئے سب سے بھلا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (492, 3, 199, N'اور بیشک کچھ کتابیں ایسے ہیں کہ اللہ پر ایمان لاتے ہیں اور اس پر جو تمہاری طرف اترا اور جو ان کی طرف اترا ان کے دل اللہ کے حضور جھکے ہوئے اللہ کی آیتوں کے بدلے ذلیل دام نہیں لیتے یہ وہ ہیں، جن کا ثواب ان کے رب کے پاس ہے اور اللہ جلد حساب کرنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (493, 3, 200, N'اے ایمان والو! صبر کرو اور صبر میں دشمنوں سے آگے رہو اور سرحد پر اسلامی ملک کی نگہبانی کرو اور اللہ سے ڈرتے رہو اس امید پر کہ کامیاب ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (494, 4, 1, N'اے لوگو! اپنے رب سے ڈرو جس نے تمہیں ایک جان سے پیدا کیا اور اسی میں سے اس کا جوڑا بنایا اور ان دونوں سے بہت سے مرد و عورت پھیلا دیئے اور اللہ سے ڈرو جس کے نام پر مانگتے ہو اور رشتوں کا لحاظ رکھو بیشک اللہ ہر وقت تمہیں دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (495, 4, 2, N'اور یتیموں کو ان کے مال دو اور ستھرے کے بدلے گندا نہ لو اور ان کے مال اپنے مالوں میں ملاکر نہ کھا جاؤ، بیشک یہ بڑا گناہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (496, 4, 3, N'ا ور اگر تمہیں اندیشہ ہو کہ یتیم لڑکیوں میں انصاف نہ کرو گے تو نکاح میں لاؤ جو عورتیں تمہیں خوش آئیں دو دو اور تین تین او ر چار چار پھر اگر ڈرو کہ دو بیبیوں کو برابر نہ رکھ سکو گے تو ایک ہی کرو یا کنیزیں جن کے تم مالک ہو یہ اس سے زیادہ قریب ہے کہ تم سے ظلم نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (497, 4, 4, N'اور عورتوں کو ان کے مہر خوشی سے دو پھر اگر وہ اپنے دل کی خوشی سے مہر میں سے تمہیں کچھ دے دیں تو اسے کھاؤ رچتا پچتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (498, 4, 5, N'اور بے عقلوں کو ان کے مال نہ دو جو تمہارے پاس ہیں جن کو اللہ نے تمہاری بسر اوقات کیا ہے اور انہیں اس میں سے کھلاؤ اور پہناؤ اور ان سے اچھی بات کہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (499, 4, 6, N'اور یتیموں کو آزماتے رہو یہاں تک کہ جب وہ نکاح کے قابل ہوں تو اگر تم ان کی سمجھ ٹھیک دیکھو تو ان کے مال انہیں سپرد کردو اور انہیں نہ کھاؤ حد سے بڑھ کر اور اس جلدی میں کہ کہیں بڑے نہ ہوجائیں اور جسے حاجت نہ ہو وہ بچتا رہے اور جو حاجت مند ہو وہ بقدر مناسب کھائے، پھر جب تم ان کے مال انہیں سپرد کرو تو ان پر گواہ کرلو، اور اللہ کافی ہے حساب لینے کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (500, 4, 7, N'مردوں کے لئے حصہ ہے اس میں سے جو چھوڑ گئے ماں باپ اور قرابت والے اور عورتوں کے لئے حصہ ہے اس میں سے جو چھوڑ گئے ماں باپ اور قرابت والے ترکہ تھوڑا ہو یا بہت، حصہ ہے اندازہ باندھا ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (501, 4, 8, N'پھر بانٹتے وقت اگر رشتہ دار اور یتیم اور مسکین آجائیں تو اس میں سے انہیں بھی کچھ دو اور ان سے اچھی بات کہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (502, 4, 9, N'اور ڈریں وہ لوگ اگر اپنے بعد ناتواں اولاد چھوڑتے تو ان کا کیسا انہیں خطرہ ہوتا تو چاہئے کہ اللہ سے ڈریں اور سیدھی بات کریں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (503, 4, 10, N'وہ جو یتیموں کا مال ناحق کھاتے ہیں وہ تو اپنے پیٹ میں نری آ گ بھرتے ہیں اور کوئی دم جاتا ہے کہ بھڑتے دھڑے (آتش کدے) میں جائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (504, 4, 11, N'اللہ تمہیں حکم دیتا ہے تمہاری اولاد کے بارے میں بیٹے کا حصہ دو بیٹیوں برابر ہے پھر اگر نری لڑکیاں ہوں اگرچہ دو سے اوپر تو ان کو ترکہ کی دو تہائی اور اگر ایک لڑکی ہو تو اس کا آدھا اور میت کے ماں باپ کو ہر ایک کو اس کے ترکہ سے چھٹا اگر میت کے اولاد ہو پھر اگر اس کی اولاد نہ ہو اور ماں باپ چھوڑے تو ماں کا تہا ئی پھر اگر اس کے کئی بہن بھا ئی ہو ں تو ماں کا چھٹا بعد اس و صیت کے جو کر گیا اور دین کے تمہارے باپ اور تمہارے بیٹے تم کیا جانو کہ ان میں کون تمہارے زیادہ کام آئے گا یہ حصہ باندھا ہوا ہے اللہ کی طرف سے بیشک اللہ علم والا حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (505, 4, 12, N'اور تمہاری بیبیاں جو چھوڑ جائیں اس میں سے تمہیں آدھا ہے اگر ان کی اولاد نہ ہو، پھر اگر ان کی اولاد ہو تو ان کے ترکہ میں سے تمہیں چوتھائی ہے جو وصیت وہ کر گئیں اور دَین نکال کر اور تمہارے ترکہ میں عورتوں کا چوتھائی ہے اگر تمہارے اولاد نہ ہو پھر اگر تمہارے اولاد ہو تو ان کا تمہارے ترکہ میں سے آٹھواں جو وصیت تم کر جاؤ اور دین نکال کر، اور اگر کسی ایسے مرد یا عورت کا ترکہ بٹنا ہو جس نے ماں باپ اولاد کچھ نہ چھوڑے اور ماں کی طرف سے اس کا بھائی یا بہن ہے تو ان میں سے ہر ایک کو چھٹا پھر اگر وہ بہن بھائی ایک سے زیادہ ہوں تو سب تہائی میں شریک ہیں میت کی وصیت اور دین نکال کر جس میں اس نے نقصان نہ پہنچایا ہو یہ اللہ کا ارشاد ہے اور اللہ علم والا حلم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (506, 4, 13, N'یہ اللہ کی حدیں ہیں اور جو حکم مانے اللہ اور اللہ کے رسول کا اللہ اسے باغوں میں لے جائے گا جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے، اور یہی ہے بڑی کامیابی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (507, 4, 14, N'اور جو اللہ اور اس کے رسول کی نافرمانی کرے اور اس کی کل حدوں سے بڑھ جائے اللہ اسے آگ میں داخل کرے گا جس میں ہمیشہ رہے گا اور اس کے لئے خواری کا عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (508, 4, 15, N'اور تمہاری عورتوں میں جو بدکاری کریں ان پر خاص اپنے میں کے چار مردوں کی گواہی لو پھر اگر وہ گواہی دے دیں تو ان عورتوں کو گھر میں بند رکھو یہاں تک کہ انہیں موت اٹھالے یا اللہ ان کی کچھ راہ نکالے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (509, 4, 16, N'اور تم میں جو مرد عورت ایسا کریں ان کو ایذا دو پھر اگر وہ توبہ کرلیں اور نیک ہوجائیں تو ان کا پیچھا چھوڑ دو، بیشک اللہ بڑا توبہ قبول کرنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (510, 4, 17, N'وہ توبہ جس کا قبول کرنا اللہ نے اپنے فضل سے لازم کرلیا ہے وہ انہیں کی ہے جو نادانی سے برائی کر بیٹھیں پھر تھوڑی دیر میں توبہ کرلیں ایسوں پر اللہ اپنی رحمت سے رجوع کرتا ہے، اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (511, 4, 18, N'اور وہ توبہ ان کی نہیں جو گناہوں میں لگے رہتے ہیں، یہاں تک کہ جب ان میں کسی کو موت آئے تو کہے اب م یں نے توبہ کی اور نہ ان کی جو کافر مریں ان کے لئے ہم نے دردناک عذاب تیار رکھا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (512, 4, 19, N'اے ایمان والو! تمہیں حلال نہیں کہ عورتوں کے وارث بن جاؤ زبردستی اور عورتوں کو روکو نہیں اس نیت سے کہ جو مہر ان کو دیا تھا اس میں سے کچھ لے لو مگر اس صورت میں کہ صریح بے حیا ئی کا کام کریں اور ان سے اچھا برتاؤ کرو پھر اگر وہ تمہیں پسند نہ آئیں تو قریب ہے کہ کوئی چیز تمہیں ناپسند ہو اور اللہ اس میں بہت بھلائی رکھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (513, 4, 20, N'اور اگر تم ایک بی بی کے بدلے دوسری بدلنا چاہو اور اسے ڈھیروں مال دے چکے ہو تو اس میں سے کچھ واپس نہ لو کیا اسے واپس لو گے جھوٹ باندھ کر اور کھلے گناہ سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (514, 4, 21, N'اور کیونکر اسے واپس لوگے حالانکہ تم میں ایک دوسرے کے سامنے بے پردہ ہولیا اور وہ تم سے گاڑھا عہد لے چکیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (515, 4, 22, N'اور باپ دادا کی منکوحہ سے نکاح نہ کرو مگر جو ہو گزرا وہ بیشک بے حیائی اور غضب کا کام ہے، اور بہت بری راہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (516, 4, 23, N'حرام ہوئیں تم پر تمہاری مائیں اور بیٹیاں اور بہنیں اور پھوپھیاں اور خالائیں اور بھتیجیاں اور بھانجیاں اور تمہاری مائیں جنہوں نے دودھ پلایا اور دودھ کی بہنیں اور عورتوں کی مائیں اور ان کی بیٹیاں جو تمہاری گود میں ہیں ان بیبیوں سے جن سے تم صحبت کرچکے ہو تو پھر اگر تم نے ان سے صحبت نہ کی ہو تو ان کی بیٹیوں سے حرج نہیں اور تمہاری نسلی بیٹوں کی بیبیں اور دو بہنیں اکٹھی کرنا مگر جو ہو گزرا بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (517, 4, 24, N'اور حرام ہیں شوہر دار عورتیں مگر کافروں کی عورتیں جو تمہاری ملک میں آجائیں یہ اللہ کا نوشتہ ہے تم پر اور ان کے سوا جو رہیں وہ تمہیں حلال ہیں کہ اپنے مالوں کے عوض تلاش کرو قید لاتے نہ پانی گراتے تو جن عورتوں کو نکاح میں لانا چاہو ان کے بندھے ہوئے مہر انہیں دو، اور قرار داد کے بعد اگر تمہارے آپس میں کچھ رضامندی ہوجاوے تو اس میں گناہ نہیں بیشک اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (518, 4, 25, N'اور تم میں بے مقدوری کے باعث جن کے نکاح میں آزاد عورتیں ایمان والیاں نہ ہوں تو ان سے نکاح کرے جو تمہارے ہاتھ کی مِلک ہیں ایمان والی کنیزیں اور اللہ تمہارے ایمان کو خوب جانتا ہے، تم میں ایک دوسرے سے ہے تو ان سے نکاح کرو ان کے مالکوں کی اجازت سے اور حسب دستور ان کے مہر انہیں دو قید میں آتیاں نہ مستی نکالتی اور نہ یار بناتی جب وہ قید میں آجائیں پھر برا کام کریں تو ان پر اس سزا کی آدھی ہے جو آزاد عورتوں پر ہے یہ اس کے لئے جسے تم میں سے زنا کا اندیشہ ہے، اور صبر کرنا تمہارے لئے بہتر ہے اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (519, 4, 26, N'اللہ چاہتا ہے کہ اپنے احکام تمہارے لئے بیان کردے اور تمہیں اگلوں کی روشیں بتادے اور تم پر اپنی رحمت سے رجوع فرمائے اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (520, 4, 27, N'اور اللہ تم پر اپنی رحمت سے رجوع فرمانا چاہتا ہے، اور جو اپنے مزوں کے پیچھے پڑے ہیں وہ چاہتے ہیں کہ تم سیدھی راہ سے بہت الگ ہوجاؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (521, 4, 28, N'اللہ چاہتا ہے کہ تم پر تخفیف کرے اور آدمی کمزور بنایا گیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (522, 4, 29, N'اے ایمان والو! آپس میں ایک دوسرے کے مال ناحق نہ کھاؤ مگر یہ کہ کوئی سودا تمہاری باہمی رضامندی کا ہو اور اپنی جانیں قتل نہ کرو بیشک اللہ تم پر مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (523, 4, 30, N'اور جو ظلم و زیادتی سے ایسا کرے گا تو عنقریب ہم اسے آگ میں داخل کریں گے اور یہ اللہ کو آسان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (524, 4, 31, N'اگر بچتے رہو کبیرہ گناہوں سے جن کی تمہیں ممانعت ہے تو تمہارے اور گناہ ہم بخش دیں گے اور تمہیں عزت کی جگہ داخل کریں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (525, 4, 32, N'اور ا س کی آرزو نہ کرو جس سے اللہ نے تم میں ایک کو دوسرے پر بڑائی دی مردوں کے لئے ان کی کمائی سے حصہ ہے، اور عورتوں کے لئے ان کی کمائی سے حصہ اور اللہ سے اس کا فضل مانگو، بیشک اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (526, 4, 33, N'اور ہم نے سب کے لئے مال کے مستحق بنادیے ہیں جو کچھ چھوڑ جائیں ماں باپ اور قرابت والے اور وہ جن سے تمہارا حلف بندھ چکا انہیں ان کا حصہ دو، بیشک ہر چیز اللہ کے سامنے ہے،')
