INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (527, 4, 34, N'مرد افسر ہیں عورتوں پر اس لیے کہ اللہ نے ان میں ایک کو دوسرے پر فضیلت دی اور اس لئے کہ مردوں نے ان پر اپنے مال خرچ کیے تو نیک بخت عورتیں ادب والیاں ہیں خاوند کے پیچھے حفاظت رکھتی ہیں جس طرح اللہ نے حفاظت کا حکم دیا اور جن عورتوں کی نافرمانی کا تمہیں اندیشہ ہو تو انہیں سمجھاؤ اور ان سے الگ سوؤ اور انہیں مارو پھر اگر وہ تمہارے حکم میں آجائیں تو ان پر زیادتی کی کوئی راہ نہ چاہو بیشک اللہ بلند بڑا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (528, 4, 35, N'اور اگر تم کو میاں بی بی کے جھگڑے کا خوف ہو تو ایک پنچ مرد والوں کی طرف سے بھیجو اور ایک پنچ عورت والوں کی طرف سے یہ دونوں اگر صلح کرانا چاہیں گے تو اللہ ان میں میل کردے گا، بیشک اللہ جاننے والا خبردار ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (529, 4, 36, N'اور اللہ کی بندگی کرو اور اس کا شریک کسی کو نہ ٹھہراؤ اور ماں باپ سے بھلائی کرو اور رشتہ داروں اور یتیموں اور محتاجوں اور پاس کے ہمسائے اور دور کے ہمسائے اور کروٹ کے ساتھی اور راہ گیر اور اپنی باندی غلام سے بیشک اللہ کو خوش نہیں آتا کوئی اترانے والے بڑائی مارنے والا')
