INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (530, 4, 37, N'جو آپ بخل کریں اور اوروں سے بخل کے لئے کہیں اور اللہ نے جو انہیں اپنے فضل سے دیا ہے اسے چھپائيں اور کافروں کے لئے ہم نے ذلت کا عذاب تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (531, 4, 38, N'اور وہ جو اپنے مال لوگوں کے دکھاوے کو خرچ کرتے ہیں اور ایمان نہیں لاتے اللہ اور نہ قیامت پر، اور جس کا مصاحب شیطان ہوا، تو کتنا برا مصاحب ہے،')
