INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (532, 4, 39, N'اور ان کا کیا نقصان تھا اگر ایمان لاتے اللہ اور قیامت پر اور اللہ کے دیے میں سے اس کی راہ میں خرچ کرتے اور اللہ ان کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (533, 4, 40, N'اللہ ایک ذرہ بھر ظلم نہیں فرماتا اور اگر کوئی نیکی ہو تو اسے دونی کرتا اور اپنے پاس سے بڑا ثواب دیتا ہے،')
