INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (534, 4, 41, N'تو کیسی ہوگی جب ہم ہر امت سے ایک گواہ لائیں اور اے محبوب! تمہیں ان سب پر گواہ اور نگہبان بناکر لائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (535, 4, 42, N'اس دن تمنا کریں گے وہ جنہوں نے کفر کیا اور رسول کی نافرمانی کی کاش انہیں مٹی میں دبا کر زمین برابر کردی جائے، اور کوئی بات اللہ سے نہ چھپاسکیں گے')
