INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (536, 4, 43, N'اے ایمان والو! نشہ کی حالت میں نماز کے پاس نہ جاؤ جب تک اتنا ہوش نہ ہو کہ جو کہو اسے سمجھو اور نہ ناپاکی کی حالت میں بے نہائے مگر مسافری میں اور اگر تم بیمار ہو یا سفر میں یا تم میں سے کوئی قضائے حاجت سے آیا ہو یا تم نے عورتو ں کو چھوا اور پانی نہ پایا تو پاک مٹی سے تیمم کرو تو اپنے منہ اور ہاتھوں کا مسح کرو بیشک اللہ معاف کرنے والا بخشنے والا ہے،')
