INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (537, 4, 44, N'کیا تم نے انہیں نہ دیکھا جن کو کتاب سے ایک حصہ ملا گمراہی مول لیتے ہیں اور چاہتے ہیں کہ تم بھی راہ سے بہک جاؤ،')
