INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (538, 4, 45, N'اور اللہ خوب جانتا ہے تمہارے دشمنوں کو اور اللہ کافی ہے والی اور اللہ کافی ہے مددگار،')
