INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (539, 4, 46, N'کچھ یہودی کلاموں کو ان کی جگہ سے پھیرتے ہیں اور کہتے ہیں ہم نے سنا اور نہ مانا اور سنیئے آپ سنائے نہ جائیں اور راعنا کہتے ہیں زبانیں پھیر کر اور دین میں طعنہ کے لئے اور اگر وہ کہتے کہ ہم نے سنا اور مانا اور حضور ہماری بات سنیں اور حضور ہم پر نظر فرمائیں تو ان کے لئے بھلائی اور راستی میں زیادہ ہوتا لیکن ان پر تو اللہ نے لعنت کی ان کے کفر کے سبب تو یقین نہیں رکھتے مگر تھوڑا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (540, 4, 47, N'اے کتاب والو! ایمان لاؤ اس پر جو ہم نے اتارا تمہارے ساتھ والی کتاب کی تصدیق فرماتا قبل اس کے کہ ہم بگاڑ دیں کچھ مونہوں کو تو انہیں پھیر دیں ان کی پیٹھ کی طرف یا انہیں لعنت کریں جیسی لعنت کی ہفتہ والوں پر اور خدا کا حکم ہوکر رہے،')
