INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (541, 4, 48, N'بیشک اللہ اسے نہیں بخشتا کہ اس کے ساتھ کفر کیا جائے اور کفر سے نیچے جو کچھ ہے جسے چاہے معاف فرمادیتا ہے اور جس نے خدا کا شریک ٹھہرایا اس نے بڑا گناہ کا طوفان باندھا،')
