INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (542, 4, 49, N'کیا تم نے انہیں نہ دیکھا جو خود اپنی ستھرائی بیان کرتے ہیں بلکہ اللہ جسے چاہے ستھرا کرے اور ان پر ظلم نہ ہوگا دانہ خرما کے ڈورے برابر')
