INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (543, 4, 50, N'دیکھو کیسا اللہ پر جھوٹ باندھا رہے ہیں اور یہ کافی ہے صریح گناہ،')
