INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (544, 4, 51, N'کیا تم نے، وہ نہ دیکھے جنہیں کتاب کا ایک حصہ ملا ایمان لاتے ہیں بت اور شیطان پر اور کافروں کو کہتے ہیں کہ یہ مسلمانوں سے زیادہ راہ پر ہیں،')
