INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (545, 4, 52, N'یہ ہیں جن پر اللہ نے لعنت کی اور جسے خدا لعنت کرے تو ہر گز اسکا کوئی یار نہ پائے گا')
