INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (546, 4, 53, N'کیا ملک میں ان کا کچھ حصہ ہے ایسا ہو تو لوگوں کو تِل بھر نہ دیں،')
