INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (547, 4, 54, N'یا لوگوں سے حسد کرتے ہیں اس پر جو اللہ نے انہیں اپنے فضل سے دیا تو ہم نے تو ابراہیم کی اولاد کو کتاب اور حکمت عطا فرمائی اور انہیں بڑا ملک دیا')
