INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (548, 4, 55, N'تو ان میں کوئی اس پر ایمان لایا اور کسی نے اس سے منہ پھیرا اور دوزخ کافی ہے بھڑکتی آگ')
