INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (549, 4, 56, N'جنہوں نے ہماری آیتوں کا انکار کیا عنقریب ہم ان کو آگ میں داخل کریں گے، جب کبھی ان کی کھالیں پک جائیں گی ہم ان کے سوا اور کھالیں انہیں بدل دیں گے کہ عذاب کا مزہ لیں، بیشک اللہ غالب حکمت والا ہے،')
