INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (550, 4, 57, N'اور جو لوگ ایمان لائے اور اچھے کام کیے عنقریب ہم انہیں باغوں میں لے جائیں گے جن کے نیچے نہریں رواں ان میں ہمیشہ رہیں گے، ان کے لیے وہاں ستھری بیبیاں ہیں اور ہم انہیں وہاں داخل کریں گے جہاں سایہ ہی سایہ ہوگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (551, 4, 58, N'بیشک اللہ تمہیں حکم دیتا ہے کہ امانتیں جن کی ہیں انہیں سپرد کرو اور یہ کہ جب تم لوگوں میں فیصلہ کرو تو انصاف کے ساتھ فیصلہ کرو بیشک اللہ تمہیں کیا ہی خوب نصیحت فرماتا ہے، بیشک اللہ سنتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (552, 4, 59, N'اے ایمان والو! حکم مانو اللہ کا اور حکم مانو رسول کا اور ان کا جو تم میں حکومت والے ہیں پھر اگر تم میں کسی بات کا جھگڑا اٹھے تو اسے اللہ اور رسول کے حضور رجوع کرو اگر اللہ اور قیامت پر ایمان رکھتے ہو یہ بہتر ہے اور اس کا انجام سب سے اچھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (553, 4, 60, N'کیا تم نے انہیں نہ دیکھا جن کا دعویٰ ہے کہ وہ ایمان لائے اس پر جو تمہاری طرف اترا اور اس پر جو تم سے پہلے اترا پھر چاہتے ہیں کہ شیطان کو اپنا پنچ بنائیں اور ان کو تو حکم یہ تھا کہ اسے اصلاً نہ مانیں اور ابلیس یہ چاہتا ہے کہ انہیں دور بہکاوے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (554, 4, 61, N'اور جب ان سے کہا جائے کہ اللہ کی اتاری ہوئی کتاب اور رسول کی طرف آؤ تو تم دیکھو گے کہ منافق تم سے منہ موڑ کر پھر جاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (555, 4, 62, N'کیسی ہوگی جب ان پر کوئی افتاد پڑے بدلہ اسکا جو انکے ہاتھوں نے آگے بھیجا پھر اے محبوب! تمہارے حضور حاضر ہوں، اللہ کی قسم کھاتے کہ ہمارا مقصود تو بھلائی اور میل ہی تھا')
