INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (557, 4, 64, N'اور ہم نے کوئی رسول نہ بھیجا مگر اس لئے کہ اللہ کے حکم سے اس کی اطاعت کی جائے اور اگر جب وہ اپنی جانوں پر ظلم کریں تو اے محبوب! تمہارے حضور حاضر ہوں اور پھر اللہ سے معافی چاہیں اور رسول ان کی شفاعت فرمائے تو ضرور اللہ کو بہت توبہ قبول کرنے والا مہربان پائیں')
