INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (565, 4, 72, N'اور تم میں کوئی وہ ہے کہ ضرور دیر لگائے گا پھر اگر تم پر کوئی افتاد پڑے تو کہے خدا کا مجھ پر احسان تھا کہ میں ان کے ساتھ حاضر نہ تھا،')
