INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (567, 4, 74, N'تو انہیں اللہ کی راہ میں لڑنا چاہئے جو دنیا کی زندگی بیچ کر آخرت لیتے ہیں اور جو اللہ کی راہ میں لڑے پھر مارا جائے یا غالب آئے تو عنقریب ہم اسے بڑا ثواب دیں گے،')
