INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (569, 4, 76, N'ایمان والے اللہ کی راہ میں لڑتے ہیں اور کفار شیطان کی راہ میں لڑتے ہیں تو شیطان کے دوستوں سے لڑو بیشک شیطان کا داؤ کمزور ہے')
