INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (570, 4, 77, N'کیا تم نے انہیں نہ دیکھا جن سے کہا گیا اپنے ہاتھ روک لو اور نماز قائم رکھو اور زکوٰة دو پھر جب ان پر جہاد فرض کیا گیا تو ان میں بعضے لوگوں سے ایسا ڈرنے لگے جیسے اللہ سے ڈرے یا اس سے بھی زائد اور بولے اے رب ہمارے! تو نے ہم پر جہاد کیوں فرض کردیا تھوڑی مدت تک ہمیں اور جینے دیا ہوتا، تم فرما دو کہ دنیا کا برتنا تھوڑا ہے اور ڈر والوں کے لئے آخرت اچھی اور تم پر تاگے برابر ظلم نہ ہوگا')
