INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (571, 4, 78, N'تم جہاں کہیں ہو موت تمہیں آلے گی اگرچہ مضبوط قلعوں میں ہو اور اُنہیں کوئی بھلائی پہنچے تو کہیں یہ اللہ کی طرف سے ہے اور انہیں کوئی برائی پہنچے تو کہیں یہ حضور کی طرف آئی تم فرمادو سب اللہ کی طرف سے ہے تو ان لوگوں کو کیا ہوا کوئی بات سمجھتے معلوم ہی نہیں ہوتے،')
