INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (572, 4, 79, N'اے سننے والے تجھے جو بھلائی پہنچے وہ اللہ کی طرف سے ہے اور جو برائی پہنچے وہ تیری اپنی طرف سے ہے اور اے محبوب ہم نے تمہیں سب لوگوں کے لئے رسول بھیجا اور اللہ کافی ہے گواہ')
