INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (573, 4, 80, N'جس نے رسول کا حکم مانا بیشک اس نے اللہ کا حکم مانا اور جس نے منہ پھیرا تو ہم نے تمہیں ان کے بچانے کو نہ بھیجا')
