INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (574, 4, 81, N'اور کہتے ہیں ہم نے حکم مانا پھر جب تمہارے پاس سے نکل کر جاتے ہیں تو ان میں ایک گروہ جو کہہ گیا تھا اس کے خلاف رات کو منصوبے گانٹھتا ہے اور اللہ لکھ رکھتا ہے ان کے رات کے منصوبے تو اے محبوب تم ان سے چشم پوشی کرو اور اللہ پر بھروسہ رکھو اور اللہ کافی ہے کام بنانے کو،')
