INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (575, 4, 82, N'تو کیا غور نہیں کرتے قرآن میں اور اگر وہ غیر خدا کے پاس سے ہوتا تو ضرور اس میں بہت اختلاف پاتے')
