INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (576, 4, 83, N'اور جب ان کے پاس کوئی بات اطمینان یا ڈر کی آتی ہے اس کا چرچا کر بیٹھتے ہیں اور اگر اس میں رسول اور اپنے ذی اختیار لوگوں کی طرف رجوع لاتے تو ضرور اُن سے اُ س کی حقیقت جان لیتے یہ جو بعد میں کاوش کرتے ہیں اور اگر تم پر اللہ کا فضل اور اس کی رحمت نہ ہوتی تو ضرور تم شیطان کے پیچھے لگ جاتے مگر تھوڑے')
