INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (577, 4, 84, N'تو اے محبوب اللہ کی راہ میں لڑو تم تکلیف نہ دیئے جاؤ گے مگر اپنے دم کی اور مسلمانوں کو آمادہ کرو قریب ہے کہ اللہ کافروں کی سختی روک دے اور اللہ کی آنچ (جنگی طاقت) سب سے سخت تر ہے اور اس کا عذاب سب سے کڑا (زبردست)')
