INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (579, 4, 86, N'اور جب تمہیں کوئی کسی لفظ سے سلام کرے تو اس سے بہتر لفظ جواب میں کہو یا یا وہی کہہ دو، بیشک اللہ ہر چیز پر حساب لینے والا ہے')
