INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (580, 4, 87, N'ا لله کہ اس کے سوا کسی کی بندگی نہیں اور وہ ضرور تمہیں اکٹھا کرے گا قیامت کے دن جس میں کچھ شک نہیں اور اللہ سے زیادہ کس کی بات سچی')
