INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (581, 4, 88, N'تو تمہیں کیا ہوا کہ منافقوں کے بارے میں دو فریق ہوگئے اور اللہ نے انہیں اوندھا کردیا ان کے کوتکوں (کرتوتوں) کے سبب کیا یہ چاہتے ہیں کہ اسے راہ دکھاؤ جسے اللہ نے گمراہ کیا اور جسے اللہ گمراہ کرے تو ہرگز اس کے لئے راہ نہ پائے گا،')
