INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (582, 4, 89, N'وہ تو یہ چاہتے ہیں کہ کہیں تم بھی کافر ہوجاؤ جیسے وہ کافر ہوئے تو تم سب ایک سے ہو جاؤ ان میں کسی کو اپنا دوست نہ بناؤ جب تک اللہ کی راہ میں گھر بار نہ چھوڑیں پھر اگر وہ منہ پھیریں تو انہیں پکڑو اور جہاں پاؤ قتل کرو، اور ان میں کسی کو نہ دوست ٹھہراؤ نہ مددگار')
