INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (583, 4, 90, N'مگر جو ایسی قوم سے علاقے رکھتے ہیں کہ تم میں ان میں معاہدہ ہے یا تمہارے پاس یوں آئے کہ ان کے دلوں میں سکت نہ رہی کہ تم سے لڑیں یا اپنی قوم سے لڑیں اور اللہ چاہتا تو ضرور انہیں تم پر قابو دیتا تو وہ بے شک تم سے لڑتے پھر اگر وہ تم سے کنارہ کریں اور نہ لڑیں اور صلح کا پیام ڈالیں تو اللہ نے تمہیں ان پر کوئی راہ نہ رکھی')
