INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (584, 4, 91, N'اب کچھ اور تم ایسے پاؤ گے جو یہ چاہتے ہیں کہ تم سے بھی امان میں رہیں اور اپنی قوم سے بھی امان میں رہیں جب کبھی انکی قوم انہیں فساد کی طرف پھیرے تو اس پر اوندھے گرتے ہیں پھر اگر وہ تم سے کنارہ نہ کریں اور صلح کی گردن نہ ڈالیں اور اپنے ہاتھ سے نہ روکیں تو انہیں پکڑو اور جہاں پاؤ قتل کرو، اور یہ ہیں جن پر ہم نے تمہیں صریح اختیار دیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (585, 4, 92, N'اور مسلمانوں کو نہیں پہنچتا کہ مسلمان کا خون کرے مگر ہاتھ بہک کر اور جو کسی مسلمان کو نادانستہ قتل کرے تو اس پر ایک مملوک مسلمان کا آزاد کرنا ہے اور خون بہا کر مقتول کے لوگوں کو سپرد کی جائے مگر یہ کہ وہ معاف کردیں پھر اگر وہ اس قوم سے ہو جو تمہاری دشمن ہے اور خود مسلمان ہے تو صرف ایک مملوک مسلمان کا آزاد کرنا اور اگر وہ اس قوم میں ہو کہ تم میں ان میں معاہدہ ہے تو اس کے لوگوں کو خوں بہا سپرد کیا جائے اور ایک مسلمان مملوک آزاد کرنا تو جس کا ہاتھ نہ پہنچے وہ لگاتار دو مہینے کے روزے یہ اللہ کے یہاں اس کی توبہ ہے اور اللہ جاننے والا حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (586, 4, 93, N'اور جو کوئی مسلمان کو جان بوجھ کر قتل کرے تو اس کا بدلہ جہنم ہے کہ مدتوں اس میں رہے اور اللہ نے اس پر غضب کیا اور اس پر لعنت کی اور اس کے لئے تیار رکھا بڑا عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (587, 4, 94, N'اے ایمان والو! جب تم جہاد کو چلو تو تحقیق کرلو اور جو تمہیں سلام کرے اس سے یہ نہ کہو کہ تو مسلمان نہیں تم جیتی دنیا کا اسباب چاہتے ہو تو اللہ کے پاس بہتری غنیمتیں ہیں پہلے تم بھی ایسے ہی تھے پھر اللہ نے تم پر احسان کیا تو تم پر تحقیق کرنا لازم ہے بیشک اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (588, 4, 95, N'برابر نہیں وہ مسلمان کہ بے عذر جہاد سے بیٹھ رہیں اور وہ کہ راہ خدا میں اپنے مالوں اور جانوں سے جہاد کرتے ہیں اللہ نے اپنے مالوں اور جانوں کے ساتھ جہاد کرنے والوں کا درجہ بیٹھنے والوں سے بڑا کیا اور اللہ نے سب سےبھلائی کا وعدہ فرمایا اور اللہ نے جہاد والوں کو بیٹھنے والوں پر بڑے ثواب سے فضیلت دی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (589, 4, 96, N'اُس کی طرف سے درجے اور بخشش اور رحمت اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (590, 4, 97, N'وہ لوگ جنکی جان فرشتے نکالتے ہیں اس حال میں کہ وہ اپنے اوپر ظلم کرتے تھے انسے فرشتے کہتے ہیں تم کاہے میں تھے کہتے ہیں کہ ہم زمین میں کمزور تھے کہتے ہیں کیا اللہ کی زمین کشادہ نہ تھی کہ تم اسمیں ہجرت کرتے، تو ایسوں کا ٹھکانا جہنم ہے، اور بہت بری جگہ پلٹنے کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (591, 4, 98, N'مگر وہ جو دبالیے گئے مرد اور عورتیں اور بچے جنہیں نہ کوئی تدبیر بن پڑے نہ راستہ جانیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (592, 4, 99, N'تو قریب ہے اللہ ایسوں کو معاف فرمائے اور اللہ معاف فرمانے والا بخشنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (593, 4, 100, N'اور جو اللہ کی راہ میں گھر بار چھوڑ کر نکلے گا وہ زمین میں بہت جگہ اور گنجائش پائے گا، اور جو اپنے گھر سے نکلا اللہ و رسول کی طرف ہجرت کرتا پھر اسے موت نے آلیا تو اس کا ثواب اللہ کے ذمہ پر ہوگیا اور اللہ بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (594, 4, 101, N'اور جب تم زمین میں سفر کرو تو تم پر گناہ نہیں کہ بعض نمازیں قصر سے پڑھو اگر تمہیں اندیشہ ہو کہ کافر تمہیں ایذا دیں گے بیشک کفار تمہارے کھلے دشمن ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (595, 4, 102, N'اور اے محبوب! جب تم ان میں تشریف فرما ہو پھر نماز میں ان کی امامت کرو تو چاہئے کہ ان میں ایک جماعت تمہارے ساتھ ہو اور وہ اپنے ہتھیار لیے رہیں پھر جب وہ سجدہ کرلیں تو ہٹ کر تم سے پیچھے ہوجائیں اور اب دوسری جماعت آئے جو اس وقت تک نماز میں شریک نہ تھی اب وہ تمہارے مقتدی ہوں اور چاہئے کہ اپنی پناہ اور اپنے ہتھیار لیے رہیں کافروں کی تمنا ہے کہ کہیں تم اپنے ہتھیاروں اور اپنے اسباب سے غافل ہو جاؤ تو ایک دفعہ تم پر جھک پڑیں اور تم پر مضائقہ نہیں اگر تمہیں مینھ کے سبب تکلیف ہو یا بیمار ہو کہ اپنے ہتھیار کھول رکھو اور اپنی پناہ لیے رہو بیشک اللہ نے کافروں کے لئے خواری کا عذاب تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (596, 4, 103, N'پھر جب تم نماز پڑھ چکو تو اللہ کی یاد کرو کھڑے اور بیٹھے اور کروٹوں پر لیٹے پھر جب مطمئن ہو جاؤ تو حسب دستور نماز قائم کرو بیشک نماز مسلمانوں پر وقت باندھا ہوا فرض ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (597, 4, 104, N'اور کافروں کی تلاش میں سستی نہ کرو اگر تمہیں دکھ پہنچتا ہے تو انہیں بھی دکھ پہنچتا ہے جیسا تمہیں پہنچتا ہے، اورتم اللہ سے وہ امید رکھتےہو جو وہ نہیں رکھتے، ور اللہ جاننے والا حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (598, 4, 105, N'اے محبوب! بیشک ہم نے تمہاری طرف سچی کتاب اتاری کہ تم لوگوں میں فیصلہ کرو جس طرح تمہیں اللہ دکھائے اور دغا والوں کی طرف سے نہ جھگڑو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (599, 4, 106, N'اور اللہ سے معافی چاہو بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (600, 4, 107, N'اور ان کی طرف سے نہ جھگڑو جو اپنی جانوں کو خیانت میں ڈالتے ہیں بیشک اللہ نہیں چاہتا کسی بڑے دغا باز گنہگار کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (601, 4, 108, N'آدمیوں سے چھپتے ہیں اور اللہ نہیں چھپتے اور ا لله ان کے پاس ہے جب دل میں وہ بات تجویز کرتے ہیں جو اللہ کو ناپسند ہے اور اللہ ان کے کاموں کو گھیرے ہوئے ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (602, 4, 109, N'سنتے ہو یہ جو تم ہو دنیا کی زندگی میں تو ان کی طرف سے جھگڑے تو ان کی طرف سے کون جھگڑے گا اللہ سے قیامت کے دن یا کون ان کا وکیل ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (603, 4, 110, N'اور جو کوئی برائی یا اپنی جان پر ظلم کرے پھر اللہ سے بخشش چاہے تو اللہ کو بخشنے والا مہربان پائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (604, 4, 111, N'اور جو گناہ کمائے تو ا س کی کمائی اسی کی جان پر پڑے اور اللہ علم و حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (605, 4, 112, N'اور جو کوئی خطا یا گناہ کمائے پھر اسے کسی بے گناہ پر تھوپ دے اس نے ضرور بہتان اور کھلا گناہ اٹھایا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (606, 4, 113, N'اور اے محبوب! اگر اللہ کا فضل و رحمت تم پر نہ ہوتا تو ان میں کے کچھ لوگ یہ چاہتے کہ تمہیں دھوکا دے دیں اور وہ اپنے ہی آپ کو بہکا رہے ہیں اور تمہارا کچھ نہ بگاڑیں گے اور اللہ نے تم پر کتاب اور حکمت اتاری اور تمہیں سکھا دیا جو کچھ تم نہ جانتے تھے اور اللہ کا تم پر بڑا فضل ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (607, 4, 114, N'ان کے اکثر مشوروں میں کچھ بھلائی نہیں مگر جو حکم دے خیرات یا اچھی بات یا لوگوں میں صلح کرنے کا اور جو اللہ کی رضا چاہنے کو ایسا کرے اسے عنقریب ہم بڑا ثواب دیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (608, 4, 115, N'اور جو رسول کا خلاف کرے بعد اس کے کہ حق راستہ اس پر کھل چکا اور مسلمانوں کی راہ سے جدا راہ چلے ہم اُسے اُس کے حال پر چھوڑ دیں گے اور اسے دوزخ میں داخل کریں گے اور کیا ہی بری جگہ پلٹنے کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (609, 4, 116, N'اللہ اسے نہیں بخشتا کہ اس کا کوئی شریک ٹھہرایا جائے اور اس سے نیچے جو کچھ ہے جسے چاہے معاف فرما دیتا ہے اور جو اللہ کا شریک ٹھہرائے وہ دور کی گمراہی میں پڑا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (610, 4, 117, N'یہ شرک والے اللہ سوا نہیں پوجتے مگر کچھ عورتوں کو اور نہیں پوجتے مگر سرکش شیطان کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (611, 4, 118, N'جس پر اللہ نے لعنت کی اور بولا قسم ہے میں ضرور تیرے بندوں میں سے کچھ ٹھہرایا ہوا حصہ لوں گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (612, 4, 119, N'قسم ہے میں ضرور بہکادوں گا اور ضرور انہیں آرزوئیں دلاؤں گا اور ضرور انہیں کہوں گا کہ وہ چوپایوں کے کان چیریں گے اور ضرور انہیں کہوں گا کہ وہ اللہ کی پیدا کی ہوئی چیزیں بدل دیں گے، اور جو اللہ کو چھوڑ کر شیطان کو دوست بنائے وہ صریح ٹوٹے میں پڑا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (613, 4, 120, N'شیطان انہیں وعدے دیتا ہے اور آرزوئیں دلاتا ہے اور شیطان انہیں وعدے نہیں دیتا مگر فریب کے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (614, 4, 121, N'اُن کا ٹھکانا دوزخ ہے اس سے بچنے کی جگہ نہ پائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (615, 4, 122, N'اور جو ایمان لائے اور اچھے کام کیے کچھ دیر جاتی ہے کہ ہم انہیں باغوں میں لے جائیں گے جن کے نیچے نہریں بہیں ہمیشہ ہمیشہ ان میں رہیں اللہ کا سچا وعدہ اور اللہ سے زیادہ کس کی بات سچی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (616, 4, 123, N'کام نہ کچھ تمہارے خیالوں پر ہے اور نہ کتاب والوں کی ہوس پر جو برائی کرے گا اس کا بدلہ پائے گا اور اللہ کے سوا نہ کوئی اپنا حمایتی پائے گا نہ مددگار')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (617, 4, 124, N'اور جو کچھ بھلے کام کرے گا مرد ہو یا عورت اور ہو مسلمان تو وہ جنت میں داخل کیے جائیں گے اور انہیں تِل بھر نقصان نہ دیا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (618, 4, 125, N'اور اس سے بہتر کس کا دین جس نے اپنا منہ اللہ کے لئے جھکا دیا اور وہ نیکی والا ہے اور ابراہیم کے دین پر جو ہر باطل سے جدا تھا اور اللہ نے ابراہیم کو اپنا گہرا دوست بنایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (619, 4, 126, N'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور ہر چیز پر اللہ کا قابو ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (620, 4, 127, N'اور تم سے عورتوں کے بارے میں فتویٰ پوچھتے ہیں تم فرمادو کہ اللہ تمہیں ان کا فتویٰ دیتا ہے اور وہ جو تم پر قرآن میں پڑھا جاتا ہے ان یتیم لڑکیوں کے بارے میں تم انہیں نہیں دیتے جو ان کا مقرر ہے اور انہیں نکاح میں بھی لانے سے منہ پھیرتے ہو اور کمزور بچوں کے بارے میں اور یہ کہ یتیموں کے حق میں انصاف پر قائم رہو اور تم جو بھلائی کرو تو اللہ کو اس کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (621, 4, 128, N'اور اگر کوئی عورت اپنے شوہر کی زیادتی یا بے رغبتی کا اندیشہ کرے تو ان پر گناہ نہیں کہ آپس میں صلح کرلیں اور صلح خوب ہے اور دل لالچ کے پھندے میں ہیں اور اگر تم نیکی اور پرہیزگاری کرو تو اللہ کو تمہارے کاموں کی خبر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (622, 4, 129, N'اور تم سے ہرگز نہ ہوسکے گا کہ عورتوں کو برابر رکھو اور چاہے کتنی ہی حرص کرو تو یہ تو نہ ہو کہ ایک طرف پورا جھک جاؤ کہ دوسری کو ادھر میں لٹکتی چھوڑ دو اور اگر تم نیکی اور پرہیزگاری کرو تو بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (623, 4, 130, N'اور اگر وہ دونوں جدا ہوجائیں تو اللہ اپنی کشائش سے تم میں ہر ایک کو دوسرے سے بے نیاز کردے گا اور اللہ کشائش والا حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (624, 4, 131, N'اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور بیشک تاکید فرمادی ہے ہم نے ان سے جو تم سے پہلے کتاب دیئے گئے اور تم کو کہ اللہ سے ڈرتے رہو اور اگر کفر کرو تو بیشک اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں اور اللہ بے نیاز ہے سب خوبیوں سراہا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (625, 4, 132, N'اور اللہ کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور اللہ کافی ہے کارساز،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (626, 4, 133, N'اے لوگوں وہ چاہے تو تمہیں لے جائے اور اوروں کو لے آئے اور اللہ کو اس کی قدرت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (627, 4, 134, N'جو دنیا کا انعام چاہے تو اللہ ہی کے پاس دنیا و آخرت دونوں کا انعام ہے اور اللہ ہی سنتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (628, 4, 135, N'اے ایمان والو! انصاف پر خوب قائم ہوجاؤ اللہ کے لئے گواہی دیتے چاہے اس میں تمہارا اپنا نقصان ہو یا ماں باپ کا یا رشتہ داروں کا جس پر گواہی دو وہ غنی ہو یا فقیر ہو بہرحال اللہ کو اس کا سب سے زیادہ اختیار ہے تو خواہش کے پیچھے نہ جاؤ کہ حق سے الگ پڑو اگر تم ہیر پھیر کرو یا منہ پھیرو تو اللہ کو تمہارے کاموں کی خبر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (629, 4, 136, N'اے ایمان والو ایمان رکھو اللہ اور اللہ کے رسول پر اور اس کتاب پر جو اپنے ان رسول پر اتاری اور اس کتاب پر جو پہلے اتاردی اور جو نہ مانے اللہ اور اس کے فرشتوں اور کتابوں اور رسولوں اور قیامت کو تو وہ ضرور دور کی گمراہی میں پڑا،')
GO
