INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (632, 4, 139, N'وہ جو مسلمانوں کو چھوڑ کر کافروں کو دوست بناتے ہیں کیا ان کے پاس عزت ڈھونڈتے ہیں تو عزت تو ساری اللہ کے لیے ہے')
