INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (633, 4, 140, N'اور بیشک اللہ تم پر کتاب میں اتار چکا کہ جب تم اللہ کی آیتوں کو سنو کہ ان کا انکار کیا جاتا اور ان کی ہنسی بنائی جاتی ہے تو ان لوگوں کے ساتھ نہ بیٹھو جب تک وہ اور بات میں مشغول نہ ہوں ورنہ تم بھی انہیں جیسے ہو بیشک اللہ منافقوں اور کافروں سب کو جہنم میں اکٹھا کرے گا')
