INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (634, 4, 141, N'وہ جو تمہاری حالت تکا کرتے ہیں تو اگر اللہ کی طرف سے تم کو فتح ملے کہیں کیا ہم تمہارے ساتھ نہ تھے اور اگر کافروں کا حصہ ہو تو ان سے کہیں کیا ہمیں تم پر قابو نہ تھا اور ہم نے تمہیں مسلمانوں سے بچایا تو اللہ تم سب میں قیامت کے دن فیصلہ کردے گا اور اللہ کافروں کو مسلمان پر کوئی راہ نہ دے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (635, 4, 142, N'بیشک منافق لوگ اپنے گمان میں اللہ کو فریب دیا چاہتے ہیں اور وہی انہیں غافل کرکے مارے گا اور جب نماز کو کھڑے ہوں تو ہارے جی سے لوگوں کو دکھاوا کرتے ہیں اور اللہ کو یاد نہیں کرتے مگر تھوڑا')
