INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (637, 4, 144, N'اے ایمان والو! کافروں کو دوست نہ بناؤ مسلمانوں کے سوا کیا یہ چاہتے ہو کہ اپنے اوپر اللہ کے لئے صریح حجت کرلو')
