INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (638, 4, 145, N'بیشک منافق دوزخ کے سب سے نیچے طبقہ میں ہیں اور تو ہرگز ان کا کوئی مددگار نہ پائے گا')
