INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (639, 4, 146, N'مگر وہ جنہوں نے توبہ کی اور سنورے اور اللہ کی رسی مضبوط تھامی اور اپنا دین خالص اللہ کے لئے کرلیا تو یہ مسلمانوں کے ساتھ ہیں اور عنقریب اللہ مسلمانوں کو بڑا ثواب دے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (640, 4, 147, N'اور اللہ تمہیں عذاب دے کر کیا کرے گا اگر تم حق مانو، اور ایمان لاؤ اور اللہ ہے صلہ دینے والا جاننے والا،')
