INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (641, 4, 148, N'اللہ پسند نہیں کرتا بری بات کا اعلان کرنا مگر مظلوم سے اور اللہ سنتا جانتا ہے،')
