INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (642, 4, 149, N'اگر تم کوئی بھلائی اعلانیہ کرو یا چھپ کر یا کسی کی برائی سے درگزرو تو بیشک اللہ معاف کرنے والا قدرت والا ہے')
