INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (643, 4, 150, N'وہ جو اللہ اور اس کے رسولوں کو نہیں مانتے اور چاہتے ہیں کہ اللہ سے اس کے رسولوں کو جدا کردیں اور کہتے ہیں ہم کسی پر ایمان لائے اور کسی کے منکر ہوئے اور چاہتے ہیں کہ ایمان و کفر کے بیچ میں کوئی راہ نکال لیں')
