INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (644, 4, 151, N'یہی ہیں ٹھیک ٹھیک کافر اور ہم نے کافروں کے لئے ذلت کا عذاب تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (645, 4, 152, N'اور وہ جو اللہ اور اس کے سب رسولوں پر ایمان لائے اور ان میں سے کسی پر ایمان میں فرق نہ کیا انہیں عنقریب اللہ ان کے ثواب دے گا اور اللہ بخشنے والا مہربان ہے')
