INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (646, 4, 153, N'اے محبوب! اہل کتاب تم سے سوال کرتے ہیں کہ ان پر آسمان سے ایک کتاب اتاردو تو وہ تو موسیٰ سے اس سے بھی بڑا سوال کرچکے کہ بولے ہمیں ا لله کو اعلانیہ دکھادو تو انہیں کڑک نے آ لیا ان کے گناہوں پر پھر بچھڑا لے بیٹھے بعداس کے لئے روشن آیتیں ان کے پاس آچکیں تو ہم نے یہ معاف فرمادیا اور ہم نے موسیٰ کو روشن غلبہ دیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (647, 4, 154, N'پھر ہم نے ان پر طور کو اونچا کیا ان سے عہد لینے کو اور ان سے فرمایا کہ دروازے میں سجدہ کرتے داخل ہو اور ان سے فرمایا کہ ہفتہ میں حد سے نہ بڑھو اور ہم نے ان سے گاڑھا عہد لیا')
