INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (648, 4, 155, N'تو ان کی کیسی بدعہدیوں کے سبب ہم نے ان پر لعنت کی اور اس لئے کہ وہ آیات الٰہی کے منکر ہوئے اور انبیاء کو ناحق شہید کرتے اور ان کے اس کہنے پر کہ ہمارے دلوں پر غلاف ہیں بلکہ اللہ نے ان کے کفر کے سبب ان کے دلوں پر مہر لگادی ہے تو ایمان نہیں لاتے مگر تھوڑے،')
