INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (649, 4, 156, N'اور اس لئے کہ انہوں نے کفر کیا اور مریم پر بڑا بہتان اٹھایا،')
