INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (650, 4, 157, N'اور ان کے اس کہنے پر کہ ہم نے مسیح عیسیٰ بن مریم اللہ کے رسول کو شہید کیا اور ہے یہ کہ انہوں نے نہ اسے قتل کیا اور نہ اسے سولی دی بلکہ ان کے لئے ان کی شبیہ کا ایک بنادیا گیا اور وہ جو اس کے بارہ میں اختلاف کررہے ہیں ضرور اس کی طرف سے شبہ میں پڑے ہوئے ہیں انہیں اس کی کچھ بھی خبر نہیں مگر یہی گمان کی پیروی اور بیشک انہوں نے اس کو قتل نہیں کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (651, 4, 158, N'بلکہ اللہ نے اسے اپنی طرف اٹھالیا اور اللہ غالب حکمت والا ہے،')
