INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (652, 4, 159, N'کوئی کتابی ایسا نہیں جو اس کی موت سے پہلے اس پر ایمان نہ لائے اور قیامت کے دن وہ ان پر گواہ ہوگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (653, 4, 160, N'تو یہودیوں کے بڑے ظلم کے سبب ہم نے وہ بعض ستھری چیزیں کہ ان کے لئے حلال تھیں ان پر حرام فرمادیں اور اس لئے کہ انہوں نے بہتوں کو اللہ کی راہ سے روکا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (654, 4, 161, N'اور اس لئے کہ وہ سود لیتے حالانکہ وہ اس سے منع کیے گئے تھے اور لوگوں کا مال ناحق کھا جاتے اور ان میں جو کافر ہوئے ہم نے ان کے لئے دردناک عذاب تیار کر رکھا ہے،')
