INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (655, 4, 162, N'ہاں جو اُن میں علم کے پکے اور ایمان والے ہیں وہ ایمان لاتے ہیں اس پر جو اے محبوب تمہاری طرف اُترا اور جو تم سے پہلے اُترا اور نماز قائم رکھنے والے اور زکوٰة دینے والے اور اللہ اور قیامت پر ایمان لانے والے ایسوں کو عنقریب ہم بڑا ثواب دیں گے،')
