INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (656, 4, 163, N'بیشک اے محبوب! ہم نے تمہاری طرف وحی بھیجی جیسے دحی نوح اور اس کے بعد پیغمبروں کو بھیجی اور ہم نے ابراہیم اور اسمٰعیل اور اسحاق اور یعقوب اور ان کے بیٹوں اور عیسیٰ اور ایوب اور یونس اور ہارون اور سلیمان کو وحی کی اور ہم نے داؤد کو زبور عطا فرمائی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (657, 4, 164, N'اور رسولوں کو جن کا ذکر آگے ہم تم سے فرماچکے اور ان رسولوں کو جن کا ذکر تم سے نہ فرمایا اور اللہ نے موسیٰ سے حقیقتاً کلام فرمایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (658, 4, 165, N'رسول خوشخبری دیتے اور ڈر سناتے کہ رسولوں کے بعد اللہ کے یہاں لوگوں کو کوئی عذر نہ رہے اور اللہ غالب حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (659, 4, 166, N'لیکن اے محبوب! اللہ اس کا گواہ ہے جو اس نے تمہاری طرف اتارا وہ اس نے اپنے علم سے اتارا ہے اور فرشتے گواہ ہیں اور اللہ کی گواہی کافی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (660, 4, 167, N'وہ جنہوں نے کفر کیا اور اللہ کی راہ سے روکا بیشک وہ دور کی گمراہی میں پڑے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (661, 4, 168, N'بیشک جنہوں نے کفر کیا اور حد سے بڑھے اللہ ہرگز انہیں نہ بخشے گا اور نہ انہیں کوئی راہ دکھائے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (662, 4, 169, N'مگر جہنم کا راستہ کہ اس میں ہمیشہ ہمیشہ رہیتں گے اور یہ اللہ کو آسان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (663, 4, 170, N'اے لوگو! تمہارے پاس یہ رسول حق کے ساتھ تمہارے رب کی طرف سے تشریف لائے تو ایمان لاؤ اپنے بھلے کو اور اگر تم کفر کرو تو بیشک اللہ ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے، اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (664, 4, 171, N'اے کتاب والو! اپنے دین میں زیادتی نہ کرو اور اللہ پر نہ کہو مگر سچ مسیح عیسیٰ مریم کا بیٹا ا لله کا رسول ہی ہے اور اس کا ایک کلمہ کہ مریم کی طرف بھیجا اور اس کے یہاں کی ایک روح تو اللہ اور اس کے رسولوں پر ایمان لاؤ اور تین نہ کہو باز رہو اپنے بھلے کو اللہ تو ایک ہی خدا ہے پاکی اُسے اس سے کہ اس کے کوئی بچہ ہو اسی کا مال ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور اللہ کافی کارساز،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (665, 4, 172, N'مسیح اللہ کا بندہ بننے سے کچھ نفرت نہیں کرتا اور نہ مقرب فرشتے اور جو اللہ کی بندگی سے نفرت اور تکبر کرے تو کوئی دم جاتا ہے کہ وہ ان سب کو اپنی طرف ہانکے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (666, 4, 173, N'تو وہ جو ایمان لائے اور اچھے کام کیے ان کی مزدوری انہیں بھرپور دے کر اپنے فضل سے انہیں اور زیادہ دے گا اور وہ جنہوں نے نفرت اور تکبر کیا تھا انہیں دردناک سزا دے گا اور اللہ کے سوا نہ اپنا کوئی حمایتی پائیں گے نہ مددگار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (667, 4, 174, N'اے لوگو! بیشک تمہارے پاس اللہ کی طرف سے واضح دلیل آئی اور ہم نے تمہاری طرف روشن نور اتارا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (668, 4, 175, N'تو وہ جو اللہ پر ایمان لائے اور اس کی رسی مضبوط تھامی تو عنقریب اللہ انہیں اپنی رحمت اور اپنے فضل میں داخل کرے گا اور انہیں اپنی طرف سیدھی راہ دکھائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (669, 4, 176, N'اے محبوب! تم سے فتویٰ پوچھتے ہیں تم فرمادو کہ اللہ تمہیں کلالہ میں فتویٰ دیتا ہے، اگر کسی مرد کا انتقال ہو جو بے اولاد ہے اور اس کی ایک بہن ہو تو ترکہ میں اس کی بہن کا آدھا ہے اور مرد اپنی بہن کا وارث ہوگا اگر بہن کی اولاد نہ ہو پھر اگر دو بہنیں ہوں ترکہ میں ان کا دو تہائی اور اگر بھائی بہن ہوں مرد بھی اور عورتیں بھی تو مرد کا حصہ دو عورتوں کے برابر، ا لله تمہارے لئے صاف بیان فرماتا ہے کہ کہیں بہک نہ جاؤ، اور اللہ ہرچیز جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (670, 5, 1, N'اے ایمان والو! اپنے قول پورے کرو تمہارے لئے حلال ہوئے بے زبان مویشی مگر وہ جو آگے سنایا جائے گا تم کو لیکن شکار حلال نہ سمجھو جب تم احرام میں ہو بیشک اللہ حکم فرماتا ہے جو چاہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (671, 5, 2, N'اے ایمان والو! حلال نہ ٹھہرالو اللہ کے نشان اور نہ ادب والے مہینے اور نہ حرم کو بھیجی ہوئی قربانیاں اور نہ جن کے گلے میں علامتیں آویزاں اور نہ ان کا مال و آبرو جو عزت والے گھر کا قصد کرکے آئیں اپنے رب کا فضل اوراس کی خوشی چاہتے اور جب احرام سے نکلو تو شکار کرسکتے ہو اور تمہیں کسی قوم کی عداوت کہ انہوں نے تم کو مسجد حرام سے روکا تھا، زیادتی کرنے پر نہ ابھارے اور نیکی اور پرہیزگاری پر ایک دوسرے کی مدد کرو اور گناہ اور زیادتی پر باہم مدد نہ دو اور اللہ سے ڈرتے رہو بیشک اللہ کا عذاب سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (672, 5, 3, N'تم پر حرام ہے مُردار اور خون اور سور کا گوشت اور وہ جس کے ذبح میں غیر خدا کا نام پکارا گیا اور جو گلا گھونٹنے سے مرے اور بے دھار کی چیز سے مارا ہوا اور جو گر کر مرا اور جسے کسی جانور نے سینگ مارا اور جسے کوئی درندہ کھا گیا مگر جنہیں تم ذبح کرلو، اور جو کسی تھان پر ذبح کیا گیا اور پانسے ڈال کر بانٹا کرنا یہ گناہ کا کا م ہے، آج تمہارے دین کی طرف سے کافروں کی آس نوٹ گئی تو اُن سے نہ ڈرو اور مجھ سے ڈرو آج میں نے تمہارے لئے دین کامل کردیا اور تم پر اپنی نعمت پوری کردی اور تمہارے لئے اسلام کو دین پسند کیا تو جو بھوک پیاس کی شدت میں ناچار ہو یوں کہ گناہ کی طرف نہ جھکے تو بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (673, 5, 4, N'اے محبوب! تم سے پوچھتے ہیں کہ اُن کے لئے کیا حلال ہوا تم فرمادو کہ حلال کی گئیں تمہارے لئے پاک چیزیں اور جو شکاری جانور تم نے سدھالیے انہیں شکار پر دوڑاتے جو علم تمہیں خدا نے دیا اس سے انہیں سکھاتے تو کھاؤ اس میں سے جو وہ مار کر تمہارے لیے رہنے دیں اور اس پر اللہ کا نام لو اور اللہ سے ڈرتے رہو بیشک اللہ کو حساب کرتے دیر نہیں لگتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (674, 5, 5, N'آج تمہارے لئے پاک چیزیں حلال ہوئیں، اور کتابیوں کا کھانا تمہارے لیے حلال ہوا، اور تمہارا کھانا ان کے لئے حلال ہے، اور پارسا عورتیں مسلمان اور پارسا عورتیں ان میں سے جن کو تم سے پہلے کتاب ملی جب تم انہیں ان کے مہر دو قید میں لاتے ہوئے نہ مستی نکالتے اور نہ ناآشنا بناتے اور جو مسلمان سے کافر ہو اس کا کیا دھرا سب اکارت گیا اور وہ آخرت میں زیاں کار ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (675, 5, 6, N'اے ایمان والو جب نماز کو کھڑے ہونا چاہو تو اپنا منہ دھوؤ اور کہنیوں تک ہاتھ اور سروں کا مسح کرو اور گٹوں تک پاؤ ں دھوؤ اور اگر تمہیں نہانے کی حاجت ہو تو خوب ستھرے ہولو اور اگر تم بیمار ہو یا سفر میں ہو یا تم میں سے کوئی قضائے حاجت سے آیا یا تم نے عورتوں سے صحبت کی اور ان صورتوں میں پانی نہ پایا مٹی سے تیمم کرو تو اپنے منہ اور ہاتھوں کا اس سے مسح کرو، اللہ نہیں چاہتا کہ تم پر کچھ تنگی رکھے ہاں یہ چاہتا ہے کہ تمہیں خوب ستھرا کردے اور اپنی نعمت تم پر پوری کردے کہ کہیں تم احسان مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (676, 5, 7, N'اور یاد کرو اللہ کا احسان اپنے اوپر اور وہ عہد جو اس نے تم سے لیا جبکہ تم نے کہا ہم نے سنا اور مانا اور اللہ سے ڈرو بیشک اللہ دلوں کی بات جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (677, 5, 8, N'اے ایمان والوں اللہ کے حکم پر خوب قائم ہوجاؤ انصاف کے ساتھ گواہی دیتے اور تم کو کسی قوم کی عداوت اس پر نہ اُبھارے کہ انصاف نہ کرو، انصاف کرو، وہ پرہیزگاری سے زیادہ قریب ہے، اور اللہ سے ڈرو، بیشک اللہ کو تمہارے کامو ں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (678, 5, 9, N'ایمان والے نیکو کاروں سے اللہ کا وعدہ ہے کہ ان کے لئے بخشش اور بڑا ثواب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (679, 5, 10, N'اور وہ جنہوں نے کفر کیا اور ہماری آیتیں جھٹلائیں وحی دوزخ والے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (680, 5, 11, N'اے ایمان والو! اللہ کا احسان اپنے اوپر یاد کرو جب ایک قوم نے چاہا کہ تم پر دست درازی کریں تو اس نے ان کے ہاتھ تم پر سے روک دیئے اور اللہ سے ڈرو اور مسلمانوں کو اللہ ہی پر بھروسہ چاہئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (681, 5, 12, N'اور بیشک اللہ نے بنی اسرائیل سے عہد کیا اور ہم نے ان میں بارہ سردار قائم کیے اور اللہ نے فرمایا بیشک میں تمہارے ساتھ ہوں ضرور اگر تم نماز قائم رکھو اور زکوٰة دو اور میرے سوالوں پر ایمان لاؤ اور ان کی تعظیم کرو اور اللہ کو قرض حسن دو بیشک میں تمہارے گناہ اتار دوں گا اور ضرور تمہیں باغوں میں لے جاؤں گا جن کے نیچے نہریں رواں، پھر اس کے بعد جو تم میں سے کفر کرے وہ ضرور سیدھی راہ سے بہکا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (682, 5, 13, N'تو ان کی کیسی بد عہدیوں پر ہم نے انہیں لعنت کی اور ان کے دل سخت کردیئے اللہ کی باتوں کو ان کے ٹھکانوں سے بدلتے ہیں اور بُھلا بیٹھے بڑا حصہ ان نصیحتوں کا جو انہیں دی گئیں اور تم ہمیشہ ان کی ایک نہ ایک دغا پر مطلع ہوتے رہو گے سوا تھوڑوں کے تو انہیں معاف کردو اور ان سے درگزرو بیشک احسان والے ا لله کو محبوب ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (683, 5, 14, N'اور وہ جنہوں نے دعویٰ کیا کہ ہم نصاریٰ ہیں ہم نے ان سے عہد لیا تو وہ بھلا بیٹھے بڑا حصہ ان نصیحتوں کا جو انہیں دی گئیں تو ہم نے ان کے آپس میں قیامت کے دن تک بَیر اور بغض ڈال دیا اور عنقریب اللہ انہیں بتادے گا جو کچھ کرتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (684, 5, 15, N'اے کتاب والو بیشک تمہارے پاس ہمارے یہ رسول تشریف لائے کہ تم پر ظاہر فرماتے ہیں بہت سی وہ چیزیں جو تم نے کتاب میں چھپا ڈالی تھیں اور بہت سی معاف فرماتے ہیں بیشک تمہارے پاس اللہ کی طرف سے ایک نور آیا اور روشن کتاب')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (685, 5, 16, N'اللہ اس سے ہدایت دیتا ہے اسے جو اللہ کی مرضی پر چلا سلامتی کے ساتھ اور انہیں اندھیریوں سے روشنی کی طرف لے جاتا ہے اپنے حکم سے اور انہیں سیدھی راہ دکھاتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (686, 5, 17, N'بیشک کافر ہوئے وہ جنہوں نے کہا کہ اللہ مسیح بن مریم ہی ہے تم فرما دو پھر اللہ کا کوئی کیا کرسکتا ہے اگر وہ چاہے کہ ہلاک کردے مسیح بن مریم اور اس کی ماں اور تمام زمین والوں کو اور اللہ ہی کے لیے ہے سلطنت آسمانوں اور زمین اور ان کے درمیان کی جو چاہے پیدا کرتا ہے، اور اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (687, 5, 18, N'اور یہودی اور نصرانی بولے کہ ہم اللہ کے بیٹے اور اس کے پیارے ہیں تم فرما دو پھر تمہیں کیوں تمہارے گناہوں پر عذاب فرماتا ہے بلکہ تم آدمی ہو اس کی مخلوقات سے جسے چاہے بخشتا ہے اور جسے چاہے سزا دیتا ہے، اور اللہ ہی کے لئے ہے سلطنت آسمانوں اور زمین اور اس کے درمیان کی، اور اسی کی طرف پھرنا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (688, 5, 19, N'اے کتاب والو! بیشک تمہارے پاس ہمارے یہ رسول تشریف لائے کہ تم پر ہمارے احکام ظاہر فرماتے ہیں بعد اس کے کہ رسولوں کا آنا مدتوں بند رہا تھا کہ کبھی کہو کہ ہمارے پاس کوئی خوشی اور ڈر سنانے والا نہ آیا تو یہ خوشی اور ڈر سنانے والے تمہارے پاس تشریف لائے ہیں، اور اللہ کو سب قدرت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (689, 5, 20, N'اور جب موسیٰ نے کہا اپنی قوم سے اے میری قوم اللہ کا احسان اپنے اوپر یاد کرو کہ تم میں سے پیغمبر کیے اور تمہیں بادشاہ کیا اور تمہیں وہ دیا جو آج سارے جہان میں کسی کو نہ دیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (690, 5, 21, N'اے قوم اس پاک زمین میں داخل ہو جو اللہ نے تمہارے لیے لکھی ہے اور پیچھے نہ پلٹو کہ نقصان پر پلٹو گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (691, 5, 22, N'بولے اے موسیٰ اس میں تو بڑے زبردست لوگ ہیں، اور ہم اس میں ہرگز داخل نہ ہوں گے جب تک وہ وہاں سے نکل نہ جائیں ہاں وہ وہاں سے نکل جائیں تو ہم وہاں جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (692, 5, 23, N'دو مرد کہ اللہ سے ڈرنے والوں میں سے تھے ا لله نے انہیں نوازا بولے کہ زبردستی دروازے میں ان پر داخل ہو اگر تم دروازے میں داخل ہوگئے تو تمہارا ہی غلبہ ہے اور اللہ ہی پر بھروسہ کرو اگر تمہیں ایمان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (693, 5, 24, N'بولے اے موسیٰ ہم تو وہاں کبھی نہ جائیں گے جب تک وہ وہاں ہیں تو آپ جائیے اور آپ کا رب تم دونوں لڑو ہم یہاں بیٹھے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (694, 5, 25, N'موسیٰ نے عرض کی کہ اے رب! میرے مجھے اختیار نہیں مگر اپنا اور اپنے بھائی کا تو تو ہم کو ان بے حکموں سے جدا رکھ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (695, 5, 26, N'فرمایا تو وہ زمین ان پر حرام ہے چالیس برس تک بھٹکتے پھریں زمین میں تو تم ان بے حکموں کا افسوس نہ کھاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (696, 5, 27, N'اور انہیں پڑھ کر سناؤ آدم کے دو بیٹوں کی سچی خبر جب دونوں نے ایک ایک نیاز پیش کی تو ایک کی قبول ہوئی اور دوسرے کی نہ قبول ہوئی بولا قسم ہے میں تجھے قتل کردوں گا کہا اللہ اسی سے قبول کرتا ہے، سے ڈر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (697, 5, 28, N'بیشک اگر تو اپنا ہاتھ مجھ پر بڑھائے گا کہ مجھے قتل کرے تو میں اپنا ہاتھ تجھ پر نہ بڑھاؤں گا کہ تجھے قتل کروں میں اللہ سے ڈرتا ہوں جو مالک ہے سارے جہاں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (698, 5, 29, N'میں تو یہ چاہتا ہوں کہ میرا اور تیرا گناہ دونوں تیرے ہی پلہ پڑے تو تو دوز خی ہوجائے، اور بے انصافوں کی یہی سزا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (699, 5, 30, N'تو اسکے نفس نے اسے بھائی کے قتل کا چاؤ دلایا تو اسے قتل کردیا تو رہ گیا نقصان میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (700, 5, 31, N'تو اللہ نے ایک کوا بھیجا زمین کریدتا کہ اسے دکھائے کیونکر اپنے بھائی کی لاش چھپائے بولا ہائے خرابی میں اس کوے جیسا بھی نہ ہوسکا کہ میں اپنے بھائی کی لاش چھپاتا تو پچتاتا رہ گیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (701, 5, 32, N'اس سبب سے ہم نے بنی اسرائیل پر لکھ دیا کہ جس نے کوئی جان قتل کی بغیر جان کے بدلے یا زمین میں فساد کیے تو گویا اس نے سب لوگوں کو قتل کیا اور جس نے ایک جان کو جِلا لیا اس نے گویا سب لوگوں کو جلالیا، اور بیشک ان کے پاس ہمارے رسول روشن دلیلوں کے ساتھ آئے پھر بیشک ان میں بہت اس کے بعد زمین میں زیادتی کرنے والے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (702, 5, 33, N'وہ کہ اللہ اور اس کے رسول سے لڑتے اور ملک میں فساد کرتے پھرتے ہیں ان کا بدلہ یہی ہے کہ گن گن کر قتل کیے جائیں یا سولی دیے جائیں یا ان کے ایک طرف کے ہاتھ اور دوسری طرف کے پاؤں کاٹے جائیں یا زمین سے دور کردیے جائیں، یہ دنیا میں ان کی رسوائی ہے، اور آخرت میں ان کے لیے بڑا غداب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (703, 5, 34, N'مگر وہ جنہوں نے توبہ کرلی اس سے پہلے کہ تم ان پر قابو پاؤ تو جان لو کہ اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (704, 5, 35, N'اے ایمان والو! اللہ سے ڈرو اور اس کی طرف وسیلہ ڈھونڈو اور اس کی راہ میں جہاد کرو اس امید پر کہ فلاح پاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (705, 5, 36, N'بیشک وہ جو کافر ہوئے جو کچھ زمین میں ہے سب اور اس کی برابر اور اگر ان کی ملک ہو کہ اسے دے کر قیامت کے عذاب سے اپنی جان چھڑائیں تو ان سے نہ لیا جائے گا اور ان کے لئے دکھ کا عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (706, 5, 37, N'دوزخ سے نکلنا چاہیں گے اور وہ اس سے نہ نکلیں گے اور ان کو دوامی سزا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (707, 5, 38, N'اور جو مرد یا عورت چور ہو تو ان کا ہاتھ کاٹو ان کے کیے کا بدلہ اللہ کی طرف سے سزا، اور اللہ غالب حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (708, 5, 39, N'تو جو اپنے ظلم کے بعد توبہ کرے اور سنور جائے تو اللہ اپنی مہر سے اس پر رجوع فرمائے گا بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (709, 5, 40, N'کیا تجھے معلوم نہیں کہ اللہ کے لئے ہے آسمانوں اور زمین کی بادشاہی، سزا دیتا ہے جسے چاہے اور بخشتا ہے جسے چاہے، اور اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (710, 5, 41, N'اے رسول! تمہیں غمگین نہ کریں وہ جو کفر پڑ دوڑتے ہیں جو کچھ وہ اپنے منہ سے کہتے ہیں ہم ایمان لائے اور ان کے دل مسلمان نہیں اور کچھ یہودی جھوٹ خوب سنتے ہیں اور لوگوں کی خوب سنتے ہیں جو تمہارے پاس حاضر نہ ہوئے اللہ کی باتوں کو ان کے ٹھکانوں کے بعد بدل دیتے ہیں، کہتے ہیں یہ حکم تمہیں ملے تو مانو اور یہ نہ ملے تو بچو اور جسے اللہ گمراہ کرنا چاہے تو ہرگز تو اللہ سے اس کا کچھ بنا نہ سکے گا، وہ ہیں کہ اللہ نے ان کا دل پاک کرنا نہ چاہا، انہیں دنیا میں رسوائی ہے، اور انہیں آخرت میں بڑا عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (711, 5, 42, N'بڑے جھوٹ سننے والے بڑے حرام خور تو اگر تمہارے حضور حاضر ہوں تو ان میں فیصلہ فرماؤ یا ان سے منہ پھیرلو اور اگر تم ان سے منہ پھیرلو گے تو وہ تمہارا کچھ نہ بگاڑیں گے اور اگر ان میں فیصلہ فرماؤ تو انصاف سے فیصلہ کرو، بیشک انصاف والے اللہ کو پسند ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (712, 5, 43, N'اور وہ تم سے کیونکر فیصلہ چاہیں گے، حالانکہ ان کے پاس توریت ہے جس میں اللہ کا حکم موجود ہے بایں ہمہ اسی سے منہ پھیرتے ہیں اور وہ ایمان لانے والے نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (713, 5, 44, N'بیشک ہم نے توریت اتاری اس میں ہدایت اور نور ہے، اس کے مطابق یہود کو حکم دیتے تھے ہمارے فرمانبردار نبی اور عالم اور فقیہہ کہ ان سے کتاب اللہ کی حفاظت چاہی گئی تھی اور وہ اس پر گواہ تھے تو لوگوں سے خوف نہ کرو اور مجھ سے ڈرو اور میری آیتوں کے بدلے ذلیل قیمت نہ لو اور جو اللہ کے اتارے پر حکم نہ کرے وہی لوگ کافر ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (714, 5, 45, N'اور ہم نے توریت میں ان پر واجب کیا کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور زخموں میں بدلہ ہے پھر جو دل کی خوشی سے بدلہ کراوے تو وہ اس کا گناہ اتار دے گا اور جو اللہ کے اتارے پر حکم نہ کرے تو وہی لوگ ظالم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (715, 5, 46, N'اور ہم ان نبیوں کے پیچھے ان کے نشانِ قدم پر عیسیٰ بن مریم کو لائے تصدیق کرتا ہوا توریت کی جو اس سے پہلے تھی اور ہم نے اسے انجیل عطا کی جس میں ہدایت اور نور ہے اور تصدیق فرماتی ہے توریت کی کہ اس سے پہلی تھی اور ہدایت اور نصیحت پرہیزگاروں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (716, 5, 47, N'اور چاہئے کہ انجیل والے حکم کریں اس پر جو اللہ نے اس میں اتارا اور جو اللہ کے اتارے پر حکم نہ کریں تو وہی لوگ فاسق ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (717, 5, 48, N'اور اے محبوب ہم نے تمہاری طرف سچی کتاب اتاری اگلی کتابوں کی تصدیق فرماتی اور ان پر محافظ و گواہ تو ان میں فیصلہ کرو اللہ کے اتارے سے اور اسے سننے والے ان کی خواہشوں کی پیروی نہ کرنا اپنے پاس آیا ہوا حق چھوڑ کر، ہم نے تم سب کے لیے ایک ایک شریعت اور راستہ رکھا اور اللہ چاہتا تو تم سب کو ایک ہی امت کردیتا مگر منظور یہ ہے کہ جو کچھ تمہیں دیا اس میں تمہیں آزمائے تو بھلائیوں کی طرف سبقت چاہو، تم سب کا پھرنا اللہ ہی کی طرف ہے تو وہ تمہیں بتادے گا جس بات میں تم جھگڑتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (718, 5, 49, N'اور یہ کہ اے مسلمان! اللہ کے اتارے پر حکم کر اور ان کی خواہشوں پر نہ چل اور ان سے بچتا رہ کہ کہیں تجھے لغزش نہ دے دیں کسی حکم میں جو تیری طرف اترا پھر اگر وہ منہ پھیریں تو جان لو کہ اللہ ان کے بعض گناہوں کی سزا ان کو پہنچایا چاہتا ہے اور بیشک بہت آدمی بے حکم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (719, 5, 50, N'تو کیا جاہلیت کا حکم چاہتے ہیں اور اللہ سے بہتر کس کا حکم یقین والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (720, 5, 51, N'اے ایمان والو! یہود و نصاریٰ کو دوست نہ بناؤ وہ آپس میں ایک دوسرے کے دوست ہیں اور تم میں جو کوئی ان سے دوستی رکھے گا تو وہ انہیں میں سے ہے بیشک اللہ بے انصافوں کو راہ نہیں دیتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (721, 5, 52, N'اب تم انہیں دیکھو گے جن کے دلوں میں آزار ہے کہ یہود و نصاریٰ کی طرف دوڑتے ہیں کہتے ہیں ہم ڈرتے ہیں کہ ہم پر کوئی گردش آجائے تو نزدیک ہے کہ اللہ فتح لائے یا اپنی طرف سے کوئی حکم پھر اس پر جو اپنے دلوں میں چھپایا تھا پچھتائے رہ جائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (722, 5, 53, N'اور ایمان والے کہتے ہیں کیا یہی ہیں جنہوں نے اللہ کی قسم کھائی تھی اپنے حلف میں پوری کوشش سے کہ وہ تمہارے ساتھ ہیں ان کا کیا دھرا سب اکارت گیا تو رہ گئے نقصان میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (723, 5, 54, N'اے ایمان والو! تم میں جو کوئی اپنے دین سے پھرے گا تو عنقریب اللہ ایسے لوگ لائے گا کہ وہ اللہ کے پیارے اور اللہ ان کا پیارا مسلمانوں پر نرم اور کافروں پر سخت اللہ کی راہ میں لڑیں گے اور کسی ملامت کرنے والے کی ملامت کا اندیشہ نہ کریں گے یہ اللہ کا فضل ہے جسے چاہے دے، اور اللہ وسعت والا علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (724, 5, 55, N'تمہارے دوست نہیں مگر اللہ اور اس کا رسول اور ایمان والے کہ نماز قائم کرتے ہیں اور زکوٰة دیتے ہیں اور اللہ کے حضور جھکے ہوئے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (725, 5, 56, N'اور جو اللہ اور اس کے رسول اور مسلمانوں کو اپنا دوست بنائے تو بیشک اللہ ہی کا گروہ غالب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (726, 5, 57, N'اے ایمان والو! جنہوں نے تمہارے دین کو ہنسی کھیل بنالیا ہے وہ جو تم سے پہلے کتاب دیے گئے اور کافر ان میں کسی کو اپنا دوست نہ بناؤ اور اللہ سے ڈرتے رہو اگر ایمان رکھتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (727, 5, 58, N'اور جب تم نماز کے لئے اذان دو تو اسے ہنسی کھیل بناتے ہیں یہ اس لئے کہ وہ نرے بے عقل لوگ ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (728, 5, 59, N'تم فرماؤ اے کتابیوں تمہیں ہمارا کیا برا لگا یہی نہ کہ ہم ایمان لائے اللہ پر اور اس پر جو ہماری طرف اترا اور اس پر جو پہلے اترا اور یہ کہ تم میں اکثر بے حکم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (729, 5, 60, N'تم فرماؤ کیا میں بتادوں جو اللہ کے یہاں اس سے بدتر درجہ میں ہیں وہ جن پر اللہ نے لعنت کی اور ان پر غضب فرمایا اور ان میں سے کردیے بندر اور سور اور شیطان کے پجاری ان کا ٹھکانا زیادہ برا ہے اور یہ سیدھی راہ سے زیادہ بہکے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (730, 5, 61, N'اور جب تمہارے پاس آئیں ہم مسلمان ہیں اور وہ آتے وقت بھی کافر تھے اور جاتے وقت بھی کافر، اور اللہ خوب جانتا ہے جو چھپا رہے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (731, 5, 62, N'اور ان میں تم بہتوں کو دیکھو گے کہ گناہ اور زیادتی اور حرام خوری پر دوڑتے ہیں بیشک بہت ہی برے کام کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (732, 5, 63, N'انہیں کیوں نہیں منع کرتے ان کے پادری اور درویش گناہ کی بات کہنے اور حرام کھانے سے، بیشک بہت ہی برے کام کررہے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (733, 5, 64, N'اور یہودی بولے اللہ کا ہاتھ بندھا ہوا ہے ان کے ہاتھ باندھے جائیں اور ان پر اس کہنے سے لعنت ہے بلکہ اس کے ہاتھ کشادہ ہیں عطا فرماتا ہے جیسے چاہے اور اے محبوب! یہ جو تمہاری طرف تمہارے رب کے پاس سے اترا اس سے ان میں بہتوں کو شرارت اور کفر میں ترقی ہوگی اور ان میں ہم نے قیامت تک آپس میں دشمنی اور بیر ڈال دیا جب کبھی لڑائی کی آگ بھڑکاتے ہیں اللہ اسے بجھا دیتا ہے اور زمین میں فساد کے لیے دوڑتے پھرتے ہیں، اور اللہ فسادیوں کو نہیں چاہتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (734, 5, 65, N'اور اگر کتاب والے ایمان لاتے اور پرہیزگاری کرتے تو ضرور ہم ان کے گناہ اتار دیتے اور ضرور انہیں چین کے باغوں میں لے جاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (735, 5, 66, N'اور اگر وہ قائم رکھتے توریت اور انجیل اور جو کچھ ان کی طرف ان کے رب کی طرف سے اترا تو انہیں رزق ملتا اوپر سے اور ان کے پاؤں کے نیچے سے ان میں کوئی گروہ اگر اعتدال پر ہے اور ان میں اکثر بہت ہی برے کام کررہے ہیں')
