INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (740, 5, 71, N'اور اس گمان میں ہیں کہ کوئی سزا نہ ہوگی تو اندھے اور بہرے ہوگئے پھر اللہ نے ان کی توبہ قبول کی پھر ان میں بہتیرے اندھے اور بہرے ہوگئے اور اللہ ان کے کام دیکھ رہا ہے،')
