INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (742, 5, 73, N'بیشک کافر ہیں وہ جو کہتے ہیں اللہ تین خداؤں میں کا تیسرا ہے اور خدا تو نہیں مگر ایک خدا اور اگر اپنی بات سے باز نہ آئے تو جو ان میں کافر مریں گے ان کو ضرور دردناک عذاب پہنچے گا،')
