INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (744, 5, 75, N'مسیح بن مریم نہیں مگر ایک رسول اس سے پہلے بہت رسول ہو گزرے اور اس کی ماں صدیقہ ہے دونوں کھانا کھاتے تھے دیکھو تو ہم کیسی صاف نشانیاں ان کے لئے بیان کرتے ہیں پھر دیکھو وہ کیسے اوندھے جاتے ہیں،')
