INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (746, 5, 77, N'تم فرماؤ اے کتاب والو! اپنے دین میں ناحق زیادتی نہ کرو اور ایسے لوگوں کی خواہش پر نہ چلو جو پہلے گمراہ ہوچکے اور بہتوں کو گمراہ کیا اور سیدھی راہ سے بہک گئے')
