INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (752, 5, 83, N'اور جب سنتے ہیں وہ جو رسول کی طرف اترا تو ان کی آنکھیں دیکھو کہ آنسوؤں سے ابل رہی ہیں اس لیے کہ وہ حق کو پہچان گئے، کہتے ہیں اے رب ہمارے! ہم ایمان لائے تو ہمیں حق کے گواہوں میں لکھ لے')
