INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (754, 5, 85, N'تو اللہ نے ان کے اس کہنے کے بدلے انہیں باغ دیے جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں گے، یہ بدلہ ہے نیکوں کا')
