INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (755, 5, 86, N'اور وہ جنہوں کفر کیا اور ہماری آیتیں جھٹلائیں وہ ہیں دوزخ والے،')
