INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (756, 5, 87, N'اے ایمان والو! حرام نہ ٹھہراؤ وہ ستھری چیزیں کہ اللہ نے تمہارے لیے حلال کیں اور حد سے نہ بڑھو، بیشک حد سے بڑھنے والے اللہ کو ناپسند ہیں،')
