INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (758, 5, 89, N'اللہ تمہیں نہیں پکڑتا تمہاری غلط فہمی کی قسموں پر ہاں ان قسموں پر گرفت فرماتے ہے جنہیں تم نے مضبوط کیا تو ایسی قسم کا بدلہ دس مسکینوں کو کھانا دینا اپنے گھر والوں کو جو کھلاتے ہو اس کے اوسط میں سے یا انہیں کپڑے دینا یا ایک بردہ آزاد کرنا تو جو ان میں سے کچھ نہ پائے تو تین دن کے روزے یہ بدلہ ہے تمہاری قسموں کا، جب قسم کھاؤ اور اپنی قسموں کی حفاظت کرو اسی طرح اللہ تم سے اپنی آیتیں بیان فرماتا ہے کہ کہیں تم احسان مانو،')
