INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (759, 5, 90, N'اے ایمان والو! شراب اور جوا اور بت اور پانسے ناپاک ہی ہیں شیطانی کام تو ان سے بچتے رہنا کہ تم فلاح پاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (760, 5, 91, N'شیطان یہی چاہتا ہے کہ تم میں بَیر اور دشمنی ڈلوا دے شراب اور جوئے میں اور تمہیں اللہ کی یاد اور نماز سے روکے تو کیا تم باز آئے،')
