INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (765, 5, 96, N'حلال ہے تمہارے لیے دریا کا شکار اور اس کا کھانا تمہارے اور مسافروں کے فائدے کو اور تم پرحرام ہے خشکی کا شکار جب تک تم احرام میں ہو اور اللہ سے ڈرو جس کی طرف تمہیں اٹھنا ہے،')
