INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (767, 5, 98, N'جان رکھو کہ اللہ کا عذاب سخت ہے اور اللہ بخشنے والا مہربان،')
