INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (770, 5, 101, N'اے ایمان والو! ایسی باتیں نہ پوچھو جو تم پر ظاہر کی جائیں تو تمہیں بری لگیں اور اگر انہیں اس وقت پوچھو گے کہ قرآن اتر رہا ہے تو تم پر ظاہر کردی جائیں گی، اللہ انہیں معاف کرچکا ہے اور اللہ بخشنے والا حلم والا ہے،')
