INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (771, 5, 102, N'تم سے اگلی ایک قوم نے انہیں پوچھا پھر ان سے منکر ہو بیٹھے،')
