INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (772, 5, 103, N'اللہ نے مقرر نہیں کیا ہے کان چِرا ہوا اور نہ بجار اور نہ وصیلہ اور نہ حامی ہاں کافر لوگ اللہ پر جھوٹا افترا باندھتے ہیں اور ان میں اکثر نرے بے عقل ہیں')
