INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (773, 5, 104, N'اور جب ان سے کہا جائے آؤ اس طرف جو اللہ نے اُتارا اور رسول کی طرف کہیں ہمیں وہ بہت ہے جس پر ہم نے اپنے باپ دادا کو پایا، کیا اگرچہ ان کے باپ دادا نہ کچھ جانیں نہ راہ پر ہوں')
