INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (898, 6, 109, N'اور انہوں نے اللہ کی قسم کھائی اپنے حلف میں پوری کوشش سے کہ اگر ان کے پاس کوئی نشانی آئی تو ضرور اس پر ایمان لائیں گے، م فرما دو کہ نشانیاں تو اللہ کے پاس ہیں اور تمہیں کیا خبر کہ جب وہ آئیں تو یہ ایمان نہ لائینگے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (899, 6, 110, N'اور ہم پھیردیتے ہیں ان کے دلوں اور آنکھوں کو جیسا وہ پہلی بار ایمان نہ لائے تھے اور انہیں چھوڑ دیتے ہیں کہ اپنی سرکشی میں بھٹکا کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (900, 6, 111, N'اور اگر ہم ان کی طرف فرشتے اُتارتے اور ان سے مردے باتیں کرتے اور ہم ہر چیز ان کے سامنے اٹھا لاتے جب بھی وہ ایمان لانے والے نہ تھے مگر یہ کہ خدا چاہتا و لیکن ان میں بہت نرے جاہل ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (901, 6, 112, N'اور اسی طرح ہم نے ہر نبی کے دشمن کیے ہیں آدمیوں اور جنوں میں کے شیطان کہ ان میں ایک دوسرے پر خفیہ ڈالتا ہے بناوٹ کی بات دھوکے کو، اور تمہارا رب چاہتا تو وہ ایسا نہ کرتے تو انہیں ان کی بناوٹوں پر چھوڑ دو')
