INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (909, 6, 120, N'اور چھوڑ دو کھلا اور چھپا گناہ، وہ جو گناہ کماتے ہیں عنقریب اپنی کمائی کی سزا پائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (910, 6, 121, N'اور اُسے نہ کھاؤ جس پر اللہ کا نام نہ لیا گیا اور وہ بیشک حکم عدولی ہے، اور بیشک شیطان اپنے دوستوں کے دلوں میں ڈالتے ہیں کہ تم سے جھگڑیں اور اگر تم ان کا کہنا مانو تو اس وقت تم مشرک ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (911, 6, 122, N'اور کیا وہ کہ مردہ تھا تو ہم نے اسے زندہ کیا اور اس کے لیے ایک نور کردیا جس سے لوگوں میں چلتا ہے وہ اس جیسا ہوجائے گا جو اندھیریوں میں ہے ان سے نکلنے والا نہیں، یونہی کافروں کی آنکھ میں ان کے اعمال بھلے کردیے گئے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (912, 6, 123, N'اور اسی طرح ہم نے ہر بستی میں اس کے مجرموں کے سرغنہ کیے کہ اس میں داؤ کھیلیں اور داؤں نہیں کھیلتے مگر اپنی جانوں پر اور انہیں شعورنہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (913, 6, 124, N'اور جب ان کے پاس کوئی نشانی آئے تو کہتے ہی ہم ہر گز ایمان نہ لائیں گے جب تک ہمیں بھی ویسا ہی نہ ملے جیسا اللہ کے رسولوں کو ملا اللہ خوب جانتا ہے جہاں اپنی رسالت رکھے عنقریب مجرموں کو اللہ کے یہاں ذلت پہنچے گی اور سخت عذاب بدلہ ان کے مکر کا،')
