INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (915, 6, 126, N'اور یہ تمہارے رب کی سیدھی راہ ہے ہم نے آیتیں مفصل بیان کردیں نصیحت ماننے والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (916, 6, 127, N'ان کے لیے سلامتی کا گھر ہے اپنے رب کے یہاں اور وہ ان کا مولیٰ ہے یہ ان کے کاموں کا پھل ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (917, 6, 128, N'اور جس دن اُن سب کو اٹھانے گا اور فرمائے گا، اے جن کے گروہ! تم نے بہت آدمی گھیرلیے اور ان کے دوست آدمی عرض کریں گے اے ہمارے رب! ہم میں ایک نے دوسرے سے فائدہ اٹھایا اور ہم اپنی اس میعاد کو پہنچ گئے جو تو نے ہمارے لیے مقرر فرمائی تھی فرمائے گا آگ تمہارا ٹھکانا ہے ہمیشہ اس میں رہو مگر جسے خدا چاہے اے محبوب! بیشک تمہارا رب حکمت والا علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (918, 6, 129, N'اور یونہی ہم ظالموں میں ایک کو دوسرے پر مسلط کرتے ہیں بدلہ ان کے کیے کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (919, 6, 130, N'اے جنوں اور آدمیوں کے گروہ! کیا تمہارے پاس تم میں کے رسول نہ آئے تھے تم پر میری آیتیں پڑھتے اور تمہیں یہ دن دیکھنے سے ڈراتے کہیں گے ہم نے اپنی جانوں پر گواہی دی اور انہیں دنیا کی زندگی نے فریب دیا اور خود اپنی جانوں پر گواہی دیں گے کہ وہ کافر تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (920, 6, 131, N'یہ اس لیے کہ تیرا رب بستیوں کو ظلم سے تباہ نہیں کرتا کہ ان کے لوگ بے خبر ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (921, 6, 132, N'اور ہر ایک کے لیے ان کے کاموں سے درجے ہیں اور تیرا رب ان کے اعمال سے بے خبر نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (922, 6, 133, N'اور اے محبوب! تمہارا رب بے پروا ہے رحمت والا، اے لوگو! وہ چاہے تو تمہیں لے جائے اور جسے چاہے تمہاری جگہ لادے جیسے تمہیں اوروں کی اولاد سے پیدا کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (923, 6, 134, N'بیشک جس کا تمہیں وعدہ دیا جاتا ہے ضرور آنے والی ہے اور تم تھکا نہیں سکتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (924, 6, 135, N'تم فرماؤ اے میری قوم! تم اپنی جگہ پر کام کیے جاؤ میں اپنا کام کرتا ہوں تو اب جاننا چاہتے ہو کس کا رہتا ہے آحرت کا گھر، بیشک ظالم فلاح نہیں پاتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (925, 6, 136, N'اور اللہ نے جو کھیتی اور مویشی پیدا کیے ان میں اسے ایک حصہ دار ٹھہرایا تو بولے یہ اللہ کا ہے ان کے خیال میں اور یہ ہمارے شریکوں کا تو وہ جو ان کے شریکوں کا ہے وہ تو خدا کو نہیں پہنچتا، اور جو خدا کا ہے وہ ان کے شریکوں کو پہنچتا ہے، کیا ہی برا حکم لگاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (926, 6, 137, N'اور یوں ہی بہت مشرکوں کی نگاہ میں ان کے شریکوں نے اولاد کا قتل بھلا کر دکھایا ہے کہ انہیں ہلاک کریں اور ان کا دین اُن پر مشتبہ کردیں اور اللہ چاہتا تو ایسا نہ کرتے تو تم انہیں چھوڑ دو وہ ہیں اور ان کے افتراء،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (927, 6, 138, N'اور بولے یہ مویشی اور کھیتی روکی ہوئی ہے اسے وہی کھائے جسے ہم چاہیں اپنے جھوٹے خیال سے اور کچھ مویشی ہیں جن پر چڑھنا حرام ٹھہرایا اور کچھ مویشی کے ذبح پر اللہ کا نام نہیں لیتے یہ سب اللہ پر جھوٹ باندھنا ہے، عنقریب وہ انہیں بدلے دے گا ان کے افتراؤں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (928, 6, 139, N'اور بولے جو ان مویشیوں کے پیٹ میں ہے وہ نرا (خالص) ہمارے مردوں کا ہے اور ہماری عورتوں پر حرام ہے، اور مرا ہوا نکلے تو وہ سب اس میں شریک ہیں، قریب ہے کہ اللہ انہیں اِن کی اُن باتوں کا بدلہ دے گا، بیشک وہ حکمت و علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (929, 6, 140, N'بیشک تباہ ہوئے وہ جو اپنی اولاد کو قتل کرتے ہیں احمقانہ جہالت سے اور حرام ٹھہراتے ہیں وہ جو اللہ نے انہیں روزی دی اللہ پر جھوٹ باندھنے کو بیشک وہ بہکے اور راہ نہ پائی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (930, 6, 141, N'اور وہی ہے جس نے پیدا کیے باغ کچھ زمین پر چھئے (چھائے) ہوئے اور کچھ بے چھئے (پھیلے) اور کھجور اور کھیتی جس میں رنگ رنگ کے کھانے اور زیتون اور انار کسی بات میں ملتے اور کسی میں الگ کھاؤ اس کا پھل جب پھل لائے اور اس کا حق دو جس دن کٹے اور بے جا نہ خرچو بیشک بے جا خرچنے والے اسے پسند نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (931, 6, 142, N'اور مویشی میں سے کچھ بوجھ اٹھانے والے اور کچھ زمین پر بچھے کھاؤ اس میں سے جو اللہ نے تمہیں روزی دی اور شیطان کے قدموں پر نہ چلو، بیشک وہ تمہارا صریح دشمن ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (932, 6, 143, N'آٹھ نر و مادہ ایک جوڑا بھیڑ کا اور ایک جوڑا بکری کا، تم فرماؤ کیا اس نے دونوں نر حرام کیے یا دونوں مادہ یا وہ جسے دنوں مادہ پیٹ میں لیے ہیں کسی علم سے بتاؤ اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (933, 6, 144, N'اور ایک جوڑا اونٹ کا اور ایک جوڑا گائے کا، تم فرماؤ کیا اس نے دونوں نر حرام کیے یا دونوں مادہ یا وہ جسے دونوں مادہ پیٹ میں لیے ہیں کیا تم موجود تھے جب اللہ نے تمہیں یہ حکم دیا تو اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے کہ لوگوں کو اپنی جہالت سے گمراہ کرے، بیشک اللہ ظالموں کو راہ نہیں دکھاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (934, 6, 145, N'تم فرماؤ میں نہیں پاتا اس میں جو میری طرف وحی ہوئی کسی کھانے والے پر کوئی کھانا حرام مگر یہ کہ مردار ہو یا رگوں کا بہتا خون یا بد جانور کا گوشت وہ نجاست ہے یا وہ بے حکمی کا جانور جس کے ذبح میں غیر خدا کا نام پکارا گیا تو جو ناچار ہوا نہ یوں کہ آپ خواہش کرے اور نہ یوں کہ ضرورت سے بڑھے تو بے شیک اللہ بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (935, 6, 146, N'اور یہودیوں پر ہم نے حرام کیا ہر ناخن والا جانور اور گائے اور بکری کی چربی ان پر حرام کی مگر جو ان کی پیٹھ میں لگی ہو یا آنت یا ہڈی سے ملی ہو، ہم نے یہ ان کی سرکشی کا بدلہ دیا اور بیشک ہم ضرور سچے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (936, 6, 147, N'پھر اگر وہ تمہیں جھٹلائیں تو تم فرماؤ کہ تمہارا رب وسیع رحمت والا ہے اور اس کا عذاب مجرموں پر سے نہیں ٹالا جاتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (937, 6, 148, N'اب کہیں گے مشرک کہ اللہ چاہتا تو نہ ہم شرک کرتے نہ ہمارے باپ دادا نہ ہم کچھ حرام ٹھہراتے ایسا ہی ان کے اگلوں نے جھٹلایا تھا یہاں تک کہ ہمارا عذاب چکھا تم فرماؤ کیا تمہارے پاس کوئی علم ہے کہ اسے ہمارے لیے نکالو، تم تو نرے گمان (خام خیال) کے پیچھے ہو اور تم یونہی تخمینے کرتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (938, 6, 149, N'تم فرماؤ تو اللہ ہی کی حجت پوری ہے تو وہ چاہتا تو سب کی ہدایت فرماتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (939, 6, 150, N'تم فرماؤ لاؤ اپنے وہ گواہ جو گواہی دیں کہ اللہ نے اسے حرام کیا پھر اگر وہ گواہی دے بیٹھیں تو تُو اے سننے والے! ان کے ساتھ گواہی نہ دینا اور ان کی خواہشوں کے پیچھے نہ چلنا جو ہماری آیتیں جھٹلاتے ہیں اور جو آخرت پر ایمان نہیں لاتے اور اپنے رب کا برابر والا ٹھہراتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (940, 6, 151, N'تم فرماؤ آؤ میں تمہیں پڑھ کر سناؤں جو تم پر تمہارے رب نے حرام کیا یہ کہ اس کا کوئی شریک نہ کرو اور ماں باپ کے ساتھ بھلائی کرو اور اپنی اولاد قتل نہ کرو مفلسی کے باعث، ہم تمہیں اور انہیں سب کو رزق دیں گے اور بے حیائیوں کے پاس نہ جاؤ جو ان میں کھلی ہیں اور جو چھپی اور جس جان کی اللہ نے حرمت رکھی اسے ناحق نہ مارو یہ تمہیں حکم فرمایا ہے کہ تمہیں عقل ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (941, 6, 152, N'اور یتیموں کے مال کے پاس نہ جاؤ مگر بہت اچھے طریقہ سے جب تک وہ اپنی جوانی کو پہنچے اور ناپ اور تول انصاف کے ساتھ پوری کرو، ہم کسی جان پر بوجھ نہیں ڈالتے مگر اس کے مقدور بھر، اور جب بات کہو تو انصاف کی کہو اگرچہ تمہارے رشتہ دار کا معاملہ ہو اور اللہ ہی کا عہد پورا کرو، یہ تمہیں تاکید فرمائی کہ کہیں تم نصیحت مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (942, 6, 153, N'اور یہ کہ یہ ہے میرا سیدھا راستہ تو اس پر چلو اور اور راہیں نہ چلو کہ تمہیں اس کی راہ سے جدا کردیں گی، یہ تمہیں حکم فرمایا کہ کہیں تمہیں پرہیزگاری ملے،')
