INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (943, 6, 154, N'پھر ہم نے موسیٰ کو کتاب عطا فرمائی پورا احسان کرنے کو اس پر جو نیکوکار ہے اور ہر چیز کی تفصیل اور ہدایت اور رحمت کہ کہیں وہ اپنے رب سے ملنے پر ایمان لائیں')
