INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (947, 6, 158, N'کاہے کے انتظار میں ہیں مگر یہ کہ آئیں ان کے پاس فرشتے یا تمہارے رب کا عذاب یا تمہارے رب کی ایک نشانی آئے جس دن تمہارے رب کی وہ ایک نشانی آئے گی کسی جان کو ایمان لانا کام نہ دے گا جو پہلے ایمان نہ لائی تھی یا اپنے ایمان میں کوئی بھلائی نہ کمائی تھی تم فرماؤ رستہ دیکھو ہم بھی دیکھتے ہیں،')
