INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (973, 7, 19, N'اور اے آدم تو اور تیرا جوڑا جنت میں رہو تو اُس سے جہاں چاہو کھاؤ اور اس پیڑ کے پاس نہ جانا کہ حد سے بڑھنے والوں میں ہو گے،')
