INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (976, 7, 22, N'تو اُتار لایا انہیں فریب سے پھر جب انہوں نے وہ پیڑ چکھا ان پر اُن کی شرم کی چیزیں کھل گئیں اور اپنے بدن پر جنت کے پتے چپٹانے لگے، اور انہیں ان کے رب نے فرمایا کیا میں نے تمہیں اس پیڑ سے منع نہ کیا اور نہ فرمایا تھا کہ شیطان تمہارا کھلا دشمن ہے،')
