INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (986, 7, 32, N'تم فرماؤ کس نے حرام کی اللہ کی وہ زینت جو اس نے اپنے بندو ں کے لیے نکالی اور پاک رزق تم فرماؤ کہ وہ ایمان والوں کے لیے ہے دنیا میں اور قیامت میں تو خاص انہی کی ہے، ہم یونہی مفصل آیتیں بیان کرتے ہیں علم والوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (987, 7, 33, N'تم فرماؤ میرے رب نے تو بے حیائیاں حرام فرمائی ہیں جو ان میں کھلی ہیں اور جو چھپی اور گناہ اور ناحق زیادتی اور یہ کہ اللہ کا شریک کرو جس کی اس نے سند نہ اتاری اور یہ کہ اللہ پر وہ بات کہو جس کا علم نہیں رکھتے،')
