INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (988, 7, 34, N'اور ہر گروہ کا ایک وعدہ ہے تو جب ان کا وعدہ آئے گا ایک گھڑی نہ پیچھے ہو نہ آگے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (989, 7, 35, N'اے آدم کی اولاد! اگر تمہارے پاس تم میں کے رسول آئیں میری آیتیں پڑھتے تو جو پرہیزگاری کرے اور سنورے تو اس پر نہ کچھ خوف اور نہ کچھ غم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (990, 7, 36, N'اور جنہوں نے ہماری آیتیں جھٹلائیں اور ان کے مقابل تکبر کیا وہ دوز خی ہیں انہیں اس میں ہمیشہ رہنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (991, 7, 37, N'تو اس سے بڑھ کر ظالم کون جس نے اللہ پر جھوٹ باندھا یا اس کی آیتیں جھٹلائیں، انہیں ان کے نصیب کا لکھا پہنچے گا یہاں تک کہ جب ان کے پاس ہمارے بھیجے ہوئے ان کی جان نکالنے آئیں تو ان سے کہتے ہیں کہاں ہیں وہ جن کو تم اللہ کے سوا پوجتے تھے، کہتے ہیں وہ ہم سے گم گئے اور اپنی جانوں پر آپ گواہی دیتے ہیں کہ وہ کافر تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (992, 7, 38, N'اللہ ان سے فرماتا ہے کہ تم سے پہلے جو اور جماعتیں جن اور آدمیوں کی آگ میں گئیں، انہیں میں جاؤ جب ایک گروہ داخل ہوتا ہے دوسرے پر لعنت کرتا ہے یہاں تک کہ جب سب اس میں جا پڑے تو پچھلے پہلوں کو کہیں گے اے رب ہمارے! انہوں نے ہم کو بہکایا تھا تو انہیں آگ کا دُونا عذاب دے، فرمائے گا سب کو دُونا ہے مگر تمہیں خبر نہیں')
