INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (993, 7, 39, N'اور پہلے پچھلوں سے کہیں گے تو تم کچھ ہم سے اچھے نہ رہے تو چکھو عذاب بدلہ اپنے کیے کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (994, 7, 40, N'وہ جنہوں نے ہماری آیتیں جھٹلائیں اور ان کے مقابل تکبر کیا ان کے لیے آسمان کے دروازے نہ کھولے جائیں گے اور نہ وہ جنت میں داخل ہوں جب تک سوئی کے ناکے اونٹ داخل نہ ہو اور مجرموں کو ہم ایسا ہی بدلہ دیتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (995, 7, 41, N'انہیں آگ ہی بچھونا اور آگ ہی اوڑھنا اور ظالموں کو ہم ایسا ہی بدلہ دیتے ہیں،')
