INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (996, 7, 42, N'اور وہ جو ایمان لائے اور طاقت بھر اچھے کام کیے ہم کسی پر طاقت سے زیادہ بوجھ نہیں رکھتے، وہ جنت والے ہیں، انہیں اس میں ہمیشہ رہنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (997, 7, 43, N'اور ہم نے ان کے سینوں سے کینے کھینچ لیے ان کے نیچے نہریں بہیں گی اور کہیں گے سب خوبیاں اللہ کو جس نے ہمیں اس کی راہ دکھائی اور ہم راہ نہ پاتے اگر اللہ ہمیں راہ نہ دکھاتا، بیشک ہمارے رب کے رسول حق لائے اور ندا ہوئی کہ یہ جنت تمہیں میراث ملی صلہ تمہارے اعمال کا،')
