INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (998, 7, 44, N'اور جنت والوں نے دوزخ والوں کو پکارا کہ ہمیں تو مل گیا جو سچا وعدہ ہم سے ہمارے رب نے کیا تھا تو کیا تم نے بھی پایا جو تمہارے رب نے سچا وعدہ تمہیں دیا تھا بولے، ہاں! اور بیچ میں منادی نے پکار دیا کہ اللہ کی لعنت ظالموں پر')
