INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (999, 7, 45, N'جو اللہ کی راہ سے روکتے ہیں اور اسے کجی چاہتے ہیں اور آخرت کا انکار رکھتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1000, 7, 46, N'اور جنت و دوزخ کے بیچ میں ایک پردہ ہے اور اعراف پر کچھ مرد ہوں گے کہ دونوں فریق کو ان کی پیشانیوں سے پہچانیں گے اور وہ جنتیوں کو پکاریں گے کہ سلام تم پر یہ جنت میں نہ گئے اور اس کی طمع رکھتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1001, 7, 47, N'اور جب ان کی آنکھیں دوزخیوں کی طرف پھریں گی کہیں گے اے ہمارے رب! ظالموں کے ساتھ نہ کر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1002, 7, 48, N'اور اعراف والے کچھ مردوں کو پکاریں گے جنہیں ان کی پیشانی سے پہچانتے ہیں کہیں گے تمہیں کیا کام آیا تمہارا جتھا اور وہ جو تم غرور کرتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1003, 7, 49, N'کیا یہ ہیں وہ لوگ جن پر تم قسمیں کھاتے تھے کہ اللہ ان پر اپنی رحمت کچھ نہ کرے گا ان سے تو کہا گیا کہ جنت میں جاؤ نہ تم کو اندیشہ نہ کچھ غم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1004, 7, 50, N'اور دوزخی بہشتیوں کو پکاریں گے کہ ہمیں اپنے پانی کا فیض دو یا اس کھانے کا جو اللہ نے تمہیں دیا کہیں گے بیشک اللہ نے ان دونوں کو کافروں پر حرام کیا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1005, 7, 51, N'جنہوں نے اپنے دین کو کھیل تماشا بنایا اور دنیا کی زیست نے انہیں فریب دیا تو آج ہم انہیں چھوڑ دیں گے جیسا انہوں نے اس دن کے ملنے کا خیال چھوڑا تھا اور جیسا ہماری آیتوں سے انکار کرتے تھے،')
