INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1091, 7, 137, N'اور ہم نے اس قوم کو جو دبا لی گئی تھی اس زمین کے پورب پچھم کا وارث کیا جس میں ہم نے برکت رکھی اور تیرے رب کا اچھا وعدہ بنی اسرائیل پر پورا ہوا، بدلہ ان کے صبر کا، اور ہم نے برباد کردیا جو کچھ فرعون اور اس کی قوم بناتی اور جو چنائیاں اٹھاتے (تعمیر کرتے) تھے،')
