INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1097, 7, 143, N'اور جب موسیٰ ہمارے وعدہ پر حاضر ہوا اور اس سے اس کے رب نے کلام فرمایا عرض کی اے رب میرے! مجھے اپنا دیدار دکھا کہ میں تجھے دیکھوں فرمایا تو مجھے ہر گز نہ دیکھ سکے گا ہاں اس پہاڑ کی طرف دیکھ یہ اگر اپنی جگہ پر ٹھہرا رہا تو عنقریب تو مجھے دیکھ لے گا پھر جب اس کے رب نے پہاڑ پر اپنا نو ر چمکایا اسے پاش پاش کردیا اور موسیٰ گرا بیہوش پھر جب ہوش ہوا بولا پاکی ہے تجھے میں تیری طرف رجوع لایا اور میں سب سے پہلا مسلمان ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1098, 7, 144, N'فرمایا اے موسیٰ میں نے تجھے لوگوں سے چن لیا اپنی رسالتوں اور اپنے کلام سے، تو لے جو میں نے تجھے عطا فرمایا اور شکر والوں میں ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1099, 7, 145, N'اور ہم نے اس کے لیے تختیوں میں لکھ دی ہر چیز کی نصیحت اور ہر چیز کی تفصیل، اور فرمایا اے موسیٰ اسے مضبوطی سے لے اور اپنی قوم کو حکم دے کر اس کی اچھی باتیں اختیار کریں عنقریب میں تمہیں دکھاؤں گا بے حکموں کا گھر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1100, 7, 146, N'اور میں اپنی آیتوں سے انہیں پھیردوں گا جو زمین میں ناحق اپنی بڑا ئی چاہتے ہیں اور اگر سب نشانیاں دیکھیں ان پر ایمان نہ لائیں اور اگر ہدایت کی راہ دیکھیں اس میں چلنا پسند نہ کریں اور گمراہی کا راستہ نظر پڑے تو اس میں چلنے کو موجود ہوجائیں، یہ اس لیے کہ انہوں نے ہماری آیتیں جھٹلائیں اور ان سے بے خبر بنے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1101, 7, 147, N'اور جنہوں نے ہماری آیتیں اور آخرت کے دربار کو جھٹلایا ان کا سب کیا دھرا اَکارت گیا، انہیں کیا بدلہ ملے گا مگر وہی جو کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1102, 7, 148, N'اور موسیٰ کے بعد اس کی قوم اپنے زیوروں سے ایک بچھڑا بنا بیٹھی بے جان کا دھڑ گائے کی طرف آواز کرتا، کیا نہ دیکھا کہ وہ ان سے نہ بات کرتا ہے اور نہ انہیں کچھ راہ بتائے اسے لیا اور وہ ظالم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1103, 7, 149, N'اور جب پچھتائے اور سمجھے کہ ہم بہکے بولے اگر ہمارا رب ہم پر مہر ہ کرے اور ہمیں نہ بخشے تو ہم تباہ ہوئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1104, 7, 150, N'اور جب موسیٰ اپنی قوم کی طرف پلٹا غصہ میں بھرا جھنجلایا ہوا کہا تم نے کیا بری میری جانشینی کی میرے بعد کیا تم نے اپنے رب کے حکم سے جلدی کی اور تختیاں ڈال دیں اور اپنے بھائی کے سر کے بال پکڑ کر اپنی طرف کھینچنے لگا کہا اے میرے ماں جائے قوم نے مجھے کمزور سمجھا اور قریب تھا کہ مجھے مار ڈالیں تو مجھ پر دشمنوں کو نہ ہنسا اور مجھے ظالموں میں نہ ملا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1105, 7, 151, N'عرض کی اے میرے رب! مجھے اور میرے بھائی کو بخش دے اور ہمیں اپنی رحمت کے اندر لے لے اور تو سب مہر والوں سے بڑھ کر مہر والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1106, 7, 152, N'بیشک وہ جو بچھڑا لے بیٹھے عنقریب انہیں ان کے رب کا غضب اور ذلت پہنچناہے دنیا کی زندگی میں، اور ہم ایسی ہی بدلہ دیتے ہیں بہتان ہایوں (باندھنے والوں) کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1107, 7, 153, N'اور جنہوں نے برائیاں کیں اور ان کے بعد توبہ کی اور ایمان لائے تو اس کے بعد تمہارا رب بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1108, 7, 154, N'اور جب موسیٰ کا غصہ تھما تختیاں اٹھالیں اور ان کی تحریر میں ہدایت اور رحمت ہے ان کے لیے جو اپنے رب سے ڈرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1109, 7, 155, N'اور موسیٰ نے اپنی قوم سے سترّ ۷۰، مرد ہمارے وعدہ کے لیے چنے پھر جب انہیں زلزلہ نے لیا موسیٰ نے عرض کی اے رب میرے! تو چاہتا تو پہلے ہی انہیں اور مجھے ہلاک کردیتا کیا تو ہمیں اس کام پر ہلاک فرمائے گا جو ہمارے بے عقلوں نے کیا وہ نہیں مگر تیرا آزمانا، تو اس سے بہکائے جسے چاہے اور راہ دکھائے جسے چاہے تو ہمارا مولیٰ ہے تو ہمیں بخش دے اور ہم پر مہر کر اور تو سب سے بہتر بخشنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1110, 7, 156, N'اور ہمارے لیے اس دنیا میں بھلائی لکھ اور آخرت میں بیشک ہم تیری طرف رجوع لائے، فرمایا میرا عذاب میں جسے چاہوں دوں اور میری رحمت ہر چیز کو گھیرے ہے تو عنقریب میں نعمتوں کو ان کے لیے لکھ دوں گا جو ڈرتے اور زکوٰة دیتے ہیں اور وہ ہماری آیتوں پر ایمان لاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1111, 7, 157, N'وہ جو غلامی کریں گے اس رسول بے پڑھے غیب کی خبریں دینے والے کی جسے لکھا ہوا پائیں گے اپنے پاس توریت اور انجیل میں وہ انہیں بھلائی کا حکم دے گا اور برائی سے منع کرے گا اور ستھری چیزیں ان کے لیے حلال فرمائے گا اور گندی چیزیں ان پر حرام کرے گا اور ان پر سے وہ بوجھ اور گلے کے پھندے جو ان پر تھے اتا رے گا، تو وہ جو اس پر ایمان لائیں اور اس کی تعظیم کریں اور اسے مدد دیں اور اس نور کی پیروی کریں جو اس کے ساتھ اترا وہی بامراد ہوئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1112, 7, 158, N'تم فرماؤ اے لوگو! میں تم سب کی طرف اس اللہ کا رسول ہوں کہ آسمانوں اور زمین کی بادشاہی اسی کو ہے اس کے سوا کوئی معبود نہیں جلائے اور مارے تو ایمان لاؤ اللہ اور اس کے رسول بے پڑھے غیب بتانے والے پر کہ اللہ اور اس کی باتوں پر ایمان لاتے ہیں اور ان کی غلامی کرو کہ تم راہ پاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1113, 7, 159, N'اور موسیٰ کی قوم سے ایک گروہ ہے کہ حق کی راہ بتا تا اور اسی سے انصاف کرتا،')
