INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1114, 7, 160, N'اور ہم نے انہیں بانٹ دیا بارہ قبیلے گروہ گروہ، اور ہم نے وحی بھیجی موسیٰ کو جب اس سے اس کی قوم نے پانی ما نگا کہ اس پتھر پر اپنا عصا مارو تو اس میں سے بارہ چشمے پھوٹ نکلے ہر گروہ نے اپنا گھاٹ پہچان لیا، اور ہم نے ان پر ابر کا سائبان کیا اور ان پر من و سلویٰ اتارا، کھاؤ ہماری دی ہوئی پاک چیزیں اور انہوں نے ہمارا کچھ نقصان نہ کیا لیکن اپنی ہی جانوں کا برا کرتے ہیں،')
