INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1148, 7, 194, N'بیشک وہ جن کو تم اللہ کے سوا پوجتے ہو تمہاری طرح بندے ہیں تو انہیں پکارو پھر وہ تمہیں جواب دیں اگر تم سچے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1149, 7, 195, N'کیا ان کے پاؤں ہیں جن سے چلیں یا ان کے ہاتھ ہیں جن سے گرفت کریں یا ان کے آنکھیں ہیں جن سے دیکھیں یا ان کے کان ہیں جن سے سنیں تم فرماؤ کہ اپنے شریکوں کو پکارو اور مجھ پر داؤ چلو اور مجھے مہلت نہ دو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1150, 7, 196, N'بیشک میرا والی اللہ ہے جس نے کتاب ا تاری اور وہ نیکوں کو دوست رکھتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1151, 7, 197, N'اور جنہیں اس کے سوا پوجتے ہو وہ تمہاری مدد نہیں کرسکتے، اور نہ خود اپنی مدد کریں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1152, 7, 198, N'اور اگر تم انہیں راہ کی طرف بلاؤ تو نہ سنیں اور تو انہیں دیکھے کہ وہ تیری طرف دیکھ رہے ہیں اور انہیں کچھ بھی نہیں سوجھتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1153, 7, 199, N'اے محبوب! معاف کرنا اختیار کرو اور بھلائی کا حکم دو اور جاہلوں سے منہ پھیرلو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1154, 7, 200, N'اور اے سننے والے اگر شیطان تجھے کوئی کونچا دے (کسی برے کام پر اکسائے) تو اللہ کی پناہ مانگ بیشک وہی سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1155, 7, 201, N'بیشک وہ جو ڈر والے ہیں جب انہیں کسی شیطانی خیال کی ٹھیس لگتی ہے ہوشیار ہوجاتے ہیں اسی وقت ان کی آنکھیں کھل جاتی ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1156, 7, 202, N'اور وہ جو شیطانوں کے بھائی ہیں شیطان انہیں گمراہی میں کھینچتے ہیں پھر کمی نہیں کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1157, 7, 203, N'اور اے محبوب! جب تم ان کے پاس کوئی آیت نہ لاؤ تو کہتے ہیں تم نے دل سے کیوں نہ بنائی تم فرما ؤ میں تو اسی کی پیروی کرتا ہوں جو میری طرف میرے رب سے وحی ہوتی ہے یہ تمہارے رب کی طرف سے آنکھیں کھولنا ہے اور ہدایت اور رحمت مسلمانوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1158, 7, 204, N'اور جب قرآن پڑھا جائے تو اسے کان لگا کر سنو اور خاموش رہو کہ تم پر رحم ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1159, 7, 205, N'اور اپنے رب کو اپن ے دل میں یاد کرو زاری اور ڈر سے اور بے آواز نکلے زبان سے صبح اور شام اور غافلوں میں نہ ہونا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1160, 7, 206, N'بیشک وہ جو تیرے رب کے پاس ہیں اس کی عبادت سے تکبر نہیں کرتے اور اس کی پاکی بولتے اور اسی کو سجدہ کرتے ہیں السجدة ۔۵')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1161, 8, 1, N'اے محبوب! تم سے غنیمتوں کو پوچھتے ہیں تم فرماؤ غنیمتوں کے مالک اللہ اور رسول ہیں تو اللہ ڈرو اور اپنے آ پس میں میل (صلح صفائی) رکھو اور اللہ اور رسول کا حکم مانو اگر ایمان رکھتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1162, 8, 2, N'ایمان والے وہی ہیں کہ جب اللہ یاد کیا جائے ان کے دل ڈر جائیں اور جب ان پر اس کی آیتیں پڑھی جائیں ان کا ایمان ترقی پائے اور اپنے رب ہی پر بھروسہ کریں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1163, 8, 3, N'وہ جو نماز قائم رکھیں اور ہمارے دیے سے کچھ ہماری راہ میں خرچ کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1164, 8, 4, N'یہی سچے مسلمان ہیں، ان کے لیے درجے ہیں ان کے رب کے پاس اور بخشش ہے اور عزت کی روزی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1165, 8, 5, N'جس طرح اے محبوب! تمہیں تمہارے رب نے تمہارے گھر سے حق کے ساتھ برآمد کیا اور بیشک مسلمانوں کا ایک گروہ اس پر ناخوش تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1166, 8, 6, N'سچی بات میں تم سے جھگڑتے تھے بعد اس کے کہ ظاہر ہوچکی گویا وہ آنکھوں دیکھی موت کی طرف ہانکے جاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1167, 8, 7, N'اور یاد کرو جب اللہ نے تمہیں وعدہ دیا تھا کہ ان دونوں گروہوں میں ایک تمہارے لیے ہے اور تم یہ چاہتے تھے کہ تمہیں وہ ملے جس میں کانٹے کا کھٹکا نہیں (کوئی نقصان نہ ہو) اور اللہ یہ چاہتا تھا کہ اپنے کلام سے سچ کو سچ کر دکھائے اور کافروں کی جڑ کا ٹ دے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1168, 8, 8, N'کہ سچ کو سچ کرے اور جھوٹ کو جھوٹا پڑے برا مانیں مجرم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1169, 8, 9, N'جب تم اپنے رب سے فریا د کرتے تھے تو اس نے تمہاری سن لی کہ میں تمہیں مدد دینے والا ہوں ہزاروں فرشتوں کی قطار سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1170, 8, 10, N'اور یہ تو اللہ نے کیا مگر تمہاری خوشی کو اور اس لیے کہ تمہارے دل چین پائیں، اور مدد نہیں مگر اللہ کی طرف سے بیشک اللہ غالب حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1171, 8, 11, N'جب اس نے تمہیں اونگھ سے گھیر دیا تو اس کی طرف سے چین (تسکین) تھی اور آسمان سے تم پر پانی اتارا کہ تمہیں اس سے ستھرا کردے اور شیطان کی ناپاکی تم سے دور فرمادے اور تمہارے دلو ں کی ڈھارس بندھائے اور اس سے تمہارے قدم جمادے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1172, 8, 12, N'جب اے محبوب! تمہارا رب فرشتوں کو وحی بھیجتا تھا کہ میں تمہارے ساتھ ہوں تم مسلمانوں کو ثابت رکھو عنقریب میں کافروں کے دلوں میں ہیبت ڈالوں گا تو کافروں کی گردنوں سے اوپر مارو اور ان کی ایک ایک پور (جوڑ) پر ضرب لگا ؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1173, 8, 13, N'یہ اس لیے کہ انہوں نے اللہ اور اس کے رسول سے مخا لفت کی اور جو اللہ اور اس کے رسول سے مخالفت کرے تو بیشک اللہ کا عذاب سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1174, 8, 14, N'یہ تو چکھو اور اس کے ساتھ یہ ہے کہ کافروں کو آ گ کا عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1175, 8, 15, N'اے ایمان والو! جب کافروں کے لام (لشکر) سے تمہارا مقابلہ ہو تو انہیں پیٹھ نہ دو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1176, 8, 16, N'اور جو اس دن انہیں پیٹھ دے گا مگر لڑائی کا ہنرَ کرنے یا اپنی جماعت میں جاملنے کو، تو وہ اللہ کے غضب میں پلٹا اور اس کا ٹھکانا دوزخ ہے، اور کیا بری جگہ ہے پلٹنے کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1177, 8, 17, N'تو تم نے انہیں قتل نہ کیا بلکہ اللہ نے انہیں قتل کیا، اور اے محبوب! وہ خاک جو تم نے پھینکی تھی بلکہ اللہ نے پھینکی اور اس لیے کہ مسلمانوں کو اس سے اچھا انعام عطا فرمائے، بیشک اللہ سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1178, 8, 18, N'یہ تو لو اور اس کے ساتھ یہ ہے کہ اللہ کافروں کا داؤ سست کرنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1179, 8, 19, N'اے کافرو! اگر تم فیصلہ مانگتے ہو تو یہ فیصلہ تم پر آچکا اور اگر با ز ا ٓ ؤ تو تمہارا بھلا ہے اور اگر تم پھر شرارت کرو تو ہم پھر نہ دیں گے اور تمہارا جتھا تمہیں کچھ کام نہ دے گا چاہے کتنا ہی بہت ہو اور اس کے ساتھ یہ ہے کہ اللہ مسلمانوں کے ساتھ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1180, 8, 20, N'اے ایمان والو! اللہ اور اس کے رسول کا حکم مانو اور سن سنا کہ اسے نہ پھرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1181, 8, 21, N'اور ان جیسے نہ ہونا جنہوں نے کہا ہم نے سنا او ر وہ نہیں سنتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1182, 8, 22, N'بیشک سب جانوروں میں بدتر اللہ کے نزدیک وہ ہیں جو بہرے گونگے ہیں جن کو عقل نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1183, 8, 23, N'اور اگر اللہ ان میں کچھ بھلائی جانتا تو انہیں سنادیتا اور اگر سنا دیتا جب بھی انجام کا ر منہ پھیر کر پلٹ جاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1184, 8, 24, N'اے ایمان والو! اللہ اور اس کے رسول کے بلانے پر حاضر ہو جب رسول تمہیں اس چیز کے لیے بلائیں جو تمہیں زندگی بخشے گی اور جان لو کہ اللہ کا حکم آدمی اور اس کے دلی ارادوں میں حائل ہوجا تا ہے اور یہ کہ تمہیں اس کی طرف اٹھنا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1185, 8, 25, N'اور اس فتنہ سے ڈرتے رہو جو ہرگز تم میں خاص ظالموں کو ہی نہ پہنچے گا اور جان لو کہ اللہ کا عذاب سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1186, 8, 26, N'اور یاد کرو جب تم تھوڑے تھے ملک میں دبے ہوئے ڈرتے تھے کہ کہیں لوگ تمہیں اچک نہ لے جائیں تو اس نے تمہیں جگہ دی اور اپنی مدد سے زور دیا اور ستھری چیزیں تمہیں روزی دیں کہ کہیں تم احسان مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1187, 8, 27, N'اے ایمان والو! اللہ اور رسول سے دغا نہ کرو اور نہ اپنی امانتوں میں دانستہ خیانت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1188, 8, 28, N'اور جان رکھو کہ تمہارے مال اور تمہاری اولاد سب فتنہ ہے اور اللہ کے پاس بڑا ثواب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1189, 8, 29, N'اے ایمان والو! اگر اللہ سے ڈرو گے تو تمہیں وہ دیگا جس سے حق کو باطل سے جدا کرلو اور تمہاری برائیاں اتار دے گا اور تمہیں بخش دے گا اور اللہ بڑے فضل والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1190, 8, 30, N'اور اے محبوب یاد کرو جب کافر تمہارے ساتھ مکر کرتے تھے کہ تمہیں بند کرلیں یا شہید کردیں یا نکا ل دیں اپنا سا مکر کرتے تھے اور اللہ اپنی خفیہ تدبیر فرماتا تھا اور اللہ کی خفیہ تدبیر سب سے بہتر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1191, 8, 31, N'اور جب ان پر ہماری آیتیں پڑھی جائیں تو کہتے ہیں ہاں ہم نے سنا ہم چاہتے تو ایسی ہم بھی کہہ دیتے یہ تو نہیں مگر اگلوں کے قصے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1192, 8, 32, N'اور جب بولے کہ اے اللہ اگر یہی (قرآن) تیری طرف سے حق ہے تو ہم پر آسمان سے پتھر برسا یا کوئی دردناک عذاب ہم پر لا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1193, 8, 33, N'اور اللہ کا کام نہیں کہ انہیں عذاب کرے جب تک اے محبوب! تم ان میں تشریف فرما ہو اور اللہ انہیں عذاب کرنے والا نہیں جب تک وہ بخشش مانگ رہے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1194, 8, 34, N'اور انہیں کیا ہے کہ اللہ انہیں عذاب نہ کرے وہ تو مسجد حرام سے روک رہے ہیں اور وہ اس کے اہل نہیں اس کے اولیاء تو پرہیزگار ہی ہیں مگر ان میں اکثر کو علم نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1195, 8, 35, N'اور کعبہ کے پاس ان کی نماز نہیں مگر سیٹی اور تالی تو اب عذاب چکھو بدلہ اپنے کفر کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1196, 8, 36, N'بیشک کافر اپنے مال خرچ کرتے ہیں کہ اللہ کی راہ سے روکیں تو اب انہیں خرچ کریں گے پھر وہ ان پر پچھتاوا ہوں گے پھر مغلوب کردیے جائیں گے اور کافروں کا حشر جہنم کی طرف ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1197, 8, 37, N'اس لیے کہ اللہ گندے کو ستھرے سے جدا فرمادے اور نجاستوں کو تلے اوپر رکھ کر سب ایک ڈھیر بناکر جہنم میں ڈال دے وہی نقصان پانے والے ہیں')
