INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1198, 8, 38, N'تم کافروں سے فرماؤ اگر وہ باز رہے تو جو ہو گزرا وہ انہیں معاف فرمادیا جائے گا اور اگر پھر وہی کریں تو اگلوں کا دستور گزر چکا ہے')
