INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1199, 8, 39, N'اور اگر ان سے لڑو یہاں تک کہ کوئی فساد باقی نہ رہے اور سارا دین اللہ ہی کا ہوجائے، اگر پھر وہ باز رہیں تو اللہ ان کے کام دیکھ رہا ہے،')
