INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1201, 8, 41, N'اور جان لو کہ جو کچھ غنیمت لو تو اس کا پانچواں حصہ خاص اللہ اور رسول و قرابت داروں اور یتیموں اور محتاجوں اور مسافروں کا ہے اگر تم ایمان لائے ہو اللہ پر اور اس پر جو ہم نے اپنے بندے پر فیصلہ کے دن اتارا جس دن دونوں فوجیں ملیں تھیں اور اللہ سب کچھ کرسکتا ہے،')
