INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1202, 8, 42, N'جب تم نالے کے کنا رے تھے اور کافر پرلے کنا رے اور قا فلہ تم سے ترائی میں اور اگر تم آپس میں کوئی وعدہ کرتے تو ضرور وقت پر برابر نہ پہنچتے لیکن یہ اس لیے کہ اللہ پورا کرے جو کام ہونا ہے کہ جو ہلاک ہو دلیل سے ہلاک ہو اور جو جئے دلیل سے جئے اور بیشک اللہ ضرور سنتا جانتا ہے،')
