INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1203, 8, 43, N'جب کہ اے محبوب! اللہ ٹمہیں کافروں کو تمہاری خواب میں تھو ڑا دکھاتا تھا اور اے مسلمانو! اگر وہ تمہیں بہت کرکے دکھاتا تو ضرور تم بزدلی کرتے اور معاملہ میں جھگڑا ڈالتے مگر اللہ نے بچا لیا بیشک وہ دلوں کی بات جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1204, 8, 44, N'او ر جب لڑتے وقت تمہیں کا فر تھو ڑے کرکے دکھائے اور تمہیں ان کی نگاہوں میں تھو ڑا کیا کہ اللہ پو را کرے جو کام ہونا ہے اور اللہ کی طرف سب کاموں کی رجوع ہے،')
