INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1206, 8, 46, N'اور اللہ اور اس کے رسول کا حکم مانو اور آپس میں جھگڑ و نہیں کہ پھر بز د لی کرو گے اور تمہاری بندھی ہوئی ہوا جاتی رہے گی اور صبر کرو، بیشک اللہ صبر والوں کے ساتھ ہے')
