INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1208, 8, 48, N'اور جبکہ شیطان نے ان کی نگاہ میں ان کے کام بھلے کر دکھائے اور بولا آج تم پر کوئی شخص غالب آنے والا نہیں اور تم میری پناہ میں ہو تو جب دونوں لشکر آمنے سامنے ہوئے الٹے پاؤں بھاگا اور بولا میں تم سے الگ ہوں میں وہ دیکھتا ہوں جو تمہیں نظر نہیں آتا میں اللہ سے ڈرتا ہوں اور اللہ کا عذاب سخت ہے،')
