INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1209, 8, 49, N'جب کہتے تھے منافق اور وہ جن کے دلوں میں ا ٓزا ر ہے کہ یہ مسلمان اپنے دین پر مغرور ہیں اور جو اللہ پر بھروسہ کرے تو بیشک اللہ غالب حکمت والا ہے،')
