INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1221, 8, 61, N'اور اگر وہ صلح کی طرف جھکیں تو تم بھی جھکو اور اللہ پر بھروسہ رکھو، بیشک وہی ہے سنتا جانتا،')
