INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1222, 8, 62, N'اور اگر وہ تمہیں فریب دیا چاہیں تو بیشک اللہ تمہیں کافی ہے، وہی ہے جس نے تمہیں زور دیا اپنی مدد کا اور مسلمانوں کا،')
