GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1226, 8, 66, N'اب اللہ نے تم پر سے تخفیف فرمائی اور اسے علم کہ تم کمزو ر ہو تو اگر تم میں سو صبر والے ہوں د و سو پر غالب آئیں گے اور اگر تم میں کے ہزار ہوں تو دو ہزار پر غالب ہوں گے اللہ کے حکم سے اور اللہ صبر والوں کے ساتھ ہے،')
