INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1230, 8, 70, N'اے غیب کی خبریں بتانے والے جو قیدی تمہارے ہاتھ میں ہیں ان سے فرماؤ اگر اللہ نے تمہارے دل میں بھلائی جانی تو جو تم سے لیا گیا اس سے بہتر تمہیں عطا فرمائے گا اور تمہیں بخش دے گا اور اللہ بخشنے والا مہربان ہے')
