INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1231, 8, 71, N'اور اے محبوب اگر وہ تم سے دغا چاہیں گے تو اس سے پہلے اللہ ہی کی خیانت کرچکے ہیں جس پر اس نے اتنے تمہارے قابو میں دے دیے اور اللہ جاننے والا حکمت والا ہے،')
