INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1237, 9, 2, N'تو چا ر مہینے زمین پر چلو پھرو اور جان رکھو کہ تم اللہ کو تھکا نہیں سکتے اور یہ کہ اللہ کافروں کو رسوا کرنے والا ہے')
