INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1238, 9, 3, N'اور منادی پکار دیتا اللہ اور اس کے رسول کی طرف سے سب لوگوں میں بڑے حج کے دن کہ اللہ بیزار ہے، مشرکوں سے اور اس کا رسول تو اگر تم توبہ کرو تو تمہا را بھلا ہے اور اگر منہ پھیرو تو جان لو کہ اللہ کو نہ تھکا سکو گے اور کافروں کو خوشخبری سناؤ دردناک عذاب کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1239, 9, 4, N'مگر وہ مشرک جن سے تمہارہ معاہدہ تھا پھر انہوں نے تمہارے عہد میں کچھ کمی نہیں کی اور تمہارے مقابل کسی کو مدد نہ دی تو ان کا عہد ٹھہری ہوئی مدت تک پورا کرو، بیشک اللہ پرہیزگاروں کو دوست رکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1240, 9, 5, N'پھر جب حرمت والے مہینے نکل جائیں تو مشرکوں کو مارو جہاں پا ؤ اور انہیں پکڑو اور قید کرو اور ہر جگہ ان کی تاک میں بیٹھو پھر اگر وہ توبہ کریں اور نماز قائم رکھیں اور زکوٰة دیں تو ان کی راہ چھوڑ دو بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1241, 9, 6, N'اور اے محبوب اگر کوئی مشرک تم سے پناہ مانگے تو اسے پناہ دو کہ وہ اللہ کا کلام سنے پھر اسے اس کی امن کی جگہ پہنچا دو یہ اس لیے کہ وہ نادان لوگ ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1242, 9, 7, N'مشرکوں کے لیے اللہ اور اس کے رسول کے پاس کوئی عہد کیونکر ہوگا مگر وہ جن سے تمہارا معاہدہ مسجد حرام کے پاس ہوا تو جب تک وہ تمہارے لیے عہد پر قائم رہیں تم ان کے لیے قائم رہو، بیشک پرہیزگار اللہ کو خوش آتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1243, 9, 8, N'بھلا کیونکر ان کا حال تو یہ ہے کہ تم پر قابو پائیں تو نہ قرابت کا لحاظ کریں نہ عہد کا، اپنے منہ سے تمہیں راضی کرتے ہیں اور ان کے دلوں میں انکار ہے اور ان میں اکثر بے حکم ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1244, 9, 9, N'اللہ کی آیتوں کے بدلے تھو ڑے دام مول لیے تو اس کی راہ سے روکا بیشک وہ بہت ہی بڑے کام کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1245, 9, 10, N'کسی مسلمان میں نہ قراب کا لحاظ کریں نہ عہد کا اور وہی سرکش ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1246, 9, 11, N'پھر اگر وہ توبہ کریں اور نماز قائم رکھیں اور زکوٰة دیں تو وہ تمہارے دینی بھائی ہیں اور ہم آیتیں مفصل بیان کرتے ہیں جاننے والوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1247, 9, 12, N'اور اگر عہد کرکے اپنی قسمیں توڑیں اور تمہارے دین پر منہ آئیں تو کفر کے سرغنوں سے لڑو بیشک ان کی قسمیں کچھ نہیں اس امید پر کہ شاید وہ باز آئیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1248, 9, 13, N'کیا اس قوم سے نہ لڑو گے جنہوں نے اپنی قسمیں توڑیں اور رسول کے نکالنے کا ارادہ کیا حالانکہ انہیں کی طرف سے پہلی ہوتی ہے، کیا ان سے ڈرتے ہو تو اللہ کا زیادہ مستحق ہے کہ اس سے ڈرو اگر ایمان رکھتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1249, 9, 14, N'تو ان سے لڑو اللہ انہیں عذاب دیگا تمہارے ہاتھوں اور انہیں رسوا کرے گا اور تمہیں ان پر مدد دے گا اور ایمان والوں کا جی ٹھنڈا کرے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1250, 9, 15, N'اور ان کے دلوں کی گھٹن دور فرمائے گا اور اللہ جس کی چاہے تو یہ قبول فرمائے اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1251, 9, 16, N'کیا اس گمان میں ہو کہ یونہی چھوڑ دیئے جاؤ گے اور ابھی اللہ نے پہچان نہ کرائی ان کی جو تم میں سے جہاد کریں گے اور اللہ اور اس کے رسول اور مسلمانوں کے سوا کسی کو اپنا محرم راز نہ بنائیں گے اور اللہ تمہارے کاموں سے خبردار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1252, 9, 17, N'مشرکوں کو نہیں پہنچتا کہ اللہ کی مسجدیں آباد کریں خود اپنے کفر کی گواہی دے کر ان کا تو سب کیا دھرا اِکا رت ہے اور وہ ہمیشہ آگ میں رہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1253, 9, 18, N'اللہ کی مسجدیں وہی آباد کرتے ہیں جو اللہ اور قیامت پر ایمان لاتے اور نما ز قائم کرتے ہیں اور زکوٰة دیتے ہیں اور اللہ کے سوا کسی سے نہیں ڈرتے تو قریب ہے کہ یہ لوگ ہدایت والوں میں ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1254, 9, 19, N'تو کیا تم نے حا جیوں کی سبیل اور مسجد حرام کی خدمت اس کے برابر ٹھہرا لی جو اللہ اور قیامت پر ایمان لایا اور اللہ کی راہ میں جہاد کیا، وہ اللہ کے نزدیک برابر نہیں، اور اللہ ظالموں کو راہ نہیں دیتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1255, 9, 20, N'وہ جو ایمان لائے اور ہجرت کی اور اپنے مال و جان سے اللہ کی راہ میں لڑے، اللہ کے یہاں ان کا درجہ بڑا ہے اور وہی مراد کو پہنچے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1256, 9, 21, N'ان کا رب انہیں خوشی سنا تا ہے اپنی رحمت اور اپنی رضا کی اور ان باغوں کی جن میں انہیں دائمی نعمت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1257, 9, 22, N'ہمیشہ ہمیشہ ان میں رہیں گے، بیشک اللہ کے پاس بڑا ثواب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1258, 9, 23, N'اے ایمان والو! اپنے باپ اور اپنے بھائیوں کو دوست نہ سمجھو اگر وہ ایمان پر کفر پسند کریں، اور تم میں جو کوئی ان سے دوستی کرے گا تو وہی ظالم ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1259, 9, 24, N'تم فرماؤ اگر تمہارے باپ اور تمہارے بیٹے اور تمہارے بھائی اور تمہاری عورتیں اور تمہارا کنبہ اور تمہاری کمائی کے مال او ر وہ سودا جس کے نقصان کا تمہیں ڈر ہے اور تمہارے پسند کا مکان یہ چیزیں اللہ اور اس کے رسول اور اس کی راہ میں لڑے سے زیاد ہ پیاری ہوں تو راستہ دیکھو یہاں تک کہ اللہ اپنا حکم لائے اور اللہ فاسقوں کو راہ نہیں دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1260, 9, 25, N'بیشک اللہ نے بہت جگہ تمہاری مدد کی اور حنین کے دن جب تم اپنی کثرت پر اترا گئے تھے تو وہ تمہارے کچھ کام نہ ا ٓئی اور زمین اتنی وسیع ہوکر تم پر تنگ ہوگئی پھر تم پیٹھ دے کر پھرگئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1261, 9, 26, N'پھر اللہ نے اپنی تسکین اتا ری اپنے رسول پر اور مسلمانوں پر اور وہ لشکر اتارے جو تم نے نہ دیکھے اور کافروں کو عذاب دیا اور منکروں کی یہی سزا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1262, 9, 27, N'پھر اس کے بعد اللہ جسے چاہے گا توبہ دے گا اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1263, 9, 28, N'اے ایمان والو! مشرک نرے ناپاک ہیں تو اس برس کے بعد وہ مسجد حرام کے پاس نہ آنے پائیں اور اگر تمہاری محتاجی کا ڈر ہے تو عنقریب اللہ تمہیں دولت مند کردے گا اپنے فضل سے اگر چاہے بیشک اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1264, 9, 29, N'لڑو ان سے جو ایمان نہیں لاتے اللہ پر اور قیامت پر اور حرام نہیں مانتے اس چیز کو جس کو حرام کیا اللہ اور اس کے رسول نے اور سچے دین کے تابع نہیں ہوتے یعنی وہ جو کتاب دیے گئے جب تک اپنے ہاتھ سے جزیہ نہ دیں ذلیل ہوکر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1265, 9, 30, N'اور یہودی بولے عزیر اللہ کا بیٹا ہے اور نصرانی بولے مسیح اللہ کا بیٹا ہے، یہ باتیں وہ اپنے منہ سے بکتے ہیں اگلے کافرو ں کی سی بات بناتے ہیں، اللہ انہیں مارے، کہاں اوندھے جاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1266, 9, 31, N'انہوں نے اپنے پادریوں اور جوگیوں کو اللہ کے سوا خدا بنالیا اور مسیح بن مریم کو اور انہیں حکم نہ تھا مگر یہ کہ ایک اللہ کو پوجیں اس کے سوا کسی کی بندگی نہیں، اسے پاکی ہے ان کے شرک سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1267, 9, 32, N'چاہتے ہیں کہ اللہ کا نور اپنے منہ سے بُجھا دیں اور اللہ نہ مانے گا مگر اپنے نور کا پورا کرنا پڑے برا مانیں کافر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1268, 9, 33, N'وہی ہے جس نے اپنا رسول ہدایت اور سچے دین کے ساتھ بھیجا کہ اسے سب دینوں پر غالب کرے پڑے برا مانیں مشرک،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1269, 9, 34, N'اے ایمان والو! بیشک بہت پادری اور جوگی لوگوں کا مال ناحق کھا جاتے ہیں اور اللہ کی راہ سے روکتے ہیں، اور وہ کہ جوڑ کر رکھتے ہیں سونا اور چاندی اور اسے اللہ کی راہ میں خرچ نہیں کرتے انہیں خوشخبری سناؤ دردناک عذاب کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1270, 9, 35, N'جس دن تپایا جائے گا جہنم کی آ گ میں پھر اس سے داغیں گے ان کی پیشانیاں اور کروٹیں اور پیٹھیں یہ ہے وہ جو تم نے اپنے لیے جوڑ کر رکھا تھا اب چکھو مزا اس جوڑنے کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1271, 9, 36, N'بیشک مہینوں کی گنتی اللہ کے نزدیک بارہ مہینے ہے اللہ کی کتاب میں جب سے اس نے آسمان اور زمین بنائے ان میں سے چار حرمت والے ہیں یہ سیدھا دین ہے، تو ان مہینوں میں اپنی جان پر ظلم نہ کرو اور مشرکوں سے ہر وقت لڑو جیسا وہ تم سے ہر وقت لڑتے ہیں، اور جان لو کہ اللہ پرہیزگاروں کے ساتھ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1272, 9, 37, N'ان کا مہینے پیچھے ہٹانا نہیں مگر اور کفر میں بڑھنا اس سے کافر بہکائے جاتے ہیں ایک برس اسے حلال ٹھہراتے ہیں اور دوسرے برس اسے حرام مانتے ہیں کہ اس گنتی کے برابر ہوجائیں جو اللہ نے حرام فرمائی اور اللہ کے حرام کیے ہوئے حلال کرلیں، ان کے برے کا م ان کی آنکھوں میں بھلے لگتے ہیں، اور اللہ کافروں کو راہ نہیں دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1273, 9, 38, N'اے ایمان والو! تمہیں کیا ہوا جب تم سے کہا جائے کہ خدا کی راہ میں کوچ کرو تو بوجھ کے مارے زمین پر بیٹھ جاتے ہو کیا تم نے دنیا کی زندگی آخرت کے بدلے پسند کرلی اور جیتی دنیا کا اسباب آخرت کے سامنے نہیں مگر تھوڑا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1274, 9, 39, N'اگر نہ کوچ کرو گے انہیں سخت سزا دے گا اور تمہاری جگہ اور تمہاری جگہ اور لوگ لے آئے گا اور تم اس کا کچھ نہ بگا ڑ سکوگے، اور اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1275, 9, 40, N'اگر تم محبوب کی مدد نہ کرو تو بیشک اللہ نے ان کی مدد فرمائی جب کافروں کی شرارت سے انہیں باہر تشریف لے جانا ہوا صرف دو جان سے جب وہ دونوں غار میں تھے جب اپنے یار سے فرماتے تھے غم نہ کھا بیشک اللہ ہمارے ساتھ ہے تو اللہ نے اس پر اپنا سکینہ اتارا اور ان فوجوں سے اس کی مدد کی جو تم نے نہ دیکھیں اور کافروں کی بات نیچے ڈالی اللہ ہی کا بول بالا ہے اور اللہ غالب حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1276, 9, 41, N'کوچ کرو ہلکی جان سے چاہے بھاری دل سے اور اللہ کی راہ میں لڑو اپنے مال اور جان سے، یہ تمہارے لیے بہتر ہے اگر جانو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1277, 9, 42, N'اگر کوئی قریب مال یا متوسط سفر ہوتا تو ضرور تمہارے ساتھ جاتے مگر ان پر تو مشقت کا راستہ دور پڑ گیا، اور اب اللہ کی قسم کھائیں گے کہ ہم سے بن پڑتا تو ضرور تمہارے ساتھ چلتے اپنی جانو کو ہلاک کرتے ہیں اور اللہ جانتا ہے کہ وہ بیشک ضرور جھوٹے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1278, 9, 43, N'اللہ تمہیں معاف کرے تم نے انہیں کیوں اِذن دے دیا جب تک نہ کھلے تھے تم پر سچے اور ظاہر نہ ہوئے تھے جھوٹے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1279, 9, 44, N'اور وہ جو اللہ اور قیامت پر ایمان رکھتے ہیں تم سے چھٹی نہ مانگیں گے اس سے کہ اپنے مال اور جان سے جہاد کریں، اور اللہ خوب جا نتا ہے پرہیزگا روں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1280, 9, 45, N'تم سے یہ چھٹی وہی مانگتے ہیں جو اللہ اور قیامت پر ایمان نہیں رکھتے اور ان کے دل شک میں پڑے ہیں تو وہ اپنے شک میں ڈانواں ڈول ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1281, 9, 46, N'انہیں نکلنا منظور ہوتا تو اس کا سامان کرتے مگر خدا ہی کو ان کا اٹھنا پسند ہوا تو ان میں کاہلی بھردی اور فرمایا گیا کہ بیٹھ رہو بیٹھ رہنے والے کے ساتھ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1282, 9, 47, N'اگر وہ تم میں نکلتے تو ان سے سوا نقصان کے تمہیں کچھ نہ بڑھتنا اور تم میں فتنہ ڈالنے کو تمہارے بیچ یں غرابیں دوڑاتے (فساد ڈالتے) اور تم میں ان کے جاسوس موجود ہیں اور اللہ خوب جانتا ہے ظالموں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1283, 9, 48, N'بیشک انہوں نے پہلے ہی فتنہ چا ہا تھا اور اے محبوب! تمہارے لیے تدبیریں الٹی پلٹیں یہاں تک کہ حق آیا اور اللہ کا حکم ظاہر ہوا اور انہیں ناگوار تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1284, 9, 49, N'اور ان میں کوئی تم سے یوں عرض کرتا ہے کہ مجھے رخصت دیجیے اور فتنہ میں نہ ڈالیے سن لو وہ فتنہ ہی میں پڑے اور بیشک جہنم گھیرے ہوئے ہے کافروں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1285, 9, 50, N'اگر تمہیں بھلائی پہنچے تو انہیں برا لگے اور اگر تمہیں کوئی مصیبت پہنچے تو کہیں ہم نے اپنا کام پہلے ہی ٹھیک کرلیا تھا اور خوشیاں مناتے پھر جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1286, 9, 51, N'تم فرماؤ ہمیں نہ پہنچے گا مگر جو اللہ نے ہمارے لیے لکھ دیا وہ ہمارا مولیٰ ہے اور مسلمانوں کو اللہ ہی پر بھروسہ چاہیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1287, 9, 52, N'تم فرماؤ تم ہم پر کس چیز کا انتظار کرتے ہو مگر دو خوبیوں میں سے ایک کا اور ہم تم پر اس انتظار میں ہیں کہ اللہ تم پر عذاب ڈالے اپنے پاس سے یا ہمارے ہاتھوں تو اب راہ دیکھو ہم بھی تمہارے ساتھ راہ دیکھ رہے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1288, 9, 53, N'تم فرماؤ کہ دل سے خرچ کرو یا ناگواری سے تم سے ہر گز قبول نہ ہوگا بیشک تم بے حکم لوگ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1289, 9, 54, N'اور وہ جو خرچ کرتے ہیں اس کا قبول ہونا بند نہ ہوا مگر اسی لیے کہ وہ اللہ اور رسول سے منکر ہوئے اور نماز کو نہیں آتے مگر جی ہارے اور خرچ نہیں کرتے مگر ناگواری سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1290, 9, 55, N'تو تمہیں ان کے مال اور ان کی اولاد کا تعجب نہ آئے، اللہ ہی چاہتا ہے کہ دنیا کی زندگی میں ان چیزوں سے ان پر وبال ڈالے اور اگر کفر ہی پر ان کا دم نکل جائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1291, 9, 56, N'اور اللہ کی قسمیں کھاتے ہیں کہ وہ تم میں سے ہیں اور تم میں سے ہیں نہیں ہاں وہ لوگ ڈرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1292, 9, 57, N'اگر پائیں کوئی پناہ یا غار یا سما جانے کی جگہ تو رسیاں تڑاتے ادھر پھر جائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1293, 9, 58, N'اور ان میں کوئی وہ ہے کہ صدقے بانٹنے میں تم پر طعن کرتا ہے تو اگر ان میں سے کچھ ملے تو راضی ہوجائیں اور نہ ملے تو جبھی وہ ناراض ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1294, 9, 59, N'اور کیا اچھا ہوتا اگر وہ اس پر راضی ہوتے جو اللہ و رسول نے ان کو دیا اور کہتے ہمیں اللہ کافی ہے اب دیتا ہے ہمیں اللہ اپنے فضل سے اور اللہ کا رسول، ہمیں اللہ ہی کی طرف رغبت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1295, 9, 60, N'زکوٰة تو انہیں لوگوں کے لیے ہے محتاج اور نرے نادار اور جو اسے تحصیل کرکے لائیں اور جن کے دلوں کو اسلام سے الفت دی جائے اور گردنیں چھڑانے میں اور قرضداروں کو اور اللہ کی راہ میں اور مسافر کو، یہ ٹھہرایا ہوا ہے اللہ کا، اور اللہ علم و حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1296, 9, 61, N'اور ان میں کوئی وہ ہیں کہ ان غیب کی خبریں دینے والے کو ستاتے ہیں اور کہتے ہیں وہ تو کان ہیں، تم فرماؤ تمہارے بھلے کے لیے کا ن ہیں اللہ پر ایمان لاتے ہیں اور مسلمانوں کی بات پر یقین کرتے ہیں اور جو تم میں مسلمان ہیں ان کے واسطے رحمت ہیں، اور جو رسول اللہ کو ایذا دیتے ہیں ان کے لیے دردناک عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1297, 9, 62, N'تمہارے سامنے اللہ کی قسم کھاتے ہیں کہ تمہیں راضی کرلیں اور اللہ و رسول کا حق زائد تھا کہ اسے راضی کرتے اگر ایمان رکھتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1298, 9, 63, N'کیا انہیں خبر نہیں کہ جو خلاف کرے اللہ اور اس کے رسول کا تو اس کے لیے جہنم کی آ گ ہے کہ ہمیشہ اس میں رہے گا، یہی بڑی رسوائی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1299, 9, 64, N'منافق ڈرتے ہیں کہ ان پر کوئی سورة ایسی اترے جو ان کے دلوں کی چھپی جتادے تم فرماؤ ہنسے جاؤ اللہ کو ضرور ظاہر کرنا ہے جس کا تمہیں ڈر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1300, 9, 65, N'اور اے محبوب اگر تم ان سے پوچھو تو کہیں گے کہ ہم تو یونہی ہنسی کھیل میں تھے تم فرماؤ کیا اللہ اور اس کی آیتوں اور اس کے رسول سے ہنستے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1301, 9, 66, N'بہانے نہ بنا ؤ تم کافر ہوچکے مسلمان ہوکر اگر ہم تم میں سے کسی کو معاف کریں تو اوروں کو عذاب دیں گے اس لیے کہ وہ مجرم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1302, 9, 67, N'منافق مرد اور منافق عورتیں ایک تھیلی کے چٹے بٹے ہیں برائی کا حکم دیں اور بھلائی سے منع کریں اور اپنی مٹھی بند رکھیں وہ اللہ کو چھوڑ بیٹھے تو اللہ نے انہیں چھوڑدیا بیشک منافق وہی پکے بے حکم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1303, 9, 68, N'اللہ نے منافق مردوں اور منافق عورتوں اور کافروں کو جہنم کی آگ کا وعدہ دیا ہے جس میں ہمیشہ رہیں گے، وہ انہیں بس ہے اور اللہ کی ان پر لعنت ہے اور ان کے لیے قائم رہنے والا عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1304, 9, 69, N'جیسے وہ جو تم سے پہلے تھے تم سے زور میں بڑھ کر تھے اور ان کے مال اور اولاد سے زیادہ، تو وہ اپنا حصہ برت گئے تو تم نے اپنا حصہ برتا جیسے اگلے اپنا حصہ برت گئے اور تم بیہودگی میں پڑے جیسے وہ پڑے تھے ان کے عمل اکارت گئے دنیا اور آخرت میں اور وہی لوگ گھاٹے میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1305, 9, 70, N'کیا انہیں اپنے سے اگلوں کی خبر نہ آئی نوح کی قوم اور عاد اور ثمود اور ابراہیم کی قوم اور مدین والے اور وہ بستیاں کہ الٹ دی گئیں ان کے رسول روشن دلیلیں ان کے پاس لائے تھے تو اللہ کی شان نہ تھی کہ ان پر ظلم کرتا بلکہ وہ خود ہی اپنی جانوں پر ظالم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1306, 9, 71, N'اور مسلمان مرد اور مسلمان عورتیں ایک دوسرے کے رفیق ہیں بھلائی کا حکم دیں اور برائی سے منع کریں اور نماز قائم رکھیں اور زکوٰة دیں اور اللہ و رسول کا حکم مانیں، یہ ہیں جن پر عنقریب اللہ رحم کرے گا، بیشک اللہ غالب حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1307, 9, 72, N'اللہ نے مسلمان مردوں اور مسلمان عورتوں کو باغوں کا وعدہ دیا ہے جن کے نیچے نہریں رواں ان میں ہمیشہ رہیں گے اور پاکیزہ مکانوں کا بسنے کے باغوں میں، اور اللہ کی رضا سب سے بڑی یہی ہے بڑی مراد پانی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1308, 9, 73, N'اے غیب کی خبریں دینے والے (نبی) جہاد فرماؤ کافروں اور منافقوں پر اور ان پر سختی کرو، اور ان کا ٹھکانا دوزخ ہے، اور کیا ہی بری جگہ پلٹنے کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1309, 9, 74, N'اللہ کی قسم کھاتے ہیں کہ انہوں نے نہ کہا اور بیشک ضرور انہوں نے کفر کی بات کہی اور اسلام میں آکر کافر ہوگئے اور وہ چاہا تھا جو انہیں نہ ملا اور انہیں کیا برا لگا یہی نہ کہ اللہ و رسول نے انہیں اپنے فضل سے غنی کردیا تو اگر وہ توبہ کریں تو ان کا بھلا ہے، اور اگر منہ پھیریں تو اللہ انہیں سخت عذاب کرے گا دنیا اور آخرت میں، اور زمین میں کوئی نہ ان کا حمایتی ہوگا اور نہ مددگار')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1310, 9, 75, N'اور ان میں کوئی وہ ہیں جنہوں نے اللہ سے عہد کیا تھا کہ اگر ہمیں اپنے فضل سے دے تو ہم ضرور خیرات کریں گے اور ہم ضرور بھلے آدمی ہوجائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1311, 9, 76, N'تو جب اللہ نے انہیں اپنے فضل سے دیا اس میں بخل کرنے لگے اور منہ پھیر کر پلٹ گئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1312, 9, 77, N'تو اس کے پیچھے اللہ نے ان کے دلوں میں نفاق رکھ دیا اس دن تک کہ اس سے ملیں گے بدلہ اس کا کہ انہوں نے اللہ سے وعدہ جھوٹا کیا اور بدلہ اس کا کہ جھوٹ بولتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1313, 9, 78, N'کیا انہیں خبر نہیں کہ اللہ ان کے دل کی چھپی اور ان کی سرگوشی کو جانتا ہے اور یہ کہ اللہ سب غیبوں کا بہت جاننے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1314, 9, 79, N'اور جو عیب لگاتے ہیں ان مسلمانوں کو کہ دل سے خیرات کرتے ہیں اور ان کو جو نہیں پاتے مگر اپنی محنت سے تو ان سے ہنستے ہیں اللہ ان کی ہنسی کی سزا دے گا، اور ان کے لیے دردناک عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1315, 9, 80, N'تم ان کی معافی چاہو یا نہ چاہو، اگر تم ستر بار ان کی معافی چاہو گے تو اللہ ہرگز انھیں نہیں بخشے گا یہ اس لیے کہ وہ اللہ اور اس کے رسول سے منکر ہوئے، اور اللہ فاسقوں کو راہ نہیں دیتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1316, 9, 81, N'پیچھے رہ جانے والے اس پر خوش ہوئے کہ وہ رسول کے پیچھے بیٹھ رہے اور انہیں گوارا نہ ہوا کہ اپنے مال اور جان سے اللہ کی راہ میں لڑیں اور بولے اس گرمی میں نہ نکلو، تم فرماؤ جہنم کی آگ سب سے سخت گرم ہے، کسی طرح انہیں سمجھ ہو تی')
