INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1317, 9, 82, N'تو انہیں چاہیے تھوڑا ہنسیں اور بہت روئیں بدلہ اس کا جو کماتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1318, 9, 83, N'پھر اے محبوب! اگر اللہ تمہیں ان میں سے کسی گروہ کی طرف واپس لے جائے اور وہ تم سے جہاد کو نکلنے کی اجازت مانگے تو تم فرمانا کہ تم کبھی میرے ساتھ نہ چلو اور ہرگز میرے ساتھ کسی دشمن سے نہ لڑو، تم نے پہلی دفعہ بیٹھ رہنا پسند کیا تو بیٹھ رہو پیچھے رہ جانے والوں کے ساتھ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1319, 9, 84, N'اور ان میں سے کسی کی میت پر کبھی نماز نہ پڑھنا اور نہ اس کی قبر پر کھڑے ہونا، بیشک اللہ اور رسول سے منکر ہوئے اور فسق ہی میں مر گئے')
