INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1320, 9, 85, N'اور ان کے مال یا اولاد پر تعجب نہ کرنا، اللہ یہی چاہتا ہے کہ اسے دنیا م یں ان پر وبال کرے اور کفر ہی پر ان کا دم نکل جائے،')
