INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1325, 9, 90, N'اور بہانے بنانے والے گنوار آئے کہ انہیں رخصت دی جائے اور بیٹھ رہے وہ جنہوں نے اللہ و رسول سے جھوٹ بولا تھا جلد ان میں کے کافروں کو دردناک عذاب پہنچے گا')
