INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1328, 9, 93, N'مؤاخذہ تو ان سے ہے جو تم سے رخصت مانگتے ہیں اور وہ دولت مند ہیں انہیں پسند آیا کہ عورتوں کے ساتھ پیچھے بیٹھ رہیں اور اللہ نے ان کے دلوں پر مہر کردی تو وہ کچھ نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1329, 9, 94, N'تم سے بہانے بنائیں گے جب تم ان کی طرف لوٹ کر جاؤ گے تم فرمانا، بہانے نہ بناؤ ہم ہرگز تمہارا یقین نہ کریں گے اللہ نے ہمیں تمہاری خبریں دے دی ہیں، اور اب اللہ و رسول تمہارے کام دیکھیں گے پھر اس کی طرف پلٹ کر جاؤ گے جو چھپے اور ظاہر سب کو جانتا ہے وہ تمہیں جتادے گا جو کچھ تم کرتے تھے،')
