INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1330, 9, 95, N'اب تمہارے آگے اللہ کی قسمیں کھائیں گے جب تم ان کی طرف پلٹ کر جاؤ گے اس لیے کہ تم ان کے خیال میں نہ پڑو تو ہاں تم ان کا خیال چھوڑو وہ تو نرے پلید ہیں اور ان کا ٹھکانا جہنم ہے بدلہ اس کا جو کماتے تھے')
