GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1332, 9, 97, N'گنوار کفر اور نفاق میں زیادہ سخت ہیں اور اسی قابل ہیں کہ اللہ نے جو حکم اپنے رسول پر اتارے اس سے جاہل رہیں، اور اللہ علم و حکمت والا ہے،')
