INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1333, 9, 98, N'اور کچھ گنوار وہ ہیں کہ جو اللہ کی راہ میں خرچ کریں تو اسے تاوان سمجھیں اور تم پر گردشیں آنے کے انتظار میں رہیں انہیں پر ہے بری گردش اور اللہ سنتا جانتا ہے،')
