INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1334, 9, 99, N'اور کچھ گاؤں والے وہ ہیں جو اللہ اور قیامت پر ایمان رکھتے ہیں اور جو خرچ کریں اسے اللہ کی نزدیکیوں اور رسول سے دعائیں لینے کا ذریعہ سمجھیں ہاں ہاں وہ ان کے لیے باعث قرب ہے اللہ جلد انہیں اپنی رحمت میں داخل کرے گا، بیشک اللہ بخشنے والا مہربان ہے،')
