INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1335, 9, 100, N'اور سب میں اگلے پہلے مہاجر اور انصار اور جو بھلائی کے ساتھ ان کے پیرو ہوئے اللہ ان سے راضی اور وہ اللہ سے راضی اور ان کے لیے تیار کر رکھے ہیں باغ جن کے نیچے نہریں بہیں ہمیشہ ہمیشہ ان میں رہیں، یہی بڑی کامیابی ہے،')
