INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1336, 9, 101, N'اور تمہارے آس پاس کے کچھ گنوار منافق ہیں، اور کچھ مدینہ والے، ان کی خو ہوگئی ہے نفاق، تم انہیں نہیں جانتے، ہم انھیں جانتے ہیں جلد ہم انہیں دوبارہ عذاب کریں گے پھر بڑے عذاب کی طرف پھیرے جائیں گے')
