INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1337, 9, 102, N'اور کچھ اور ہیں جو اپنے گناہوں کے مقر ہوئے اور ملایا ایک کام اچھا اور دوسرا بڑا قریب ہے کہ اللہ ان کی توبہ قبول کرے، بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1338, 9, 103, N'اے محبوب! ان کے مال میں سے زکوٰة تحصیل کرو جس سے تم انھیں ستھرا اور پاکیزہ کردو اور ان کے حق میں دعائے خیر کرو بیشک تمہاری دعا ان کے دلوں کا چین ہے، اور اللہ سنتا جانتا ہے،')
