INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1339, 9, 104, N'کیا انہیں خبر نہیں کہ اللہ ہی اپنے بندوں کی توبہ قبول کرتا اور صدقے خود اپنی دست قدرت میں لیتا ہے اور یہ کہ اللہ ہی توبہ قبول کرنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1340, 9, 105, N'اور تم فرما ؤ کام کرو اب تمہارے کام دیکھے گا اللہ اور اس کے رسول اور مسلمان، اور جلد اس کی طرف پلٹوگے جو چھپا اور کھلا سب جانتا ہے تو وہ تمہارے کام تمہیں جتاوے گا،')
