INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1341, 9, 106, N'اور کچھ موقوف رکھے گئے اللہ کے حکم پر، یا ان پر عذاب کرے یا ان کی توبہ قبول کرے اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1342, 9, 107, N'اور وہ جنہوں نے مسجد بنائی نقصان پہنچانے کو اور کفر کے سبب اور مسلمانوں میں تفرقہ ڈالنے کو اور اس کے انتظار میں جو پہلے سے اللہ اور اس کے رسول کا مخالف ہے اور وہ ضرور قسمیں کھائیں گے ہم نے تو بھلائی چاہی، اور اللہ گواہ ہے کہ وہ بیشک جھوٹے ہیں،')
