INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1343, 9, 108, N'اس مسجد میں تم کبھی کھڑے نہ ہونا، بیشک وہ مسجد کہ پہلے ہی دن سے جس کی بنیاد پرہیزگاری پر رکھی گئی ہے وہ اس قابل ہے کہ تم اس میں کھڑے ہو، اس میں وہ لوگ ہیں کہ خوب ستھرا ہونا چاہتے ہیں اور ستھرے اللہ کو پیارے ہیں،')
