INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1344, 9, 109, N'تو کیا جس نے اپنی بنیاد رکھی اللہ سے ڈر اور اس کی رضا پر وہ بھلا یا وہ جس نے اپنی نیو چنی ایک گراؤ (ٹوٹے ہوئے کناروں والے) گڑھے کے کنارے تو وہ اسے لے کر جہنم کی آ گ میں ڈھے پڑا اور اللہ ظالموں کو راہ نہیں دیتا،')
