INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1345, 9, 110, N'وہ تعمیر جو چنی (کی) ہمیشہ ان کے دلوں میں کھٹکتی رہے گی مگر یہ کہ ان کے دل ٹکڑے ٹکڑے ہوجائیں اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1346, 9, 111, N'بیشک اللہ نے مسلمانوں سے ان کے مال اور جان خریدلیے ہیں اس بدلے پر کہ ان کے لیے جنت ہے اللہ کی راہ میں لڑیں تو ماریں اور مریں اس کے ذمہ کرم پر سچا وعدہ توریت اور انجیل اور قرآن میں اور اللہ سے زیادہ قول کا پورا کون تو خوشیاں مناؤ اپنے سودے کی جو تم نے اس سے کیا ہے، اور یہی بڑی کامیابی ہے،')
