INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1347, 9, 112, N'توبہ والے عبادت والے سراہنے والے روزے والے رکوع والے سجدہ والے بھلائی کے بتانے والے اور برائی سے روکنے والے اور اللہ کی حدیں نگاہ رکھنے والے اور خوشی سناؤ مسلمانوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1348, 9, 113, N'نبی اور ایمان والوں کو لائق نہیں کہ مشرکوں کی بخشش چاہیں اگرچہ وہ رشتہ دار ہوں جبکہ انہیں کھل چکا کہ وہ دوزخی ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1349, 9, 114, N'اور ابراہیم کا اپنے باپ کی بخشش چاہنا وہ تو نہ تھا مگر ایک وعدے کے سبب جو اس سے کرچکا تھا پھر جب ابراہیم کو کھل گیا کہ وہ اللہ کا دشمن ہے اس سے تنکا توڑ دیا (لاتعلق ہوگیا) بیشک ابراہیم بہت آہیں کرنے والا متحمل ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1350, 9, 115, N'اور اللہ کی شان نہیں کہ کسی قوم کو ہدایت کرکے گمراہ فرمائے جب تک انہیں صاف نہ بتادے کہ کسی چیز سے انہیں بچنا ہے بیشک اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1351, 9, 116, N'بیشک اللہ ہی کے لیے ہے آسمانوں اور زمین کی سلطنت، جِلاتا ہے اور مارتا ہے، اور اللہ کے سوا نہ تمہارا کوئی والی اور نہ مددگار،')
GO
