INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1390, 10, 26, N'بھلائی والوں کے لیے بھلائی ہے اور اس سے بھی زائد اور ان کے منہ پر نہ چڑھے گی سیاہی اور نہ خواری وہی جنت والے ہیں وہ اس میں ہمیشہ رہیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1391, 10, 27, N'اور جنہوں نے برائیاں کمائیں تو برائی کا بدلہ اسی جیسا اور ان پر ذلت چڑھے گی، انہیں اللہ سے بچانے والا کوئی نہ ہوگا، گویا ان کے چہروں پر اندھیری رات کے ٹکڑے چڑھا دیئے ہیں وہی دوزخ والے ہیں، وہ اس میں ہمیشہ رہیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1392, 10, 28, N'اور جس دن ہم ان سب کو اٹھائیں گے پھر مشرکوں سے فرمائیں گے اپنی جگہ رہو تم اور تمہارے شریک تو ہم انہیں مسلمانوں سے جدا کردیں گے اور ان کے شریک ان سے کہیں گے تم ہمیں کب پوجتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1393, 10, 29, N'تو اللہ گواہ کافی ہے ہم میں اور تم میں کہ ہمیں تمہارے پوجنے کی خبر بھی نہ تھی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1394, 10, 30, N'یہاں ہر جان جا نچ لے گی جو آگے بھیجا اور اللہ کی طرف پھیرے جائیں گے جو ان کا سچا مولیٰ ہے اور ان کی ساری بناوٹیں ان سے گم ہوجائیں گی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1395, 10, 31, N'تم فرماؤ تمہیں کون روزی دیتا ہے آسمان اور زمین سے یا کون مالک ہے کان اور آنکھوں کا اور کون نکالتا ہے زندہ کو مردے سے اور نکالتا ہے مردہ کو زندہ سے اور کون تمام کاموں کی تدبیر کرتا ہے تو اب کہیں گے کہ اللہ تو تم فرماؤ تو کیوں نہیں ڈرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1396, 10, 32, N'تو یہ اللہ ہے تمہارا سچا رب پھر حق کے بعد کیا ہے مگر گمراہی پھر کہاں پھرے جاتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1397, 10, 33, N'یونہی ثابت ہوچکی ہے تیرے رب کی بات فاسقوں پر تو وہ ایمان نہیں لائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1398, 10, 34, N'تم فرماؤ تمہارے شریکوں میں کوئی ایسا ہے کہ اول بنائے پھر فنا کے بعد دوبارہ بنائے تم فرماؤ اللہ اوّل بناتا ہے پھر فنا کے بعد دوبارہ بنائے گا تو کہاں اوندھے جاتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1399, 10, 35, N'تم فرماؤ تمہارے شریکوں میں کوئی ایسا ہے کہ حق کی راہ دکھائے تم فرماؤ کہ اللہ حق کی راہ دکھاتا ہے، تو کیا جو حق کی راہ دکھائے اس کے حکم پر چلنا چاہیے یا اس کے جو خود ہی راہ نہ پائے جب تک راہ نہ دکھایا جائے تو تمہیں کیا ہوا کیسا حکم لگاتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1400, 10, 36, N'اور ان میں اکثر تو نہیں چلتے مگر گمان پر بیشک گمان حق کا کچھ کام نہیں دیتا، بیشک اللہ ان کاموں کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1401, 10, 37, N'اور اس قرآن کی یہ شان نہیں کہ کوئی اپنی طرف سے بنالے بے اللہ کے اتارے ہاں وہ اگلی کتابوں کی تصدیق ہے اور لوح میں جو کچھ لکھا ہے سب کی تفصیل ہے اس میں کچھ شک نہیں ہے پروردگار عالم کی طرف سے ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1402, 10, 38, N'کیا یہ کہتے ہیں کہ انہوں نے اسے بنالیا ہے تم فرماؤ تو اس جیسی کوئی ایک سورة لے آؤ اور اللہ کو چھوڑ کر جو مل سکیں سب کو بلا لاؤ اگر تم سچے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1403, 10, 39, N'بلکہ اسے جھٹلایا جس کے علم پر قابو نہ پایا اور ابھی انہوں نے اس کا انجام نہیں دیکھا ایسے ہی ان سے اگلوں نے جھٹلایا تھا تو دیکھو ظالموں کیسا انجام ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1404, 10, 40, N'اور ان میں کوئی اس پر ایمان لاتا ہے اور ان میں کوئی اس پر ایمان نہیں لاتا ہے، اور تمہارا رب مفسدوں کو خوب جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1405, 10, 41, N'اور اگر وہ تمہیں جھٹلائیں تو فرمادو کہ میرے لیے میری کرنی اور تمہارے لیے تمہاری کرنی (اعمال) تمہیں میرے کام سے علاقہ نہیں اور مجھے تمہارے کام سے لاتعلق نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1406, 10, 42, N'اور ان میں کوئی وہ ہیں جو تمہاری طرف کان لگاتے ہیں تو کیا تم بہروں کو سنا دو گے اگرچہ انہیں عقل نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1407, 10, 43, N'اور ان میں کوئی تمہاری طرف تکتا ہے کیا تم اندھوں کو راہ دکھا دو گے اگرچہ وہ نہ سوجھیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1408, 10, 44, N'بیشک اللہ لوگوں پر کچھ ظلم نہیں کرتا ہاں لوگ ہی اپنی جانوں پر ظلم کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1409, 10, 45, N'اور جس دن انہیں اٹھائے گا گویا دنیا میں نہ رہے تھے مگر اس دن کی ایک گھڑی آپس میں پہچان کریں گے کہ پورے گھاٹے میں رہے وہ جنہوں نے اللہ سے ملنے کو جھٹلایا اور ہدایت پر نہ تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1410, 10, 46, N'اور اگر ہم تمہیں دکھا دیں کچھ اس میں سے جو انہیں وعدہ دے رہے ہیں یا تمہیں پہلے ہی اپنے پاس بلالیں بہرحال انہیں ہماری طرف پلٹ کر آنا ہے پھر اللہ گواہ ہے ان کے کاموں پر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1411, 10, 47, N'اور ہر امت میں ایک رسول ہوا جب ان کا رسول ان کے پاس آتا ان پر انصاف کا فیصلہ کردیا جاتا اور ان پر ظلم نہیں ہوتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1412, 10, 48, N'اور کہتے ہیں یہ وعدہ کب آئے گا اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1413, 10, 49, N'تم فرماؤ میں اپنی جان کے برے بھلے کا (ذاتی) اختیار نہیں رکھتا مگر جو اللہ چاہے ہر گروہ کا ایک وعدہ ہے جب ان کا وعدہ آئے گا تو ایک گھڑی نہ پیچھے ہٹیں نہ آگے بڑھیں،')
