INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1414, 10, 50, N'تم فرماؤ بھلا بتاؤ تو اگر اس کا عذاب تم پر رات کو آئے یا دن کو تو اس میں وہ کونسی چیز ہے کہ مجرموں کو جس کی جلدی ہے،')
