INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1415, 10, 51, N'تو کیا جب ہو پڑے گا اس وقت اس کا یقین کرو گے کیا اب مانتے ہو پہلے تو اس کی جلدی مچارہے تھے،')
