INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1416, 10, 52, N'پھر ظالموں سے کہا جائے گا ہمیشہ کا عذاب چکھو تمہیں کچھ اور بدلہ نہ ملے گا مگر وہی جو کماتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1417, 10, 53, N'اور تم سے پوچھتے ہیں کیا وہ حق ہے، تم فرماؤ، ہاں! میرے رب کی قسم بیشک وہ ضرور حق ہے، اور تم کچھ تھکا نہ سکو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1418, 10, 54, N'اور اگر ہر ظالم جان، زمین میں جو کچھ ہے سب کی مالک ہوتی، ضرور اپنی جان چھڑانے میں دیتی اور دل میں چپکے چپکے پشیمان ہوئے جب عذاب دیکھا اور ان میں انصاف سے فیصلہ کردیا گیا اور ان پر ظلم نہ ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1419, 10, 55, N'سن لو بیشک اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور زمین میں سن لو بیشک اللہ کا وعدہ سچا ہے مگر ان میں اکثر کو خبر نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1420, 10, 56, N'وہ جِلاتا اور مارتا ہے اور اسی کی طرف پھرو گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1421, 10, 57, N'اے لوگو! تمہارے پاس تمہارے رب کی طرف سے نصیحت آئی اور دلوں کی صحت اور ہدایت اور رحمت ایمان والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1422, 10, 58, N'تم فرماؤ اللہ ہی کے فضل اور اسی کی رحمت اور اسی پر چاہیے کہ خوشی کریں وہ ان کے سب دھن دولت سے بہتر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1423, 10, 59, N'تم فرماؤ بھلا بتاؤ تو وہ جو اللہ نے تمہارے لیے رزق اتارا اس میں تم نے اپنی طرف سے حرام و حلال ٹھہرالیا تم فرماؤ کیا اللہ نے اس کی تمہیں اجازت دی یا اللہ پر جھوٹ باندھتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1424, 10, 60, N'اور کیا گمان ہے ان کا، جو اللہ پر جھوٹ باندھتے ہیں کہ قیامت میں ان کا کیا حال ہوگا، بیشک اللہ لوگوں پر فضل کرتا ہے مگر اکثر لوگ شکر نہیں کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1425, 10, 61, N'اور تم کسی کام میں ہو اور اس کی طرف سے کچھ قرآن پڑھو اور تم لوگ کوئی کام کرو ہم تم پر گواہ ہوتے ہیں جب تم اس کو شروع کرتے ہو، اور تمہارے رب سے ذرہ بھر کوئی چیز غائب نہیں زمین میں نہ آسمان میں اور نہ اس سے چھوٹی اور نہ اس سے بڑی کوئی چیز نہیں جو ایک روشن کتاب میں نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1426, 10, 62, N'سن لو بیشک اللہ کے ولیوں پر نہ کچھ خو ف ہے نہ کچھ غم')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1427, 10, 63, N'وہ جو ایمان لائے اور پرہیزگاری کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1428, 10, 64, N'انہیں خوشخبری ہے دنیا کی زندگی میں اور آخرت میں، اللہ کی باتیں بدل نہیں سکتیں یہی بڑی کامیابی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1429, 10, 65, N'اور تم ان کی باتو ں کا غم نہ کرو بیشک عزت ساری اللہ کے لیے ہے وہی سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1430, 10, 66, N'سن لو بیشک اللہ ہی کے مِلک ہیں جتنے آسمانوں میں ہیں اور جتنے زمینوں میں اور کاہے کے پیچھے جارہے ہیں وہ جو اللہ کے سوا شریک پکار رہے ہیں، وہ تو پیچھے نہیں جاتے مگر گمان کے اور وہ تو نہیں مگر اٹکلیں دوڑاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1431, 10, 67, N'وہی ہے جس نے تمہارے لیے رات بنائی کہ اس میں چین پاؤ اور دن بنایا تمہاری آنکھوں کھولتا بیشک اس میں نشانیاں ہیں سننے والوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1432, 10, 68, N'بولے اللہ نے اپنے لیے اولاد بنائی پاکی اس کو، وہی بے نیاز ہے، اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں تمہارے پاس اس کی کوئی بھی سند نہیں، کیا اللہ پر وہ بات بتاتے ہو جس کا تمہیں علم نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1433, 10, 69, N'تم فرماؤ وہ جو اللہ پر جھوٹ باندھتے ہیں ان کا بھلا نہ ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1434, 10, 70, N'دنیا میں کچھ برت لینا (فائدہ اٹھانا) ہے پھر انہیں ہماری طرف واپس آنا پھر ہم انہیں سخت عذاب چکھائیں گے بدلہ ان کے کفر کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1435, 10, 71, N'اور انہیں نوح کی خبر پڑھ کر سناؤ جب اس نے اپنی قوم سے کہا اے میری قوم اگر تم پر شاق گزرا ہے میرا کھڑا ہونا اور اللہ کی نشانیاں یاد دلانا تو میں نے اللہ ہی پر بھروسہ کیا تو مِل کر کام کرو اور اپنے جھوٹے معبودوں سمیت اپنا کام پکا کرلو تمہارے کام میں تم پر کچھ گنجلک (الجھن) نہ رہے پھر جو ہو سکے میرا کرلو اور مجھے مہلت نہ دو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1436, 10, 72, N'پھر اگر تم منہ پھیرو تو میں تم سے کچھ اجرت نہیں مانگتا میرا اجر تو نہیں مگر اللہ پر اور مجھے حکم ہے کہ میں مسلمانوں سے ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1437, 10, 73, N'تو انہوں نے اسے جھٹلایا تو ہم نے اسے اور جو اس کے ساتھ کشتی میں تھے ان کو نجات دی اور انہیں ہم نے نائب کیا اور جنہوں نے ہماری آیتیں جھٹلائیں ان کو ہم نے ڈبو دیا تو دیکھو ڈرائے ہوؤں کا انجام کیسا ہوا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1438, 10, 74, N'پھر اس کے بعد اور رسول ہم نے ان کی قوموں کی طرف بھیجے تو وہ ان کے پاس روشن دلیلیں لائے تو وہ ایسے نہ تھے کہ ایمان لاتے اس پر جسے پہلے جھٹلا چکے تھے، ہم یونہی مہر لگادیتے ہیں سرکشوں کے دلوں پر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1439, 10, 75, N'پھر ان کے بعد ہم نے موسٰی اور ہارون کو فرعون اور اس کے درباریوں کی طرف اپنی نشانیاں دے کر بھیجا تو انہوں نے تکبر کیا اور وہ مجرم لوگ تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1440, 10, 76, N'تو جب ان کے پاس ہماری طرف سے حق آیا بولے یہ تو ضرور کھلا جادو ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1441, 10, 77, N'موسیٰ نے کہا کیا حق کی نسبت ایسا کہتے ہو جب وہ تمہارے پاس آیا کیا یہ جادو ہے اور جادوگر مراد کو نہیں پہنچتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1442, 10, 78, N'بولے کیا تم ہمارے پاس اس لیے آئے ہو کہ ہمیں اس سے پھیردو جس پر ہم نے اپنے باپ دادا کو پایا اور زمین میں تمہیں دونوں کی بڑائی رہے، اور ہم تم پر ایمان لانے کے نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1443, 10, 79, N'اور فرعون بولا ہر جادوگر علم والے کو میرے پاس لے آؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1444, 10, 80, N'پھر جب جادوگر آئے ان سے موسیٰ نے کہا ڈالو جو تمہیں ڈالنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1445, 10, 81, N'پھر جب انہوں نے ڈالا موسیٰ نے کہا یہ جو تم لائے یہ جادو ہے اب اللہ اسے باطل کردے گا، اللہ مفسدوں کا کام نہیں بناتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1446, 10, 82, N'اور اللہ اپنی باتوں سے حق کو حق کر دکھاتا ہے پڑے برا مانیں مجرم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1447, 10, 83, N'تو موسیٰ پر ایمان نہ لائے مگر اس کی قوم کی اولاد سے کچھ لوگ فرعون اور اس کے درباریوں سے ڈرتے ہوئے کہ کہیں انہیں ہٹنے پر مجبور نہ کردیں اور بیشک فرعون زمین پر سر اٹھانے والا تھا، اور بیشک وہ حد سے گزر گیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1448, 10, 84, N'اور موسیٰ نے کہا اے میری قوم اگر تم اللہ پر ایمان لائے تو اسی پر بھروسہ کرو اگر تم اسلام رکھتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1449, 10, 85, N'بولے ہم نے اللہ پر بھروسہ کیا الہٰی ہم کو ظالم لوگوں کے لیے آزمائش نہ بنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1450, 10, 86, N'اور اپنی رحمت فرماکر ہمیں کافروں سے نجات دے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1451, 10, 87, N'اور ہم نے موسیٰ اور اس کے بھائی کو وحی بھیجی کہ مصر میں اپنی قوم کے لیے مکانات بناؤ اور اپنے گھروں کو نماز کی جگہ کرو اور نماز قائم رکھو، اور مسلمانوں کو خوشخبری سناؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1452, 10, 88, N'اور موسیٰ نے عرض کی اے رب ہمارے تو نے فرعون اور اس کے سرداروں کو آرائش اور مال دنیا کی زندگی میں دیے، اے رب ہمارے! اس لیے کہ تیری راہ سے بہکادیں، اے رب ہمارے! ان کے مال برباد کردے اور ان کے دل سخت کردے کہ ایمان نہ لائیں جب تک دردناک عذاب نہ دیکھ لیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1453, 10, 89, N'فرمایا تم دونوں کی دعا قبول ہوئی تو ثابت قدم رہو اور نادانوں کی راہ نہ چلو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1454, 10, 90, N'اور ہم بنی اسرائیل کو دریا پار لے گئے تو فرعون اور اس کے لشکروں نے ان کا پیچھا کیا سرکشی اور ظلم سے یہاں تک کہ جب اسے ڈوبنے نے ا ٓ لیا بولا میں ایمان لایا کہ کوئی سچا معبود نہیں سوا اس کے جس پر بنی اسرائیل ایمان لائے اور میں مسلمان ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1455, 10, 91, N'کیا اب اور پہلے سے نافرمان رہا اور تو فسادی تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1456, 10, 92, N'آج ہم تیری لاش کو اوترا دیں (باقی رکھیں) گے تو اپنے پچھلوں کے لیے نشانی ہو اور بیشک لوگ ہما ری آ یتو ں سے غافل ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1457, 10, 93, N'اور بیشک ہم نے بنی اسرائیل کو عزت کی جگہ دی اور انہیں ستھری روزی عطا کی تو اختلاف میں نہ پڑے مگر علم آنے کے بعد بیشک تمہارا رب قیامت کے دن ان میں فیصلہ کردے گا جس بات میں جھگڑتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1458, 10, 94, N'اور اے سننے والے! اگر تجھے کچھ شبہ ہو اس میں جو ہم نے تیری طرف اتارا تو ان سے پوچھ دیکھ جو تجھ سے پہلے کتاب پڑھنے والے ہیں بیشک تیرے پاس تیرے رب کی طرف سے حق آیا تو تُو ہر گز شک والوں میں نہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1459, 10, 95, N'اور ہرگز ان میں نہ ہونا جنہوں نے اللہ کی آیتیں جھٹلائیں کہ تو خسارے والوں میں ہوجائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1460, 10, 96, N'بیشک وہ جن پر تیرے رب کی بات ٹھیک پڑچکی ہے ایمان نہ لائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1461, 10, 97, N'اگرچہ سب نشانیاں ان کے پاس آئیں جب تک دردناک عذاب نہ دیکھ لیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1462, 10, 98, N'تو ہوئی ہوتی نہ کوئی بستی کہ ایمان لاتی تو اس کا ایمان کام آتا ہاں یونس کی قوم، جب ایمان لائے ہم نے ان سے رسوائی کا عذاب دنیا کی زندگی میں ہٹادیا اور ایک وقت تک انہیں برتنے دیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1463, 10, 99, N'اور اگر تمہارا رب چاہتا زمین میں جتنے ہیں سب کے سب ایمان لے آتے تو کیا تم لوگوں کو زبردستی کرو گے یہاں تک کہ مسلمان ہوجائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1464, 10, 100, N'اور کسی جان کی قدرت نہیں کہ ایمان لے آئے مگر اللہ کے حکم سے اور عذاب ان پر ڈالنا ہے جنہیں عقل نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1465, 10, 101, N'تم فرماؤ دیکھو آسمانوں اور زمین میں کیا ہے اور آیتیں اور رسول انہیں کچھ نہیں دیتے جن کے نصیب میں ایمان نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1466, 10, 102, N'تو انہیں کاہے کا انتظار ہے مگر انہیں لوگوں کے سے دنوں کا جو ان سے پہلے ہو گزرے تم فرماؤ تو انتظار کرو میں بھی تمہارے ساتھ انتظار میں ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1467, 10, 103, N'پھر ہم اپنے رسولوں اور ایمان والوں کو نجات دیں گے بات یہی ہے ہمارے ذمہ کرم پر حق ہے مسلمانوں کو نجات دینا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1468, 10, 104, N'تم فرماؤ، اے لوگو! اگر تم میرے دین کی طرف سے کسی شبہ میں ہو تو میں تو اسے نہ پوجوں کا جسے تم اللہ کے سوا پوجتے ہو ہاں اس اللہ کو پوجتا ہوں جو تمہاری جان نکالے گا اور مجھے حکم ہے کہ ایمان والوں میں ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1469, 10, 105, N'اور یہ کہ اپنا منہ دین کے لیے سیدھا رکھ سب سے الگ ہوکر اور ہرگز شرک والوں میں نہ ہونا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1470, 10, 106, N'اور اللہ کے سوا اس کی بندگی نہ کر جو نہ تیرا بھلا کرسکے نہ برا، پھر اگر ایسا کرے تو اس وقت تو ظالموں سے ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1471, 10, 107, N'اور اگر تجھے اللہ کوئی تکلیف پہنچائے تو اس کا کوئی ٹالنے والا نہیں اس کے سوا، اور اگر تیرا بھلا چاہے تو اس کے فضل کے رد کرنے والا کوئی نہیں اسے پہنچا تا ہے اپنے بندوں میں جسے چاہے، اور وہی بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1472, 10, 108, N'تم فرماؤ اے لوگو! تمہارے پاس تمہارے رب کی طرف سے حق آیا تو جو راہ پر آیا وہ اپنے بھلے کو راہ پر آیا اور جو بہکا وہ اپنے برے کو بہکا اور کچھ میں کڑوڑا (حاکمِ اعلیٰ) نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1473, 10, 109, N'اور اس پر چلو جو تم پر وحی ہوتی ہے اور صبر کرو یہاں تک کہ اللہ حکم فرمائے اور وہ سب سے بہتر حکم فرمانے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1474, 11, 1, N'یہ ایک کتاب ہے جس کی آیتیں حکمت بھری ہیں پھر تفصیل کی گئیں حکمت والے خبردار کی طرف سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1475, 11, 2, N'کہ بندگی نہ کرو مگر اللہ کی بیشک میں تمہارے لیے اس کی طرف سے ڈر اور خوشی سنانے والا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1476, 11, 3, N'اور یہ کہ اپنے رب سے معافی مانگو پھر اس کی طرف توبہ کرو تمہیں بہت اچھا برتنا (فائدہ اٹھانا) دے گا ایک ٹھہرائے وعدہ تک اور ہر فضیلت والے کو اس کا فضل پہنچائے گا اور اگر منہ پھیرو تو میں تم پر بڑے دن کے عذاب کا خوف کرتا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1477, 11, 4, N'تمہیں اللہ ہی کی طرف پھرنا ہے اور وہ ہر شے پر قادر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1478, 11, 5, N'سنو وہ اپنے سینے دوہرے کرتے (منہ چھپاتے) ہیں کہ اللہ سے پردہ کریں سنو جس وقت وہ اپنے کپڑوں سے سارا بدن ڈھانپ لیتے ہیں اس وقت بھی اللہ ان کا چھپا اور ظاہر سب کچھ جانتا ہے بیشک وہ دلوں کی بات جاننے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1479, 11, 6, N'اور زمین پر چلنے والا کوئی ایسا نہیں جس کا رزق اللہ کے ذمہٴ کرم پر نہ ہو اور جانتا ہے کہ کہاں ٹھہرے گا اور کہاں سپرد ہوگا سب کچھ ایک صاف بیان کرنے والی کتاب میں ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1480, 11, 7, N'اور وہی ہے جس نے آسمانوں اور زمین کو چھ دن میں بنایا اور اس کا عرش پانی پر تھا کہ تمہیں آزمائے تم میں کس کا کام اچھا ہے، اور اگر تم فرماؤ کہ بیشک تم مرنے کے بعد اٹھائے جاؤ گے تو کافر ضرور کہیں گے کہ یہ تو نہیں مگر کھلا جادو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1481, 11, 8, N'اور اگر ہم ان سے عذاب کچھ گنتی کی مدت تک ہٹادیں تو ضرور کہیں گے کس چیز نے روکا ہے سن لو جس دن ان پر آئے گا ان سے پھیرا نہ جائے گا، اور انہیں گھیرے گا وہی عذاب جس کی ہنسی اڑاتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1482, 11, 9, N'اور اگر ہم آدمی کو اپنی کسی رحمت کا مزہ دیں پھر اسے اس سے چھین لیں ضرور وہ بڑا ناامید ناشکرا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1483, 11, 10, N'اور اگر ہم اسے نعمت کا مزہ دیں اس مصیبت کے بعد جس اسے پہنچی تو ضرور کہے گا کہ برائیاں مجھ سے دور ہوئیں بیشک وہ خوش ہونے والا بڑائی مارنے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1484, 11, 11, N'مگر جنہوں نے صبر کیا اور اچھے کام کیے ان کے لیے بخشش اور بڑا ثواب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1485, 11, 12, N'تو کیا جو وحی تمہاری طرف ہوتی ہے اس میں سے کچھ تم چھوڑ دو گے اور اس پر دل تنگ ہوگے اس بناء پر کہ وہ کہتے ہیں ان کے ساتھ کوئی خزانہ کیوں نہ اترا ان کے ساتھ کوئی فرشتہ آتا، تم تو ڈر سنانے والے ہو اور اللہ ہر چیز پر محافظ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1486, 11, 13, N'کیا یہ کہتے ہیں کہ انھوں نے اسے جی سے بنالیا، تم فرماؤ کہ تم ایسی بنائی ہوئی دس سورتیں لے آؤ اور اللہ کے سوا جو مل سکیں سب کو بلالو اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1487, 11, 14, N'تو اے مسلمانو اگر وہ تمہاری اس بات کا جواب نہ دے سکیں تو سمجھ لو کہ وہ اللہکے علم ہی سے اترا ہے اور یہ کہ اس کے سوا کوئی سچا معبود نہیں تو کیا اب تم مانو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1488, 11, 15, N'جو دنیا کی زندگی اور آرائش چاہتا ہو ہم اس میں ان کا پورا پھل دے دیں گے اور اس میں کمی نہ دیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1489, 11, 16, N'یہ ہیں وہ جن کے لیے آخرت میں کچھ نہیں مگر آ گ اور اکارت گیا جو کچھ وہاں کرتے تھے اور نابود ہوئے جو ان کے عمل تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1490, 11, 17, N'تو کیا وہ جو اپنے رب کی طرف سے روشن دلیل پر ہو اور اس پر اللہ کی طرف سے گواہ آئے اور اس سے پہلے موسیٰ کی کتاب پیشوا اور رحمت وہ اس پر ایمان لاتے ہیں، اور جو اس کا منکر ہو سارے گروہوں میں تو آگ اس کا وعدہ ہے تو اے سننے والے! تجھے کچھ اس میں شک نہ ہو، بیشک وہ حق ہے تیرے رب کی طرف سے لیکن بہت آدمی ایمان نہیں رکھتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1491, 11, 18, N'اور اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے اور اپنے رب کے حضور پیش کیے جائیں گے اور گواہ کہیں گے یہ ہیں جنہوں نے اپنے رب پر جھوٹ بولا تھا، ارے ظا لموں پر خدا کی لعنت')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1492, 11, 19, N'جو اللہ کی راہ سے روکتے ہیں اور اس میں کجی چاہتے ہیں، اور وہی آخرت کے منکر ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1493, 11, 20, N'وہ تھکانے والے نہیں زمین میں اور نہ اللہ سے جدا ان کے کوئی حمایتی انہیں عذاب پر عذاب ہوگا وہ نہ سن سکتے تھے اور نہ دیکھتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1494, 11, 21, N'وہی ہیں جنہوں نے اپنی جانیں گھاٹے میں ڈالیں اور ان سے کھوئی گئیں جو باتیں جوڑتے تھے خواہ نخواہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1495, 11, 22, N'(ضرور) وہی آخرت میں سب سے زیادہ نقصان میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1496, 11, 23, N'بیشک جو ایمان لائے اور اچھے کام کیے اور اپنے رب کی طرف رجوع لائے وہ جنت والے ہیں، وہ اس میں ہمیشہ رہیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1497, 11, 24, N'دونوں فریق کا حال ایسا ہے جیسے ایک اندھا اور بہرا اور دوسرا دیکھتا اور سنتا کيا ان دونوں حال کا ايک سا ہے تو کياتم دہيان نہيں کرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1498, 11, 25, N'اور بے شک ہم نے نوح کو اس کی قوم کی طرف بھيجا کہ میں تمہارے لیے صریح ڈر سنانے والا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1499, 11, 26, N'کہ اللہ کے سوا کسی کو نہ پوجو، بیشک میں تم پر ایک مصیبت والے دن کے عذاب سے ڈرتا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1500, 11, 27, N'تو اس کی قوم کے سردار جو کافر ہوئے تھے بولے ہم تو تمہیں اپنے ہی جیسا آدمی دیکھتے ہیں اور ہم نہیں دیکھتے کہ تمہاری پیروی کسی نے کی ہو مگر ہمارے کمینوں نے سرسری نظر سے اور ہم تم میں اپنے اوپر کوئی بڑائی نہیں پاتے بلکہ ہم تمہیں جھوٹا خیال کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1501, 11, 28, N'بولا اے میری قوم! بھلا بتاؤ تو اگر میں اپنے رب کی طرف سے دلیل پر ہوں اور اس نے مجھے اپنے پاس سے رحمت بخشی تو تم اس سے اندھے رہے، کیا ہم اسے تمہارے گلے چپیٹ (چپکا) دیں اور تم بیزار ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1502, 11, 29, N'اور اے قوم! میں تم سے کچھ اس پر مال نہیں مانگتا میرا اجر تو اللہ ہی پر ہے اور میں مسلمانوں کو دور کرنے والا نہیں بیشک وہ اپنے رب سے ملنے والے ہیں لیکن میں تم کو نرے جاہل لوگ پا تا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1503, 11, 30, N'اور اے قوم مجھے اللہ سے کون بچالے گا اگر میں انہیں دور کروں گا، تو کیا تمہیں دھیان نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1504, 11, 31, N'اور میں تم سے نہیں کہتا کہ میرے پاس اللہ کے خزانے ہیں اور نہ یہ کہ میں غیب جان جانتا ہوں اور نہ یہ کہتا ہوں کہ میں فرشتہ ہوں اور میں انہیں نہیں کہتا جن کو تمہاری نگاہیں حقیر سمجھتی ہیں کہ ہرگز انہیں اللہ کوئی بھلائی نہ دے گا، اللہ خوب جانتا ہے جو ان کے دلوں میں ہے ایسا کروں تو ضرور میں ظالموں میں سے ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1505, 11, 32, N'بولے اے نوح تم ہم سے جھگڑے اور بہت ہی جھگڑے تو لے ا ٓ ؤ جس کا ہمیں وعدے دے رہے ہو اگر تم سچے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1506, 11, 33, N'بولا وہ تو اللہ تم پر لائے گا اگر چاہے اور تم تھکا نہ سکو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1507, 11, 34, N'اور تمہیں میری نصیحت نفع نہ دے گی اگر میں تمہارا بھلا چاہوں جبکہ اللہ تمہاری گمراہی چاہے، وہ تمہارا رب ہے، اور اسی کی طرف پھرو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1508, 11, 35, N'کیا یہ کہتے ہیں کہ انہوں نے اپنے جی سے بنالیا تم فرماؤ اگر میں نے بنالیا ہوگا تو میرا گناہ مجھ پر ہے اور میں تمہارے گناہ سے الگ ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1509, 11, 36, N'اور نوح کو وحی ہوئی تمہاری قوم سے مسلمان نہ ہوں گے مگر جتنے ایمان لاچکے تو غم نہ کھا اس پر جو وہ کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1510, 11, 37, N'اور کشتی بناؤ ہمارے سامنے اور ہمارے حکم سے اور ظالموں کے بارے میں مجھ سے بات نہ کرنا وہ ضرور ڈوبائے جائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1511, 11, 38, N'اور نوح کشتی بناتا ہے اور جب اس کی قوم کے سردار اس پر گزرتے اس پر ہنستے بولا اگر تم ہم پر ہنستے ہو تو ایک وقت ہم تم پر ہنسیں گے جیسا تم ہنستے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1512, 11, 39, N'تو اب جان جاؤ گے کس پر آتا ہے وہ عذاب کہ اسے رسوا کرے اور اترتا ہے وہ عذاب جو ہمیشہ رہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1513, 11, 40, N'یہاں تک کہ کہ جب ہمارا حکم آیا اور تنور اُبلا ہم نے فرمایا کشتی میں سوار کرلے ہر جنس میں سے ایک جوڑا نر و مادہ اور جن پر بات پڑچکی ہے ان کے سوا اپنے گھر والوں اور باقی مسلمانوں کو اور اس کے ساتھ مسلمان نہ تھے مگر تھوڑے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1514, 11, 41, N'اور بولا اس میں سوار ہو اللہ کے نام پر اس کا چلنا اور اس کا ٹھہرنا بیشک میرا رب ضرور بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1515, 11, 42, N'اور وہی انہیں لیے جارہی ہے ایسی موجوں میں جیسے پہاڑ اور نوح نے اپنے بیٹے کو پکارا اور وہ اس سے کنارے تھا اے میرے بچے ہمارے ساتھ سوار ہوجا اور کافروں کے ساتھ نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1516, 11, 43, N'بولا اب میں کسی پہاڑ کی پناہ لیتا ہوں وہ مجھے پانی سے بچالے گا، کہا آج اللہ کے عذاب سے کوئی بچانے والا نہیں مگر جس پر وہ رحم کرے اور ان کے بیچ میں موج آڑے آئی تو وہ ڈوبتوں میں رہ گیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1517, 11, 44, N'اور حکم فرمایا گیا کہ اے زمین! اپنا پانی نگل لے اور اے آسمان! تھم جا اور پانی خشک کردیا گیا اور کام تمام ہوا اور کشتی کوہ ِ جودی پر ٹھہری اور فرمایا گیا کہ دور ہوں بے انصاف لوگ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1518, 11, 45, N'اور نوح نے اپنے رب کو پکارا عرض کی اے میرے رب میرا بیٹا بھی تو میرا گھر والا ہے اور بیشک تیرا وعدہ سچا ہے اور تو سب سے بڑا حکم والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1519, 11, 46, N'فرمایا اے نوح! وہ تیرے گھر والوں میں نہیں بیشک اس کے کام بڑے نالائق ہیں، تو مجھ سے وہ بات نہ مانگ جس کا تجھے علم نہیں میں تجھے نصیحت فرماتا ہوں کہ نادان نہ بن،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1520, 11, 47, N'عرض کی اے رب میرے میں تیری پناہ چاہتا ہوں کہ تجھ سے وہ چیز مانگوں جس کا مجھے علم نہیں، اور اگر تو مجھے نہ بخشے اور رحم نہ کرے تو میں زیاں کار ہوجاؤں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1521, 11, 48, N'فرمایا گیا اے نوح! کشتی سے اتر ہماری طرف سے سلام اور برکتوں کےساتھ جو تجھ پر ہیں اور تیرے ساتھ کے کچھ گروہوں پر اور کچھ گروہ ہیں جنہیں ہم دنیا برتنے دیں گے پھر انہیں ہماری طرف سے دردناک عذاب پہنچے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1522, 11, 49, N'یہ غیب کی خبریں ہم تمہاری طرف وحی کرتے ہیں انہیں نہ تم جانتے تھے نہ تمہاری قوم اس سے پہلے، تو صبر کرو بیشک بھلا انجام پرہیزگاروں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1523, 11, 50, N'اور عاد کی طرف ان کے ہم قوم ہود کو کہا اے میری قوم! اللہ کو پوجو اس کے سوا تمہارا کوئی معبود نہیں، تم تو بڑے مفتری (بالکل جھوٹے الزام عائد کرنے والے) ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1524, 11, 51, N'اے قوم! میں اس پر تم سے کچھ اجرت نہیں مانگتا، میری مزدوری تو اسی کے ذمہ ہے جس نے مجھے پیدا کیا تو کیا تمہیں عقل نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1525, 11, 52, N'اور اے میری قوم اپنے رب سے معافی چاہو پھر اس کی طرف رجوع لاؤ تم پر زور کا پانی بھیجے گا، اور تم میں جتنی قوت ہے اس سے زیادہ دے گا اور جرم کرتے ہوئے روگردانی نہ کرو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1526, 11, 53, N'بولے اے ہود تم کوئی دلیل لے کر ہمارے پاس نہ آئے اور ہم خالی تمہارے کہنے سے اپنے خداؤں کو چھوڑنے کے نہیں نہ تمہاری بات پر یقین لائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1527, 11, 54, N'ہم تو یہی کہتے ہیں کہ ہمارے کسی خدا کی تمہیں بری جھپٹ (پکڑ) پہنچی کہا میں اللہ کو گواہ کرتا ہوں اور تم سب گواہ ہوجاؤ کہ میں بیزار ہوں ان سب سے جنہیں تم اللہ کے سوا اس کا شریک ٹھہراتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1528, 11, 55, N'تم سب مل کر میرا برا چاہو پھر مجھے مہلت نہ دو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1529, 11, 56, N'میں نے اللہ پر بھروسہ کیا جو میرا رب ہے اور تمہارا رب، کوئی چلنے والا نہیں جس کی چوٹی اس کے قبضہٴ قدرت میں نہ ہو بیشک میرا رب سیدھے راستہ پر ملتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1530, 11, 57, N'پھر اگر تم منہ پھیرو تو میں تمہیں پہنچا چکا جو تمہاری طرف لے کر بھیجا گیا اور میرا رب تمہاری جگہ اوروں کو لے آئے گا اور تم اس کا کچھ نہ بگاڑ سکو گے بیشک میرا رب ہر شے پر نگہبان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1531, 11, 58, N'اور جب ہمارا حکم آیا ہم نے ہود اور اس کے ساتھ کے مسلمانوں کو اپنی رحمت فرما کر بچالیا اور انہیں سخت عذاب سے نجات دی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1532, 11, 59, N'اور یہ عاد ہیں کہ اپنے رب کی آیتوں سے منکر ہوئے اور اس کے رسولوں کی نافرمانی کی اور ہر بڑے سرکش ہٹ دھرم کے کہنے پر چلے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1533, 11, 60, N'اور ان کے پیچھے لگی اس دنیا میں لعنت اور قیامت کے دن، سن لو! بیشک عاد اپنے رب سے منکر ہوئے، ارے دور ہوں عاد ہود کی قوم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1534, 11, 61, N'اور ثمود کی طرف ان کے ہم قوم صا لح کو کہا اے میری قوم اللہ کو پوجو اس کے سوا تمہارا کوئی معبود نہیں اس نے تمہیں زمین میں پیدا کیا اور اس میں تمہیں بسایا تو اس سے معافی چاہو پھر اس کی طرف رجوع لاؤ، بیشک میرا رب قریب ہے دعا سننے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1535, 11, 62, N'بولے اے صا لح! اس سے پہلے تو تم ہم میں ہونہار معلوم ہوتے تھے کیا تم ہمیں اس سے منع کرتے ہو کہ اپنے باپ دادا کے معبودوں کو پوجیں اور بیشک جس بات کی طرف ہمیں بلاتے ہو ہم اس سے ایک بڑے دھوکا ڈالنے والے شک میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1536, 11, 63, N'بولا اے میری قوم! بھلا بتاؤ تو اگر میں اپنے رب کی طرف سے روشن دلیل پر ہوں اور اس نے مجھے اپنے پاس سے رحمت بخشی تو مجھے اس سے کون بچائے گا اگر میں اس کی نافرمانی کروں تو تم مجھے سوا نقصان کے کچھ نہ بڑھاؤ گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1537, 11, 64, N'اور اے میری قوم! یہ اللہ کا ناقہ ہے تمہارے لیے نشانی تو اسے چھوڑ دو کہ اللہ کی زمین میں کھائے اور اسے بری طرح ہاتھ نہ لگانا کہ تم کو نزدیک عذاب پہنچے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1538, 11, 65, N'تو انہوں نے اس کی کونچیں کاٹیں تو صا لح نے کہا اپنے گھرو ں میں تین دن اور برت لو (فائدہ اٹھالو) یہ وعدہ ہے کہ جھوٹا نہ ہوگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1539, 11, 66, N'پھر جب ہمارا حکم آیا ہم نے صا لح اور اس کے ساتھ کے مسلمانوں کو اپنی رحمت فرماکر بچالیا اور اس دن کی رسوائی سے، بیشک تمہارا رب قومی عزت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1540, 11, 67, N'اور ظالموں کو چنگھاڑ نے آ لیا تو صبح اپنے گھروں میں گھٹنوں کے بل پڑے رہ گئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1541, 11, 68, N'گویا کبھی یہاں بسے ہی نہ تھے، سن لو! بیشک ثمود اپنے رب سے منکر ہوئے ارے لعنت ہو ثمود پر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1542, 11, 69, N'اور بیشک ہمارے فرشتے ابراہیم کے پاس مژدہ لے کر آئے بولے سلام کہا کہا سلام پھر کچھ دیر نہ کی کہ ایک بچھڑا بھنا لے آئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1543, 11, 70, N'پھر جب دیکھا کہ ان کے ہاتھ کھانے کی طرف نہیں پہنچتے ان کو اوپری سمجھا اور جی ہی جی میں ان سے ڈرنے لگا، بولے ڈریے نہیں ہم قوم لوط کی طرف بھیجے گئے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1544, 11, 71, N'اور اس کی بی بی کھڑی تھی وہ ہنسنے لگی تو ہم نے اسے اسحاق کی خوشخبری دی اور اسحاق کے پیچھے یعقوب کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1545, 11, 72, N'بولی ہائے خرابی کیا میرے بچہ ہوگا اور میں بوڑھی ہوں اور یہ ہیں میرے شوہر بوڑھے بیشک یہ تو اچنبھے کی بات ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1546, 11, 73, N'فرشتے بولے کیا اللہ کے کام کا اچنبھا کرتی ہو اللہ کی رحمت اور اس کی برکتیں تم پر اس گھر والو! بیشک وہی ہے سب خوبیوں والا عزت والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1547, 11, 74, N'پھر جب ابراہیم کا خوف زائل ہوا اور اسے خوشخبری ملی ہم سے قوم لوط کے بارے میں جھگڑنے لگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1548, 11, 75, N'بیشک ابراہیم تحمل والا بہت آہیں کرنے والا رجوع کرنے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1549, 11, 76, N'اے ابراہیم اس خیال میں نہ پڑ بیشک تیرے رب کا حکم آچکا اور بیشک ان پر عذاب آنے والا ہے کہ پھیرا نہ جائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1550, 11, 77, N'اور جب لوط کے یہاں ہمارے فرشتے آئے اسے ان کا غم ہوا او ر ان کے سبب دل تنگ ہوا اور بولا یہ بڑی سختی کا دن ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1551, 11, 78, N'اور اس کے پاس کی قوم دوڑتی آئی، ور انہیں آگے ہی سے برے کاموں کی عادت پڑی تھی کہا اے قوم! یہ میری قوم کی بیٹیاں ہیں یہ تمہارے لیے ستھری ہیں تو اللہ سے ڈرو اور مجھے میرے مہمانوں میں رسوا نہ کرو، کیا تم میں ایک آدمی بھی نیک چلن نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1552, 11, 79, N'بولے تمہیں معلوم ہے کہ تمہاری قوم کی بیٹیوں میں ہمارا کوئی حق نہیں اور تم ضرور جانتے ہو جو ہماری خواہش ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1553, 11, 80, N'بولے اے کاش! مجھے تمہارے مقابل زور ہوتا یا کسی مضبوط پائے کی پناہ لیتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1554, 11, 81, N'فرشتے بولے اے لوط ہم تمہارے رب کے بھیجے ہوئے ہیں وہ تم تک نہیں پہنچ سکتے تو اپنے گھر والوں کو راتوں رات لے جاؤ اور تم میں کوئی پیٹھ پھیر کر نہ دیکھے سوائے تمہاری عورت کے اسے بھی وہی پہنچنا ہے جو انہیں پہنچے گا بیشک ان کا وعدہ صبح کے وقت کا ہے کیا صبح قریب نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1555, 11, 82, N'پھر جب ہمارا حکم آیا ہم نے اس بستی کے اوپر کو اس کا نیچا کردیا اور اس پر کنکر کے پتھر لگا تار برسائے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1556, 11, 83, N'جو نشان کیے ہوئے تیرے رب کے پاس ہیں اور وہ پتھر کچھ ظالموں سے دور نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1557, 11, 84, N'اور مدین کی طرف ان کے ہم قوم شعیب کو کہا اے میری قوم اللہ کو پوجو اس کے سوا کوئی معبود نہیں اور ناپ اور تول میں کمی نہ کرو بیشک میں تمہیں آسودہ حال دیکھتا ہوں اور مجھے تم پر گھیر لینے والے دن کا عذاب کا ڈر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1558, 11, 85, N'اور اے میری قوم ناپ اور تول انصاف کے ساتھ پوری کرو اور لوگوں کو ان کی چیزیں گھٹا کر نہ دو اور زمین میں فساد مچاتے نہ پھرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1559, 11, 86, N'اللہ کا دیا جو بچ رہے وہ تمہارے لیے بہتر ہے اگر تمہیں یقین ہو اور میں کچھ تم پر نگہبان نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1560, 11, 87, N'بولے اے شعیب! کیا تمہاری نماز تمہیں یہ حکم دیتی ہے کہ ہم اپنے باپ دادا کے خداؤں کو چھوڑ دیں یا اپنے مال میں جو چا ہیں نہ کریں ہاں جی تمہیں بڑے عقلمند نیک چلن ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1561, 11, 88, N'کہا اے میری قوم بھلا بتاؤ تو اگر میں اپنے رب کی طرف سے ایک روشن دلیل پر ہوں او راس نے مجھے اپنے پاس سے اچھی روزی دی اور میں نہیں چاہتا ہوں کہ جس بات سے تمہیں منع کرتا ہوں آپ اس کے خلاف کرنے لگوں میں تو جہاں تک بنے سنوارنا ہی چاہتا ہوں، اور میری توفیق اللہ ہی کی طرف سے ہے، میں نے اسی پر بھروسہ کیا اور اسی کی طرف رجوع ہوتا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1562, 11, 89, N'اور اے میری قوم تمہیں میری ضد یہ نہ کموادے کہ تم پر پڑے جو پڑا تھا نوح کی قوم یا ہود کی قوم یا صا لح کی قوم پر، اور لوط کی قوم تو کچھ تم سے دور نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1563, 11, 90, N'اور اپنے رب سے معافی چاہو پھر اس کی طرف رجوع لاؤ، بیشک میرا رب مہربان محبت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1564, 11, 91, N'بولے اے شعیب! ہماری سمجھ میں نہیں آتیں تمہاری بہت سی باتیں اور بیشک ہم تمہیں اپنے میں کمزور دیکھتے ہیں اور اگر تمہارا کنبہ نہ ہوتا تو ہم نے تمہیں پتھراؤ کردیا ہوتا اور کچھ ہماری نگاہ میں تمہیں عزت نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1565, 11, 92, N'کہا اے میری قوم کیا تم پر میرے کنبہ کا دباؤ اللہ سے زیادہ ہے اور اسے تم نے اپنی پیٹھ کے پیچھے ڈال رکھا بیشک جو کچھ تم کرتے ہو سب میرے رب کے بس میں ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1566, 11, 93, N'اور اے قوم تم اپنی جگہ اپنا کام کیے جا ؤ میں اپنا کام کرتا ہوں، اب جاننا چاہتے ہو کس پر آتا ہے وہ عذاب کہ اسے رسوا کرے گا اور کون جھوٹا ہے، اور انتظار کرو میں بھی تمہارے ساتھ انتظار میں ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1567, 11, 94, N'اور جب ہمارا حکم آیا ہم نے شعیب اور اس کے ساتھ کے مسلمانوں کو اپنی رحمت فرماکر بچالیا اور ظالموں کو چنگھاڑ نے آ لیا تو صبح اپنے گھروں میں گھٹنوں کے بل پڑے رہ گئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1568, 11, 95, N'گویا کبھی وہاں بسے ہی نہ تھے، ارے دُور ہوں مدین جیسے دور ہوئے ثمود')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1569, 11, 96, N'اور بیشک ہم نے موسیٰ کو اپنی آیتوں اور صریح غلبے کے ساتھ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1570, 11, 97, N'فرعون اور ا س کے درباریوں کی طرف بھیجا تو وہ فرعون کے کہنے پر چلے اور فرعون کا کام راستی کا نہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1571, 11, 98, N'اپنی قوم کے آگے ہوگا قیامت کے دن تو انہیں دوزخ میں لا اتارے گا اور و ه کیا ہی برا گھاٹ اترنے کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1572, 11, 99, N'اور ان کے پیچھے پڑی اس جہان میں لعنت اور قیامت کے دن کیا ہی برا انعام جو انہیں ملا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1573, 11, 100, N'یہ بستیوں کی خبریں ہیں کہ ہم تمہیں سناتے ہیں ان میں کوئی کھڑی ہے اور کوئی کٹ گئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1574, 11, 101, N'اور ہم نے ان پر ظلم نہ کیا خود انہوں نے اپنا برا کیا تو ان کے معبود جنہیں اللہ کے سوا پوجتے تھے ان کے کچھ کام نہ آئے جب تمہارے رب کا حکم آیا اور ان سے انہیں ہلاک کے سوا کچھ نہ بڑھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1575, 11, 102, N'اور ایسی ہی پکڑ ہے تیرے رب کی جب بستیوں کو پکڑتا ہے ان کے ظلم پر، بیشک اس کی پکڑ دردناک کرّ ی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1576, 11, 103, N'بیشک اس میں نشانی ہے اس کے لیے جو آخرت کے عذاب سے ڈرے وہ دن ہے جس میں سب لوگ اکٹھے ہوں گے اور وہ دن حاضری کا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1577, 11, 104, N'اور ہم اسے پیچھے نہیں ہٹاتے مگر ایک گنی ہوئی مدت کے لیئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1578, 11, 105, N'جب وہ دن آئے گا کوئی بے حکم خدا بات نہ کرے گا تو ان میں کوئی بدبخت ہے اور کوئی خوش نصیب')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1579, 11, 106, N'تو وہ جو بدبخت ہیں وہ تو دوزخ میں ہیں وہ اس گدھے کی طرح رینکیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1580, 11, 107, N'وہ اس میں رہیں گے جب تک آسمان و زمین رہیں مگر جتنا تمہارے رب نے چاہا بیشک تمہارا رب جب جو چاہے کرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1581, 11, 108, N'اور وہ جو خوش نصیب ہوئے وہ جنت میں ہیں ہمیشہ اس میں رہیں گے جب تک آسمان و زمین مگر جتنا تمہارے رب نے چاہا یہ بخشش ہے کبھی ختم نہ ہوگی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1582, 11, 109, N'تو اے سننے والے! دھوکا میں نہ پڑ اس سے جیسے یہ کافر پوجتے ہیں یہ ویسا ہی پوجتے ہیں جیسا پہلے ان کے باپ دادا پوجتے تھے اور بیشک ہم ان کا حصہ انہیں پورا پھیردیں گے جس میں کمی نہ ہوگی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1583, 11, 110, N'اور بیشک ہم نے موسیٰ کو کتاب دی تو اس میں پھوٹ پڑگئی اگر تمہارے رب کی ایک بات پہلے نہ ہوچکی ہوتی تو جبھی ان کا فیصلہ کردیا جاتا اور بیشک وہ اس کی طرف سے دھوکا ڈالنے والے شک میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1584, 11, 111, N'اور بیشک جتنے ہیں ایک ایک کو تمہارا رب اس کا عمل پورا بھردے گا اسے ان کے کا موں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1585, 11, 112, N'تو قائم رہو جیسا تمہیں حکم ہے اور جو تمہارے ساتھ رجوع لایا ہے اور اے لوگو! سرکشی نہ کرو بیشک وہ تمہارے کام دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1586, 11, 113, N'اور ظالموں کی طرف نہ جھکو کہ تمہیں آ گ چھوئے گی اور اللہ کے سوا تمہارا کوئی حما یتی نہیں پھر مدد نہ پاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1587, 11, 114, N'اور نماز قائم رکھو دن کے دونوں کناروں اور کچھ رات کے حصوں میں بیشک نیکیاں برائیوں کو مٹادیتی ہیں، یہ نصیحت ہے نصیحت ماننے والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1588, 11, 115, N'اور صبر کرو کہ اللہ نیکوں کا نیگ (اجر) ضائع نہیں کرتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1589, 11, 116, N'تو کیوں نہ ہوئے تم میں سے اگلی سنگتوں (قوموں) میں ایسے جن میں بھلائی کا کچھ حصہ لگا رہا ہوتا کہ زمین میں فساد سے روکتے ہاں ان میں تھوڑے تھے وہی جن کو ہم نے نجات دی اور ظالم اسی عیش کے پیچھے پڑے رہے جو انہیں دیا گیا اور وہ گنہگار تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1590, 11, 117, N'اور تمہارا رب ایسا نہیں کہ بستیوں کو بے وجہ ہلاک کردے اور ان کے لوگ اچھے ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1591, 11, 118, N'اور اگرتمہارا رب چاہتا تو سب آدمیوں کو ایک ہی امت کردیتا اور وہ ہمیشہ اختلاف میں رہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1592, 11, 119, N'مگر جن پر تمہارے رب نے رحم کیا اور لوگ اسی لیے بنائے ہیں اور تمہارے رب کی بات پوری ہوچکی کہ بیشک ضرور جہنم بھر دوں گا جنوں اور آدمیوں کو ملا کر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1593, 11, 120, N'اور سب کچھ ہم تمہیں رسولوں کی خبریں سناتے ہیں جس سے تمہا را دل ٹھیرائیں اور اس سورت میں تمہارے پاس حق آیا اور مسلمانوں کو پند و نصیحت')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1594, 11, 121, N'اور کافروں سے فرماؤ تم اپنی جگہ کام کیے جاؤ ہم اپنا کام کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1595, 11, 122, N'اور راہ دیکھو ہم بھی راہ دیکھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1596, 11, 123, N'اور اللہ ہی کے لیے ہیں آسمانوں اور زمین کے غیب اور اسی کی طرف سب کاموں کی رجوع ہے تو اس کی بندگی کرو اور اس پر بھروسہ رکھو، اور تمہارا رب تمہارے کا موں سے غافل نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1597, 12, 1, N'یہ روشن کتاب کی آیتیں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1598, 12, 2, N'بیشک ہم نے اسے عربی قرآن اتارا کہ تم سمجھو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1599, 12, 3, N'ہم تمہیں سب اچھا بیان سناتے ہیں اس لیے کہ ہم نے تمہاری طرف اس قرآن کی وحی بھیجی اگرچہ بیشک اس سے پہلے تمہیں خبر نہ تھی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1600, 12, 4, N'یاد کرو جب یوسف نے اپنے با پ سے کہا اے میرے باپ میں نے گیارہ تارے اور سورج اور چاند دیکھے انہیں اپنے لیے سجدہ کرتے دیکھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1601, 12, 5, N'کہا اے میرے بچے اپنا خواب اپنے بھائیوں سے نہ کہنا وہ تیرے ساتھ کوئی چا ل چلیں گے بیشک شیطان آدمی کا کھلا دشمن ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1602, 12, 6, N'اور اسی طرح تجھے تیرا رب چن لے گا اور تجھے باتوں کا انجام نکا لنا سکھائے گا اور تجھ پر اپنی نعمت پوری کرے گا اور یعقوب کے گھر والوں پر جس طرح تیرے پہلے دنوں باپ دادا ابراہیم ؑ اور اسحق ؑ پر پوری کی بیشک تیرا رب علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1603, 12, 7, N'بیشک یوسف اور اس کے بھائیوں میں پوچھنے والوں کے لیے نشانیاں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1604, 12, 8, N'جب بولے کہ ضرور یوسف اور اس کا بھائی ہمارے باپ کو ہم سے زیادہ پیارے ہیں اور ہم ایک جماعت ہیں بیشک ہمارے باپ صراحةً ان کی محبت میں ڈوبے ہوئے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1605, 12, 9, N'یوسف کو مار ڈالو یا کہیں زمین میں پھینک آؤ کہ تمہارے باپ کا منہ صرف تمہاری ہی طرف رہے اور اس کے بعد پھر نیک ہوجانا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1606, 12, 10, N'ان میں ایک کہنے والا بولا یوسف کو مارو نہیں اور اسے اندھے کنویں میں ڈال دو کہ کوئی چلتا اسے آکر لے جائے اگر تمہیں کرنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1607, 12, 11, N'بولے اے ہمارے باپ! آپ کو کیا ہوا کہ یوسف کے معامل ہ میں ہمارا اعتبار نہیں کرتے اور ہم تو اس کے خیر خواہ ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1608, 12, 12, N'کل اسے ہمارے ساتھ بھیج دیجئے کہ میوے کھائے اور کھیلے اور بیشک ہم اس کے نگہبان ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1609, 12, 13, N'بولا بیشک مجھے رنج دے گا کہ اسے لے جاؤ اور ڈرتا ہوں کہ اسے بھیڑیا کھالے اور تم اس سے بے خبر رہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1610, 12, 14, N'بولے اگر اسے بھیڑیا کھا جائے اور ہم ایک جماعت ہیں جب تو ہم کسی مصرف کے نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1611, 12, 15, N'پھر جب اسے لے گئے اور سب کی رائے یہی ٹھہری کہ اسے اندھے کنویں میں ڈال دیں اور ہم نے اسے وحی بھیجی کہ ضرور تو انہیں ان کا یہ کام جتادے گا ایسے وقت کہ وہ نہ جانتے ہوں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1612, 12, 16, N'اور رات ہوئے اپنے باپ کے پاس روتے ہوئے آئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1613, 12, 17, N'بولے اے ہمارے باپ ہم دوڑ کرتے نکل گئے اور یوسف کو اپنے اسباب کے پاس چھوڑا تو اسے بھیڑیا کھا گیا اور آپ کسی طرح ہمارا یقین نہ کریں گے اگرچہ ہم سچے ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1614, 12, 18, N'اور اس کے کر ُتے پر ایک جھوٹا خون لگا لائے کہا بلکہ تمہارے دلوں نے ایک بات تمہارے واسطے بنالی ہے تو صبر اچھا، اور اللہ ہی مدد چاہتا ہوں ان باتوں پر جو تم بتارہے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1615, 12, 19, N'اور ایک قافلہ آیا انہوں نے اپنا پانی لانے والا بھیجا تو اس نے اپنا ڈول ڈال بولا آہا کیسی خوشی کی بات ہے یہ تو ایک لڑکا ہے اور اسے ایک پونجی بناکر چھپالیا اور اللہ جانتا ہے جو وہ کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1616, 12, 20, N'اور بھائیوں نے اسے کھوٹے داموں گنتی کے روپوں پر بیچ ڈالا اور انہیں اس میں کچھ رغبت نہ تھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1617, 12, 21, N'اور مصر کے جس شخص نے اسے خریدا وہ اپنی عورت سے بولا انہیں عزت سے رکھو شاید ان سے ہمیں نفع پہنچے یا ان کو ہم بیٹا بنالیں اور اسی طرح ہم نے یوسف کو اس زمین میں جماؤ (رہنے کا ٹھکانا) دیا اور اس لیے کہ اسے باتوں کا انجام سکھائیں ۰ف۵۳) اور اللہ اپنے کام پر غالب ہے مگر اکثر آدمی نہیں جانتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1618, 12, 22, N'اور جب اپنی پوری قوت کو پہنچا ہم نے اسے حکم اور علم عطا فرمایا اور ہم ایسا ہی صلہ دیتے ہیں نیکوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1619, 12, 23, N'اور وہ جس عورت کے گھر میں تھا اس نے اسے لبھایا کہ اپنا آپا نہ روکے اور دروازے سب بند کردیے اور بولی آؤ تمہیں سے کہتی ہوں کہا اللہ کی پناہ وہ عزیز تو میرا رب یعنی پرورش کرنے والا ہے اس نے مجھے اچھی طرح رکھا بیشک ظالموں کا بھلا نہیں ہوتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1620, 12, 24, N'اور بیشک عورت نے اس کا ارادہ کیا اور وہ بھی عورت کا ارادہ کرتا اگر اپنے رب کی دلیل نہ دیکھ لیتا ہم نے یوں ہی کیا کہ اس سے برائی اور بے حیائی کو پھیر دیں بیشک وہ ہمارے چنے ہوئے بندوں میں سے ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1621, 12, 25, N'اور دونوں دروازے کی طرف دوڑے اور عورت نے اس کا کر ُتا پیچھے سے چیر لیا اور دونوں کو عورت کا میاں دروازے کے پاس ملا بولی کیا سزا ہے اس کی جس نے تیری گھر والی سے بدی چاہی مگر یہ کہ قید کیا جائے یا دکھ کی مار')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1622, 12, 26, N'کہا اس نے مجھ کو لبھایا کہ میں اپنی حفاظت نہ کروں اور عورت کے گھر والوں میں سے ایک گواہ نے گواہی دی اگر ان کا کر ُتا آگے سے چرا ہے تو عورت سچی ہے اور انہوں نے غلط کہا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1623, 12, 27, N'اور اگر ان کا کر ُتا پیچھے سے چاک ہوا تو عورت جھوٹی ہے اور یہ سچے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1624, 12, 28, N'پھر جب عزیز نے اس کا کر ُتا پیچھے سے چرا دیکھا بولا بیشک یہ تم عورتوں کا چرتر (فریب) ہے بیشک تمہارا چرتر (فریب) بڑا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1625, 12, 29, N'اے یوسف! تم اس کا خیال نہ کرو اور اے عورت! تو اپنے گناہ کی معافی مانگ بیشک تو خطاواروں میں ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1626, 12, 30, N'اور شہر میں کچھ عورتیں بولیں کہ عزیز کی بی بی اپنے نوجوان کا دل لبھاتی ہ ے بیشک ان کی محبت اس کے دل میں پَیر گئی (سماگئی) ہے ہم تو اسے صر یح خود رفتہ پاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1627, 12, 31, N'تو جب زلیخا نے ان کا چرچا سنا تو ان عورتوں کو بلا بھیجا اور ان کے لیے مسندیں تیار کیں اور ان میں ہر ایک کو ایک چھری دی اور یوسف سے کہا ان پر نکل آؤ جب عورتوں نے یوسف کو دیکھا اس کی بڑائی بولنے لگیں اور اپنے ہاتھ کاٹ لیے اور بولیں اللہ کو پاکی ہے یہ تو جنس بشر سے نہیں یہ تو نہیں مگر کوئی معزز فرشتہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1628, 12, 32, N'زلیخا نے کہا تو يہ ہیں وہ جن پر مجھے طعنہ دیتی تھیں اور بیشک میں نے ان کا جِی لبھانا چاہا تو انہوں نے اپنے آپ کو بچا یا اور بیشک اگر وہ یہ کام نہ کریں گے جو میں ان سے کہتی ہوں تو ضرور قید میں پڑیں گے اور وہ ضرور ذلت اٹھائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1629, 12, 33, N'یوسف نے عرض کی اے میرے رب! مجھے قید خانہ زیادہ پسند ہے اس کام سے جس کی طرف یہ مجھے بلاتی ہیں اور اگر تو مجھ سے ان کا مکر نہ پھیرے گا تو میں ان کی طرف مائل ہوں گا اور نادان بنوں گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1630, 12, 34, N'تو اس کے رب نے اس کی سن لی اور اس سے عورتوں کا مکر پھیردیا، بیشک وہی سنتا جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1631, 12, 35, N'پھر سب کچھ نشانیاں دیکھ دکھا کر پچھلی مت انہیں یہی آئی کہ ضرور ایک مدت تک اسے قیدخانہ میں ڈالیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1632, 12, 36, N'اور اس کے ساتھ قیدخانہ میں دو جوان داخل ہوئے ان میں ایک بولا میں نے خواب میں دیکھا کہ شراب نچوڑتا ہوں اور دوسرا بولا میں نے خواب دیکھا کہ میرے سر پر کچھ روٹیاں ہیں جن میں سے پرند کھاتے ہیں، ہمیں اس کی تعبیر بتایے، بیشک ہم آپ کو نیکو کار دیکھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1633, 12, 37, N'یوسف نے کہا جو کھانا تمہیں ملا کرتا ہے وہ تمہارے پاس نہ آنے پائے گا کہ میں اس کی تعبیر اس کے آنے سے پہلے تمہیں بتادوں گا یہ ان علموں میں سے ہے جو مجھے میرے رب نے سکھایا ہے، بیشک میں نے ان لوگوں کا دین نہ مانا جو اللہ پر ایمان نہیں لاتے اور وہ آخرت سے منکر ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1634, 12, 38, N'اور میں نے اپنے باپ دادا ابراہیم ؑ اور اسحق ؑ اور یعقوب کا دین اختیار کیا ہمیں نہیں پہنچتا کہ کسی چیز کو اللہ کا شریک ٹھہرائیں، یہ اللہ کا ایک فضل ہے ہم پر اور لوگوں پر مگر اکثر لوگ شکر نہیں کرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1635, 12, 39, N'اے میرے قیدخانہ کے دونوں ساتھیو! کیا جدا جدا رب اچھے یا ایک اللہ جو سب پر غالب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1636, 12, 40, N'تم اس کے سوا نہیں پوجتے مگر نرے نام (فرضی نام) جو تم نے اور تمہارے باپ دادا نے تراش لیے ہیں اللہ نے ان کی کوئی سند نہ اتاری، حکم نہیں مگر اللہ کا اس نے فرمایا کہ اس کے سوا کسی کو نہ پوجو یہ سیدھا دین ہے لیکن اکثر لوگ نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1637, 12, 41, N'اے قید خانہ کے دونوں ساتھیو! تم میں ایک تو اپنے رب (بادشاہ) کو شراب پلائے گا رہا دوسرا وہ سو ُلی دیا جائے گا تو پرندے اس کا سر کھائیں گے حکم ہوچکا اس بات کا جس کا تم سوال کرتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1638, 12, 42, N'اور یوسف نے ان دونوں میں سے جسے بچتا سمجھا اس سے کہا اپنے رب (بادشاہ) کے پاس میرا ذکر کرنا تو شیطان نے اسے بھلا دیا کہ اپنے رب (بادشاہ) کے سامنے یوسف کا ذکر کرے تو یوسف کئی برس اور جیل خانہ میں رہا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1639, 12, 43, N'اور بادشاہ نے کہا میں نے خواب میں دیکھیں سات گائیں فربہ کہ انہیں سات دُبلی گائیں کھارہی ہیں اور سات بالیں ہری اور دوسری سات سوکھی اے درباریو! میرے خواب کا جواب دو اگر تمہیں خواب کی تعبیر آتی ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1640, 12, 44, N'بولے پریشان خوابیں ہیں اور ہم خواب کی تعبیر نہیں جانتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1641, 12, 45, N'اور بولا وہ جو ان دونوں میں سے بچا تھا اور ایک مدت بعد اسے یاد آیا میں تمہیں اس کی تعبیر بتاؤں گا مجھے بھیجو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1642, 12, 46, N'اے یوسف! اے صدیق! ہمیں تعبیر دیجئے سات فربہ گایوں کی جنہیں سات دُبلی کھاتی ہیں اور سات ہری بالیں اور دوسری سات سوکھی شاید میں لوگوں کی طرف لوٹ کر جاؤں شاید وہ آگاہ ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1643, 12, 47, N'کہا تم کھیتی کرو گے سات برس لگارتار تو جو کاٹو اسے اس کی بال میں رہنے دو مگر تھوڑا جتنا کھالو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1644, 12, 48, N'پھر اس کے بعد سات برس کرّے (سخت تنگی والے) آئیں گے کہ کھا جائیں گے جو تم نے ان کے لیے پہلے جمع کر رکھا تھا مگر تھوڑا جو بچالو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1645, 12, 49, N'پھر ان کے بعد ایک برس آئے گا جس میں لوگوں کو مینھ دیا جائے گا اور اس میں رس نچوڑیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1646, 12, 50, N'اور بادشاہ بولا کہ انہیں میرے پاس لے آؤ تو جب اس کے پاس ایلچی آیا کہا اپنے رب (بادشاہ) کے پاس پلٹ جا پھر اس سے پوچھ کیا حال ہے اور عورتوں کا جنہوں نے اپنے ہاتھ کاٹے تھے، بیشک میرا رب ان کا فریب جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1647, 12, 51, N'بادشاہ نے کہا اے عورتو! تمہارا کیا کام تھا جب تم نے یوسف کا دل لبھانا چاہا، بولیں اللہ کو پاکی ہے ہم نے ان میں کوئی بدی نہیں پائی عزیز کی عورت بولی اب اصلی بات کھل گئی، میں نے ان کا جی لبھانا چاہا تھا اور وہ بیشک سچے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1648, 12, 52, N'یوسف نے کہا یہ میں نے اس لیے کیا کہ عزیز کو معلوم ہوجائے کہ میں نے پیٹھ پیچھے اس کی خیانت نہ کی اور اللہ دغا بازوں کا مکر نہیں چلنے دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1649, 12, 53, N'اور میں اپنے نفس کو بے قصور نہیں بتاتا بیشک نفس تو برائی کا بڑا حکم دینے والا ہے مگر جس پر میرا رب رحم کرے بیشک میرا رب بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1650, 12, 54, N'اور بادشاہ بولا انہيں میرے پاس لے آؤ کہ میں انہیں اپنے لیے چن لوں پھر جب اس سے بات کی کہا بیشک آج آپ ہمارے یہاں معزز معتمد ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1651, 12, 55, N'یوسف نے کہا مجھے زمین کے خزانوں پر کردے بیشک میں حفاظت والا علم والا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1652, 12, 56, N'اور یوں ہی ہم نے یوسف کو اس ملک پر قدرت بخشی اس میں جہاں چاہے رہے ہم اپنی رحمت جسے چاہیں پہنچائیں اور ہم نیکوں کا نیگ (اَجر) ضائع نہیں کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1653, 12, 57, N'اور بیشک آخرت کا ثواب ان کے لیے بہتر جو ایمان لائے اور پرہیزگار رہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1654, 12, 58, N'اور یوسف کے بھائی آئے تو اس کے پاس حاضر ہوئے تو یوسف نے انہیں پہچان لیا اور وہ اس سے انجان رہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1655, 12, 59, N'اور جب ان کا سامان مہیا کردیا کہ اپنا سوتیلا بھائی میرے پاس لے آؤ کیا نہیں دیکھتے کہ میں پورا ناپتا ہوں اور میں سب سے بہتر مہمان نواز ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1656, 12, 60, N'پھر اگر اسے لیکر میرے پاس نہ آؤ تو تمہارے لیے میرے یہاں ماپ نہیں اور میرے پاس نہ پھٹکنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1657, 12, 61, N'بولے ہم اس کی خواہش کریں گے اس کے باپ سے اور ہمیں یہ ضرور کرنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1658, 12, 62, N'اور یوسف نے اپنے غلاموں سے کہا ان کی پونجی ان کی خورجیوں میں رکھ دو شاید وہ اسے پہچانیں جب اپنے گھر کی طرف لوٹ کر جائیں شاید وہ واپس آئیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1659, 12, 63, N'پھر جب وہ اپنے باپ کی طرف لوٹ کر گئے بولے اے ہمارے باپ ہم سے غلہ روک دیا گیا ہے تو ہمارے بھائی کو ہمارے پاس بھیج دیجئے کہ غلہ لائیں اور ہم ضرور اس کی حفاظت کریں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1660, 12, 64, N'کہا کیا اس کے بارے میں تم پر ویسا ہی اعتبار کرلوں جیسا پہلے اس کے بھائی کے بارے میں کیا تھا تو اللہ سب سے بہتر نگہبان اور وہ ہر مہربان سے بڑھ کر مہربان،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1661, 12, 65, N'اور جب انہوں نے اپنا اسباب کھولا اپنی پونجی پائی کہ ان کو پھیر دی گئی ہے، بولے اے ہمارے باپ اب اور کیا چاہیں، یہ ہے ہماری پونجی ہمیں واپس کردی گئی اور ہم اپنے گھر کے لیے غلہ لائیں اور اپنے بھائی کی حفاظت کریں اور ایک اونٹ کا بوجھ اور زیادہ پائیں، یہ دنیا بادشاہ کے سامنے کچھ نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1662, 12, 66, N'کہا میں ہرگز اسے تمہارے ساتھ نہ بھیجوں گا جب تک تم مجھے کا اللہ کا یہ عہد نہ دے دو کہ ضرور اسے لے کر آ ؤ گے مگر یہ کہ تم گھِر جاؤ پھر انہوں نے یعقوب کو عہد دے دیا کہا اللہ کا ذمہ ہے ان باتوں پر جو کہہ رہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1663, 12, 67, N'اور کہا اے میرے بیٹوں! ایک دروازے سے نہ داخل ہونا اور جدا جدا دروا زوں سے جانا میں تمہیں اللہ سے بچا نہیں سکتا حکم تو سب اللہ ہی کا ہے، میں نے اسی پر بھروسہ کیا اور بھروسہ کرنے والوں کو اسی پر بھروسہ چاہیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1664, 12, 68, N'اور جب وہ داخل ہوئے جہاں سے ان کے باپ نے حکم دیا تھا وہ کچھ انہیں کچھ انہیں اللہ سے بچا نہ سکتا ہاں یعقوب کے جی کی ایک خواہش تھی جو اس نے پوری کرلی، اور بیشک وہ صاحب علم ہے ہمارے سکھائے سے مگر اکثر لوگ نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1665, 12, 69, N'اور جب وہ یوسف کے پاس گئے اس نے اپنے بھائی کو اپنے پاس جگہ دی کہا یقین جان میں ہی تیرا بھائی ہوں تو یہ جو کچھ کرتے ہیں اس کا غم نہ کھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1666, 12, 70, N'پھر جب ان کا سامان مہیا کردیا پیالہ اپنے بھائی کے کجاوے میں رکھ دیا پھر ایک منادی نے ندا کی اے قافلہ والو! بیشک تم چور ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1667, 12, 71, N'بولے اور ان کی طرف متوجہ ہوئے تم کیا نہیں پاتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1668, 12, 72, N'بولے، بادشاہ کا پیمانہ نہیں ملتا اور جو اسے لائے گا اس کے لیے ایک اونٹ کا بوجھ ہے اور میں اس کا ضامن ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1669, 12, 73, N'بولے خدا کی قسم! تمہیں خوب معلوم ہے کہ ہم زمین میں فساد کرنے نہ آئے اور نہ ہم چور ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1670, 12, 74, N'بولے پھر کیا سزا ہے اس کی اگر تم جھوٹے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1671, 12, 75, N'بولے اس کی سزا یہ ہے کہ جس کے اسباب میں ملے وہی اس کے بدلے میں غلام بنے ہمارے یہاں ظالموں کی یہی سزا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1672, 12, 76, N'تو اول ان کی خرُجیوں سے تلاشی شروع کی اپنے بھائی کی خرُجی سے پہلے پھر اسے اپنے بھائی کی خرُجی سے نکال لیا ہم نے یوسف کو یہی تدبیر بتائی بادشاہی قانون میں اسے نہیں پہنچتا تھا کہ اپنے بھائی کو لے لے مگر یہ کہ خدا چاہے ہم جسے چاہیں درجوں بلند کریں اور ہر علم والے اوپر ایک علم والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1673, 12, 77, N'بھائی بولے اگر یہ چوری کرے تو بیشک اس سے پہلے اس کا بھائی چوری کرچکا ہے تو یوسف نے یہ بات اپنے دل میں رکھی اور ان پر ظاہر نہ کی، جی میں کہا تم بدتر جگہ ہو اور اللہ خوب جانتا ہے جو باتیں بناتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1674, 12, 78, N'بولے اے عزیز! اس کے ایک باپ ہیں بوڑھے بڑے تو ہم میں اس کی جگہ کسی کو لے لو، بیشک ہم تمہارے احسان دیکھ رہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1675, 12, 79, N'کہا خدا کی پناہ کہ ہم میں مگر اسی کو جس کے پاس ہمارا مال ملا جب تو ہم ظالم ہوں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1676, 12, 80, N'پھر جب اس سے نا امید ہوئے الگ جاکر سرگوشی کرنے لگے، ان کا بڑا بھائی بولا کیا تمہیں خبر نہیں کہ تمہارے باپ نے تم سے اللہ کا عہد لے لیا تھا اور اس سے پہلے یوسف کے حق میں تم نے کیسی تقصیر کی تو میں یہاں سے نہ ٹلوں گا یہاں تک کہ میرے باپ اجازت دیں یا اللہ مجھے حکم فرمائے اور اس کا حکم سب سے بہتر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1677, 12, 81, N'اپنے باپ کے پاس لوٹ کر جاؤ پھر عرض کرو اے ہمارے باپ بیشک آپ کے بیٹے نے چوری کی اور ہم تو اتنی ہی بات کے گواہ ہوئے تھے جتنی ہمارے علم میں تھی اور ہم غیب کے نگہبان نہ تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1678, 12, 82, N'اور اس بستی سے پوچھ دیکھئے جس میں ہم تھے اور اس قافلہ سے جس میں ہم آئے، اور ہم بیشک سچے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1679, 12, 83, N'کہا تمہارے نفس نے تمہیں کچھ حیلہ بنادیا، تو اچھا صبر ہے، قریب ہے کہ اللہ ان سب کو مجھ سے لا، ملائے بیشک وہی علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1680, 12, 84, N'اور ان سے منہ پھیرا اور کہا ہائے افسوس! یوسف کی جدائی پر اور اس کی آنکھیں غم سے سفید ہوگئیں وہ غصہ کھا تا رہا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1681, 12, 85, N'بولے خدا کی قسم! آپ ہمیشہ یوسف کی یاد کرتے رہیں گے یہاں تک کہ گور کنارے جا لگیں یا جان سے گزر جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1682, 12, 86, N'کہا میں تو اپنی پریشانی اور غم کی فریاد اللہ ہی سے کرتا ہوں اور مجھے اللہ کی وہ شانیں معلوم ہیں جو تم نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1683, 12, 87, N'اے بیٹو! جا ؤ یوسف اور اس کے بھائی کا سراغ لگاؤ اور اللہ کی رحمت سے مایوس نہ ہو، بیشک اللہ کی رحمت سے نا امید نہیں ہوتے مگر کافر لوگ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1684, 12, 88, N'پھر جب وہ یوسف کے پاس پہنچے بولے اے عزیز ہمیں اور ہمارے گھر والوں کو مصیبت پہنچی اور ہم بے قدر پونجی لے کر آئے ہیں تو آپ ہمیں پورا ناپ دیجئے اور ہم پر خیرات کیجئے بیشک اللہ خیرات والوں کو صلہ دیتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1685, 12, 89, N'بولے کچھ خبر ہے تم نے یوسف اور اس کے بھائی کے ساتھ کیا کِیا تھا جب تم نادان تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1686, 12, 90, N'بولے کیا سچ مچ آپ ہی یوسف ہیں، کہا میں یوسف ہوں اور یہ میرا بھائی، بیشک اللہ نے ہم پر احسان کیا بیشک جو پرہیزگاری اور صبر کرے تو اللہ نیکوں کا نیگ (اجر) ضائع نہیں کرتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1687, 12, 91, N'بولے خدا کی قسم! بیشک اللہ نے آپ کو ہم پر فضیلت دی اور بیشک ہم خطاوار تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1688, 12, 92, N'کہا آج تم پر کچھ ملامت نہیں، اللہ تمہیں معاف کرے، اور وہ سب مہربانوں سے بڑھ کر مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1689, 12, 93, N'میرا یہ کرتا لے جاؤ اسے میرے باپ کے منہ پر ڈالو ان کی آنکھیں کھل جائیں گی اور اپنے سب گھر بھر کو میرے پاس لے آ ؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1690, 12, 94, N'جب قافلہ مصر سے جدا ہوا یہاں ان کے باپ نے کہا بیشک میں یوسف کی خوشبو پا تا ہوں اگر مجھے یہ نہ کہو کہ سٹھ (بہک) گیا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1691, 12, 95, N'بیٹے بولے خدا کی قسم! آپ اپنی اسی پرانی خود رفتگی میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1692, 12, 96, N'پھر جب خوشی سنانے والا آیا اس نے وہ کرتا یعقوب کے منہ پر ڈالا اسی وقت اس کی آنکھیں پھر آئیں (دیکھنے لگیں) کہ میں نہ کہتا تھا کہ مجھے اللہ کی وہ شانیں معلوم ہیں جو تم نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1693, 12, 97, N'بولے اے ہمارے باپ! ہمارے گناہوں کی معافی مانگئے بیشک ہم خطاوار ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1694, 12, 98, N'کہا جلد میں تمہاری بخشش اپنے رب سے چاہو ں گا، بیشک وہی بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1695, 12, 99, N'پھر جب وہ سب یوسف کے پاس پہنچے اس نے اپنے ماں باپ کو اپنے پاس جگہ دی اور کہا مصر میں داخل ہو اللہ چاہے تو امان کے ساتھ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1696, 12, 100, N'اور اپنے ماں باپ کو تخت پر بٹھایا اور سب اس کے لیے سجدے میں گرے اور یوسف نے کہا اے میرے باپ یہ میرے پہلے خواب کی تعبیر ہے بیشک اسے میرے رب نے سچا کیا، اور بیشک اس نے مجھ پر احسان کیا کہ مجھے قید سے نکالا اور آپ سب کو گاؤں سے لے آیا بعد اس کے کہ شیطان نے مجھ میں اور میرے بھائیوں میں ناچاقی کرادی تھی، بیشک میرا رب جس بات کو چاہے آسان کردے بیشک وہی علم و حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1697, 12, 101, N'اے میرے رب بیشک تو نے مجھے ایک سلطنت دی اور مجھے کچھ باتوں کا انجام نکالنا سکھایا، اے آسمانوں اور زمین کے بنانے والے تو میرا کام بنانے والا ہے دنیا اور آخرت میں، مجھے مسلمان اٹھا اور ان سے مِلا جو تیرے قرب خاص کے لائق ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1698, 12, 102, N'یہ کچھ غیب کی خبریں ہیں جو ہم تمہاری طرف وحی کرتے ہیں اور تم ان کے پاس نہ تھے جب انہوں نے اپنا کام پکا کیا تھا اور وہ داؤں چل رہے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1699, 12, 103, N'اور اکثر آدمی تم کتنا ہی چاہو ایمان نہ لائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1700, 12, 104, N'اور تم اس پر ان سے کچھ اجرت نہ مانگتے یہ تو نہیں مگر سارے جہان کو نصیحت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1701, 12, 105, N'اور کتنی نشانیاں ہیں آسمانوں اور زمین میں کہ اکثر لوگ ان پر گزرتے ہیں اور ان سے بے خبر رہتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1702, 12, 106, N'اور ان میں اکثر وہ ہیں کہ اللہ پر یقین نہیں لاتے مگر شرک کرتے ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1703, 12, 107, N'کیا اس سے نڈر ہو بیٹھے کہ اللہ کا عذاب انہیں آکر گھیر لے یا قیامت ان پر اچانک آجائے اور انہیں خبر نہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1704, 12, 108, N'تم فرماؤ یہ میری راہ ہے میں اللہ کی طرف بلاتا ہوں میں اور جو میرے قدموں پرچلیں دل کی آنکھیں رکھتے ہیں ۰ف۲۳۳) اور اللہ کو پاکی ہے اور میں شریک کرنے والا نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1705, 12, 109, N'اور ہم نے تم سے پہلے جتنے رسول بھیجے سب مرد ہی تھے جنہیں ہم وحی کرتے اور سب شہر کے ساکن تھے تو یہ لوگ زمین پرچلے نہیں تو دیکھتے ان سے پہلوں کا کیا انجام ہوا اور بیشک آخرت کا گھر پرہیزگاروں کے لیے بہتر تو کیا تمہیں عقل نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1706, 12, 110, N'یہاں تک جب رسولوں کو ظاہری اسباب کی امید نہ رہی اور لوگ سمجھے کہ رسولوں نے غلط کہا تھا اس وقت ہماری مدد آئی تو جسے ہم نے چاہا بچالیا گیا اور ہمارا عذاب مجرموں سے پھیرا نہیں جاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1707, 12, 111, N'بیشک ان کی خبروں سے عقل مندوں کی آنکھیں کھلتی ہیں یہ کوئی بناوٹ کی بات نہیں لیکن اپنوں سے اگلے کاموں کی تصدیق ہے اور ہر چیز کا مفصل بیان اور مسلمانوں کے لیے ہدایت اور رحمت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1708, 13, 1, N'یہ کتاب کی آیتیں ہیں اور وہ جو تمہاری طرف تمہارے رب کے پاس سے اترا حق ہے مگر اکثر آدمی ایمان نہیں لاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1709, 13, 2, N'اللہ ہے جس نے آسمانوں کو بلند کیا بے ستونوں کے کہ تم دیکھو پھر عرش پر استوا فرمایا جیسا اس کی شان کے لائق ہے اور سورج اور چاند کو مسخر کیا ہر ایک، ایک ٹھہرائے ہوئے وعدہ تک چلتا ہے اللہ کام کی تدبیر فرماتا اور مفصل نشانیاں بتاتا ہے کہیں تم اپنے رب رب کا ملنا یقین کرو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1710, 13, 3, N'اور وہی ہے جس نے زمین کو پھیلا اور اس میں لنگر اور نہریں بنائیں، اور زمین ہر قسم کے پھل دو دو طرح کے بنائے رات سے دن کو چھپا لیتا ہے، بیشک اس میں نشانیاں ہیں دھیان کرنے والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1711, 13, 4, N'اور زمین کے مختلف قطعے ہیں اور ہیں پاس پاس اور باغ ہیں انگوروں کے اور کھیتی اور کھجور کے پیڑ ایک تھالے (تھال) سے اُگے اور الگ الگ سب کو ایک ہی پانی دیا جا تا ہے اور پھلوں میں ہم ایک کو دوسرے سے بہتر کرتے ہیں، بیشک اس میں نشانیاں ہیں عقل مندوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1712, 13, 5, N'اور اگر تم تعجب کرو تو اچنبھا تو ان کے اس کہنے کا ہے کہ کیا ہم مٹی ہو کر پھر نئے بنیں گے وہ ہیں جو اپنے رب سے منکر ہوئے اور وہ ہیں جن کی گردنوں میں طوق ہوں گے اور وہ دوزخ والے ہیں انھیں اسی میں رہنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1713, 13, 6, N'اور تم سے عذاب کی جلدی کرتے ہیں رحمت سے پہلے اور ان اگلوں کی سزائیں ہوچکیں اور بیشک تمہارا رب تو لوگوں کے ظلم پر بھی انہیں ایک طرح کی معافی دیتا ہے اور بیشک تمہارے رب کا عذاب سخت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1714, 13, 7, N'اور کا فر کہتے ہیں ان پر ان کی طرف سے کوئی نشانی کیو ں نہیں اتری تم تو ڈر سنانے والے ہو اور ہر قوم کے ہادی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1715, 13, 8, N'اللہ جانتا ہے جو کچھ کسی مادہ کے پیٹ میں ہے اور پیٹ جو کچھ گھٹتے بڑھتے ہیں اور ہر چیز اس کے پاس ایک اندازے سے ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1716, 13, 9, N'ہر چھپے اور کھلے کا جاننے والا سب سے بڑا بلندی والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1717, 13, 10, N'برابر ہیں جو تم میں بات آہستہ کہے اور جو آواز سے اور جو رات میں چھپا ہے اور جو دن میں راہ چلتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1718, 13, 11, N'آدمی کے لیے بدلی والے فرشتے ہیں اس کے آگے پیچھے کہ بحکم خدا اس کی حفاظت کرتے ہیں بیشک اللہ کسی قوم سے اپنی نعمت نہیں بدلتا جب تک وہ خود اپنی حالت نہ بدلیں، اور جب کسی قوم سے برائی چاہے تو وہ پھر نہیں سکتی، اور اس کے سوا ان کا کوئی حمایتی نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1719, 13, 12, N'وہی ہے تمہیں بجلی دکھاتا ہے ڈر کو اور امید کو اور بھاری بدلیاں اٹھاتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1720, 13, 13, N'اور گر ج اسے سراہتی ہوئی اس کی پاکی بولتی ہے اور فرشتے اس کے ڈر سے اور کڑک بھیجتا ہے تو اسے ڈالتا ہے جس پر چاہے اور وہ اللہ میں جھگڑتے ہوتے ہیں اور اس کی پکڑ سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1721, 13, 14, N'اسی کا پکارنا سچا ہے اور اُس کے سوا جن کو پکارتے ہیں وہ ان کی کچھ بھی نہیں سنتے مگر اس کی طرح جو پانی کے سامنے اپنی ہتھیلیاں پھیلائے بیٹھا ہے کہ اس کے منہ میں پہنچ جائے اور وہ ہرگز نہ پہنچے گا، اور کافروں کی ہر دعا بھٹکتی پھرتی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1722, 13, 15, N'اور اللہ ہی کو سجدہ کرتے ہیں جتنے آسمانوں اور زمین میں ہیں خوشی سے خواہ مجبوری سے اور ان کی پرچھائیاں ہر صبح و شام السجدة ۔۲')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1723, 13, 16, N'تم فرماؤ کون رب ہے آسمانوں اور زمین کا، تم خود ہی فرما ؤ اللہ تم فرما ؤ تو کیا اس کے سوا تم نے وہ حمایتی بنائے ہیں جو اپنا بھلا برا نہیں کرسکتے ہیں تم فرما ؤ کیا برابر ہوجائیں گے اندھا اور انکھیارا (بینا) یا کیا برابر ہوجائیں گی اندھیریاں اور اجالا کیا اللہ کے لیے ایسے شریک ٹھہراتے ہیں جنہوں نے اللہ کی طرح کچھ بنایا تو انہیں ان کا اور اس کا بنانا ایک سا معلوم ہوا تم فرما ؤ اللہ ہر چیز کا بنانے والا ہے اور وہ اکیلا سب پر غالب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1724, 13, 17, N'اس نے آسمان سے پانی اتارا تو نالے اپنے اپنے لائق بہہ نکلے تو پانی کی رو اس پر ابھرے ہوئے جھاگ اٹھا لائی، اور جس پر آگ دہکاتے ہیں گہنا یا اور اسباب بنانے کو اس سے بھی ویسے ہی جھاگ اٹھتے ہیں اللہ بتاتا ہے کہ حق و باطل کی یہی مثال ہے، تو جھاگ تو پھک (جل) کر دور ہوجاتا ہے، اور وہ جو لوگوں کے کام آئے زمین میں رہتا ہے اللہ یوں ہی مثالیں بیان فرماتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1725, 13, 18, N'جن لوگوں نے اپنے رب کا حکم مانا انہیں کے لیے بھلائی ہے اور جنہوں نے اس کا حکم نہ مانا اگر زمین میں جو کچھ ہے وہ سب اور اس جیسا اور ان کی ملِک میں ہوتا تو اپنی جان چھڑانے کو دے دیتے یہی ہیں جن کا برُ ا حساب ہوگا اور ان کا ٹھکانا جہنم ہے، اور کیا ہی بُرا بچھونا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1726, 13, 19, N'تو کیا وہ جانتا ہے جو کچھ تمہاری طرف تمہارے رب کے پاس سے اترا حق ہے وہ اس جیسا ہوگا جو اندھا ہے نصیحت وہی مانتے ہیں جنہیں عقل ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1727, 13, 20, N'وہ جو اللہ کا عہد پورا کرتے ہیں اور قول باندھ کر پھرتے نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1728, 13, 21, N'اور وہ کہ جوڑتے ہیں اسے جس کے جوڑنے کا اللہ نے حکم دیا اور اپنے رب سے ڈرتے ہیں اور حساب کی بُرائی سے اندیشہ رکھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1729, 13, 22, N'اور وہ جنہوں نے صبر کیا اپنے رب کی رضا چاہنے کو اور نماز قائم رکھی اور ہمارے دیئے سے ہماری راہ میں چھپے اور ظاہر کچھ خرچ کیا اور برائی کے بدلے بھلائی کرکے ٹالتے ہیں انہیں کے لیے پچھلے گھر کا نفع ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1730, 13, 23, N'بسنے کے باغ جن میں وہ داخل ہوں گے اور جو لائق ہوں ان کے باپ دادا اور بیبیوں اور اولاد میں اور فرشتے ہر دروازے سے ان پر یہ کہتے آئیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1731, 13, 24, N'سلامتی ہو تم پر تمہارے صبر کا بدلہ تو پچھلا گھر کیا ہی خوب ملا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1732, 13, 25, N'اور وہ جو اللہ کا عہد اس کے پکے ہونے کے بعد توڑتے اور جس کے جوڑنے کو اللہ نے فرمایا اسے قطع کرتے اور زمین میں فساد پھیلاتے ہیں ان کا حصہ لعنت ہی ہے اور اُن کا نصیبہ بُرا گھر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1733, 13, 26, N'اللہ جس کے لیے چاہے رزق کشادہ اور تنگ کرتا ہے، اور کا فر دنیا کی زندگی پر اترا گئے (نازاں ہوئے) اور دنیا کی زندگی آخرت کے مقابل نہیں مگر کچھ دن برت لینا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1734, 13, 27, N'اور کافر کہتے ان پر کوئی نشانی ان کے رب کی طرف سے کیوں نہ اتری، تم فرماؤ بیشک اللہ جسے چاہے گمراہ کرتا ہے اور اپنی راہ اسے دیتا ہے جو اس کی طرف رجوع لائے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1735, 13, 28, N'وہ جو ایمان لائے اور ان کے دل اللہ کی یاد سے چین پاتے ہیں، سن لو اللہ کی یاد ہی میں دلوں کا چین ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1736, 13, 29, N'وہ جو ایمان لائے اور اچھے کام کیے ان کو خوشی ہے اور اچھا انجام')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1737, 13, 30, N'اسی طرح ہم نے تم کو اس امت میں بھیجا جس سے پہلے امتیں ہو گزریں کہ تم انہیں پڑھ کر سناؤ جو ہم نے تمہاری طرف وحی کی اور وہ رحمن کے منکر ہورہے ہیں تم فرماؤ وہ میرا رب ہے اس کے سوا کسی کی بندگی نہیں میں نے اسی پر بھروسہ کیا اور اسی کی طرف میری رجوع ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1738, 13, 31, N'اور اگر کوئی ایسا قرآن آتا جس سے پہاڑ ٹل جاتے یا زمین پھٹ جاتی یا مردے باتیں کرتے جب بھی یہ کافر نہ مانتے بلکہ سب کام اللہ ہی کے اختیار ميں ہیں تو کیا مسلمان اس سے نا امید نہ ہوئے کہ اللہ چاہتا تو سب آدمیوں کو ہدایت کردیتا اور کافروں کو ہمیشہ کے لیے یہ سخت دھمک (ہلادینے والی مصیبت) پہنچتی رہے گی یا ان کے گھروں کے نزدیک اترے گی یہاں تک کہ اللہ کا وعدہ آئے بیشک اللہ وعدہ خلاف نہیں کرتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1739, 13, 32, N'اور بیشک تم سے اگلے رسولوں سے بھی ہنسی کی گئی تو میں نے کافروں کو کچھ دنوں ڈھیل دی پھر انہیں پکڑا تو میرا عذاب کیسا تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1740, 13, 33, N'تو کیا وہ ہر جان پر اس کے اعمال کی نگہداشت رکھتا ہے اور وہ اللہ کے شریک ٹھہراتے ہیں، تم فرماؤ ان کا نام تو لو یا اسے وہ بتاتے ہو جو اس کے علم میں ساری زمین میں نہیں یا یوں ہی اوپری بات بلکہ کافروں کی نگاہ میں ان کا فریب اچھا ٹھہرا ہے اور راہ سے روکے گئے اور جسے اللہ گمراہ کرے اسے کوئی ہدایت کرنے والا نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1741, 13, 34, N'انہیں دنیا کے جیتے عذاب ہوگا اور بیشک آخرت کا عذاب سب سے سخت اور انہیں اللہ سے بچانے والا کوئی نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1742, 13, 35, N'احوال اس جنت کا کہ ڈر والوں کے لیے جس کا وعدہ ہے، اس کے نیچے نہریں بہتی ہیں، اس کے میوے ہمیشہ اور اس کا سایہ ڈر والوں کا تو یہ انجام ہے اور کافروں کا انجام آ گ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1743, 13, 36, N'اور جن کو ہم نے کتاب دی وہ اس پر خوش ہوتے جو تمہاری طرف اترا اور ان گروہوں میں کچھ وہ ہیں کہ اس کے بعض سے منکر ہیں، تم فرماؤ مجھے تو یہی حکم ہے کہ اللہ کی بندگی کروں اور اس کا شریک نہ ٹھہراؤں، ميں اسی کی طرف بلاتا ہوں اور اسی کی طرف مجھے پھرنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1744, 13, 37, N'اور اسی طرح ہم نے اسے عربی فیصلہ اتارا اور اے سننے والے! اگر تو ان کی خواہشوں پر چلے گا بعد اس کے کہ تجھے علم آچکا تو اللہ کے آگے نہ تیرا کوئی حمایتی ہوگا نہ بچانے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1745, 13, 38, N'اور بیشک ہم نے تم سے پہلے رسول بھیجے اور ان کے لیے بیبیاں اور بچے کیے اور کسی رسول کا کام نہیں کہ کوئی نشانی لے آئے مگر اللہ کے حکم سے، ہر وعدہ کی ایک لکھت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1746, 13, 39, N'اللہ جو چاہے مٹاتا اور ثابت کرتا ہے اور اصل لکھا ہوا اسی کے پاس')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1747, 13, 40, N'اور اگر ہمیں تمہیں دکھا د یں کوئی وعدہ جو انہیں دیا جاتا ہے یا پہلے ہی اپنے پاس بلائیں تو بہرحال تم پر تو ضرور پہنچانا ہے اور حساب لینا ہمارا ذمہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1748, 13, 41, N'کیا انہیں نہیں سوجھتا کہ ہر طرف سے ان کی آبادی گھٹاتے آرہے ہیں اور اللہ حکم فرماتا ہے اس کا حکم پیچھے ڈالنے والا کوئی نہیں اور اسے حساب لیتے دیر نہیں لگتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1749, 13, 42, N'اور ان سے اگلے فریب کرچکے ہیں تو ساری خفیہ تدبیر کا مالک تو اللہ ہی ہے جانتا ہے جو کچھ کوئی جان کمائے اور اب جاننا چاہتے ہیں کافر، کسے ملتا ہے پچھلا گھر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1750, 13, 43, N'اور کافر کہتے ہی تم رسول نہیں، تم فرماؤ اللہ گواہ کافی ہے مجھ میں اور تم میں اور وہ جسے کتاب کا علم ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1751, 14, 1, N'ایک کتاب ہے کہ ہم نے تمہاری طرف اتاری کہ تم لوگوں کو اندھیریوں سے اجالے میں لا ؤ ان کے رب کے حکم سے اس کی راہ کی طرف جو عزت والا سب خوبیوں والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1752, 14, 2, N'اللہ کہ اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں اور کافروں کی خرابی ہے ایک سخت عذاب سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1753, 14, 3, N'جنہیں آخرت سے دنیا کی زندگی پیاری ہے اور اللہ کی راہ سے روکتے اور اس میں کجی چاہتے ہیں، وہ دور کی گمراہی میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1754, 14, 4, N'اور ہم نے ہر رسول اس کی قوم ہی کی زبان میں بھیجا کہ وہ انہیں صاف بتائے پھراللہ گمراہ کرتا ہے جسے چاہے اور وہ راہ دکھاتا ہے جسے چاہے، اور وہی عزت و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1755, 14, 5, N'اور بیشک ہم نے موسیٰ کو اپنی نشانیاں دے کر بھیجا کہ اپنی قوم کو اندھیریوں سے اجالے میں لا، اور انہیں اللہ کے دن یا د دِلا بیشک اس میں نشانیاں ہیں ہر بڑے صبرے والے شکر گزار کرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1756, 14, 6, N'اور جب موسیٰ نے اپنی قوم سے کہا یاد کرو اپنے اوپر اللہ کا احسان جب اس نے تمہیں فرعون والوں سے نجات دی جو تم کو بری مار دیتے تھے اور تمہارے بیٹوں کو ذبح کرتے اور تمہاری بیٹیاں زندہ رکھتے، اور اس میں تمہارے رب کا بڑا فضل ہوا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1757, 14, 7, N'اور یاد کرو جب تمہارے رب نے سنادیا کہ اگر احسان مانو گے تو میں تمہیں اور دونگا اور اگر ناشکری کرو تو میرا عذاب سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1758, 14, 8, N'اور موسیٰ نے کہا اگر تم اور زمین میں جتنے ہیں سب کا فر ہوجاؤ تو بیشک اللہ بے پروہ سب خوبیوں والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1759, 14, 9, N'کیا تمہیں ان کی خبریں نہ آئیں جو تم سے پہلے تھی نوح کی قوم اور عاد اور ثمود اور جو ان کے بعد ہوئے، انہیں اللہ ہی جانے ان کے پاس ان کے رسول روشن دلیلیں لے کر آئے تو وہ اپنے ہاتھ اپنے منہ کی طرف لے گئے اور بولے ہم منکر ہیں اس کے جو تمہارے ہاتھ بھیجا گیا اور جس راہ کی طرف ہمیں بلاتے ہو اس میں ہمیں وہ شک ہے کہ بات کھلنے نہیں دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1760, 14, 10, N'ان کے رسولوں نے کہا کیا اللہ میں شک ہے آسمان اور زمین کا بنانے والا، تمہیں بلاتا ہے کہ تمہارے کچھ گناہ بخشے اور موت کے مقرر وقت تک تمہاری زندگی بے عذاب کاٹ دے، بولے تم تو ہمیں جیسے آدمی ہو تم چاہتے ہو کہ ہمیں اس سے باز رکھو جو ہمارے باپ دادا پوجتے تھے اب کوئی روشن سند ہمارے پاس لے آؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1761, 14, 11, N'ان کے رسولوں نے ان سے کہا ہم ہیں تو تمہاری طرح انسان مگر اللہ اپنے بندوں میں جس پر چاہے احسان فرماتا ہے اور ہمارا کام نہیں کہ ہم تمہارے پاس کچھ سند لے آئیں مگر اللہ کے حکم سے، اور مسلمانوں کو اللہ ہی پر بھروسہ چاہیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1762, 14, 12, N'اور ہمیں کیا ہوا کہ اللہ پر بھروسہ نہ کریں اس نے تو ہماری راہیں ہمیں دکھادیں اور تم جو ہمیں ستا رہے ہو ہم ضرور اس پر صبر کریں گے، اور بھروسہ کرنے والوں کو اللہ ہی پر بھروسہ چاہیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1763, 14, 13, N'اور کافروں نے اپنے رسولوں سے کہا ہم ضرور تمہیں اپنی زمین سے نکال دیں گے یا تم ہمارے دین پر کچھ ہوجاؤ، تو انہیں ان کے رب نے وحی بھیجی کہ ہم ضرور ظالموں کو ہلاک کریں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1764, 14, 14, N'اور ضرور ہم تم کو ان کے بعد زمین میں بسائیں گے یہ اس لیے ہے جو میرے حضو ر کھڑے ہونے سے ڈرے اور میں نے جو عذاب کا حکم سنایا ہے، اس سے خوف کرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1765, 14, 15, N'اور انہوں نے فیصلہ مانگا اور ہر سرکش ہٹ دھرم نا مُراد ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1766, 14, 16, N'جہنم اس کے پیچھے لگی اور اسے پیپ کا پانی پلایا جائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1767, 14, 17, N'بہ مشکل اس کا تھوڑا تھوڑا گھونٹ لے گا اور گلے سے نیچے اتارنے کی امید نہ ہوگی اور اسے ہر طرف سے موت آئے گی اور مرے گا نہیں، اور اس کے پیچھے ایک گاڑھا عذاب')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1768, 14, 18, N'اپنے رب سے منکروں کا حال ایسا ہے کہ ان کے کام ہیں جیسے راکھ کہ اس پر ہوا کا سخت جھونکا آیا آندھی کے دن میں ساری کمائی میں سے کچھ ہاتھ نہ لگا، یہی ہے دور کی گمراہی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1769, 14, 19, N'کیا تو نے نہ دیکھا کہ اللہ نے آسمان اور زمین حق کے ساتھ بنائے اگر چاہے تو تمہیں لے جائے اور ایک نئی مخلوق لے آئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1770, 14, 20, N'اور یہ اللہ پر کچھ دشوار نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1771, 14, 21, N'اور سب اللہ کے حضور اعلانیہ حاضر ہوں گے تو جو کمزور تھے بڑائی والوں سے کہیں گے ہم تمہارے تابع تھے کیا تم سے ہوسکتا ہے کہ اللہ کے عذاب میں سے کچھ ہم پر سے ٹال دو کہیں گے اللہ ہمیں ہدایت کرتا تو ہم تمہیں کرتے ہم پر ایک سا ہے چاہے بے قراری کریں یا صبر سے رہیں ہمیں کہیں پناہ نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1772, 14, 22, N'اور شیطان کہے گا جب فیصلہ ہوچکے گا بیشک اللہ نے تم کو سچا وعدہ دیا تھا اور میں نے جو تم کو وعدہ دیا تھا وہ میں نے تم سے جھوٹا کیا اور میرا تم پر کچھ قابو نہ تھا مگر یہی کہ میں نے تم کو بلایا تم نے میری مان لی تو اب مجھ پر الزام نہ رکھو خود اپنے اوپر الزام رکھو نہ میں تمہاری فریاد کو پہنچ سکوں نہ تم میری فریاد کو پہنچ سکو، وہ جو پہلے تم نے مجھے شریک ٹھہرایا تھا میں اس سے سخت بیزار ہوں، بیشک ظالموں کے لیے دردناک عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1773, 14, 23, N'اور وہ جو ایمان لائے اور اچھے کام کیے وہ باغوں میں داخل کیے جائیں گے جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں اپنے رب کے حکم سے، اس میں ان کے ملتے وقت کا اکرام سلام ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1774, 14, 24, N'کیا تم نے نہ دیکھا اللہ نے کیسی مثال بیان فرمائی پاکیزہ بات کی جیسے پاکیزہ درخت جس کی جڑ قائم اور شاخیں آسمان میں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1775, 14, 25, N'ہر وقت پھل دیتا ہے اپنے رب کے حکم سے اور اللہ لوگوں کے لیے مثالیں بیان فرماتا ہے کہ کہیں وہ سمجھیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1776, 14, 26, N'اور گندی بات کی مثال جیسے ایک گندہ پیڑ کہ زمین کے اوپر سے کاٹ دیا گیا اب اسے کوئی قیام نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1777, 14, 27, N'اللہ ثابت رکھتا ہے ایمان والوں کو حق بات پر دنیا کی زندگی میں اور آخرت میں اور اللہ ظالموں کو گمراہ کرتا ہے اور اللہ جو چاہے کرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1778, 14, 28, N'کیا تم نے انہیں نہ دیکھا جنہوں نے اللہ کی نعمت ناشکری سے بدل دی اور اپنی قوم کو تباہی کے گھر لا اتار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1779, 14, 29, N'وہ جو دوزخ ہے اس کے اندر جائیں گے، اور کیا ہی بری ٹھہرنے کی جگہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1780, 14, 30, N'اور اللہ کے لیے برابر والے ٹھہراے کہ اس کی راہ سے بہکاویں تم فرماؤ کچھ برت لو کہ تمہارا انجام آگ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1781, 14, 31, N'میرے ان بندوں سے فرماؤ جو ایمان لائے کہ نماز قائم رکھیں اور ہمارے دیے میں سے کچھ ہماری راہ میں چھپے اور ظاہر خرچ کریں اس دن کے آنے سے پہلے جس میں نہ سوداگری ہوگی نہ یارانہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1782, 14, 32, N'اللہ ہے جس نے آسمان اور زمین بنائے اور آسمان سے پانی اتارا تو اس سے کچھ پھل تمہارے کھانے کو پیدا کیے اور تمہارے لیے کشتی کو مسخر کیا کہ اس کے حکم سے دریا میں چلے اور تمہارے لیے ندیاں مسخر کیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1783, 14, 33, N'اور تمہارے لیے سورج اور چاند مسخر کیے جو برابر چل رہے ہیں اور تمہارے لیے رات اور دن مسخر کیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1784, 14, 34, N'اور تمہیں بہت کچھ منہ مانگا دیا، اور اگر اللہ کی نعمتیں گنو تو شمار نہ کرسکو گے، بیشک آدمی بڑا ظالم ناشکرا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1785, 14, 35, N'اور یاد کرو جب ابراہیم نے عرض کی اے میرے رب اس شہر کو امان والا کردے اور مجھے اور میرے بیٹوں کو بتوں کے پوجنے سے بچا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1786, 14, 36, N'اے میرے رب بیشک بتوں نے بہت لوگ بہکائے دیے تو جس نے میرا ساتھ دیا وہ تو میرا ہے اور جس نے میرا کہا نہ مانا تو بیشک تو بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1787, 14, 37, N'اے میرے رب میں نے اپنی کچھ اولاد ایک نالے میں بسائی جس میں کھیتی نہیں ہوتی تیرے حرمت والے گھر کے پاس اے میرے رب اس لیے کہ وہ نماز قائم رکھیں تو تو لوگوں کے کچھ دل ان کی طرف مائل کردے اور انہیں کچھ پھل کھانے کو دے شاید وہ احسان مانیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1788, 14, 38, N'اے ہمارے رب تو جانتا ہے جو ہم چھپاتے ہیں اور ظاہر کرتے اور اللہ پر کچھ چھپا نہیں زمین میں اور نہ آسمان میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1789, 14, 39, N'سب خوبیاں اللہ کو جس نے مجھے بڑھاپے میں اسماعیل و اسحاق دیئے بیشک میرا رب دعا سننے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1790, 14, 40, N'اے میرے رب! مجھے نماز قائم کرنے والا رکھ اور کچھ میری اولاد کو اے ہمارے رب اور ہماری دعا سن لے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1791, 14, 41, N'اے ہمارے رب مجھے بخش دے اور میرے ماں باپ کو اور سب مسلمانوں کو جس دن حساب قائم ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1792, 14, 42, N'اور ہرگز اللہ کو بےخبر نہ جاننا ظالموں کے کام سے انہیں ڈھیل نہیں دے رہا ہے مگر ایسے دن کے لیے جس میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1793, 14, 43, N'آنکھیں کھلی کی کھلی رہ جائیں گی بے تحاشا دوڑے نکلیں گے اپنے سر اٹھائے ہوئے کہ ان کی پلک ان کی طرف لوٹتی نہیں اور ان کے دلوں میں کچھ سکت نہ ہوگی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1794, 14, 44, N'اور لوگوں کو اس دن سے ڈراؤ جب ان پر عذاب آئے گا تو ظالم کہیں گے اے ہمارے رب! تھوڑی دیر ہمیں مہلت دے کہ ہم تیرا بلانا مانیں اور رسولوں کی غلامی کریں تو کیا تم پہلے قسم نہ کھاچکے تھے کہ ہمیں دنیا سے کہیں ہٹ کر جانا نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1795, 14, 45, N'اور تم ان کے گھروں میں بسے جنہوں نے اپنا برا کیا تھا اور تم پر خوب کھل گیا ہم نے ان کے ساتھ کیسا کیا اور ہم نے تمہیں مثالیں دے کر بتادیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1796, 14, 46, N'اور بیشک وہ اپنا سا داؤں (فریب) چلے اور ان کا داؤں اللہ کے قابو میں ہے، اور ان کا داؤں کچھ ایسانہ تھا جس سے یہ پہاڑ ٹل جائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1797, 14, 47, N'تو ہر گز خیال نہ کرنا کہ اللہ اپنے رسولوں سے وعدہ خلاف کرے گا بیشک اللہ غالب ہے بدلہ لینے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1798, 14, 48, N'جس دن بدل دی جائے گی زمین اس زمین کے سوا اور آسمان اور لوگ سب نکل کھڑے ہوں گے ایک اللہکے سامنے جو سب پر غالب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1799, 14, 49, N'اور اس دن تم مجرموں کو دیکھو گے کہ بیڑیوں میں ایک دوسرے سے جڑے ہوں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1800, 14, 50, N'ان کے کرُتے رال ہوں گے اور ان کے چہرے آ گ ڈھانپ لے گی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1801, 14, 51, N'اس لیے کہ اللہ ہر جان کو اس کی کمائی کا بدلہ دے، بیشک اللہ کو حساب کرتے کچھ دیر نہیں لگتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1802, 14, 52, N'یہ لوگوں کو حکم پہنچانا ہے اور اس لیے کہ وہ اس سے ڈرائے جائیں اور اس لیے کہ وہ جان لیں کہ وہ ایک ہی معبود ہے اور اس لیے کہ عقل والے نصیحت مانیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1803, 15, 1, N'یہ آیتیں ہیں کتاب اور روشن قرآن کی-')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1804, 15, 2, N'بہت آرزوئیں کریں گے کافر کاش مسلمان ہوتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1805, 15, 3, N'انہیں چھوڑو کہ کھائیں اور برتیں اور امید انہیں کھیل میں ڈالے تو اب جانا چاہتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1806, 15, 4, N'اور جو بستی ہم نے ہلاک کی اس کا ایک جانا ہوا نوشتہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1807, 15, 5, N'کو ئی گروہ اپنے وعدہ سے آگے نہ بڑھے نہ پیچھے ہٹے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1808, 15, 6, N'اور بولے کہ اے وہ جن پر قرآن اترا بیشک مجنون ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1809, 15, 7, N'ہمارے پاس فرشتے کیوں نہیں لاتے اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1810, 15, 8, N'ہم فرشتے بیکار نہیں اتارتے اور وہ اتریں تو انہیں مہلت نہ ملے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1811, 15, 9, N'بیشک ہم نے اتارا ہے یہ قرآن اور بیشک ہم خود اس کے نگہبان ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1812, 15, 10, N'اور بیشک ہم نے تم سے پہلے اگلی امتوں میں رسول بھیجے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1813, 15, 11, N'اور ان کے پاس کوئی رسول نہیں آتا مگر اس سے ہنسی کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1814, 15, 12, N'ایسے ہی ہم اس ہنسی کو ان مجرموں کے دلوں میں راہ دیتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1815, 15, 13, N'وہ اس پر ایمان نہیں لاتے اور اگلوں کی راہ پڑچکی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1816, 15, 14, N'اور اگر ہم ان کے لیے آسمان میں کوئی دروازہ کھول دیں کہ دن کو اس میں چڑھتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1817, 15, 15, N'جب بھی یہی کہتے کہ ہماری نگاہ باندھ دی گئی ہے بلکہ ہم پر جادو ہوا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1818, 15, 16, N'اور بیشک ہم نے آسمان میں برج بنائے اور اسے دیکھنے والو ں کے لیے آراستہ کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1819, 15, 17, N'اور اسے ہم نے ہر شیطان مردود سے محفوظ رکھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1820, 15, 18, N'مگر جو چوری چھپے سننے جائے تو اس کے پیچھے پڑتا ہے روشن شعلہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1821, 15, 19, N'اور ہم نے زمین پھیلائی اور اس میں لنگر ڈالے اور اس میں ہر چیز اندازے سے اگائی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1822, 15, 20, N'اور تمہارے لیے اس میں روزیاں کردیں اور وہ کردیے جنہیں تم رزق نہیں دیتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1823, 15, 21, N'اور کوئی چیز نہیں جس کے ہمارے پاس خزانے نہ ہوں اور ہم اسے نہیں اتارتے مگر ایک معلوم انداز سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1824, 15, 22, N'اور ہم نے ہوائیں بھیجیں بادلوں کو با رور کرنے والیاں تو ہم نے آسمان سے پانی اتارا پھر وہ تمہیں پینے کو دیا اور تم کچھ اس کے خزانچی نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1825, 15, 23, N'اور بیشک ہم ہی جِلائیں اور ہم ہی ماریں اور ہم ہی وارث ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1826, 15, 24, N'اور بیشک ہمیں معلوم ہیں جو تم میں آگے بڑھے اور بیشک ہمیں معلوم ہیں جو تم میں پیچھے رہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1827, 15, 25, N'اور بیشک تمہارا رب ہی تمہیں قیامت میں اٹھائے گا بیشک وہی علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1828, 15, 26, N'اور بیشک ہم نے آدمی کو بجتی ہوئی مٹی سے بنایا جو اصل میں ایک سیاہ بودار گارا تھی، ف۳۳)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1829, 15, 27, N'اور جِن کو اس سے پہلے بنایا بے دھوئیں کی آگ سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1830, 15, 28, N'اور یاد کرو جب تمہارے رب نے فرشتوں سے فرمایا کہ میں آدمی کو بنانے والا ہوں بجتی مٹی سے جو بدبودار سیاہ گارے سے ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1831, 15, 29, N'تو جب میں اسے ٹھیک کرلوں اور اور میں اپنی طرف کی خاص معز ز ر وح پھونک دوں تو اس کے لیے سجدے میں گر پڑنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1832, 15, 30, N'تو جتنے فرشتے تھے سب کے سب سجدے میں گرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1833, 15, 31, N'سوا ابلیس کے، اس نے سجدہ والوں کا ساتھ نہ مانا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1834, 15, 32, N'فرمایا اے ابلیس تجھے کیا ہوا کہ سجدہ کرنے والوں سے الگ رہا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1835, 15, 33, N'بولا مجھے زیبا نہیں کہ بشر کو سجدہ کروں جسے تو نے بجتی مٹی سے بنایا جو سیاہ بودار گارے سے تھی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1836, 15, 34, N'فرمایا تو جنت سے نکل جا کہ تو مردود ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1837, 15, 35, N'اور بیشک قیامت تک تجھ پر لعنت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1838, 15, 36, N'بولا اے میرے رب تو مجھے مہلت دے اس دن تک کہ وہ اٹھائے جائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1839, 15, 37, N'فرمایا تو ان میں سے ہے جن کو اس معلوم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1840, 15, 38, N'وقت کے دن تک مہلت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1841, 15, 39, N'بولا اے رب میرے! قسم اس کی کہ تو نے مجھے گمراہ کیا میں انہیں زمین میں بھلاوے دوں گا اور ضرور میں ان سب کو بے راہ کروں گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1842, 15, 40, N'مگر جو ان میں تیرے چنے ہوئے بندے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1843, 15, 41, N'فرمایا یہ راستہ سیدھا میری طرف آتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1844, 15, 42, N'بیشک میرے بندوں پر تیرا کچھ قابو نہیں سوا ان گمراہوں کے جو تیرا ساتھ دیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1845, 15, 43, N'اور بیشک جہنم ان سب کا وعدہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1846, 15, 44, N'اس کے سات دروازے ہیں، ہر دروازے کے لیے ان میں سے ایک حصہ بٹا ہوا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1847, 15, 45, N'بیشک ڈر والے باغوں اور چشموں میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1848, 15, 46, N'ان میں داخل ہو سلامتی کے ساتھ امان میں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1849, 15, 47, N'اور ہم نے ان کے سینوں میں جو کچھ کینے تھے سب کھینچ لیے آپس میں بھائی ہیں تختوں پر روبرو بیٹھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1850, 15, 48, N'نہ انہیں اس میں کچھ تکلیف پہنچے نہ وہ اس میں سے نکالے جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1851, 15, 49, N'خبردو (۵۴) میرے بندوں کو کہ بیشک میں ہی ہوں بخشے والا مہربان،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1852, 15, 50, N'اور میرا ہی عذاب دردناک عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1853, 15, 51, N'اور انہیں احوال سناؤ ابراہیم کے مہمانوں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1854, 15, 52, N'جب وہ اس کے پاس آئے تو بولے سلام کہا ہمیں تم سے ڈر معلوم ہوتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1855, 15, 53, N'انہوں نے کہا ڈریے نہیں ہم آپ کو ایک علم والے لڑکے کی بشارت دیتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1856, 15, 54, N'کہا کیا اس پر مجھے بشارت دیتے ہو کہ مجھے بڑھاپا پہنچ گیا اب کاہے پر بشارت دیتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1857, 15, 55, N'کہا ہم نے آپ کو سچی بشارت دی ہے آپ ناامید نہ ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1858, 15, 56, N'کہا اپنے رب کی رحمت سے کون ناامید ہو مگر وہی جو گمراہ ہوئے، ف۶۱)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1859, 15, 57, N'کہا پھر تمہارا کیا کام ہے اے فرشتو!')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1860, 15, 58, N'بولے ہم ایک مجرم قوم کی طرف بھیجے گئے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1861, 15, 59, N'مگر لوط کے گھر والے، ان سب کو ہم بچالیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1862, 15, 60, N'مگر اس کی عورت ہم ٹھہراچکے ہیں کہ وہ پیچھے رہ جانے والوں میں ہے، ف۶۵)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1863, 15, 61, N'تو جب لوط کے گھر فرشتے آئے، ۶۶)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1864, 15, 62, N'کہا تم تو کچھ بیگانہ لوگ ہو، ف۶۷)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1865, 15, 63, N'کہا بلکہ ہم تو آپ کے پاس وہ لائے ہیں جس میں یہ لوگ شک کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1866, 15, 64, N'اور ہم آپ کے پاس سچا حکم لائے ہیں اور ہم بیشک سچے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1867, 15, 65, N'تو اپنے گھر والوں کو کچھ رات رہے لے کر باہر جایے اور آپ ان کے پیچھے چلئے اور تم میں کوئی پیچھے پھر کر نہ دیکھے اور جہاں کو حکم ہے سیدھے چلے جایئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1868, 15, 66, N'اور ہم نے اسے اس حکم کا فیصلہ سنادیا کہ صبح ہوتے ان کافروں کی جڑ کٹ جائے گی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1869, 15, 67, N'اور شہر والے خوشیاں مناتے آئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1870, 15, 68, N'لوط نے کہا یہ میرے مہمان ہیں مجھے فضیحت (رُسوا) نہ کرو، ف۷۵)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1871, 15, 69, N'اور اللہ سے ڈرو اور مجھے رسوا نہ کرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1872, 15, 70, N'بولے کیا ہم نے تمہیں منع نہ کیا تھا کہ اوروں کے معاملہ میں دخل نہ دو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1873, 15, 71, N'کہا یہ قوم کی عورتیں میری بیٹیاں ہیں اگر تمہیں کرنا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1874, 15, 72, N'اے محبوب تمہاری جان کی قسم بیشک وہ اپنے نشہ میں بھٹک رہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1875, 15, 73, N'تو دن نکلتے انہیں چنگھاڑ نے آلیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1876, 15, 74, N'تو ہم نے اس بستی کا اوپر کا حصہ اس نے نیچے کا حصہ کردیا اور ان پر کنکر کے پتھر برسائے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1877, 15, 75, N'بیشک اس میں نشانیاں ہیں فراست والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1878, 15, 76, N'اور بیشک وہ بستی اس راہ پر ہے جو اب تک چلتی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1879, 15, 77, N'بیشک اس میں نشانیاں ہیں ایمان والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1880, 15, 78, N'اور بیشک جھاڑی والے ضرور ظالم تھے، ف۸۲)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1881, 15, 79, N'تو ہم نے ان سے بدلہ لیا اور بیشک دونوں بستیاں کھلے راستہ پر پڑتی ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1882, 15, 80, N'اور بیشک حجر والو ں نے رسولوں کو جھٹلایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1883, 15, 81, N'اور ہم نے ان کو اپنی نشانیاں دیں تو وہ ان سے منہ پھیرے رہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1884, 15, 82, N'اور وہ پہاڑوں میں گھر تراشتے تھے بے خوف')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1885, 15, 83, N'تو انہیں صبح ہوتے چنگھاڑ نے آلیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1886, 15, 84, N'تو ان کی کمائی کچھ ان کے کام نہ آئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1887, 15, 85, N'اور ہم نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے عبث نہ بنایا، اور بیشک قیامت آنے والی ہے تو تم اچھی طرح درگزر کرو، ف۹۳)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1888, 15, 86, N'بیشک تمہارا رب ہی بہت پیدا کرنے والا جاننے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1889, 15, 87, N'اور بیشک ہم نے تم کو سات آیتیں دیں جو دہرائی جاتی ہیں اور عظمت والا قرآن،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1890, 15, 88, N'اپنی آنکھ اٹھاکر اس چیز کو نہ دیکھو جو ہم نے ان کے جوڑوں کو برتنے کو دی اور ان کا کچھ غم نہ کھاؤ اور مسلمانوں کو اپنی رحمت کے پروں میں لے لو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1891, 15, 89, N'اور فرماؤ کہ میں ہی ہوں صاف ڈر سنانے والا (اس عذاب سے)،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1892, 15, 90, N'جیسا ہم نے بانٹنے والوں پر اتارا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1893, 15, 91, N'جنہوں نے کلامِ الٰہی کو تکے بوٹی کرلیا، ف۹۹)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1894, 15, 92, N'تو تمہارے رب کی قسم ہم ضرور ان سب سے پوچھیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1895, 15, 93, N'جو کچھ وہ کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1896, 15, 94, N'تو اعلانیہ کہہ دو جس بات کا تمہیں حکم ہے اور مشرکوں سے منہ پھیر لو، ف۱۰۳)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1897, 15, 95, N'بیشک ان ہنسنے والوں پر ہم تمہیں کفا یت کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1898, 15, 96, N'جو ا لله کے ساتھ دوسرا معبود ٹھہراتے ہیں تو اب جان جائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1899, 15, 97, N'اور بیشک ہمیں معلوم ہے کہ ان کی باتوں سے تم دل تنگ ہوتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1900, 15, 98, N'تو اپنے رب کو سراہتے ہوئے اس کی پاکی بولو اور سجدہ والوں میں ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1901, 15, 99, N'اور مرتے دم تک اپنے رب کی عبادت میں رہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1902, 16, 1, N'اب آتا ہے اللہ کا حکم تو اس کی جلدی نہ کرو پاکی اور برتری ہے اسے ان شریکوں سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1903, 16, 2, N'ملائکہ کو ایمان کی جان یعنی وحی لے کر اپنے جن بندوں پر چاہے اتارتا ہے کہ ڈر سناؤ کہ میرے سوا کسی کی بندگی نہیں تو مجھ سے ڈرو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1904, 16, 3, N'اس نے آسمان اور زمین بجا بنائے وہ ان کے شرک سے برتر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1905, 16, 4, N'(اس نے) آدمی کو ایک نِتھری بوند سے بنایا تو جبھی کھلا جھگڑالو ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1906, 16, 5, N'اور چوپائے پیدا کیے ان میں تمہارے لیے گرم لباس اور منفعتیں ہیں اور ان میں سے کھاتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1907, 16, 6, N'اور تمہارا ان میں تجمل ہے جب انہیں شام کو واپس لاتے ہو اور جب چرنے کو چھوڑتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1908, 16, 7, N'اور وہ تمہارے بوجھ اٹھا کر لے جاتے ہیں ایسے شہر کی طرف کہ اس تک نہ پہنچتے مگر ادھ مرے ہوکر، بیشک تمہارا رب نہایت مہربان رحم والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1909, 16, 8, N'اور گھوڑے اور خچر اور گدھے کہ ان پر سوار ہو اور زینت کے لیے، اور وہ پیدا کرے گا جس کی تمہیں خبر نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1910, 16, 9, N'اور بیچ کی راہ ٹھیک اللہ تک ہے اور کوئی راہ ٹیڑھی ہے اور چاہتا تو تم سب کو راہ پر لاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1911, 16, 10, N'وہی ہے جس نے آسمان سے پانی اتارا اس سے تمہارا پینا ہے اور اس سے درخت ہیں جن سے چَراتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1912, 16, 11, N'اس پانی سے تمہارے لیے کھیتی اگاتا ہے اور زیتون اور کھجور اور انگور اور ہر قسم کے پھل بیشک اس میں نشانی ہے دھیان کرنے والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1913, 16, 12, N'اور اس نے تمہارے لیے مسخر کیے رات اور دن اور سورج اور چاند، اور ستارے اس کے حکم کے باندھے ہیں بیشک اس آیت میں نشانیاں ہیں عقل مندوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1914, 16, 13, N'اور وہ جو تمہارے لیے زمین میں پیدا کیا رنگ برنگ بیشک اس میں نشانی ہے یاد کرنے والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1915, 16, 14, N'اور وہی ہے جس نے تمہارے لیے دریا مسخر کیا کہ اس میں سے تازہ گوشت کھاتے ہو اور اس میں سے گہنا (زیور) نکالتے ہو جسے پہنتے ہو اور تو اس میں کشتیاں دیکھے کہ پانی چیر کر چلتی ہیں اور اس لیے کہ تم اس کا فضل تلاش کرو اور کہیں احسان مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1916, 16, 15, N'اور اس نے زمین میں لنگر ڈالے کہ کہیں تمہیں لے کر نہ کانپے اور ندیاں اور رستے کہ تم راہ پاؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1917, 16, 16, N'اور علامتیں اور ستارے سے وہ راہ پاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1918, 16, 17, N'تو کیا جو بنائے وہ ایسا ہوجائے گا جو نہ بنائے تو کیا تم نصیحت نہیں مانتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1919, 16, 18, N'اور اگر اللہ کی نعمتیں گنو تو انہیں شمار نہ کرسکو گے بیشک اللہ بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1920, 16, 19, N'اور اللہ جانتا ہے جو چھپاتے اور ظاہر کرتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1921, 16, 20, N'اور اللہ کے سوا جن کو پوجتے ہو ہیں (۳۲) وہ کچھ بھی نہیں بناتے اور وہ خود بنائے ہوئے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1922, 16, 21, N'مُردے ہیں زندہ نہیں اور انہیں خبر نہیں لوگ کب اٹھائے جایں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1923, 16, 22, N'تمہارا معبوثد ایک معبود ہے تو وہ جو آخرت پر ایمان نہیں لاتے ان کے دل منکر ہیں اور وہ مغرور ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1924, 16, 23, N'فی الحقیقت اللہ جانتا ہے جو چھپاتے اور جو ظاہر کرتے ہیں، بیشک وہ مغروروں کو پسند نہیں فرماتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1925, 16, 24, N'اور جب ان سے کہا جائے تمہارے رب نے کیا اتارا کہیں اگلوں کی کہانیاں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1926, 16, 25, N'کہ قیامت کے دن اپنے بوجھ پورے اٹھائیں اور کچھ بوجھ ان کے جنہیں اپنی جہالت سے گمراہ کرتے ہیں، سن لو کیا ہی برا بوجھ اٹھاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1927, 16, 26, N'بیشک ان سے اگلوں نے فریب کیا تھا تو اللہ نے ان کی چنائی کو نیو سے (تعمیر کو بنیاد) سے لیا تو اوپر سے ان پر چھت گر پڑی اور عذاب ان پر وہاں سے آیا جہاں کی انہیں خبر نہ تھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1928, 16, 27, N'پھر قیامت کے دن انہیں رسوا کرے گا اور فرمائے گا کہاں ہیں میرے وہ شریک جن میں تم جھگڑتے تھے علم والے کہیں گے آج ساری رسوائی اور برائی کافروں پر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1929, 16, 28, N'وہ کہ فرشتے ان کی جان نکالتے ہیں اس حال پر کیا وہ اپنا برا کررہے تھے اب صلح ڈالیں گے کہ ہم تو کچھ برائی نہ کرتے تھے ہاں کیوں نہیں، بیشک اللہ خوب جانتا ہے جو تمہارے کوتک (برے اعمال) تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1930, 16, 29, N'اب جہنم کے دروازوں میں جاؤ کہ ہمیشہ اس میں رہو، تو کیا ہی برا ٹھکانا مغروروں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1931, 16, 30, N'اور ڈر والوں سے کہا گیا تمہارے رب رب نے کیا اتارا، بولے خوبی جنہوں نے اس دنیا میں بھلائی کی ان کے لیے بھلائی ہے اور بیشک پچھلا گھر سب سے بہتر، اور ضرور کیا ہی اچھا گھر پرہیزگاروں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1932, 16, 31, N'بسنے کے باغ جن میں جائیں گے ان کے نیچے نہریں رواں انہیں وہاں ملے گا جو چاہیں اللہ ایسا ہی صلہ دیتا ہے پرہیزگاروں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1933, 16, 32, N'وہ جن کی جان نکالتے ہیں فرشتے ستھرے پن میں یہ کہتے ہوئے کہ سلامتی ہو تم پر جنت میں جاؤ بدلہ اپنے کیے کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1934, 16, 33, N'کاہے کے انتظار میں ہیں مگر اس کے کہ فرشتے ان پر آئیں یا تمہارے رب کا عذاب آئے ان سے اگلوں نے ایسا ہی کیا اور اللہ نے ان پر کچھ ظلم نہ کیا، ہاں وہ خود ہی اپنی جانوں پر ظلم کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1935, 16, 34, N'تو ان کی بری کمائیاں ان پر پڑیں اور انہیں گھیرلیا اس نے جس پر ہنستے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1936, 16, 35, N'اور مشرک بولے اللہ چاہتا تو اس کے سوا کچھ نہ پوجنے نہ ہم اور نہ ہمارے باپ دادا اور نہ اس سے جدا ہو کر ہم کوئی چیز حرام ٹھہراتے جیسا ہی ان سے اگلوں نے کیا تو رسولوں پر کیا ہے مگر صاف پہنچا دینا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1937, 16, 36, N'اور بیشک ہر امت میں ہم نے ایک رسول بھیجا کہ اللہ کو پوجو اور شیطان سے بچو تو ان میں کسی کو اللہ نے راہ دکھائی اور کسی پر گمراہی ٹھیک اتری تو زمین میں چل پھر کر دیکھو کیسا انجام ہوا جھٹلانے والوں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1938, 16, 37, N'اگر تم ان کی ہدایت کی حرص کرو تو بیشک اللہ ہدایت نہیں دیتا جسے گمراہ کرے اور ان کا کوئی مددگار نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1939, 16, 38, N'اور انہوں نے اللہ کی قسم کھائی اپنے حلف میں حد کی کوشش سے کہ اللہ مُردے نہ اٹھائے گا ہاں کیوں نہیں (۷۹) سچا وعدہ اس کے ذمہ پر لیکن اکثر لوگ نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1940, 16, 39, N'اس لیے کہ انہیں صاف بتادے جس بات میں جھگڑتے تھے اور اس لیے کہ کافر جان لیں کہ وہ جھوٹے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1941, 16, 40, N'جو چیز ہم چاہیں اس سے ہمارا فرمانا یہی ہوتا ہے کہ ہم کہیں ہوجا وہ فوراً ہوجاتی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1942, 16, 41, N'اور جنہوں نے اللہ کی راہ مں ی اپنے گھر بار چھوڑے مظلوم ہوکر ضرور ہم انہیں دنیا میں اچھی جگہ دیں گے اور بیشک آخرت کا ثواب بہت بڑا ہے کسی طرح لوگ جانتے، ف۸۶)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1943, 16, 42, N'وہ جنہوں نے صبر کیا اور اپنے رب ہی پر بھروسہ کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1944, 16, 43, N'اور ہم نے تم سے پہلے نہ بھیجے مگر مرد جن کی طرف ہم وحی کرتے، تو اے لوگو! علم والوں سے پوچھو اگر تمہیں علم نہیں، ف۹۰)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1945, 16, 44, N'روشن دلیلیں اور کتابیں لے کر اور اے محبوب ہم نے تمہاری ہی طرف یہ یاد گار اتاری کہ تم لوگوں سے بیان کردو جو ان کی طرف اترا اور کہیں وہ دھیان کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1946, 16, 45, N'تو کیا جو لوگ بڑے مکر کرتے ہیں اس سے نہیں ڈرتے کہ اللہ انہیں زمین میں دھنسادے یا انہیں وہاں سے عذاب آئے جہاں سے انہیں خبر نہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1947, 16, 46, N'یا انہیں چلتے پھرتے پکڑ لے کہ وہ تھکا نہیں سکتے، ف۹۸)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1948, 16, 47, N'یا انہیں نقصان دیتے دیتے گرفتار کرلے کہ بیشک تمہارا رب نہایت مہربان رحم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1949, 16, 48, N'اور کیا انہوں نے نہ دیکھا کہ جو چیز اللہ نے بنائی ہے اس کی پرچھائیاں دائیں اور بائیں جھکتی ہیں اللہ کو سجدہ کرتی اور وہ اس کے حضور ذلیل ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1950, 16, 49, N'اور اللہ ہی کو سجدہ کرتے ہیں جو کچھ آسمانوں میں ہیں اور جو کچھ زمین میں چلنے والا ہے اور فرشتے اور وہ غرور نہیں کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1951, 16, 50, N'اپنے اوپر اپنے رب کا خوف کرتے ہیں اور وہی کرتے ہیں جو انہیں حکم ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1952, 16, 51, N'اور اللہ نے فرمادیا دو خدا نہ ٹھہراؤ وہ تو ایک ہی معبود ہے تو مجھ ہی سے ڈرو، ف۱۰۶)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1953, 16, 52, N'اور اسی کا ہے جو کچھ آسمانوں اور زمین میں ہے اور اسی کی فرمانبرداری لازم ہے، تو اللہ کے سوا کسی دوسرے سے ڈرو گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1954, 16, 53, N'اور تمہارے پاس جو نعمت ہے سب اللہ کی طرف سے ہے پھر جب تمہیں تکلیف پہنچتی ہے تو اسی کی طرف پناہ لے جاتے ہو، ف۱۰۹)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1955, 16, 54, N'پھر جب وہ تم سے برائی ٹال دیتا ہے تو تم میں ایک گروہ اپنے رب کا شریک ٹھہرانے لگتا ہے، ف۱۱۰)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1956, 16, 55, N'کہ ہماری دی ہوئی نعمتوں کی ناشکری کریں، تو کچھ برت لو (۱۱۱) کہ عنقریب جان جاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1957, 16, 56, N'اور انجانی چیزوں کے لیے ہماری دی ہوئی روزی میں سے حصہ مقرر کرتے ہیں خدا کی قسم تم سے ضرور سوال ہونا ہے جو کچھ جھوٹ باندھتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1958, 16, 57, N'اور اللہ کے لیے بیٹیاں ٹھہراتے ہیں پاکی ہے اس کو اور اپنے لیے جو اپنا جی چاہتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1959, 16, 58, N'اور جب ان میں کسی کو بیٹی ہونے کی خوشخبری دی جاتی ہے تو دن بھر اس کا منہ کالا رہتا ہے اور وہ غصہ کھا تا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1960, 16, 59, N'لوگوں سے چھپا پھرتا ہے اس بشارت کی برائی کے سبب، کیا اسے ذلت کے ساتھ رکھے گا یا اسے مٹی میں دبادے گا ارے بہت ہی برا حکم لگاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1961, 16, 60, N'جو آخرت پر ایمان نہیں لاتے انہیں کا بر ا حال ہے، اور اللہ کی شان سب سے بلند، اور وہی عزت و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1962, 16, 61, N'اور اگر اللہ لوگوں کو ان کے ظلم پر گرفت کرتا تو زمین پر کوئی چلنے والا نہیں چھوڑتا لیکن انہیں ایک ٹھہرائے وعدے تک مہلت دیتا ہے پھر جب ان کا وعدہ آئے گا نہ ایک گھڑی پیچھے ہٹیں نہ آگے بڑھیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1963, 16, 62, N'اور اللہ کے لیے وہ ٹھہراتے ہیں جو اپنے لیے ناگوار ہے اور ان کی زبانیں جھوٹ کہتی ہیں کہ ان کے لیے بھلائی ہے تو آپ ہی ہوا کہ ان کے لیے آگ ہے اور وہ حد سے گزارے ہوئے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1964, 16, 63, N'خدا کی قسم ہم نے تم سے پہلے کتنی امتوں کی طرف رسول بھیجے تو شیطان نے ان کے کوتک (برُے اعمال) ان کی آنکھوں میں بھلے کر دکھائے تو آج وہی ان کا رفیق ہے اور ان کے لیے دردناک عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1965, 16, 64, N'اور ہم نے تم پر یہ کتاب نہ اتاری مگر اس لیے کہ تم لوگوں پر روشن کردو جس بات میں اختلاف کریں اور ہدایت اور رحمت ایمان والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1966, 16, 65, N'اور اللہ نے آسمان سے پانی اتارا تو اس سے زمین کو زندہ کردیا اس کے مرے پیچھے بیشک اس میں نشانی ہے ان کو جو کان رکھتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1967, 16, 66, N'اور بیشک تمہارے لیے چوپایوں میں نگاہ حاصل ہونے کی جگہ ہے ہم تمہیں پلاتے ہیں اس چیز میں سے جو ان کے پیٹ میں ہے، گوبر اور خون کے بیچ میں سے خالص دودھ گلے سے سہل اترتا پینے والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1968, 16, 67, N'اور کھجور اور انگور کے پھلوں میں سے کہ اس سے نبیذ بناتے ہو اور اچھا رزق بیشک اس میں نشانی ہے عقل والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1969, 16, 68, N'اور تمہارے رب نے شہد کی مکھی کو الہام کیا کہ پہاڑوں میں گھر بنا اور درختوں میں اور چھتوں میں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1970, 16, 69, N'پھر ہر قسم کے پھل میں سے کھا اور اپنے رب کی راہیں چل کر تیرے لیے نرم و آسان ہیں، اس کے پیٹ سے ایک پینے کی چیز رنگ برنگ نکلتی ہے، جس میں لوگوں کی تندرستی ہے، بیشک اس میں نشانی ہے دھیان کرنے والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1971, 16, 70, N'اور اللہ نے تمہیں پیدا کیا پھر تمہاری جان قبض کرے گا اور تم میں کوئی سب سے ناقض عمر کی طرف پھیرا جاتا ہے کہ جاننے کے بعد کچھ نہ جانے بیشک اللہ کچھ جانتا ہے سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1972, 16, 71, N'اور اللہ نے تم میں ایک دوسرے پر رزق میں بڑائی دی تو جنہیں بڑائی دی ہے وہ اپنا رزق اپنے باندی غلاموں کو نہ پھیر دیں گے کہ وہ سب اس میں برابر ہوجائیں تو کیا اللہ کی نعمت سے مکرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1973, 16, 72, N'اور اللہ نے تمہارے لیے تمہاری جنس سے عورتیں بنائیں اور تمہارے لیے تمہاری عورتوں سے بیٹے اور پوتے نواسے پیدا کیے اور تمہیں ستھری چیزوں سے روز ی دی تو کیا جھوٹی بات پر یقین لاتے ہیں اور اللہ کے فضل سے منکر ہوتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1974, 16, 73, N'اور اللہ کے سوا ایسوں کو پوجتے ہیں جو انہیں آسمان اور زمین سے کچھ بھی روزی دینے کا اختیار نہیں رکھتے نہ کچھ کرسکتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1975, 16, 74, N'تو اللہ کے لیے مانند نہ ٹھہراؤ بیشک اللہ جانتا ہے اور تم نہیں جانتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (1976, 16, 75, N'اللہ نے ایک کہاوت بیان فرمائی ایک بندہ ہے دوسرے کی ملک آپ کچھ مقدور نہیں رکھتا اور ایک جسے ہم نے اپنی طرف سے اچھی روزی عطا فرمائی تو وہ اس میں سے خرچ کرتا ہے چھپے اور ظاہر کیا وہ برابر ہوجائیں گے سب خوبیاں اللہ کو ہیں بلکہ ان میں اکثر کو خبر نہیں')
GO
