INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2024, 16, 123, N'پھر ہم نے تمہیں وحی بھیجی کہ دین ابراہیم کی پیروی کرو جو ہر باطل سے الگ تھا اور مشرک نہ تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2025, 16, 124, N'ہفتہ تو انہیں پر رکھا گیا تھا جو اس میں مختلف ہوگئے اور بیشک تمہارا رب قیا مت کے دن ان میں فیصلہ کردے گا جس بات میں اختلاف کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2026, 16, 125, N'اپنے رب کی راہ کی طرف بلاؤ پکی تدبیر اور اچھی نصیحت سے اور ان سے اس طریقہ پر بحث کرو جو سب سے بہتر ہو بیشک تمہارا رب خوب جانتا ہے جو اس کی راہ سے بہکا اور وہ خوب جانتا ہے راہ والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2027, 16, 126, N'اور اگر تم سزا دو تو ایسی ہی سزا دو جیسی تمہیں تکلیف پہونچائی تھی اور اگر تم صبر کرو تو بیشک صبر والوں کو صبر سب سے اچھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2028, 16, 127, N'اور اے محبوب! تم صبر کرو اور تمہارا صبر اللہ ہی کی توفیق سے ہے اور ان کا غم نہ کھاؤ اور ان کے فریبوں سے دل تنگ نہ ہو، ف۲۸۹)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2029, 16, 128, N'بیشک اللہ ان کے ساتھ ہے جو ڈرتے ہیں اور جو نیکیاں کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2030, 17, 1, N'پاکی ہے اسے جو اپنے بندے کو، راتوں رات لے گیا مسجد حرام سے مسجد اقصیٰ تک جس کے گرداگرد ہم نے برکت رکھی کہ ہم اسے اپنی عظیم نشانیاں دکھائیں، بیشک وہ سنتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2031, 17, 2, N'اور ہم نے موسیٰ کو کتاب عطا فرمائی اور اسے بنی اسرائیل کے لیے ہدایت کیا کہ میرے سوا کسی کو کارسام نہ ٹھہراؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2032, 17, 3, N'اے ان کی اولاد! جن کو ہم نے نوح کے ساتھ سوار کیا بیشک وہ بڑا شکرا گزار بندہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2033, 17, 4, N'اور ہم نے بنی اسرائیل کو کتاب میں وحی بھیجی کہ ضرور تم زمین میں دوبارہ فساد مچاؤ گے اور ضرور بڑا غرور کرو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2034, 17, 5, N'پھر جب ان میں پہلی بار کا وعدہ آیا ہم نے تم پر اپنے بندے بھیجے سخت لڑائی والے تو وہ شہروں کے اندر تمہاری تلاش کو گھسے اور یہ ایک وعدہ تھا جسے پورا ہونا تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2035, 17, 6, N'پھر ہم نے ان پر اُلٹ کر تمہارا حملہ کردیا اور تم کو مالوں اور بیٹوں سے مدد دی اور تمہارا جتھا بڑھا دیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2036, 17, 7, N'اگر تم بھلائی کرو گے اپنا بھلا کرو گے اور اگر بُرا کرو گے تو اپنا، پھر جب دوسری بار کا وعدہ آیا کہ دشمن تمہارا منہ بگاڑ دیں اور مسجد میں داخل ہوں جیسے پہلی بار داخل ہوئے تھے اور جس چیز پر قابو پائیں تباہ کرکے برباد کردیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2037, 17, 8, N'قریب ہے کہ تمہارا رب تم پر رحم کرے اور اگر تم پھر شرارت کرو تو ہم پھر عذاب کریں گے اور ہم نے جہنم کو کافروں کا قید خانہ بنایا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2038, 17, 9, N'بیشک یہ قرآن وہ راہ دکھاتا ہے جو سب سے سیدھی ہے اور خوشی سناتا ہے ایمان والوں کو جو اچھے کام کریں کہ ان کے لیے بڑا ثواب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2039, 17, 10, N'اور یہ کہ جو آخرت پر ایمان نہیں لاتے ہم نے ان کے لیے دردناک عذاب تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2040, 17, 11, N'اور آدمی برائی کی دعا کرتا ہے جیسے بھلائی مانگتا ہے اور آدمی بڑا جلد باز ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2041, 17, 12, N'اور ہم نے رات اور دن کو دو نشانیاں بنایا تو رات کی نشانی مٹی ہوئی رکھی اور دن کی نشانیاں دکھانے والی کہ اپنے کا فضل تلاش کرو اور برسوں کی گنتی اور حساب جانو اور ہم نے ہر چیز خوب جدا جدا ظاہر فرمادی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2042, 17, 13, N'اور ہر انسان کی قسمت ہم نے اس کے گلے سے لگادی اور اس کے لیے قیامت کے دن ایک نوشتہ نکالیں گے جسے کھلا ہوا پائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2043, 17, 14, N'فرمایا جائے گا کہ اپنا نامہ (نامہٴ اعمال) پڑھ آج تو خود ہی اپنا حساب کرنے کو بہت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2044, 17, 15, N'جو راہ پر آیا وہ اپنے ہی بھلے کو راہ پر آیا اور جو بہکا تو اپنے ہی برے کو بہکا اور کوئی بوجھ اٹھانے والی جان دوسرے کا بوجھ نہ اٹھائے گی اور ہم عذاب کرنے والے نہیں جب تک رسول نہ بھیج لیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2045, 17, 16, N'اور جب ہم کسی بستی کو ہلاک کرنا چاہتے ہیں اس کے خوشحالوں پر احکام بھیجتے ہیں پھر وہ اس میں بے حکمی کرتے ہیں تو اس پر بات پوری ہوجاتی ہے تو ہم اسے تباہ کرکے برباد کردیتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2046, 17, 17, N'اور ہم نے کتنی ہی سنگتیں (قومیں) نوح کے بعد ہلاک کردیں اور تمہارا رب کافی ہے اپنے بندوں کے گناہوں سے خبردار دیکھنے والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2047, 17, 18, N'جو یہ جلدی والی چاہے ہم اسے اس میں جلد دے دیں جو چاہیں جسے چاہیں پھر اس کے لیے جہنم کردیں کہ اس میں جائے مذمت کیا ہوا دھکے کھاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2048, 17, 19, N'اور جو آخرت چاہے اور اس کی سی کوشش کرے اور ہو ایمان والا تو انہیں کی کوشش ٹھکانے لگی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2049, 17, 20, N'ہم سب کو مدد دیتے ہیں اُن کو بھی اور اُن کو بھی، تمہارے رب کی عطا سے اور تمہارے رب کی عطا پر روک نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2050, 17, 21, N'دیکھو ہم نے ان میں ایک کو ایک پر کیسی بڑائی دی اور بیشک آخرت درجوں میں سب سے بڑی اور فضل میں سب سے اعلیٰ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2051, 17, 22, N'اے سننے والے اللہ کے ساتھ دوسرا خدا نہ ٹھہرا کہ تُو بیٹھ رہے گا مذمت کیا جاتا بیکس')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2052, 17, 23, N'اور تمہارے رب نے حکم فرمایا کہ اس کے سوا کسی کو نہ پُوجو اور ماں باپ کے ساتھ اچھا سلوک کرو، اگر تیرے سامنے ان میں ایک یا دونوں بڑھاپے کو پہنچ جائیں تو ان سے ہُوں، نہ کہنا اور انہیں نہ جھڑکنا اور ان سے تعظیم کی بات کہنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2053, 17, 24, N'اور ان کے لیے عاجزی کا بازو بچھا نرم دلی سے اور عرض کر کہ اے میرے رب تو ان دونوں پر رحم کر جیسا کہ ان دنوں نے مجھے چھٹپن (بچپن) میں پالا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2054, 17, 25, N'تمہارا رب خوب جانتا ہے جو تمہارے دلوں میں ہے اگر تم لائق ہوئے تو بیشک وہ توبہ کرنے والوں کو بخشنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2055, 17, 26, N'اور رشتہ داروں کو ان کا حق دے اور مسکین اور مسافر کو اور فضول نہ اڑا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2056, 17, 27, N'بیشک اڑانے والے شیطانوں کے بھائی ہیں اور شیطان اپنے رب کا بڑا ناشکرا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2057, 17, 28, N'اور اگر تو ان سے منہ پھیرے اپنے رب کی رحمت کے انتظار میں جس کی تجھے امید ہے تو ان سے آسان بات کہہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2058, 17, 29, N'اور اپنا ہاتھ اپنی گردن سے بندھا ہوا نہ رکھ اور نہ پورا کھول دے کہ تو بیٹھ رہے ملامت کیا ہوا تھکا ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2059, 17, 30, N'بیشک تمہارا رب جسے چاہے رزق کشادہ دیتا اور کستا ہے (تنگی دیتا ہے) بیشک وہ اپنے بندوں کو خوب جانتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2060, 17, 31, N'اور اپنی اولاد کو قتل نہ کرو مفلسی کے ڈر سے ہم انہیں بھی رزق دیں گے اور تمہیں بھی، بیشک ان کا قتل بڑی خطا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2061, 17, 32, N'اور بدکاری کے پاس نہ جاؤ بیشک وہ بے حیائی ہے، اور بہت ہی بری راہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2062, 17, 33, N'اور کوئی جان جس کی حرمت اللہ نے رکھی ہے ناحق نہ مارو، اور جو ناحق نہ مارا جائے تو بیشک ہم نے اس کے وارث کو قابو دیا تو وہ قتل میں حد سے نہ بڑھے ضرور اس کی مدد ہونی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2063, 17, 34, N'اور یتیم کے مال کے پاس تو جاؤ مگر اس راہ سے جو سب سے بھلی ہے یہاں تک کہ وہ اپنی جوانی کو پہنچے اور عہد پورا کرو بیشک عہد سے سوال ہونا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2064, 17, 35, N'اور ماپو تو پورا ماپو اور برابر ترازو سے تولو، یہ بہتر ہے اور اس کا انجام اچھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2065, 17, 36, N'اور اس بات کے پیچھے نہ پڑ جس کا تجھے علم نہیں بیشک کان اور آنکھ اور دل ان سب سے سوال ہونا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2066, 17, 37, N'اور زمین میں اتراتا نہ چل بیشک ہر گز زمین نہ چیر ڈالے گا، اور ہرگز بلندی میں پہاڑوں کو نہ پہنچے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2067, 17, 38, N'یہ جو کچھ گزرا ان میں کی بُری بات تیرے رب کو ناپسند ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2068, 17, 39, N'یہ ان وحیوں میں سے ہے جو تمہارے رب نے تمہاری طرف بھیجی حکمت کی باتیں اور اے سننے والے اللہ ساتھ دوسرا خدا نہ ٹھہرا کہ تو جہنم میں پھینکا جائے گا طعنہ پاتا دھکے کھاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2069, 17, 40, N'کیا تمہارے رب نے تم کو بیٹے چن دیے اور اپنے لیے فرشتوں سے بیٹیاں بنائیں بیشک تم بڑا بول بولتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2070, 17, 41, N'اور بیشک ہم نے اس قرآن میں طرح طرح سے بیان فرمایا کہ وہ سمجھیں اور اس سے انھیں نہیں بڑھتی مگر نفرت')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2071, 17, 42, N'تم فرماؤ اگر اس کے ساتھ اور خدا ہوتے جیسا یہ بکتے ہیں جب تو وہ عرش کے مالک کی طرف کوئی راہ ڈھونڈ نکالتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2072, 17, 43, N'اسے پاکی اور برتری ان کی باتوں سے بڑی برتری،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2073, 17, 44, N'اس کی پاکی بولتے ہیں ساتوں آسمان اور زمین اور جو کوئی ان میں ہیں اور کوئی چیز نہیں جو اسے سراہتی ہوتی اس کی پاکی نہ بولے ہاں تم ان کی تسبیح نہیں سمجھتے بیشک وہ حلم والا بخشنے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2074, 17, 45, N'اور اے محبوب! تم نے قرآن پڑھا ہم نے تم پر اور ان میں کہ آخرت پر ایمان ہیں لاتے ایک چھپا ہوا پردہ کردیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2075, 17, 46, N'اور ہم نے ان کے دلوں پر غلاف ڈال دیے ہیں کہ اسے نہ سمجھیں اور ان کے کانوں میں ٹینٹ (روئی) اور جب تم قرآن میں اپنے اکیلے رب کی یاد کرتے ہو وہ پیٹھ پھیر کر بھاگتے ہیں نفرت کرتے،')
GO
