INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2167, 18, 27, N'اور تلاوت کرو جو تمہارے رب کی کتاب تمہیں وحی ہوئی اس کی باتوں کا کوئی بدلنے والا نہیں اور ہرگز تم اس کے سوا پناہ نہ پاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2168, 18, 28, N'اور اپنی جان ان سے مانوس رکھو جو صبح و شام اپنے رب کو پکارتے ہیں اس کی رضا چاہتے ہیں اور تمہاری آنکھیں انہیں چھوڑ کر اور پر نہ پڑیں کیا تم دنیا کی زندگانی کا سنگھار چاہو گے، اور اس کا کہا نہ مانو جس کا دل ہم نے اپنی یاد سے غافل کردیا اور وہ اپنی خواہش کے پیچھے چلا اور اس کا کام حد سے گزر گیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2169, 18, 29, N'اور فرما دو کہ حق تمہارے رب کی طرف سے ہے تو جو چاہے ایمان لائے اور جو چاہے کفر کرے بیشک ہم نے ظالموں کے لیے وہ آگ تیار کر رکھی ہے جس کی دیواریں انہیں گھیر لیں گی، اور اگر پانی کے لیے فریاد کریں تو ان کی فریاد رسی ہوگی اس پانی سے کہ چرخ دے (کھولتے ہوئے) دھات کی طرح ہے کہ ان کے منہ بھون دے گا کیا ہی برا پینا ہے اور دوزخ کیا ہی بری ٹھہرنے کی جگہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2170, 18, 30, N'بیشک جو ایمان لائے اور نیک کام کیے ہم ان کے نیگ (اجر) ضائع نہیں کرتے جن کے کام اچھے ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2171, 18, 31, N'ان کے لیے بسنے کے باغ ہیں ان کے نیچے ندیاں بہیں وہ اس میں سونے کے کنگن بہنائے جایں گے اور سبز کپڑے کریب اور قناویز کے پہنیں گے وہاں تختوں پر تکیہ لگائے کیا ہی اچھا ثواب اور جنت کی کیا ہی اچھی آرام کی جگہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2172, 18, 32, N'اور ان کے سامنے دو مردوں کا حال بیان کرو کہ ان میں ایک کو ہم نے انگوروں کے دو باغ دیے اور ان کو کھجوروں سے ڈھانپ لیا اور ان کے بیچ میں کھیتی رکھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2173, 18, 33, N'دونوں باغ اپنے پھل لائے اور اس میں کچھ کمی نہ دی اور دونوں کے بیچ میں ہم نے نہر بہائی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2174, 18, 34, N'اور وہ پھل رکھتا تھا تو اپنے ساتھی سے بولا اور وہ اس سے رد و بدل کرتا تھا میں تجھ سے مال میں زیادہ ہوں اور آدمیوں کا زیادہ زور رکھتا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2175, 18, 35, N'اپنے باغ میں گیا اور اپنی جان پر ظلم کرتا ہوا بولا مجھے گمان نہیں کہ یہ کبھی فنا ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2176, 18, 36, N'اور میں گمان نہیں کرتا کہ قیامت قائم ہو اور اگر میں اپنے رب کی طرف پھر گیا بھی تو ضرور اس باغ سے بہتر پلٹنے کی جگہ پاؤں گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2177, 18, 37, N'اس کے ساتھی نے اس سے اُلٹ پھیر کرتے ہوئے جواب دیا کیا تو اس کے ساتھ کفر کرتا ہے جس نے تجھے مٹی سے بنایا پھر نطفہ سے پھر تجھے ٹھیک مرد کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2178, 18, 38, N'لیکن میں تو یہی کہتا ہوں کہ وہ اللہ ہی میرا رب ہے او ر میں کسی کو اپنے رب کا شریک نہیں کرتا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2179, 18, 39, N'اور کیوں نہ ہوا کہ جب تو اپنے باغ میں گیا تو کہا ہوتا جو چاہے اللہ، ہمیں کچھ زور نہیں مگر اللہ کی مدد کا اگر تو مجھے اپنے سے مال و اولاد میں کم دیکھتا تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2180, 18, 40, N'تو قریب ہے کہ میرا رب مجھے تیرے باغ سے اچھا دے اور تیرے باغ پر آسمان سے بجلیاں اتارے تو وہ پٹ پر میدان (سفید زمین) ہوکر رہ جائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2181, 18, 41, N'یا اس کا پانی زمین میں دھنس جائے پھر تو اسے ہرگز تلاش نہ کرسکے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2182, 18, 42, N'اور اس کے پھل گھیر لیے گئے تو اپنے ہاتھ ملتا رہ گیا اس لاگت پر جو اس باغ میں خرچ کی تھی اور وہ اپنی ٹیٹوں پر (اوندھے منہ) گرا ہوا تھا اور کہہ رہا ہے، اے کاش! میں نے اپنے رب کا کسی کو شریک نہ کیا ہوتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2183, 18, 43, N'اور اس کے پاس کوئی جماعت نہ تھی کہ اللہ کے سامنے اس کی مدد کرتی نہ وہ بدلہ لینے کے قابل تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2184, 18, 44, N'یہاں کھلتا ہے کہ اختیار سچے اللہ کا ہے، اس کا ثواب سب سے بہتر اور اسے ماننے کا انجام سب سے بھلا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2185, 18, 45, N'اور ان کے سامنے زندگانی دنیا کی کہاوت بیان کرو جیسے ایک پانی ہم نے آسمان اتارا تو اس کے سبب زمین کا سبزہ گھنا ہوکر نکلا کہ سوکھی گھاس ہوگیا جسے ہوائیں اڑائیں اور اللہ ہر چیز پر قابو والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2186, 18, 46, N'مال اور بیٹے یہ جیتی دنیا کا سنگھار ہے اور باقی رہنے والی اچھی باتیں ان کا ثواب تمہارے رب کے یہاں بہتر اور وہ امید میں سب سے بھلی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2187, 18, 47, N'اور جس دن ہم پہاڑوں کو چلائیں گے اور تم زمین کو صاف کھلی ہوئی دیکھو گے اور ہم انہیں اٹھائیں گے تو ان میں سے کسی کو نہ چھوڑیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2188, 18, 48, N'اور سب تمہارے رب کے حضور پرا باندھے پیش ہوں گے بیشک تم ہمارے پاس ویسے ہی آئےجیسا ہم نے تمہیں پہلی بار بنایا تھا بلکہ تمہارا گمان تھا کہ ہم ہر گز تمہارے لیے کوئی وعدہ کا وقت نہ رکھیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2189, 18, 49, N'اور نامہٴ اعمال رکھا جائے گا تو تم مجرموں کو دیکھو گے کہ اس کے لکھے سے ڈرتے ہوں گے اور کہیں گے ہائے خرابی ہماری اس نوشتہ کو کیا ہوا نہ اس نے کوئی چھوٹا گناہ چھوڑا نہ بڑا جسے گھیر لیا ہو اور اپنا سب کیا انہوں نے سامنے پایا، اور تمہارا رب کسی پر ظلم نہیں کرتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2190, 18, 50, N'اور یاد کرو جب ہم نے فرشتوں کو فرمایا کہ آدم کو سجدہ کرو تو سب نے سجدہ کیا سوا ابلیس کے، قومِ جن سے تھا تو اپنے رب کے حکم سے نکل گیا بھلا کیا اسے اور اس کی اولاد و میرے سوا دوست بناتے ہو اور وہ ہمارے دشمن ہیں ظالموں کو کیا ہی برا بدل (بدلہ) ملا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2191, 18, 51, N'نہ میں نے آسمانوں اور زمین کو بناتے وقت انہیں سامنے بٹھالیا تھا، نہ خود ان کے بناتے وقت اور نہ میری شان، کہ گمراہ کرنے والوں کو بازوں بناؤں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2192, 18, 52, N'اور جس دن فرمائے گا کہ پکارو میرے شریکوں کو جو تم گمان کرتے تھے تو انہیں پکاریں گے وہ انہیں جواب نہ دیں گے اور ہم ان کے درمیان ایک ہلاکت کا میدان کردیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2193, 18, 53, N'اور مجرم دوزخ کو دیکھیں گے تو یقین کریں گا کہ انہیں اس میں گرنا ہے اور اس سے پھرنے کی کوئی جگہ نہ پائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2194, 18, 54, N'اور بیشک ہم نے لوگوں کے لیے اس قرآن میں ہر قسم کی مثل طرح طرح بیان فرمائی اور آدمی ہر چیز سے بڑھ کر جھگڑالو ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2195, 18, 55, N'اور آدمیوں کو کسی چیز نے اس سے روکا کہ ایمان لاتے جب ہدایت ان کے پاس آئی اور اپنے رب سے معافی مانگتے مگر یہ کہ ان پر اگلوں کا دستور آئے یا ان پر قسم قسم کا عذاب آئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2196, 18, 56, N'اور ہم رسولوں کو نہیں بھیجتے مگر خوشی ڈر سنانے والے اور جو کافر ہیں وہ باطل کے ساتھ جھگڑتے ہیں کہ اس سے حق کو ہٹادیں اور انہوں نے میری آیتوں کی اور جو ڈر انہیں سناتے گئے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2197, 18, 57, N'ان کی ہنسی بنالی اور اس سے بڑھ کر ظالم کون جسے اس کے رب کی آیتیں یاد دلائی جائیں تو وہ ان سے منہ پھیرلے اور اس کے ہاتھ جو آگے بھیج چکے اسے بھول جائے ہم نے ان کے دلوں پر غلاف کردیے ہیں کہ قرآن نہ سمجھیں اور ان کے کانوں میں گرانی اور اگر تم انہیں ہدایت کی طرف بلاؤ تو جب بھی ہرگز کبھی راہ نہ پائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2198, 18, 58, N'اور تمہارا رب بخشنے والا مہر وا لا ہے، اگر وہ انہیں ان کے کیے پر پکڑتا تو جلد ان پر عذاب بھیجتا بلکہ ان کے لیے ایک وعدہ کا وقت ہے جس کے سامنے کوئی پناہ نہ پائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2199, 18, 59, N'اور یہ بستیاں ہم نے تباہ کردیں جب انہوں نے ظلم کیا اور ہم نے ان کی بربادی کا ایک وعدہ رکھا تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2200, 18, 60, N'اور یاد کرو جب موسیٰ نے اپنے خادم سے کہا میں باز نہ رہوں گا جب تک وہاں نہ پہنچوں جہاں دو سمندر ملے ہیں یا قرنوں (مدتوں تک) چلا جاؤں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2201, 18, 61, N'پھر جب وہ دونوں ان دریاؤں کے ملنے کی جگہ پہنچے اپنی مچھلی بھول گئے اور اس نے سمندر میں اپنی راہ لی سرنگ بناتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2202, 18, 62, N'پھر جبب وہاں سے گزر گئے موسیٰ نے خادم سے کہا ہمارا صبح کا کھانا لاؤ بیشک ہمیں اپنے اس سفر میں بڑی مشقت کا سامنا ہوا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2203, 18, 63, N'بولا بھلا دیکھئے تو جب ہم نے اس چٹان کے پاس جگہ لی تھی تو بیشک میں مچھلی کو بھول گیا، اور مجھے شیطان ہی نے بھلا دیا کہ میں اس کا مذکور کروں اور اس نے تو سمندر میں اپنی راہ لی، اچنبھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2204, 18, 64, N'موسیٰ نے کہا یہی تو ہم چاہتے تھے تو پیچھے پلٹے اپنے قدموں کے نشان دیکھتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2205, 18, 65, N'تو ہمارے بندوں میں سے ایک بندہ پایا جسے ہم نے اپنے پاس سے رحمت دی اور اسے اپنا علم لدنی عطا کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2206, 18, 66, N'اس سے موسیٰ نے کہا کیا میں تمہارے ساتھ رہوں اس شرط پر کہ تم مجھے سکھادو گے نیک بات جو تمہیں تعلیم ہوئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2207, 18, 67, N'کہا آپ میرے ساتھ ہرگز نہ ٹھہر سکیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2208, 18, 68, N'اور اس بات پر کیونکر صبر کریں گے جسے آپ کا علم محیط نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2209, 18, 69, N'کہا عنقریب اللہ چاہے تو تم مجھے صابر پاؤ گے اور میں تمہارے کسی حکم کے خلاف نہ کروں گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2210, 18, 70, N'کہا تو اگر آپ میرے ساتھ رہنے ہیں تو مجھ سے کسی بات کو نہ پوچھنا جب تک میں خود اس کا ذکر نہ کروں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2211, 18, 71, N'اب دونوں چلے یہاں تک کہ جب کشتی میں سوار ہوئے اس بندہ نے اسے چیر ڈالا موسیٰ نے کہا کیا تم نے اسے اس لیے چیرا کہ اس کے سواروں کو ڈبا دو بیشک یہ تم نے بری بات کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2212, 18, 72, N'کہا میں نہ کہتا تھا کہ آپ میرے ساتھ ہرگز نہ ٹھہر سکیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2213, 18, 73, N'کہا مجھ سے میری بھول پر گرفت نہ کرو اور مجھ پر میرے کام میں مشکل نہ ڈالو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2214, 18, 74, N'پھر دونوں چلے یہاں تک کہ جب ایک لڑکا ملا اس بندہ نے اسے قتل کردیا، موسیٰ نے کہا کیا تم نے ایک ستھری جان بے کسی جان کے بدلے قتل کردی، بیشک تم نے بہت بری بات کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2215, 18, 75, N'کہا میں نے آپ سے نہ کہا تھا کہ آپ ہرگز میرے ساتھ نہ ٹھہرسکیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2216, 18, 76, N'کہا اس کے بعد میں تم سے کچھ پوچھوں تو پھر میرے ساتھ نہ رہنا، بیشک میری طرف سے تمہارا عذر پورا ہوچکا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2217, 18, 77, N'پھر دونوں چلے یہاں تک کہ جب ایک گاؤں والوں کے پاس آئے ان دہقانوں سے کھانا مانگا انہوں نے انہیں دعوت دینی قبول نہ کی پھر دونوں نے اس گاؤں میں ایک دیوار پا ئی کہ گرا چاہتی ہے اس بندہ نے اسے سیدھا کردیا، موسیٰ نے کہا تم چاہتے تو اس پر کچھ مزدوری لے لیتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2218, 18, 78, N'کہا یہ میری اور آپ کی جدائی ہے اب میں آپ کو ان باتوں کا پھیر (بھید) بتاؤں گا جن پر آپ سے صبر نہ ہوسکا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2219, 18, 79, N'وہ جو کشتی تھی وہ کچھ محتاجوں کی تھی کہ دریا میں کام کرتے تھے، تو میں نے چاہا کہ اسے عیب دار کردوں اور ان کے پیچھے ایک بادشاہ تھا کہ ہر ثابت کشتی زبردستی چھین لیتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2220, 18, 80, N'اور وہ جو لڑکا تھا اس کے ماں باپ مسلمان تھے تو ہمیں ڈر ہوا کہ وہ ان کو سرکشی اور کفر پر چڑھاوے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2221, 18, 81, N'تو ہم نے چاہا کہ ان دونوں کا رب اس سے بہتر ستھرا اور اس سے زیادہ مہربانی میں قریب عطا کرے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2222, 18, 82, N'رہی وہ دیوار وہ شہر کے دو یتیم لڑکوں کی تھی اور اس کے نیچے ان کا خزانہ تھا اور ان کا باپ نیک آدمی تھا تو آپ کے رب نے چاہا کہ وہ دونوں اپنی جوانی کو پہنچیں اور اپنا خزانہ نکالیں، آپ کے رب کی رحمت سے اور یہ کچھ میں نے اپنے حکم سے نہ کیا یہ پھیر ہے ان باتوں کا جس پر آپ سے صبر نہ ہوسکا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2223, 18, 83, N'اور تم سے ذوالقرنین کو پوچھتے ہیں تم فرماؤ میں تمہیں اس کا مذکور پڑھ کر سناتا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2224, 18, 84, N'بیشک ہم نے اسے زمین میں قابو دیا اور ہر چیز کا ایک سامان عطا فرمایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2225, 18, 85, N'تو وہ ایک سامان کے پیچھے چلا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2226, 18, 86, N'یہاں تک کہ جب سورج ڈوبنے کی جگہ پہنچا اسے ایک سیاہ کیچڑ کے چشمے میں ڈوبتا پایا اور وہاں ایک قوم ملی ہم نے فرمایا اے ذوالقرنین یا تو تُو انہیں عذاب دے یا ان کے ساتھ بھلائی اختیار کرے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2227, 18, 87, N'عرض کی کہ وہ جس نے ظلم کیا اسے تو ہم عنقریب سزادیں گے پھر اپنے رب کی طرف پھیرا جائے گا وہ اسے بری مار دے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2228, 18, 88, N'اور جو ایمان لایا اور نیک کام کیا تو اس کا بدلہ بھلائی ہے اور عنقریب ہم اسے آسان کام کہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2229, 18, 89, N'پھر ایک سامان کے پیچھے چلا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2230, 18, 90, N'یہاں تک کہ جب سورج نکلنے کی جگہ پہنچا، اسے ایسی قوم پر نکلتا پایا جن کے لیے ہم نے سورج سے کوئی آڑ نہیں رکھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2231, 18, 91, N'بات یہی ہے، اور جو کچھ اس کے پاس تھا سب کو ہمارا علم محیط ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2232, 18, 92, N'پھر ایک ساما ن کے پیچھے چلا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2233, 18, 93, N'یہاں تک کہ جب دو پہاڑوں کے بیچ پہنچا ان سے ادھر کچھ ایسے لوگ پائے کہ کوئی بات سمجھتے معلوم نہ ہوتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2234, 18, 94, N'انھوں نے کہا، اے ذوالقرنین! بیشک یاجوج ماجوج زمین میں فساد مچاتے ہیں تو کیا ہم آپ کے لیے کچھ مال مقرر کردیں اس پر کہ آپ ہم میں اور ان میں ایک دیوار بنادیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2235, 18, 95, N'کہا وہ جس پر مجھے میرے رب نے قابو دیا ہے بہتر ہے تو میری مدد طاقت سے کرو میں تم میں اور ان میں ایک مضبوط آڑ بنادوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2236, 18, 96, N'میرے پاس لوہے کے تختے لاؤ یہاں تک کہ وہ جب دیوار دونوں پہاڑوں کے کناروں سے برابر کردی، کہا دھونکو، یہاں تک کہ جب اُسے آگ کردیا کہا لاؤ، میں اس پر گلا ہوا تانبہ اُنڈیل دوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2237, 18, 97, N'تو یاجوج و ماجوج اس پر نہ چڑھ سکے اور نہ اس میں سوراخ کرسکے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2238, 18, 98, N'کہا یہ میرے رب کی رحمت ہے، پھر جب میرے رب کا وعدہ آئے گا اسے پاش پاش کردے گا اور میرے رب کا وعدہ سچا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2239, 18, 99, N'اور اس دن ہم انہیں چھوڑ دیں گے کہ ان کا ایک گروہ دوسرے پر ریلا (سیلاب کی طرح) آوے گا اور صُور پھونکا جائے گا تو ہم سب کو اکٹھا کر لائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2240, 18, 100, N'اور ہم اس دن جہنم کافروں کے سامنے لائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2241, 18, 101, N'وہ جن کی آنکھوں پر میری یاد سے پردہ پڑا تھا اور حق بات سن نہ سکتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2242, 18, 102, N'تو کیا کافر یہ سمجھتے ہیں کہ میرے بندوں کو میرے سوا حمایتی بنالیں گے بیشک ہم نے کافروں کی مہمانی کو جہنم تیار کر رکھی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2243, 18, 103, N'تم فرماؤ کیا ہم تمہیں بتادیں کہ سب سے بڑھ کر ناقص عمل کن کے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2244, 18, 104, N'ان کے جن کی ساری کوشش دنیا کی زندگی میں گم گئی اور وہ اس خیال میں ہیں کہ اچھا کام کررہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2245, 18, 105, N'یہ لوگ جنہوں نے اپنے رب کی آیتیں اور اس کا ملنا نہ مانا تو ان کا کیا دھرا سب اکارت ہے تو ہم ان کے لیے قیامت کے دن کوئی تول نہ قائم کریں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2246, 18, 106, N'یہ ان کا بدلہ ہے جہنم، اس پر کہ انہوں نے کفر کیا اور میری آیتوں اور میرے رسولوں کی ہنسی بنائی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2247, 18, 107, N'بیشک جو ایمان لائے اور اچھے کام کیے فردوس کے باغ ان کی مہمانی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2248, 18, 108, N'وہ ہمیشہ ان ہی میں رہیں گے ان سے جگہ بدلنا نہ چاہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2249, 18, 109, N'تم فرمادو اگر سمندر میرے رب کی باتوں کے لیے، سیاہی ہو تو ضرور سمندر ختم ہوجائے گا اور میرے رب کی باتیں ختم نہ ہوں گی اگرچہ ہم ویسا ہی اور اس کی مدد کو لے آئیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2250, 18, 110, N'تو فرماؤ ظاہر صورت بشری میں تو میں تم جیسا ہوں مجھے وحی آتی ہے کہ تمہارا معبود ایک ہی معبود ہے تو جسے اپنے رب سے ملنے کی امید ہو اسے چاہیے کہ نیک کام کرے اور اپنے رب کی بندگی میں کسی کو شریک نہ کرے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2251, 19, 1, N'کھیٰعص')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2252, 19, 2, N'یہ مذکور ہے تیرے رب کی اس رحمت کا جو اس نے اپنے بندہ زکریا پر کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2253, 19, 3, N'جب اس نے اپنے رب کو آہستہ پکارا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2254, 19, 4, N'عرض کی اے میرے رب میری ہڈی کمزور ہوگئی اور سرے سے بڑھاپے کا بھبھوکا پھوٹا (شعلہ چمکا) اور اے میرے رب میں تجھے پکار کر کبھی نامراد نہ رہا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2255, 19, 5, N'اور مجھے اپنے بعد اپنے قرابت والوں کا ڈر ہے اور میری عورت بانجھ ہے تو مجھے اپنے پاس سے کوئی ایسا دے ڈال جو میرا کام اٹھائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2256, 19, 6, N'وہ میرا جانشین ہو اور اولاد یعقوب کا وارث ہو، اور اے میرے رب! اسے پسندیدہ کر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2257, 19, 7, N'اے زکریا ہم تجھے خوشی سناتے ہیں ایک لڑکے کی جن کا نام یحییٰ ہے اس کے پہلے ہم نے اس نام کا کوئی نہ کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2258, 19, 8, N'عرض کی اے میرے رب! میرے لڑکا کہاں سے ہوگا میری عورت تو بانجھ ہے اور میں بڑھاپے سے سوکھ جانے کی حالت کو پہنچ گیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2259, 19, 9, N'فرمایا ایسا ہی ہے تیرے رب نے فرمایا وہ مجھے آسان ہے اور میں نے تو اس سے پہلے تجھے اس وقت بنایا جب تک کچھ بھی نہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2260, 19, 10, N'عرض کی اے میرے رب! مجھے کوئی نشانی دے دے فرمایا تیری نشانی یہ ہے کہ تو تین رات دن لوگوں سے کلام نہ کرے بھلا چنگا ہوکر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2261, 19, 11, N'تو اپنی قوم پر مسجد سے باہر آیا تو انہیں اشارہ سے کہا کہ صبح و شام تسبیح کرتے رہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2262, 19, 12, N'اے یحییٰ کتاب مضبوط تھام، اور ہم نے اسے بچپن ہی میں نبوت دی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2263, 19, 13, N'اور اپنی طرف سے مہربانی اور ستھرائی اور کمال ڈر والا تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2264, 19, 14, N'اور اپنے ماں باپ سے اچھا سلوک کرنے والا تھا زبردست و نافرمان نہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2265, 19, 15, N'اور سلامتی ہے اس پر جس دن پیدا ہوا اور جس دن مرے گا اورجس دن مردہ اٹھایا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2266, 19, 16, N'اور کتاب میں مریم کو یاد کرو جب اپنے گھر والوں سے پورب کی طرف ایک جگہ الگ گئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2267, 19, 17, N'تو ان سے ادھر ایک پردہ کرلیا، تو اس کی طرف ہم نے اپنا روحانی (روح الامین) بھیجا وہ اس کے سامنے ایک تندرست آدمی کے روپ میں ظاہر ہوا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2268, 19, 18, N'بولی میں تجھ سے رحمان کی پناہ مانگتی ہوں اگر تجھے خدا کا ڈر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2269, 19, 19, N'بولا میں تیرے رب کا بھیجا ہوا ہوں، کہ میں تجھے ایک ستھرا بیٹا دوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2270, 19, 20, N'بولی میرے لڑکا کہاں سے ہوگا مجھے تو کسی آدمی نے ہاتھ نہ لگایا نہ میں بدکار ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2271, 19, 21, N'کہا یونہی ہے تیرے رب نے فرمایا ہے کہ یہ مجھے آسان ہے، اور اس لیے کہ ہم اسے لوگوں کے واسطے نشانی کریں اور اپنی طرف سے ایک رحمت اور یہ کام ٹھہرچکا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2272, 19, 22, N'اب مریم نے اسے پیٹ میں لیا پھر اسے لیے ہوئے ایک دور جگہ چلی گئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2273, 19, 23, N'پھر اسے جننے کا درد ایک کھجور کی جڑ میں لے آیا بولی ہائے کسی طرح میں اس سے پہلے مرگئی ہوتی اور بھولی بسری ہوجاتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2274, 19, 24, N'تو اسے اس کے تلے سے پکارا کہ غم نہ کھا بیشک تیرے رب نے نیچے ایک نہر بہادی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2275, 19, 25, N'اور کھجور کی جڑ پکڑ کر اپنی طرف ہلا تجھ پر تازی پکی کھجوریں گریں گی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2276, 19, 26, N'تو کھا اور پی اور آنکھ ٹھنڈی رکھ پھر اگر تو کسی آدمی کو دیکھے تو کہہ دینا میں نے آج رحمان کا روزہ مانا ہے تو آج ہرگز کسی آدمی سے بات نہ کرو ں گی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2277, 19, 27, N'تو اسے گود میں لے اپنی قوم کے پاس آئی بولے اے مریم! بیشک تو نے بہت بری بات کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2278, 19, 28, N'اے ہارون کی بہن تیرا باپ برا آدمی نہ تھا اور نہ تیری ماں بدکار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2279, 19, 29, N'اس پر مریم نے بچے کی طرف اشارہ کیا وہ بولے ہم کیسے بات کریں اس سے جو پالنے میں بچہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2280, 19, 30, N'بچہ نے فرمایا میں اللہ کا بندہ اس نے مجھے کتاب دی اور مجھے غیب کی خبریں بتانے والا (نبی) کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2281, 19, 31, N'اور اس نے مجھے مبارک کیا میں کہیں ہوں اور مجھے نماز و زکوٰة کی تاکید فرمائی جب تک جیوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2282, 19, 32, N'اور اپنی ماں سے اچھا سلوک کرنے والا اور مجھے زبردست بدبخت نہ کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2283, 19, 33, N'اور وہی سلامتی مجھ پر جس دن میں پیدا ہوا اور جس دن مروں اور جس دن زندہ اٹھایا جاؤں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2284, 19, 34, N'یہ ہے عیسیٰ مریم کا بیٹا سچی بات جس میں شک کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2285, 19, 35, N'اللہ کو لائق نہیں کہ کسی کو اپنا بچہ ٹھہرائے پاکی ہے اس کو جب کسی کام کا حکم فرماتا ہے تو یونہی کہ اس سے فرماتا ہے ہوجاؤ وہ فوراًٰ ہوجاتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2286, 19, 36, N'اور عیسیٰ نے کہا بیشک اللہ رب ہے میرا اور تمہارا تو اس کی بندگی کرو، یہ راہ سیدھی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2287, 19, 37, N'پھر جماعتیں آپس میں مختلف ہوگئیں تو خرابی ہے، کافروں کے لیے ایک بڑے دن کی حاضری سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2288, 19, 38, N'کتنا سنیں گے اور کتنا دیکھیں گے جس دن ہمارے پاس حاضر ہونگے مگر آج ظالم کھلی گمراہی میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2289, 19, 39, N'اور انہیں ڈر سناؤ پچھتاوے کے دن کا جب کام ہوچکے گا اور وہ غفلت میں ہیں اور نہیں مانتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2290, 19, 40, N'بیشک زمین اور جو کچھ اس پر ہے سب کے وارث ہم ہوں گے اور وہ ہماری ہی طرف پھریں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2291, 19, 41, N'اور کتاب میں ابراہیم کو یاد کرو بیشک وہ صدیق تھا (نبی) غیب کی خبریں بتاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2292, 19, 42, N'جب اپنے باپ سے بولا اے میرے باپ کیوں ایسے کو پوجتا ہے جو نہ سنے نہ دیکھے اور نہ کچھ تیرے کام آئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2293, 19, 43, N'اے میرے باپ بیشک میرے پاس وہ علم آیا جو تجھے نہ آیا تو تُو میرے پیچھے چلا آ میں تجھے سیدھی راہ دکھاؤں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2294, 19, 44, N'اے میرے باپ شیطان کا بندہ نہ بن بیشک شیطان رحمان کا نافرمان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2295, 19, 45, N'اے میرے باپ میں ڈرتا ہوں کہ تجھے رحمن کا کوئی عذاب پہنچے تو تُو شیطان کا رفیق ہوجائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2296, 19, 46, N'بولا کیا تو میرے خداؤں سے منہ پھیرتا ہے، اے ابراہیم بیشک اگر تو باز نہ آیا تو میں تجھے پتھراؤ کروں گا اور مجھ سے زمانہ دراز تک بے علاقہ ہوجا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2297, 19, 47, N'کہا بس تجھے سلام ہے قریب ہے کہ میں تیرے لیے اپنے رب سے معافی مانگوں گا بیشک وہ مجھ مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2298, 19, 48, N'اور میں ایک کنارے ہوجاؤں گا تم سے اور ان سب سے جن کو اللہ کے سوا پوجتے ہو اور اپنے رب کو پوجوں گا قریب ہے کہ میں اپنے رب کی بندگی سے بدبخت نہ ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2299, 19, 49, N'پھر جب ان سے اور اللہ کے سوا ان کے معبودوں سے کنارہ کر گیا ہم نے اسے اسحاق اور یعقوب عطا کیے، اور ہر ایک کو غیب کی خبریں بتانے والا کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2300, 19, 50, N'اور ہم نے انہیں اپنی رحمت عطا کی اور ان کے لیے سچی بلند ناموری رکھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2301, 19, 51, N'اور کتاب میں موسیٰ کو یاد کرو، بیشک وہ چنا ہوا تھا اور رسول تھا غیب کی خبریں بتانے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2302, 19, 52, N'اور اسے ہم نے طور کی داہنی جانب سے ندا فرمائی اور اسے اپنا راز کہنے کو قریب کیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2303, 19, 53, N'اور اپنی رحمت سے اس کا بھائی ہارون عطا کیا (غیب کی خبریں بتانے والا نبی)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2304, 19, 54, N'اور کتاب میں اسماعیل کو یاد کرو بیشک وہ وعدے کا سچا تھا اور رسول تھا غیب کی خبریں بتاتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2305, 19, 55, N'اور اپنے گھر والوں کو نماز اور زکوٰة کا حکم دیتا اور اپنے رب کو پسند تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2306, 19, 56, N'اور کتاب میں ادریس کو یاد کرو بیشک وہ صدیق تھا غیب کی خبریں دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2307, 19, 57, N'اور ہم نے اسے بلند مکان پر اٹھالیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2308, 19, 58, N'یہ ہیں جن پر ا لله نے احسان کیا غیب کی خبریں بتانے میں سے آدم کی اولاد سے اور ان میں جن کو ہم نے نوح کے ساتھ سوار کیا تھا اور ابراہیم اور یعقوب کی اولاد سے اور ان میں سے جنہیں ہم نے راہ دکھائی اور چن لیا جب ان پر رحمن کی آیتیں پڑھی جاتیں گر پڑتے سجدہ کرتے اور روتے (السجدة) ۵')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2309, 19, 59, N'تو ان کے بعد ان کی جگہ وہ ناخلف آئے جنہوں نے نمازیں گنوائیں اور اپنی خواہشوں کے پیچھے ہوئے تو عنقریب وہ دوزخ میں غی کا جنگل پائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2310, 19, 60, N'مگر جو تائب ہوئے اور ایمان لائے اور اچھے کام کیے تو یہ لوگ جنت میں جائیں گے اور انہیں کچھ نقصان نہ دیا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2311, 19, 61, N'بسنے کے باغ جن کا وعدہ رحمن نے اپنے بندوں سے غیب میں کیا بیشک اس کا وعدہ آنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2312, 19, 62, N'وہ اس میں کوئی بیکار بات نہ سنیں گے مگر سلام اور انہیں اس میں ان کا رزق ہے صبح و شام')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2313, 19, 63, N'یہ وہ باغ ہے جس کا وارث ہم اپنے بندوں میں سے اسے کریں گے جو پرہیزگار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2314, 19, 64, N'(اور جبریل نے محبوب سے عرض کی (ٖف ۱۰۹) ہم فرشتے نہیں اترتے مگر حضور کے رب کے حکم سے اسی کا ہے جو ہمارے آگے ہے اور جو ہمارے پیچھے اور جو اس کے درمیان ہے اور حضور کا رب بھولنے والا نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2315, 19, 65, N'آسمانوں اور زمین اور جو کچھ ان کے بیچ میں ہے سب کا مالک تو اے پوجو اور اس کی بندگی پر ثابت رہو، کیا اس کے نام کا دوسرا جانتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2316, 19, 66, N'اور آدمی کہتا ہے کیا جب میں مرجاؤں گا تو ضرور عنقریب جِلا کر نکالا جاؤں گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2317, 19, 67, N'اور کیا آدمی کو یاد نہیں کہ ہم نے اس سے پہلے اسے بنایا اور وہ کچھ نہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2318, 19, 68, N'تو تمہارے رب کی قسم ہم انہیں اور شیطانوں سب کو گھیر لائیں گے اور انہیں دوزخ کے آس پاس حاضر کریں گے گھٹنوں کے بل گرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2319, 19, 69, N'پھر ہم ہر گروہ سے نکالیں گے جو ان میں رحمن پر سب سے زیادہ بے باک ہوگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2320, 19, 70, N'پھر ہم خوب جانتے ہیں جو اس آگ میں بھوننے کے زیادہ لائق ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2321, 19, 71, N'اور تم میں کوئی ایسا نہیں جس کا گزر دوزخ پر نہ ہو تمہارے رب کے ذمہ پر یہ ضرور ٹھہری ہوئی بات ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2322, 19, 72, N'پھر ہم ڈر والوں کو بچالیں گے اور ظالموں کو اس میں چھوڑ دیں گے گھٹنوں کے بل گرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2323, 19, 73, N'اور جب ان پر ہماری روشن آیتیں پڑھی جاتی ہیں کافر مسلمانوں سے کہتے ہیں کون سے گروہ کا مکان اچھا اورمجلس بہتر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2324, 19, 74, N'اور ہم نے ان سے پہلے کتنی سنگتیں کھپادیں (قومیں ہلاک کردیں) کہ وہ ان سے بھی سامان اور نمود میں بہتر تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2325, 19, 75, N'تم فرماؤ جو گمراہی میں ہو تو اسے رحمن خوب ڈھیل دے یہاں تک کہ جب وہ دیکھیں وہ چیز جس کا انہیں وعدہ دیا جاتا ہے یا تو عذاب یا قیامت تو اب جان لیں گے کہ کس کا برا درجہ ہے اور کس کی فوج کمزور')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2326, 19, 76, N'او رجنہوں نے ہدایت پائی اللہ انھیں اور ہدایت بڑھائے گا اور باقی رہنے والی نیک باتوں کا تیرے رب کے یہاں سب سے بہتر ثواب اور سب سے بھلا انجام')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2327, 19, 77, N'تو کیا تم نے اسے دیکھا جو ہماری آیتوں سے منکر ہوا اور کہتا ہے مجھے ضرو ر مال و اولاد ملیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2328, 19, 78, N'کیا غیب کو جھانک آیا ہے یا رحمن کے پاس کوئی قرار رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2329, 19, 79, N'ہرگز نہیں اب ہم لکھ رکھیں گے جو وہ کہتا ہے اور اسے خوب لمبا عذاب دیں گے،')
GO
