INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2402, 20, 54, N'تم کھاؤ اور اپنے مویشیوں کو چَراؤ بیشک اس میں نشانیاں ہیں عقل والوں کو،')
