INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2406, 20, 58, N'تو ضرور ہم بھی تمہارے آگے ویسا ہی جادو لائیں گے تو ہم میں اور اپنے میں ایک وعدہ ٹھہرادو جس سے نہ ہم بدلہ لیں نہ تم ہموار جگہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2407, 20, 59, N'موسیٰ نے کہا تمہارا وعدہ میلے کا دن ہے اور یہ کہ لوگ دن چڑھے جمع کیے جائیں')
