INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2416, 20, 68, N'ہم نے فرمایا ڈر نہیں بیشک تو ہی غالب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2417, 20, 69, N'اور ڈال تو دے جو تیرے داہنے ہاتھ میں ہے اور ان کی بناوٹوں کو نگل جائے گا، وہ جو بناکر لائے ہیں وہ تو جادوگر کا فریب ہے، اور جادوگر کا بھلا نہیں ہوتا کہیں آوے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2418, 20, 70, N'تو سب جادوگر سجدے میں گرالیے گئے بولے ہم اس پر ایمان لائے جو ہارون اور موسیٰ کا رب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2419, 20, 71, N'فرعون بولا کیا تم اس پر ایمان لائے قبل اس کے کہ میں تمہیں اجازت دوں، بیشک وہ تمہارا بڑا ہے جس نے تم سب کو جادو سکھایا تو مجھے قسم ہے ضرور میں تمہارے ایک طرف کے ہاتھ اور دوسری طرف کے پاؤں کاٹوں گا اور تمہیں کھجور کے ڈھنڈ (تنے) پر سُولی چڑھاؤں گا، اور ضرور تم جان جاؤ گے کہ ہم میں کس کا عذاب سخت اور دیرپا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2420, 20, 72, N'بولے ہم ہرگز تجھے ترجیح نہ دیں گے ان روشن دلیلوں پر جو ہمارے پاس آئیں ہمیں اپنے پیدا کرنے والے والے کی قسم تو تُو کر چُک جو تجھے کرنا ہے تو اس دنیا ہی کی زندگی میں تو کرے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2421, 20, 73, N'بیشک ہم اپنے رب پر ایمان لائے کہ وہ ہماری خطائیں بخش دے اور وہ جو تو نے ہمیں مجبور کیا جادو پر اور ا لله بہتر ہے اور سب سے زیادہ باقی رہنے والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2422, 20, 74, N'بیشک جو اپنے رب کے حضور مجرم ہوکر آئے تو ضرور اس کے لیے جہنم ہے جس میں نہ مرے نہ جئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2423, 20, 75, N'اور جو اس کے حضور ایمان کے ساتھ آئے کہ اچھے کام کیے ہوں تو انہیں کے درجے اونچے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2424, 20, 76, N'بسنے کے باغ جن کے نیچے نہریں بہیں ہمیشہ ان میں رہیں، اور یہ صلہ ہے اس کا جو پاک ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2425, 20, 77, N'اور بیشک ہم نے موسیٰ کو وحی کی کہ راتوں رات میرے بندوں کو لے چل اور ان کے لیے دریا میں سوکھا راستہ نکال دے تجھے ڈر نہ ہوگا کہ فرعون آلے اور نہ خطرہ')
