INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2426, 20, 78, N'تو ان کے پیچھے فرعون پڑا اپنے لشکر لے کر تو انہیں دریا نے ڈھانپ لیا جیسا ڈھانپ لیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2427, 20, 79, N'اور فرعون نے اپنی قوم کو گمراہ کیا اور راہ نہ دکھائی')
GO
