GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2429, 20, 81, N'کھاؤ جو پاک چیزیں ہم نے تمہیں روزی دیں اور اس میں زیادتی نہ کرو کہ تم پر میرا غضب اترے اور جس پر میرا غضب اترا بیشک وہ گرا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2430, 20, 82, N'اور بیشک میں بہت بخشنے والا ہوں اسے جس نے توبہ کی اور ایمان لایا اور اچھا کام کیا پھر ہدایت پر رہا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2431, 20, 83, N'اور تو نے اپنی قوم سے کیوں جلدی کی اے موسیٰ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2432, 20, 84, N'عرض کی کہ وہ یہ ہیں میرے پیچھے اور اے میرے رب تیری طرف میں جلدی کرکے حاضر ہوا کہ تو راضی ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2433, 20, 85, N'فرمایا، تو ہم نے تیرے آنے کے بعد تیری قوم بلا میں ڈالا اور انہیں سامری نے گمراہ کردیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2434, 20, 86, N'تو موسیٰ اپنی قوم کی طرف پلٹا غصہ میں بھرا افسوس کرتا کہا اے میری قوم کیا تم سے تمہارے رب نے اچھا وعدہ نہ تھا کیا تم پر مدت لمبی گزری یا تم نے چاہا کہ تم پر تمہارے رب کا غضب اترے تو تم نے میرا وعدہ خلاف کیا')
