INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2436, 20, 88, N'تو اس نے ان کے لیے ایک بچھڑا نکالا بے جان کا دھڑ گائے کی طرح بولتا یہ ہے تمہارا معبود اور موسیٰ کا معبود تو بھول گئے')
