INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2443, 20, 95, N'موسیٰ نے کہا اب تیرا کیا حال ہے اے سامری!')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2444, 20, 96, N'بولا میں نے وہ دیکھا جو لوگوں نے نہ دیکھا تو ایک مٹھی بھر لی فرشتے کے نشان سے پھر اسے ڈال دیا اور میرے جی کو یہی بھلا لگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2445, 20, 97, N'کہا تو چلتا بن کہ دنیا کی زندگی میں تیری سزا یہ ہے کہ تو کہے چھو نہ جا اور بیشک تیرے لیے ایک وعدہ کا وقت ہے جو تجھ سے خلاف نہ ہوگا اور اپنے اس معبود کو دیکھ جس کے سامنے تو دن بھر آسن مارے (پوجا کے لیے بیٹھا) رہا قسم ہے ہم ضرور اسے جلائیں گے پھر ریزہ ریزہ کرکے دریا میں بہائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2446, 20, 98, N'تمہارا معبود تو وہی اللہ ہے جس کے سوا کسی کی بندگی نہیں ہر چیز کو اس کا علم محیط ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2447, 20, 99, N'ہم ایسا ہی تمہارے سامنے اگلی خبریں بیان فرماتے ہیں اور ہم نے تم کو اپنے پاس سے ایک ذکر عطا فرمایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2448, 20, 100, N'جو اس سے منہ پھیرے تو بیشک وہ قیامت کے دن ایک بوجھ اٹھائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2449, 20, 101, N'وہ ہمیشہ اس میں رہیں گے اور وہ قیامت کے دن ان کے حق میں کیا ہی بڑا بوجھ ہوگا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2450, 20, 102, N'جس دن صُور پھونکا جائے گا اور ہم اس دن مجرموں کو اٹھائیں گے نیلی آنکھیں')
