INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2451, 20, 103, N'آپس میں چپکے چپکے کہتے ہوں گے کہ تم دنیا میں نہ رہے مگر دس رات')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2452, 20, 104, N'ہم خوب جانتے ہیں جو وہ کہیں گے جبکہ ان میں سب سے بہتر رائے والا کہے گا کہ تم صرف ایک ہی دن رہے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2453, 20, 105, N'اور تم سے پہاڑوں کو پوچھتے ہیں تم فرماؤ انہیں میرا رب ریزہ ریزہ کرکے اڑا دے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2454, 20, 106, N'تو زمین کو پٹ پر (چٹیل میدان) ہموار کر چھوڑے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2455, 20, 107, N'کہ تو اس میں نیچا اونچا کچھ نہ دیکھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2456, 20, 108, N'اس دن پکارنے والے کے پیچھے دوڑیں گے اس میں کجی نہ ہوگی اور سب آوازیں رحمن کے حضو ر پست ہوکر رہ جائیں گی تو تُو نہ سنے گا مگر بہت آہستہ آواز')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2457, 20, 109, N'اس دن کسی کی شفاعت کام نہ دے گی، مگر اس کی جسے رحمن نے اذن دے دیا ہے اور اس کی بات پسند فرمائی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2458, 20, 110, N'وہ جانتا ہے جو کچھ ان کے آگے ہے اور جو کچھ ان کے پیچھے اور ان کا علم اسے نہیں گھیر سکتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2459, 20, 111, N'اور سب منہ جھک جائیں گے اس زندہ قائم رکھنے والے کے حضور اور بیشک نامراد رہا جس نے ظلم کا بوجھ لیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2460, 20, 112, N'اور جو کچھ نیک کام کرے اور ہو مسلمان تو اسے نہ زیادتی کا خوف ہوگا اور نہ نقصان کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2461, 20, 113, N'اور یونہی ہم نے اسے عربی قرآن اتارا اور اس میں طرح طرح سے عذاب کے وعدے دیے کہ کہیں انہیں ڈر ہو یا ان کے دل میں کچھ سوچ پیدا کرے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2462, 20, 114, N'تو سب سے بلند ہے ا لله سچا بادشاہ اور قرآن میں جلدی نہ کرو جب تک اس کی وحی تمہیں پوری نہ ہولے اور عرض کرو کہ اے میرے رب! مجھے علم زیادہ دے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2463, 20, 115, N'اور بیشک ہم نے آدم کو اس سے پہلے ایک تاکیدی حکم دیا تھا تو وہ بھول گیا اور ہم نے اس کا قصد نہ پایا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2464, 20, 116, N'اور جب ہم نے فرشتوں سے فرمایا کہ آدم کو سجدہ کرو تو سب سجدہ میں گرے مگر ابلیس، اس نے نہ مانا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2465, 20, 117, N'تو ہم نے فرمایا، اے آدم! بیشک یہ تیرا اور تیری بی بی کا دشمن ہے تو ایسا نہ ہو کہ وہ تم دونوں کو جنت سے نکال دے پھر تو مشقت میں پڑے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2466, 20, 118, N'بیشک تیرے لیے جنت میں یہ ہے کہ نہ تو بھوکا ہو اور نہ ننگا ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2467, 20, 119, N'اور یہ کہ تجھے نہ اس میں پیاس لگے نہ دھوپ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2468, 20, 120, N'تو شیطان نے اسے وسوسہ دیا بولا، اے آدم! کیا میں تمہیں بتادوں ہمیشہ جینے کا پیڑ اور وہ بادشاہی کہ پرانی نہ پڑے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2469, 20, 121, N'تو ان دونوں نے اس میں سے کھالیا اب ان پر ان کی شرم کی چیزیں ظاہر ہوئیں اور جنت کے پتے اپنے اوپر چپکانے لگے اور آدم سے اپنے رب کے حکم میں لغزش واقع ہوئی تو جو مطلب چاہا تھا اس کی راہ نہ پائی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2470, 20, 122, N'پھر اس کے رب نے چن لیا تو اس پر اپنی رحمت سے رجوع فرمائی اور اپنے قرب خاص کی راہ دکھائی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2471, 20, 123, N'فرمایا تم دونوں مل کر جنت سے اترو تم میں ایک دوسرے کا دشمن ہے، پھر اگر تم سب کو میری طرف سے ہدایت آئے، تو جو میری ہدایت کا پیرو ہو ا وہ نہ بہکے نہ بدبخت ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2472, 20, 124, N'اور جس نے میری یاد سے منہ پھیرا تو بیشک اس کے لیے تنگ زندگانی ہے اور ہم اسے قیامت کے دن اندھا اٹھائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2473, 20, 125, N'کہے گا اے رب میرے! مجھے تو نے کیوں اندھا اٹھایا میں تو انکھیارا (بینا) تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2474, 20, 126, N'فرمائے گا یونہی تیرے پاس ہماری آیتیں آئیں تھیں تو نے انہیں بھلادیا اور ایسے ہی آج تیری کوئی نہ لے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2475, 20, 127, N'اور ہم ایسا ہی بدلہ دیتے ہیں جو حد سے بڑھے اور اپنے رب کی آیتوں پر ایمان نہ لائے، اور بیشک آخرت کا عذاب سب سے سخت تر اور سب سے دیرپا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2476, 20, 128, N'تو کیا انہیں اس سے راہ نہ ملی کہ ہم نے ان سے پہلے کتنی سنگتیں (قومیں) ہلاک کردیں کہ یہ ان کے بسنے کی جگہ چلتے پھرتے ہیں بیشک اس میں نشانیاں ہیں عقل والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2477, 20, 129, N'اور اگر تمہارے رب کی ایک بات نہ گزر چکی ہوتی تو ضرور عذاب انھیں لپٹ جاتا اور اگر نہ ہوتا ایک وعدہ ٹھہرایا ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2478, 20, 130, N'تو ان کی باتوں پر صبر کرو اور اپنے رب کو سراہتے ہوئے اس کی پاکی بولو سورج چمکنے سے پہلے اور اس کے ڈوبنے سے پہلے اور رات کی گھڑیوں میں اس کی پاکی بولو اور دن کے کناروں پر اس امید پر کہ تم راضی ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2479, 20, 131, N'اور اے سننے والے اپنی آنکھیں نہ پھیلا اس کی طرف جو ہم نے کافروں کے جوڑوں کو برتنے کے لیے دی ہے جتنی دنیا کی تازگی کہ ہم انہیں اس کے سبب فتنہ میں ڈالیں اور تیرے رب کا رزق سب سے اچھا اور سب سے دیرپا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2480, 20, 132, N'اور اپنے گھر والوں کو نماز کا حکم دے اور خود اس پر ثابت رہ، کچھ ہم تجھ سے روزی نہیں مانگتے ہم تجھے روزی دیں گے اور انجام کا بھلا پرہیزگاری کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2481, 20, 133, N'اور کافر بولے یہ اپنے رب کے پاس سے کوئی نشانی کیوں نہیں لاتے اور کیا انہیں اس کا بیان نہ آیا جو اگلے صحیفوں میں ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2482, 20, 134, N'اور اگر ہم انہیں کسی عذاب سے ہلاک کردیتے رسول کے آنے سے پہلے تو ضرور کہتے اے ہمارے رب! تو نے ہماری طرف کوئی رسول کیوں نہ بھیجا کہ ہم تیری آیتوں پر چلتے قبل اس کے کہ ذلیل و رسوا ہوتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2483, 20, 135, N'تم فرماؤ سب راہ دیکھ رہے ہیں تو تم بھی راہ دیکھو تو اب جان جاؤ گے کہ کون ہیں سیدھی راہ والے اور کس نے ہدایت پائی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2484, 21, 1, N'لوگوں کا حساب نزدیک اور وہ غفلت میں منہ پھیرے ہیں')
