GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2486, 21, 3, N'ان کے دل کھیل میں پڑے ہیں اور ظالموں نے آپس میں خفیہ مشورت کی کہ یہ کون ہیں ایک تم ہی جیسے آدمی تو ہیں کیا جادو کے پاس جاتے ہو دیکھ بھال کر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2487, 21, 4, N'نبی نے فرمایا میرا رب جانتا ہے آسمانوں اور زمین میں ہر بات کو، اور وہی ہے سنتا جانتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2488, 21, 5, N'بلکہ بولے پریشان خوابیں ہیں بلکہ ان کی گڑھت (گھڑی ہوئی چیز) ہے بلکہ یہ شاعر ہیں تو ہمارے پاس کوئی نشانی لائیں جیسے اگلے بھیجے گئے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2489, 21, 6, N'ان سے پہلے کوئی بستی ایمان نہ لائی جسے ہم نے ہلاک کیا، تو کیا یہ ایمان لائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2490, 21, 7, N'اور ہم نے تم سے پہلے نہ بھیجے مگر مرد جنہیں ہم وحی کرتے تو اے لوگو! علم والوں سے پوچھو اگر تمہیں علم نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2491, 21, 8, N'اور ہم نے انہیں خالی بدن نہ بنایا کہ کھانا نہ کھائیں اور نہ وہ دنیا میں ہمیشہ رہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2492, 21, 9, N'پھر ہم نے اپنا وعدہ انہیں سچا کر دکھایا تو انہیں نجات دی اور جن کو چاہی اور حد سے بڑھنے والوں کو ہلاک کردیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2493, 21, 10, N'بیشک ہم سے تمہاری طرف ایک کتاب اتاری جس میں تمہاری ناموری ہے تو کیا تمہیں عقل نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2494, 21, 11, N'اور کتنی ہی بستیاں ہم نے تباہ کردیں کہ وہ ستمگار تھیں اور ان کے بعد اور قوم پیدا کی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2495, 21, 12, N'تو جب انہوں نے ہمارا عذاب پایا جبھی وہ اس سے بھاگنے لگے')
