INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2496, 21, 13, N'نہ بھاگو اور لوٹ کے جاؤ ان آسائشوں کی طرف جو تم کو دی گئیں تھیں اور اپنے مکانوں کی طرف شاید تم سے پوچھنا ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2497, 21, 14, N'بولے ہائے خرابی ہماری بیشک ہم ظالم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2498, 21, 15, N'تو وہ یہی پکارتے رہے یہاں تک کہ ہم نے انہیں کردیا کاٹے ہوئے بجھے ہوئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2499, 21, 16, N'اور ہم نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے عبث نہ بنائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2500, 21, 17, N'اگر ہم کوئی بہلاوا اختیار کرنا چاہتے تو اپنے پاس سے اختیار کرتے اگر ہمیں کرنا ہوتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2501, 21, 18, N'بلکہ ہم حق کو باطل پر پھینک مارتے ہیں تو وہ اس کا بھیجہ نکال دیتا ہے تو جبھی وہ مٹ کر رہ جاتا ہے اور تمہاری خرابی ہے ان باتوں سے جو بناتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2502, 21, 19, N'اور اسی کے ہیں جتنے آسمانوں اور زمین میں ہیں اور اس کے پاس والے اس کی عبادت سے تکبر نہیں کرتے اور نہ تھکیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2503, 21, 20, N'رات دن اس کی پاکی بولتے ہیں اور سستی نہیں کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2504, 21, 21, N'کیا انہوں نے زمین میں سے کچھ ایسے خدا بنالیے ہیں کہ وہ کچھ پیدا کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2505, 21, 22, N'اگر آسمان و زمین میں اللہ کے سوا اور خدا ہوتے تو ضرور وہ تباہ ہوجاتے تو پاکی ہے اللہ عرش کے مالک کو ان باتوں سے جو یہ بناتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2506, 21, 23, N'اس سے نہیں پوچھا جاتا جو وہ کرے اور ان سب سے سوال ہوگا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2507, 21, 24, N'کیا اللہ کے سوا اور خدا بنا رکھے ہیں، تم فرماؤ اپنی دلیل لاؤ یہ قرآن میرے ساتھ والوں کا ذکر ہے اور مجھ سے اگلوں کا تذکرہ بلکہ ان میں اکثر حق کو نہیں جانتے تو وہ رو گرداں، ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2508, 21, 25, N'اور ہم نے تم سے پہلے کوئی رسول نہ بھیجا مگر یہ کہ ہم اس کی طرف وحی فرماتے کہ میرے سوا کوئی معبود نہیں تو مجھی کو پوجو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2509, 21, 26, N'اور بولے رحمن نے بیٹا اختیار کیا پاک ہے وہ بلکہ بندے ہیں عزت والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2510, 21, 27, N'بات میں اس سے سبقت نہیں کرتے اور وہ اسی کے حکم پر کاربند ہوتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2511, 21, 28, N'وہ جانتا ہے جو ان کے آگے ہے اور جو ان کے پیچھے ہے اور شفاعت نہیں کرتے مگر اس کے لیے جسے وہ پسند فرمائے اور وہ اس کے خوف سے ڈر رہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2512, 21, 29, N'اور ان میں جو کوئی کہے کہ میں اللہ کے سوا معبود ہوں تو اسے ہم جہنم کی جزا دیں گے، ہم ایسی ہی سزا دیتے ہیں ستمگاروں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2513, 21, 30, N'کیا کافروں نے یہ خیال نہ کیا کہ آسمان اور زمین بند تھے تو ہم نے انہیں کھولا اور ہم نے ہر جاندار چیز پانی سے بنائی تو کیا وہ ایمان لائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2514, 21, 31, N'اور زمین میں ہم نے لنگر ڈالے کہ انھیں لے کر نہ کانپے اور ہم نے اس میں کشادہ راہیں رکھیں کہ کہیں وہ راہ پائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2515, 21, 32, N'اور ہم نے آسمان کو چھت بنایا نگاہ رکھی گئی اور وہ اس کی نشانیوں سے روگرداں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2516, 21, 33, N'اور وہی ہے جس نے بنائے رات اور دن اور سورج اور چاند ہر ایک ایک گھیرے میں پیر رہا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2517, 21, 34, N'اور ہم نے تم سے پہلے کسی آدمی کے لیے دنیا میں ہمیشگی نہ بنائی تو کیا اگر تم انتقال فرماؤ تو یہ ہمیشہ رہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2518, 21, 35, N'ہر جان کو موت کا مزہ چکھنا ہے، اور ہم تمہاری آزمائش کرتے ہیں برائی اور بھلائی سے جانچنے کو اور ہماری ہی طرف تمہیں لوٹ کر آنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2519, 21, 36, N'اور جب کافر تمہیں دیکھتے ہیں تو تمہیں نہیں ٹھہراتے مگر ٹھٹھا کیا یہ ہیں وہ جو تمہارے خداؤں کو برا کہتے ہیں اور وہ رحمن ہی کی یاد سے منکر ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2520, 21, 37, N'آدمی جلد باز بنایا گیا، اب میں تمہیں اپنی نشانیاں دکھاؤں گا مجھ سے جلدی نہ کرو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2521, 21, 38, N'اور کہتے ہیں کب ہوگا یہ وعدہ اگر تم سچے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2522, 21, 39, N'کسی طرح جانتے کافر اس وقت کو جب نہ روک سکیں گے اپنے مونہوں سے آگے اور نہ اپنی پیٹھوں سے اور نہ ان کی مدد ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2523, 21, 40, N'بلکہ وہ ان پر اچانک آپڑے گی تو انہیں بے حواس کردے گی پھر نہ وہ اسے پھیرسکیں گے اور نہ انہیں مہلت دی جائے گی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2524, 21, 41, N'اور بیشک تم سے اگلے رسولوں کے ساتھ ٹھٹھا کیا گیا تو مسخرگی کرنے والوں کا ٹھٹھا انہیں کو لے بیٹھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2525, 21, 42, N'تم فرماؤ شبانہ روز تمہاری کون نگہبانی کرتا ہے رحمان سے بلکہ وہ اپنے رب کی یاد سے منہ پھیرے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2526, 21, 43, N'کیا ان کے کچھ خدا ہیں جو ان کو ہم سے بچاتے ہیں وہ اپنی ہی جانوں کو نہیں بچاسکتے اور نہ ہماری طرف سے ان کی یاری ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2527, 21, 44, N'بلکہ ہم نے ان کو اور ان کے باپ دادا کو برتاوا دیا یہاں تک کہ زندگی ان پر دراز ہوئی تو کیا نہیں دیکھتے کہ ہم زمین کو اس کے کناروں سے گھٹاتے آرہے ہیں تو کیا یہ غالب ہوں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2528, 21, 45, N'تم فرماؤ کہ میں تم کو صرف وحی سے ڈراتا ہوں اور بہرے پکارنا نہیں سنتے جب ڈرائے جائیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2529, 21, 46, N'اور اگر انہیں تمہارے رب کے عذاب کی ہوا چھو جائے تو ضرور کہیں گے ہائے خرابی ہماری بیشک ہم ظالم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2530, 21, 47, N'اور ہم عدل کی ترازوئیں رکھیں گے قیامت کے دن تو کسی جان پر کچھ ظلم نہ ہوگا، اور اگر کوئی چیز رائی کے دانہ کے برابر ہو تو ہم اسے لے آئیں گے، اور ہم کافی ہیں حساب کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2531, 21, 48, N'اور بیشک ہم نے موسیٰ اور ہارون کو فیصلہ دیا اور اجالا اور پرہیزگاروں کو نصیحت')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2532, 21, 49, N'وہ جو بے دیکھے اپنے رب سے ڈرتے ہیں اور انہیں قیامت کا اندیشہ لگا ہوا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2533, 21, 50, N'اور یہ ہے برکت والا ذکر کہ ہم نے اتارا تو کیا تم اس کے منکر ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2534, 21, 51, N'اور بیشک ہم نے ابراہیم کو پہلے ہی سے اس کی نیک راہ عطا کردی اور ہم اس سے خبردار تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2535, 21, 52, N'جب اس نے اپنے باپ اور قوم سے کہا یہ مورتیں کیا ہیں جن کے آگے تم آسن مارے (پوجا کے لیے بیٹھے) ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2536, 21, 53, N'بولے ہم نے اپنے دادا کو ان کی پوجا کرتے پایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2537, 21, 54, N'کہا بے شک تم اور تمہارے باپ دادا سب کھلی گمراہی میں ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2538, 21, 55, N'بولے کیا تم ہمارے پاس حق لائے ہو یا یونہی کھیلتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2539, 21, 56, N'کہا بلکہ تمہارا رب وہ ہے جو رب ہے آسمان اور زمین کا جس نے انہیں پیدا کیا، اور میں اس پر گواہوں میں سے ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2540, 21, 57, N'اور مجھے اللہ کی قسم ہے میں تمہارے بتوں کا برا چاہوں گا بعد اس کے کہ تم پھر جاؤ پیٹھ دے کر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2541, 21, 58, N'تو ان سب کو چورا کردیا مگر ایک کو جو ان کا سب سے بڑا تھا کہ شاید وہ اس سے کچھ پوچھیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2542, 21, 59, N'بولے کس نے ہمارے خداؤں کے ساتھ یہ کام کیا بیشک وہ ظالم ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2543, 21, 60, N'ان میں کے کچھ بولے ہم نے ایک جوان کو انہیں برا کہتے سنا جسے ابراہیم کہتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2544, 21, 61, N'بولے تو اسے لوگوں کے سامنے لاؤ شاید وہ گواہی دیں')
