INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2545, 21, 62, N'بولے کیا تم نے ہمارے خداؤں کے ساتھ یہ کام کیا اے ابراہیم')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2546, 21, 63, N'فرمایا بلکہ ان کے اس بڑے نے کیا ہوگا تو ان سے پوچھو اگر بولتے ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2547, 21, 64, N'تو اپنے جی کی طرف پلٹے اور بولے بیشک تمہیں ستمگار ہو')
