INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2548, 21, 65, N'پھر اپنے سروں کے بل اوندھائے گئے کہ تمہیں خوب معلوم ہے یہ بولتے نہیں')
