INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2552, 21, 69, N'ہم نے فرمایا اے آگ ہو جا ٹھنڈی اور سلامتی ابراہیم پر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2553, 21, 70, N'اور انہوں نے اس کا برا چاہا تو ہم نے انہیں سب سے بڑھ کر زیاں کار کردیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2554, 21, 71, N'اور ہم اسے اور لوط کو نجات بخشی اس زمین کی طرف جس میں ہم نے جہاں والوں کے لیے برکت رکھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2555, 21, 72, N'اور ہم نے اسے اسحاق عطا فرمایا اور یعقوب پوتا، اور ہم نے ان سب کو اپنے قرب خاص کا سزاوار کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2556, 21, 73, N'اور ہم نے انہیں امام کیا کہ ہمارے حکم سے بلاتے ہیں اور ہم نے انہیں وحی بھیجی اچھے کام کرنے اور نماز برپا رکھنے اور زکوٰة دینے کی اور وہ ہماری بندگی کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2557, 21, 74, N'اور لوط کو ہم نے حکومت اور علم دیا اور اسے اس بستی سے نجات بخشی جو گندے کام کرتی تھی بیشک وہ برُے لوگ بے حکم تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2558, 21, 75, N'اور ہم نے اسے اپنی رحمت میں داخل کیا، بیشک وہ ہمارے قرب خاص سزاواروں میں ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2559, 21, 76, N'اور نوح کو جب اس سے پہلے اس نے ہمیں پکارا تو ہم نے اس کی دعا قبول کی اور اسے اور اس کے گھر والوں کو بڑی سختی سے نجات دی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2560, 21, 77, N'اور ہم نے ان لوگوں پر اس کو مدد دی جنہوں نے ہماری آیتیں جھٹلائیں، بیشک وہ برے لوگ تھے تو ہم نے ان سب کو ڈبو دیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2561, 21, 78, N'اور داؤد اور سلیمان کو یاد کرو جب کھیتی کا ایک جھگڑا چکاتے تھے، جب رات کو اس میں کچھ لوگوں کی بکریاں چھوٹیں اور ہم ان کے حکم کے وقت حاضر تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2562, 21, 79, N'ہم نے وہ معاملہ سلیمان کو سمجھادیا اور دونوں کو حکومت اور علم عطا کیا اور داؤد کے ساتھ پہاڑ مسخر فرمادیے کہ تسبیح کرتے اور پرندے اور یہ ہمارے کام تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2563, 21, 80, N'اور ہم نے اسے تمہارا ایک پہناوا بنانا سکھایا کہ تمہیں تمہاری آنچ سے (زخمی ہونے سے) بچائے تو کیا تم شکر کروگے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2564, 21, 81, N'اور سلیمان کے لیے تیز ہوا مسخر کردی کہ اس کے حکم سے چلتی اس زمین کی طرف جس میں ہم نے برکت رکھی اور ہم کو ہر چیز معلوم ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2565, 21, 82, N'اور شیطانوں میں سے جو اس کے لیے غوطہ لگاتے اور اس کے سوا اور کام کرتے اور ہم انہیں روکے ہوئے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2566, 21, 83, N'اور ایوب کو (یاد کرو) جب اس نے اپنے رب کو پکارا کہ مجھے تکلیف پہنچی اور تو سب مہر والوں سے بڑھ کر مہر والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2567, 21, 84, N'تو ہم نے اس کی دعا سن لی تو ہم نے دور کردی جو تکلیف اسے تھی اور ہم نے اسے اس کے گھر والے اور ان کے ساتھ اتنے ہی اور عطا کیے اپنے پاس سے رحمت فرما کر اور بندی والوں کے لیے نصیحت')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2568, 21, 85, N'اور اسماعیل اور ادریس اور ذوالکفل کو (یاد کرو)، وہ سب صبر والے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2569, 21, 86, N'اور انہیں ہم نے اپنی رحمت میں داخل کیا، بیشک وہ ہمارے قربِ خاص کے سزاواروں میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2570, 21, 87, N'اور ذوالنون، کو (یاد کرو) جب چلا غصہ میں بھرا تو گمان کیا کہ ہم اس پر تنگی نہ کریں گے تو اندھیریوں میں پکارا کوئی معبود نہیں سوا تیرے پاکی ہے تجھ کو، بیشک مجھ سے بے جا ہوا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2571, 21, 88, N'تو ہم نے اس کی پکار سن لی اور سے غم سے نجات بخشی اور ایسی ہی نجات دیں گے مسلمانوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2572, 21, 89, N'اور زکریا کو جب اس نے اپنے رب کو پکارا، اے میرے رب مجھے اکیلا نہ چھوڑ اور تو سب سے بہتر اور وارث')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2573, 21, 90, N'تو ہم نے اس کی دعا قبول کی اور اسے یحییٰ عطا فرمایا اور اس کے لیے اس کی بی بی سنواری بیشک وہ بھلے کاموں میں جلدی کرتے تھے اور ہمیں پکارتے تھے امید اور خوف سے، اور ہمارے حضور گڑگڑاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2574, 21, 91, N'اور اس عورت کو اس نے اپنی پارسائی نگاہ رکھی تو ہم نے اس میں اپنی روح پھونکی اور اسے اور اس کے بیٹے کو سارے جہاں کے لیے نشانی بنایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2575, 21, 92, N'بیشک تمہارا یہ دین ایک ہی دین ہے اور میں تمہارا رب ہوں تو میری عبادت کرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2576, 21, 93, N'اور اَوروں نے اپنے کام آپس میں ٹکڑے ٹکڑے کرلیے سب کو ہماری طرف پھرنا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2577, 21, 94, N'تو جو کچھ بھلے کام کرے اور ہو ایمان والا تو اس کی کوشش کی بے قدری نہیں، اور ہم اسے لکھ رہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2578, 21, 95, N'اور حرام ہے اس بستی پر جسے ہم نے ہلاک کردیا کہ پھر لوٹ کر آئیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2579, 21, 96, N'یہاں تک کہ جب کھولے جائیں گے یاجوج و ماجوج اور وہ ہر بلندی سے ڈھلکتے ہوں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2580, 21, 97, N'اور قریب آیا سچا وعدہ تو جبھی آنکھیں پھٹ کر رہ جائیں گی کافروں کی کہ ہائے ہماری خرابی بیشک ہم اس سے غفلت میں تھے بلکہ ہم ظالم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2581, 21, 98, N'بیشک تم اور جو کچھ اللہ کے سوا تم پوجتے ہو سب جہنم کے ایندھن ہو، تمہیں اس میں جانا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2582, 21, 99, N'اگر یہ خدا ہوتے جہنم میں نہ جاتے، اور ان سب کو ہمیشہ اس میں رہنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2583, 21, 100, N'وہ اس میں رینکیں گے اور وہ اس میں کچھ نہ سنیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2584, 21, 101, N'بیشک وہ جن کے لیے ہمارا وعدہ بھلائی کا ہوچکا وہ جنہم سے دور رکھے گئے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2585, 21, 102, N'وہ اس کی بھنک (ہلکی سی آواز بھی) نہ سنیں گے اور وہ اپنی من مانتی خواہشوں میں ہمیشہ رہیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2586, 21, 103, N'انہیں غم میں نہ ڈالے گی وہ سب سے بڑی گھبراہٹ اور فرشتے ان کی پیشوائی کو آئیں گے کہ یہ ہے تمہارا وہ دن جس کا تم سے وعدہ تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2587, 21, 104, N'جس دن ہم آسمان کو لپیٹیں گے جیسے سجل فرشتہ نامہٴ اعمال کو لپیٹتا ہے، جیسے پہلے اسے بنایا تھا ویسے ہی پھر کردیں گے یہ وعدہ ہے ہمارے ذمہ، ہم کو اس کا ضرور کرنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2588, 21, 105, N'اور بیشک ہم نے زبور میں نصیحت کے بعد لکھ دیا کہ اس زمین کے وارث میرے نیک بندے ہوں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2589, 21, 106, N'بیشک یہ قرآن کافی ہے عبادت والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2590, 21, 107, N'اور ہم نے تمہیں نہ بھیجا مگر رحمت سارے جہان کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2591, 21, 108, N'تم فرماؤ مجھے تو یہی وحی ہوتی ہے کہ تمہارا خدا نہیں مگر ایک اللہ تو کیا تم مسلمان ہوتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2592, 21, 109, N'پھر اگر وہ منہ پھیریں تو فرمادو میں نے تمہیں لڑائی کا اعلان کردیا، برابری پر اور میں کیا جانوں کہ پاس ہے یا دور ہے وہ جو تمہیں وعدہ دیا جاتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2593, 21, 110, N'بیشک اللہ جانتا ہے آواز کی بات اور جانتا ہے جو تم چھپاتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2594, 21, 111, N'اور میں کیا جانوں شاید وہ تمہاری جانچ ہو اور ایک وقت تک برتوانا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2595, 21, 112, N'نبی نے عرض کی کہ اے میرے رب حق فیصلہ فرمادے اور ہمارے رب رحمنٰ ہی کی مدد درکار ہے ان باتوں پر جو تم بتاتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2596, 22, 1, N'اے لوگو! اپنے رب سے ڈرو بیشک قیامت کا زلزلہ بڑی سخت چیز ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2597, 22, 2, N'جس دن تم اسے دیکھو گے ہر دودھ پلانے والی اپنے دودھ پیتے کو بھول جائے گی اور ہر گابھ اپنا گابھ ڈال دے گی اور تو لوگوں کو دیکھے گا جیسے نشہ میں ہیں اور نشہ میں نہ ہوں گے مگر ہے یہ کہ اللہ کی مار کڑی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2598, 22, 3, N'اور کچھ لوگ وہ ہیں کہ اللہ کے معاملہ میں جھگڑتے ہیں بے جانے بوجھے، اور ہر سرکش شیطان کے پیچھے ہو لیتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2599, 22, 4, N'جس پر لکھ دیا گیا ہے کہ جو اس کی دوستی کرے گا تو یہ ضرور اسے گمراہ کردے گا اور اسے عذاب دوزخ کی راہ بتائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2600, 22, 5, N'اے لوگو! اگر تمہیں قیامت کے دن جینے میں کچھ شک ہو تو یہ غور کرو کہ ہم نے تمہیں پیدا کیا مٹی سے پھر پانی کی بوند سے پھر خون کی پھٹک سے (ف۹۱۲ پھر گوشت کی بوٹی سے نقشہ بنی اور بے بنی تاکہ ہم تمہارے لیے اپنی نشانیاں ظاہر فرمائیں اور ہم ٹھہرائے رکھتے ہیں ماؤں کے پیٹ میں جسے چاہیں ایک مقرر میعاد تک پھر تمہیں نکالتے ہیں بچہ پھر اس لیے کہ تم اپنی جوانی کو پہنچو اور تم میں کوئی پہلے ہی مرجاتا ہے اور کوئی سب میں نکمی عمر تک ڈالا جاتا ہے کہ جاننے کے بعد کچھ نہ جانے اور تو زمین کو دیکھے مرجھائی ہوئی پھر جب ہم نے اس پر پانی اتارا تر و تازہ ہوئی اور ابھر آئی اور ہر رونق دار جوڑا اُگا لائی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2601, 22, 6, N'یہ اس لیے ہے کہ اللہ ہی حق ہے اور یہ کہ وہ مردے جِلائے گا اور یہ کہ وہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2602, 22, 7, N'اور اس لیے کہ قیامت آنے والی اس میں کچھ شک نہیں، اور یہ کہ اللہ اٹھائے گا انہیں جو قبروں میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2603, 22, 8, N'اور کوئی آدمی وہ ہے کہ اللہ کے بارے میں یوں جھگڑتا ہے کہ نہ تو علم نہ کوئی دلیل اور نہ کوئی روشن نوشتہ (تحریر)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2604, 22, 9, N'حق سے اپنی گردن موڑے ہوئے تاکہ اللہ کی راہ سے بہکادے اس کے لیے دنیا میں رسوائی ہے اور قیامت کے دن ہم اسے آگ کا عذاب چکھائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2605, 22, 10, N'یہ اس کا بدلہ ہے جو تیرے ہاتھوں نے آگے بھیجا اور اللہ بندوں پر ظلم نہیں کرتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2606, 22, 11, N'اور کچھ آدمی اللہ کی بندگی ایک کنارہ پر کرتے ہیں پھر اگر انہیں کوئی بھلائی پہنچ گئی جب تو چین سے ہیں اور جب کوئی جانچ آکر پڑی منہ کے بل پلٹ گئے، ف۳۲) دنیا اور آخرت دونوں کا گھاٹا یہی ہے صر یح نقصان')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2607, 22, 12, N'اللہ کے سوا ایسے کو پوجتے ہیں جو ان کا برا بھلا کچھ نہ کرے یہی ہے دور کی گمراہی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2608, 22, 13, N'ایسے کو پوجتے نہیں جس کے نفع سے نقصان کی توقع زیادہ ہے بیشک کیا ہی برا مولیٰ اور بیشک کیا ہی برا رفیق،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2609, 22, 14, N'بیشک اللہ داخل کرے گا انہیں جو ایمان لائے اور بھلے کام کیے باغوں میں جن کے نیچے نہریں رواں، بیشک اللہ کرتا ہے جو چاہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2610, 22, 15, N'جو یہ خیال کرتا ہو کہ اللہ اپنے نبی کی مدد نہ فرمائے گا دنیا اور آخرت میں تو اسے چاہیے کہ اوپر کو ایک رسی تانے پھر اپنے آپ کو پھانسی دے لے پھر دیکھے کہ اس کا یہ داؤں کچھ لے گیا اس بات کو جس کی اسے جلن ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2611, 22, 16, N'اور بات یہی ہے کہ ہم نے یہ قرآن اتارا روشن آیتیں اور یہ کہ اللہ راہ دیتا ہے جسے چاہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2612, 22, 17, N'بیشک مسلمان اور یہودی اور ستارہ پرست اور نصرانی اور آتش پرست اور مشرک، بیشک اللہ ان سب میں قیامت کے دن فیصلہ کردے گا بیشک ہر چیز اللہ کے سامنے ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2613, 22, 18, N'کیا تم نے نہ دیکھا کہ اللہ کے لیے سجدہ کرتے ہیں وہ جو آسمانوں اور زمین میں ہیں اور سورج اور چاند اور تارے اور پہاڑ اور درخت اور چوپائے اور بہت آدمی اور بہت وہ ہیں جن پر عذاب مقرر ہوچکا اور جسے اللہ ذلیل کرے اسے کوئی عزت دینے والا نہیں، بیشک اللہ جو چاہے کرے، (السجدة) ۶')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2614, 22, 19, N'یہ دو فریق ہیں کہ اپنے رب میں جھگڑے تو جو کافر ہوئے ان کے لیے آگ کے کپڑے بیونتے (کاٹے) گئے ہیں اور ان کے سروں پر کھولتا پانی ڈالا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2615, 22, 20, N'جس سے گل جائے گا جو کچھ ان کے پیٹوں میں ہے اور ان کی کھالیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2616, 22, 21, N'اور ان کے لیے لوہے کے گرز ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2617, 22, 22, N'جب گھٹن کے سبب اس میں سے نکلنا چاہیں گے اور پھر اسی میں لوٹا دیے جائیں گے، اور حکم ہوگا کہ چکھو آگ کا عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2618, 22, 23, N'بیشک اللہ داخل کرے گا انہیں جو ایمان لائے اور اچھے کام کیے بہشتوں میں جن کے نیچے نہریں بہیں اس میں پہنائے جائیں گے سونے کے کنگن اور موتی اور وہاں ان کی پوشاک ریشم ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2619, 22, 24, N'اور انہیں پاکیزہ بات کی ہدایت کی گئی اور سب خوبیوں سراہے کی راہ بتائی گئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2620, 22, 25, N'بیشک وہ جنہوں نے کفر کیا اور روکتے ہیں اللہ کی راہ اور اس ادب والی مسجد سے جسے ہم نے سب لوگوں کے لیے مقرر کیا کہ اس میں ایک سا حق ہے وہاں کے رہنے والے اور پردیسی کا، اور جو اس میں کسی زیادتی کا ناحق ارادہ کرے ہم اسے دردناک عذاب چکھائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2621, 22, 26, N'اور جب کہ ہم نے ابراہیم کو اس گھر کا ٹھکانا ٹھیک بتادیا اور حکم دیا کہ میرا کوئی شریک نہ کر اور میرا گھر ستھرا رکھ طواف والوں اور اعتکاف والوں اور رکوع سجدے والوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2622, 22, 27, N'اور لوگوں میں حج کی عام ندا کردے وہ تیرے پاس حاضر ہوں گے پیادہ اور ہر دبلی اونٹنی پر کہ ہر دور کی راہ سے آتی ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2623, 22, 28, N'تاکہ وہ اپنا فائدہ پائیں اور اللہ کا نام لیں جانے ہوئے دنوں میں اس پر کہ انہیں روزی دی بے زبان چوپائے تو ان میں سے خود کھاؤ اور مصیبت زدہ محتاج کو کھلاؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2624, 22, 29, N'پھر اپنا میل کچیل اتاریں اور اپنی منتیں پوری کریں اور اس آزاد گھر کا طواف کریں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2625, 22, 30, N'بات یہ ہے اور جو اللہ کی حرمتوں کی تعظیم کرے تو وہ اس کے لیے اس کے رب کے یہاں بھلا ہے، اور تمہارے لیے حلال کیے گئے بے زبان چوپائے سوا ان کے جن کی ممانعت تم پر پڑھی جاتی ہے تو دور ہو بتوں کی گندگی سے اور بچو جھوٹی بات سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2626, 22, 31, N'ایک اللہ کے ہوکر کہ اس کا ساجھی کسی کو نہ کرو، اور جو اللہ کا شریک کرے وہ گویا گرا آسمان سے کہ پرندے اسے اچک لے جاتے ہیں یا ہوا اسے کسی دور جگہ پھینکتی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2627, 22, 32, N'بات یہ ہے، اور جو اللہ کے نشانوں کی تعظیم کرے تو یہ دلوں کی پرہیزگاری سے ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2628, 22, 33, N'تمہارے لیے چوپایوں میں فائدے ہیں ایک مقررہ میعاد تک پھر ان کا پہنچنا ہے اس آزاد گھر تک')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2629, 22, 34, N'اور ہر امت کے لیے ہم نے ایک قربانی مقرر فرمائی کہ اللہ کا نام لیں اس کے دیے ہوئے بے زبان چوپایوں پر تو تمہارا معبود ایک معبود ہے تو اسی کے حضور گردن رکھو اور اے محبوب خوشی سنادو ان تواضع والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2630, 22, 35, N'کہ جب اللہ کا ذکر ہوتا ہے ان کے دل ڈرنے لگتے ہیں اور جو افتاد پڑے اس کے سنے والے اور نماز برپا رکھنے والے اور ہمارے دیے سے خرچ کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2631, 22, 36, N'اور قربانی کے ڈیل دار جانور اور اونٹ اور گائے ہم نے تمہارے لیے اللہ کی نشانیوں سے کیے تمہارے لیے ان میں بھلائی ہے تو ان پر اللہ کا نام لو ایک پاؤں بندھے تین پاؤں سے کھڑے پھر جب ان کی کروٹیں گرجائیں تو ان میں سے خود کھاؤ اور صبر سے بیٹھنے والے اور بھیک مانگنے والے کو کھلاؤ، ہم نے یونہی ان کو تمہارے بس میں دے دیا کہ تم احسان مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2632, 22, 37, N'اللہ کو ہرگز نہ ان کے گوشت پہنچتے ہیں نہ ان کے خون ہاں تمہاری پرہیزگاری اس تک باریاب ہوتی ہے یونہی ان کو تمہارے پس میں کردیا کہ تم اللہ کی بڑائی بولو اس پر کہ تم کو ہدایت فرمائی، اور اے محبوب! خوشخبری سناؤ نیکی والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2633, 22, 38, N'بیشک اللہ بلائیں ٹالتا ہے، مسلمانوں کی بیشک اللہ دوست نہیں رکھتا ہر بڑے دغا باز ناشکرے کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2634, 22, 39, N'پروانگی (اجازت) عطا ہوئی انہیں جن سے کافر لڑتے ہیں اس بناء پر کہ ان پر ظلم ہوا اور بیشک اللہ ان کی مدد کرنے پر ضرور قادر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2635, 22, 40, N'وہ جو اپنے گھروں سے ناحق نکالے گئے صرف اتنی بات پر کہ انہوں نے کہا ہمارا رب اللہ ہے اور اللہ اگر آدمیوں میں ایک کو دوسرے سے دفع نہ فرماتا تو ضرور ڈھادی جاتیں خانقاہیں اور گرجا اور کلیسے اور مسجدیں جن میں اللہ کا بکثرت نام لیا جاتا ہے، اور بیشک اللہ ضرور مدد فرمائے گا اس کی جو اس کے دین کی مدد کرے گا بیشک ضرور اللہ قدرت والا غالب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2636, 22, 41, N'وہ لوگ کہ اگر ہم انہیں زمین میں قابو دیں تو نماز برپا رکھیں اور زکوٰة اور بھلائی کا حکم کریں اور برائی سے روکیں اور اللہ ہی کے لیے سب کاموں کا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2637, 22, 42, N'اور اگر یہ تمہاری تکذیب کرتے ہیں تو بیشک ان سے پہلے جھٹلا چکی ہے نوح کی قوم اور عاد اور ثمود')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2638, 22, 43, N'اور ابراہیم کی قوم اور لوط کی قوم،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2639, 22, 44, N'اور مدین والے اور موسیٰ کی تکذیب ہوئی تو میں نے کافرو ں کو ڈھیل دی پھر انہیں پکڑا تو کیسا ہوا میرا عذاب')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2640, 22, 45, N'اور کتنی ہی بستیاں ہم نے کھپادیں (ہلاک کردیں) کہ وہ ستمگار تھیں تو اب وہ اپنی چھتوں پر ڈہی (گری) پڑی ہیں اور کتنے کنویں بیکار پڑے اور کتنے محل گچ کیے ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2641, 22, 46, N'تو کیا زمین میں نہ چلے کہ ان کے دل ہوں جن سے سمجھیں یا کان ہوں جن سے سنیں تو یہ کہ آنکھیں اندھی نہیں ہوتیں بلکہ وہ دل اندھے ہوتے ہیں جو سینو ں میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2642, 22, 47, N'اور یہ تم سے عذاب مانگنے میں جلدی کرتے ہیں اور اللہ ہرگز اپنا وعدہ جھوٹا نہ کرے گا اور بیشک تمہارے رب کے یہاں ایک دن ایسا ہے جیسے تم لوگوں کی گنتی میں ہزار برس')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2643, 22, 48, N'اور کتنی بستیاں کہ ہم نے ان کو ڈھیل دی اس حال پر کہ وہ ستمگار تھیں پھر میں نے انہیں پکڑا اور میری ہی طرف پلٹ کر آتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2644, 22, 49, N'تم فرمادو کہ اے لوگو! میں تو یہی تمہارے لیے صریح ڈر سنانے والا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2645, 22, 50, N'تو جو ایمان لائے اور اچھے کام کیے ان کے لیے بخشش ہے اور عزت کی روزی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2646, 22, 51, N'اور وہ جو کوشش کرتے ہیں ہماری آیتوں میں ہار جیت کے ارادہ سے وہ جہنمی ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2647, 22, 52, N'اور ہم نے تم سے پہلے جتنے رسول یا نبی بھیجے سب پر کبھی یہ واقعہ گزرا ہے کہ جب انہوں نے پڑھا تو شیطان نے ان کے پڑھنے میں لوگوں پر کچھ اپنی طرف سے ملادیا تو مٹا دیتا ہے اللہ اس شیطان کے ڈالے ہوئے کو پھر اللہ اپنی آیتیں پکی کردیتا ہے اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2648, 22, 53, N'تاکہ شیطان کے ڈالے ہوئے کو فتنہ کردے ان کے لیے جن کے دلوں میں بیماری ہے اور جن کے دل سخت ہیں اور بیشک ستمگار دُھرکے (پرلے درجے کے) جھگڑالو ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2649, 22, 54, N'اور اس لیے کہ جان لیں وہ جن کو علم ملا ہے کہ وہ تمہارے رب کے پاس سے حق ہے تو اس پر ایمان لائیں تو جھک جائیں اس کے لیے ان کے دل، اور بیشک اللہ ایمان والوں کو سیدھی راہ چلانے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2650, 22, 55, N'اور کافر اس سے ہمیشہ شک میں رہیں گے یہاں تک کہ ان پر قیامت آجائے اچانک یا ان پر ایسے دن کا عذاب آئے جس کا پھل ان کے لیے کچھ اچھا نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2651, 22, 56, N'بادشاہی اس دن اللہ ہی کی ہے، وہ ان میں فیصلہ کردے گا، تو جو ایمان لائے اور اچھے کام کیے وہ چین کے باغوں میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2652, 22, 57, N'اور جنہوں نے کفر کیا اور ہماری آیتیں جھٹلائیں ان کے لیے ذلت کا عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2653, 22, 58, N'اور وہ جنہوں نے اللہ کی راہ میں اپنے گھر بار چھوڑے پھر مارے گئے یا مرگئے تواللہ ضرور انہیں اچھی روزی دے گا اور بیشک اللہ کی روزی سب سے بہتر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2654, 22, 59, N'ضرور انہیں ایسی جگہ لے جائے گا جسے وہ پسند کریں گے اور بیشک اللہ علم اور حلم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2655, 22, 60, N'بات یہ ہے اور جو بدلہ لے جیسی تکلیف پہنچائی گئی تھی پھر اس پر زیادتی کی جائے تو بیشک اللہ اس کی مدد فرمائے گا بیشک اللہ معاف کرنے والا بخشنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2656, 22, 61, N'یہ اس لیے کہ اللہ تعالیٰ رات کو ڈالتا ہے دن کے حصہ میں اور دن کو لاتا ہے رات کے حصہ میں اور اس لیے کہ اللہ سنتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2657, 22, 62, N'یہ اس لیے کہ اللہ ہی حق ہے اور اس کے سوا جسے پوجتے ہیں وہی باطل ہے اور اس لیے کہ اللہ ہی بلندی بڑائی والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2658, 22, 63, N'کیا تو نے نہ دیکھا کہ اللہ نے آسمان سے پانی اتارا تو صبح کو زمین ہریالی ہوگئی، بیشک اللہ پاک خبردار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2659, 22, 64, N'اسی کا مال ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور بیشک اللہ ہی بے نیاز سب خوبیوں سراہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2660, 22, 65, N'کیا تو نے نہ دیکھا کہ اللہ نے تمہارے بس میں کردیا جو کچھ زمین میں ہے اور کشتی کہ دریا میں اس کے حکم سے چلتی ہے اور وہ روکے ہوئے ہے آسمان کو کہ زمین پر نہ گر پڑے مگر اس کے حکم سے، بیشک اللہ آدمیوں پر بڑی مہر والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2661, 22, 66, N'اور وہی ہے جس نے تمہیں زندہ کیا اور پھر تمہیں مارے گا پھر تمہیں جِلائے گا بیشک آدمی بڑا ناشکرا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2662, 22, 67, N'ہر امت کے لیے ہم نے عبادت کے قاعدے بنادیے کہ وہ ان پر چلے تو ہرگز وہ تم سے اس معاملہ میں جھگڑا نہ کریں اور اپنے رب کی طرف بلاؤ بیشک تم سیدھی راہ پر ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2663, 22, 68, N'اور اگر وہ تم سے جھگڑیں تو فرمادو کہ اللہ خوب جانتا ہے تمہارے کوتک (تمہاری کرتوت)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2664, 22, 69, N'اللہ تم پر فیصلہ کردے گا قیامت کے دن جس بات میں اختلاف کرتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2665, 22, 70, N'کیا تو نے نہ جانا کہ اللہ جانتا ہے جو کچھ آسمانوں اور زمین میں ہے، بیشک یہ سب ایک کتاب میں ہے بیشک یہ اللہ پر آسان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2666, 22, 71, N'اور اللہ کے سوا ایسوں کو پوجتے ہیں جن کی کوئی سند اس نے نہ اتاری اور ایسوں کو جن کا خود انہیں کچھ علم نہیں اور ستمگاروں کا کوئی مددگار نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2667, 22, 72, N'اور جب ان پر ہماری روشن آیتیں پڑھی جائیں تو تم ان کے چہروں پر بگڑنے کے آثار دیکھو گے جنہوں نے کفر کیا، قریب ہے کہ لپٹ پڑیں ان کو جو ہماری آیتیں ان پر پڑھتے ہیں، تم فرمادو کیا میں تمہیں بتادوں جو تمہارے اس حال سے بھی بدتر ہے وہ آگ ہے، اللہ نے اس کا وعدہ دیا ہے کافروں کو، اور کیا ہی بری پلٹنے کی جگہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2668, 22, 73, N'اے لوگو! ایک کہاوت فرمائی جاتی ہے اسے کان لگا کر سنو وہ جنہیں اللہ کے سوا تم پوجتے ہو ایک مکھی نہ بناسکیں گے اگرچہ سب اس پر اکٹھے ہوجائیں اور اگر مکھی ان سے کچھ چھین کرلے جائے تو اس سے چھڑا نہ سکیں کتنا کمزور چاہنے والا اور وہ جس کو چاہا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2669, 22, 74, N'اللہ کی قدر نہ جانی جیسی چاہیے تھی بیشک اللہ قوت والا غالب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2670, 22, 75, N'اللہ چن لیتا ہے فرشتوں میں سے رسول اور آدمیوں میں سے بیشک اللہ سنتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2671, 22, 76, N'جانتا ہے جو ان کے آگے ہے اور جو ان کے پیچھے ہے اور سب کاموں کی رجوع اللہ کی طرف ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2672, 22, 77, N'اے ایمان والو! رکوع اور سجدہ کرو اور اپنے رب کی بندگی کرو اور بھلے کام کرو اس امید پر کہ تمہیں چھٹکارا ہو، (السجدة) عندالشافعیؒ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2673, 22, 78, N'اور اللہ کی راہ میں جہاد کرو جیسا حق ہے جہاد کرنے کا اس نے تمہیں پسند کیا اور تم پر دین میں کچھ تنگی نہ رکھی تمہارے باپ ابراہیم کا دین اللہ نے تمہارا نام مسلمان رکھا ہے اگلی کتابوں میں اور اس قرآن میں تاکہ رسول تمہارا نگہبان و گواہ ہو اور تم اور لوگوں پر گواہی دو تو نماز برپا رکھو اور زکوٰة دو اور اللہ کی رسی مضبوط تھام لو وہ تمہارا مولیٰ ہے تو کیا ہی اچھا مولیٰ اور کیا ہی اچھا مددگار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2674, 23, 1, N'بیشک مراد کو پہنچے ایمان والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2675, 23, 2, N'جو اپنی نماز میں گڑگڑاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2676, 23, 3, N'اور وہ جو کسی بیہودہ بات کی طرف التفات نہیں کرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2677, 23, 4, N'اور وہ کہ زکوٰة دینے کا کام کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2678, 23, 5, N'اور وہ جو اپنی شرمگاہوں کی حفاظت کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2679, 23, 6, N'مگر اپنی بیبیوں یا شرعی باندیوں پر جو ان کے ہاتھ کی مِلک ہیں کہ ان پر کوئی ملامت نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2680, 23, 7, N'تو جو ان دو کے سوا کچھ اور چاہے وہی حد سے بڑھنے والے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2681, 23, 8, N'اور وہ جو اپنی امانتوں اور اپنے عہد کی رعایت کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2682, 23, 9, N'اور وہ جو اپنی نمازوں کی نگہبانی کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2683, 23, 10, N'یہی لوگ وارث ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2684, 23, 11, N'کہ فردوس کی میراث پائیں گے، وہ اس میں ہمیشہ رہیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2685, 23, 12, N'اور بیشک ہم نے آدمی کو چنی ہوئی (انتخاب کی) مٹی سے بنایا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2686, 23, 13, N'پھر اسے پانی کی بوند کیا ایک مضبوط ٹھہراؤ میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2687, 23, 14, N'پھر ہم نے اس پانی کی بوند کو خون کی پھٹک کیا پھر خون کی پھٹک کو گوشت کی بوٹی پھر گوشت کی بوٹی کو ہڈیاں پھر ان ہڈیوں پر گوشت پہنایا، پھر اسے اور صورت میں اٹھان دی تو بڑی برکت والا ہے اللہ سب سے بہتر بتانے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2688, 23, 15, N'پھر اس کے بعد تم ضرور مرنے والے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2689, 23, 16, N'پھر تم سب قیامت کے دن اٹھائے جاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2690, 23, 17, N'اور بیشک ہم نے تمہارے اوپر سات راہیں بنائیں اور ہم خلق سے بے خبر نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2691, 23, 18, N'اور ہم نے آسمان سے پانی اتارا ایک اندازہ پر پھر اسے زمین میں ٹھہرایا اور بیشک ہم اس کے لے جانے پر قادر ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2692, 23, 19, N'تو اس سے ہم نے تمہارے باغ پیدا کیے کھجوروں اور انگوروں کے تمہارے لیے ان میں بہت سے میوے ہیں اور ان میں سے کھاتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2693, 23, 20, N'اور وہ پیڑ پیدا کیا کہ طور سینا سے نکلتا ہے لے کر اگتا ہے تیل اور کھانے والوں کے لیے سالن')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2694, 23, 21, N'اور بیشک تمہارے لیے چوپایوں میں سمجھنے کا مقام ہے، ہم تمہیں پلاتے ہیں اس میں سے جو ان کے پیٹ میں ہے اور تمہارے لیے ان میں بہت فائدے ہیں اور ان سے تمہاری خوراک ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2695, 23, 22, N'اور ان پر اور کشتی پر سوار کیے جاتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2696, 23, 23, N'اور بیشک ہم نے نوح کو اس کی قوم کی طرف بھیجا تو اس نے کہا اے میری قوم اللہ کو پوجو اس کے سوا تمہارا کوئی خدا نہیں، تو کیا تمہیں ڈر نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2697, 23, 24, N'تو اس کی قوم کے جن سرداروں نے کفر کیا بولے یہ تو نہیں مگر تم جیسا آدمی چاہتا ہے کہ تمہارا بڑا بنے اور اللہ چاہتا تو فرشتے اتارتا ہم نے تو یہ اگلے باپ داداؤں میں نہ سنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2698, 23, 25, N'وہ تو نہیں مگر ایک دیوانہ مرد تو کچھ زمانہ تک اس کا انتظار کیے رہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2699, 23, 26, N'نوح نے عرض کی اے میرے رب! میری مدد فرما اس پر کہ انہوں نے مجھے جھٹلایا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2700, 23, 27, N'تو ہم نے اسے وحی بھیجی کہ ہماری نگاہ کے سامنے اور ہمارے حکم سے کشتی بنا پھر جب ہمارا حکم آئے اور تنور ابلے تو اس میں بٹھالے ہر جوڑے میں سے دو اور اپنے گھر والے مگر ان میں سے وہ جن پر بات پہلے پڑچکی اور ان ظالموں کے معاملہ میں مجھ سے بات نہ کرنا یہ ضرور ڈبوئے جائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2701, 23, 28, N'پھر جب ٹھیک بیٹھ لے کشتی پر تُو اور تیرے ساتھ والے تو کہہ سب خوبیاں اللہ کو جس نے ہمیں ان ظالموں سے نجات دی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2702, 23, 29, N'اور عرض کر کہ اے میرے رب مجھے برکت والی جگہ اتار اور تو سب سے بہتر اتارنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2703, 23, 30, N'بیشک اس میں ضرو ر نشانیاں اور بیشک ضرور ہم جانچنے والے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2704, 23, 31, N'پھر ان کے بعد ہم نے اور سنگت (قوم) پیدا کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2705, 23, 32, N'تو ان میں ایک رسول انہیں میں سے بھیجا کہ اللہ کی بندگی کرو اس کے سوا تمہارا کوئی خدا نہیں، تو کیا تمہیں ڈر نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2706, 23, 33, N'اور بولے اس قوم کے سردار جنہوں نے کفر کیا اور آخرت کی حاضری کو جھٹلایا اور ہم نے انہیں دنیا کی زندگی میں چین دیا کہ یہ تو نہیں مگر جیسا آدمی جو تم کھاتے ہو اسی میں سے کھاتا ہے اور جو تم پیتے ہو اسی میں سے پیتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2707, 23, 34, N'اور اگر تم کسی اپنے جیسے آدمی کی اطاعت کرو جب تو تم ضرور گھاٹے میں ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2708, 23, 35, N'کیا تمہیں یہ وعدہ دیتا ہے کہ تم جب مرجاؤ گے اور مٹی اور ہڈیاں ہوجاؤ گے اس کے بعد پھر نکالے جاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2709, 23, 36, N'کتنی دور ہے کتنی دور ہے جو تمہیں وعدہ دیا جاتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2710, 23, 37, N'وہ تو نہیں مگر ہماری دنیا کی زندگی کہ ہم مرتے جیتے ہیں اور ہمیں اٹھنا نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2711, 23, 38, N'وہ تو نہیں مگر ایک مرد جس نے اللہ پر جھوٹ باندھا اور ہم اسے ماننے کے نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2712, 23, 39, N'عرض کی کہ اے میرے رب میری مدد فرما اس پر کہ انہوں نے مجھے جھٹلایا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2713, 23, 40, N'اللہ نے فرمایا کچھ دیر جاتی ہے کہ یہ صبح کریں گے پچھتاتے ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2714, 23, 41, N'تو انہیں آلیا سچی چنگھاڑ نے تو ہم نے انہیں گھاس کوڑا کردیا تو دور ہوں ظالم لوگ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2715, 23, 42, N'پھر ان کے بعد ہم نے اور سنگتیں (قومیں) پیدا کیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2716, 23, 43, N'کوئی امت اپنی میعاد سے نہ پہلے جائے نہ پیچھے رہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2717, 23, 44, N'پھر ہم نے اپنے رسول بھیجے ایک پیچے دوسرا جب کسی امت کے پاس اس کا رسول آیا انہوں نے اسے جھٹلایا تو ہم نے اگلوں سے پچھلے ملادیے اور انہیں کہانیاں کر ڈالا تو دور ہوں وہ لوگ کہ ایمان نہیں لاتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2718, 23, 45, N'پھر ہم نے موسیٰ اور اس کے بھائی ہارون کو اپنی آیتوں اور روشن سند کے ساتھ بھیجا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2719, 23, 46, N'فرعون اور اس کے درباریوں کی طرف تو انہوں نے غرور کیا اور وہ لوگ غلبہ پائے ہوئے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2720, 23, 47, N'تو بولے کیا ہم ایمان لے آئیں اپنے جیسے دو آدمیوں پر اور ان کی قوم ہماری بندگی کررہی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2721, 23, 48, N'تو انہوں نے ان دونوں کو جھٹلایا تو ہلاک کیے ہوؤں میں ہوگئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2722, 23, 49, N'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی کہ ان کو ہدایت ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2723, 23, 50, N'اور ہم نے مریم اور اس کے بیٹے کو نشانی کیا اور انہیں ٹھکانا دیا ایک بلند زمین جہاں بسنے کا مقام اور نگاہ کے سامنے بہتا پانی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2724, 23, 51, N'اے پیغمبرو! پاکیزہ چیزیں کھاؤ اور اچھا کام کرو، میں تمہارے کاموں کو جانتا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2725, 23, 52, N'اور بیشک یہ تمہارا دین ایک ہی دین ہے اور میں تمہارا رب ہوں تو مجھ سے ڈرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2726, 23, 53, N'تو ان کی امتوں نے اپنا کام آپس میں ٹکڑے ٹکڑے کرلیا ہر گروہ جو اس کے پاس ہے اس پر خوش ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2727, 23, 54, N'تو تم ان کو چھوڑ دو ان کے نشہ میں ایک وقت تک')
