INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2802, 24, 11, N'تو تمہارا پردہ کھول دیتا بیشک وہ کہ یہ بڑا بہتان لائے ہیں تمہیں میں کی ایک جماعت ہے اسے اپنے لیے برا نہ سمجھو، بلکہ وہ تمہارے لیے بہتر ہے ان میں ہر شخص کے لیے وہ گناہ ہے جو اس نے کمایا اور ان میں وہ جس نے سب سے بڑا حصہ لیا اس کے لیے بڑا عذاب ہے')
