INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2806, 24, 15, N'جب تم ایسی بات اپنی زبانوں پر ایک دوسرے سے سن کر لاتے تھے اور اپنے منہ سے وہ نکالتے تھے جس کا تمہیں علم نہیں اور اسے سہل سمجھتے تھے اور وہ اللہ کے نزدیک بڑی بات ہے')
