INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2811, 24, 20, N'اور اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی اور یہ کہ اللہ تم پر نہایت مہربان مہروالا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2812, 24, 21, N'تو تم اس کا مزہ چکھتے اے ایمان والو! شیطان کے قدموں پر نہ چلو، اور جو شیطان کے قدموں پر چلے تو وہ تو بے حیائی اور بری ہی بات بتائے گا اور اگر اللہ کا فضل اور اس کی رحمت تم پر نہ ہوتی تو تم میں کوئی بھی کبھی ستھرا نہ ہوسکتا ہاں اللہ ستھرا کردیتا ہے جسے چاہے اور اللہ سنتا جانتا ہے،')
GO
