INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2815, 24, 24, N'جس دن ان پر گواہی دیں گے ان کی زبانیں اور ان کے ہاتھ اور ان کے پاؤں جو کچھ کرتے تھے،')
