INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2816, 24, 25, N'اس دن اللہ انہیں ان کی سچی سزا پوری دے گا اور جان لیں گے کہ اللہ ہی صریح حق ہے،')
