INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2817, 24, 26, N'گندیاں گندوں کے لیے اور گندے گندیوں کے لیے اور ستھریاں ستھروں کے لیے اور ستھرے ستھریوں کے لیے وہ پاک ہیں ان باتوں سے جو یہ کہہ رہے ہیں، ان کے لیے بخشش اور عزت کی روزی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2818, 24, 27, N'اے ایمان والو! اپنے گھروں کے سوا اور گھروں میں نہ جاؤ جب تک اجازت نہ لے لو اور ان کے ساکنوں پر سلام نہ کرلو یہ تمہارے لیے بہتر ہے کہ تم دھیان کرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2819, 24, 28, N'پھر اگر ان میں کسی کو نہ پاؤ جب بھی بے ما لکوں کی اجازت کے ان میں نہ جاؤ اور اگر تم سے کہا جائے واپس جاؤ تو واپس ہو یہ تمہارے لیے بہت ستھرا ہے، اللہ تمہارے کاموں کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2820, 24, 29, N'اس میں تم پر کچھ گناہ نہیں کہ ان گھروں میں جاؤ جو خاص کسی کی سکونت کے نہیں اور ان کے برتنے کا تمہیں اختیار ہے، اور اللہ جانتا ہے جوتم ظاہر کرتے ہو، اور جو تم چھپاتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2821, 24, 30, N'مسلمان مردوں کو حکم دو اپنی نگاہیں کچھ نیچی رکھیں اور اپنی شرمگاہوں کی حفاظت کریں یہ ان کے لیے بہت ستھرا ہے، بیشک اللہ کو ان کے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2822, 24, 31, N'اور مسلمان عورتوں کو حکم دو اپنی نگاہیں کچھ نیچی رکھیں اور اپنی پارسائی کی حفاظت کریں اور اپنا بناؤ نہ دکھائیں مگر جتنا خود ہی ظاہر ہے اور وہ دوپٹے اپنے گریبانوں پر ڈالے رہیں، اور اپنا سنگھار ظاہر نہ کریں مگر اپنے شوہروں پر یا اپنے باپ یا شوہروں کے باپ یا اپنے بیٹوں یا شوہروں کے بیٹے یا اپنے بھائی یا اپنے بھتیجے یا اپنے بھانجے یا اپنے دین کی عورتیں یا اپنی کنیزیں جو اپنے ہاتھ کی ملک ہوں یا نوکر بشرطیکہ شہوت والے مرد نہ ہوں یا وہ بچے جنہیں عورتوں کی شرم کی چیزوں کی خبر نہیں اور زمین پر پاؤں زور سے نہ رکھیں کہ جانا جائے ان کا چھپا ہوا سنگھار اور اللہ کی طرف توبہ کرو اے مسلمانو! سب کے سب اس امید پر کہ تم فلاح پاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2823, 24, 32, N'اور نکاح کردو اپنوں میں ان کا جو بے نکاح ہوں اور اپنے لائق بندوں اور کنیزوں کا اگر وہ فقیر ہوں تو اللہ انہیں غنی کردے گا اپنے فضل کے سبب اور اللہ وسعت والا علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2824, 24, 33, N'اور چاہیے کہ بچے رہیں وہ جو نکاح کا مقدور نہیں رکھتے یہاں تک کہ اللہ مقدور والا کردے اپنے فضل سے اور تمہارے ہاتھ کی مِلک باندی غلاموں میں سے جو یہ چاہیں کہ کچھ مال کمانے کی شرط پر انہیں آزادی لکھ دو تو لکھ دو اگر ان میں کچھ بھلائی جانو اور اس پر ان کی مدد کرو اللہ کے مال سے جو تم کو دیا اور مجبور نہ کرو اپنی کنیزوں کو بدکاری پر جب کہ وہ بچنا چاہیں تاکہ تم دنیوی زندگی کا کچھ مال چاہو اور جو انہیں مجبور کرے گا تو بیشک اللہ بعد اس کے کہ وہ مجبوری ہی کی حالت پر رہیں بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2825, 24, 34, N'اور بیشک ہم نے اتاریں تمہاری طرف روشن آیتیں اور کچھ ان لوگوں کا بیان جو تم سے پہلے ہو گزرے اور ڈر والوں کے لیے نصیحت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2826, 24, 35, N'اللہ نور ہے آسمانوں اور زمینوں کا، اس کے نور کی مثال ایسی جیسے ایک طاق کہ اس میں چراغ ہے وہ چراغ ایک فانوس میں ہے وہ فانوس گویا ایک ستارہ ہے موتی سا چمکتا روشن ہوتا ہے برکت والے پیڑ زیتون سے جو نہ پورب کا نہ پچھم کا قریب ہے کہ اس کا تیل بھڑک اٹھے اگرچہ اسے آگ نہ چھوئے نور پر نور ہے اللہ اپنے نور کی راہ بتاتا ہے جسے چاہتا ہے، اور اللہ مثالیں بیان فرماتا ہے لوگوں کے لیے، اور اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2827, 24, 36, N'ان گھروں میں جنہیں بلند کرنے کا اللہ نے حکم دیا ہے اور ان میں اس کا نام لیا جاتا ہے، اللہ کی تسبیح کرتے ہیں ان میں صبح اور شام')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2828, 24, 37, N'وہ مرد جنہیں غافل نہیں کرتا کوئی سودا اور نہ خرید و فروخت اللہ کی یاد اور نماز برپا رکھنے اور زکوٰة دینے سے ڈرتے ہیں اس دن سے جس میں الٹ جائیں گے دل اور آنکھیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2829, 24, 38, N'تاکہ اللہ انہیں بدلہ دے ان کے سب سے بہتر کام کام اور اپنے فضل سے انہیں انعام زیادہ دے، اور اللہ روزی دیتا ہے جسے چاہے بے گنتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2830, 24, 39, N'اور جو کافر ہوئے ان کے کام ایسے ہیں جیسے دھوپ میں چمکتا ریتا کسی جنگل میں کہ پیاسا اسے پانی سمجھے، یہاں تک جب اس کے پاس آیا تو اسے کچھ نہ پایا اور اللہ کو اپنے قریب پایا تو اس نے اس کا حساب پورا بھردیا، اور اللہ جلد حساب کرلیتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2831, 24, 40, N'یا جیسے اندھیریاں کسی کنڈے کے (گہرائی والے) دریا میں اس کے اوپر موج مو ج کے اوپر اور موج اس کے اوپر بادل، اندھیرے ہیں ایک پر ایک جب اپنا ہاتھ نکالے تو سوجھائی دیتا معلوم نہ ہو اور جسے اللہ نور نہ دے اس کے لیے کہیں نور نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2832, 24, 41, N'کیا تم نے نہ دیکھا کہ اللہ کی تسبیح کرتے ہیں جو کوئی آسمانوں اور زمین میں ہیں اور پرندے پر پھیلائے سب نے جان رکھی ہے اپنی نماز اور اپنی تسبیح، اور اللہ ان کے کاموں کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2833, 24, 42, N'اور اللہ ہی کے لیے ہے سلطنت آسمانوں اور زمین کی اور اللہ ہی کی طرف پھر جانا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2834, 24, 43, N'کیا تو نے نہ دیکھا کہ اللہ نرم نرم چلاتا ہے بادل کو پھر انہیں آپس میں مِلاتا ہے پھر انہیں تہہ پر تہہ کردیتا ہے تو تُو دیکھے کہ اس کے بیچ میں سے مینہ نکلتا ہے اور اتارتا ہے آسمان سے اس میں جو برف کے پہاڑ ہیں ان میں سے کچھ اولے پھر ڈالنا ہے انہیں جس پر چاہے اور پھیردیتا ہے انہیں جس سے چاہے قریب ہے کہ اس کی بجلی کی چمک آنکھ لے جائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2835, 24, 44, N'اللہ بدلی کرتا ہے رات اور دن کی بیشک اس میں سمجھنے کا مقام ہے نگاہ والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2836, 24, 45, N'اور اللہ نے زمین پر ہر چلنے والا پانی سے بنایا تو ان میں کوئی اپنے پیٹ پر چلتا ہے اور ان میں کوئی دو پاؤں پر چلتا ہے اور ان میں کوئی چار پاؤں پر چلتا ہے اللہ بناتا ہے جو چاہے، بیشک اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2837, 24, 46, N'بیشک ہم نے اتاریں صاف بیان کرنے والی آیتیں اور اللہ جسے چاہے سیدھی راہ دکھائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2838, 24, 47, N'اور کہتے ہیں ہم ایمان لائے اللہ اور رسول پر اور حکم مانا پھر کچھ ان میں کے اس کے بعد پھر جاتے ہیں اور وہ مسلمان نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2839, 24, 48, N'اور جب بلائے جائیں اللہ اور اس کے رسول کی طرف کہ رسول ان میں فیصلہ فرمائے تو جبھی ان کا ایک فریق منہ پھیر جاتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2840, 24, 49, N'اور اگر ان میں ڈگری ہو (ان کے حق میں فیصلہ ہو) تو اس کی طرف آئیں مانتے ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2841, 24, 50, N'کیا ان کے دلوں میں بیماری ہے یا شک رکھتے ہیں کیا یہ ڈرتے ہیں کہ اللہ و رسول ان پر ظلم کریں گے بلکہ خود ہی ظالم ہیں،')
