INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2842, 24, 51, N'مسلمانوں کی بات تو یہی ہے جب اللہ اور رسول کی طرف بلائے جائیں کہ رسول ان میں فیصلہ فرمائے کہ عرض کریں ہم نے سنا اور حکم مانا او ریہی لوگ مراد کو پہنچے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2843, 24, 52, N'اور جو حکم مانے اللہ اور اس کے رسول کا اور اللہ سے ڈرے اور پرہیزگاری کرے تو یہی لوگ کامیاب ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2844, 24, 53, N'اور انہوں نے اللہ کی قسم کھائی اپنے حلف میں حد کی کوشش سے کہ اگر تم انہیں حکم دو گے تو وہ ضرور جہاد کو نکلیں گے تم فرماؤ قسمیں نہ کھاؤ موافق شرع حکم برداری چاہیے، اللہ جانتا ہے جو تم کرتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2845, 24, 54, N'تم فرماؤ حکم مانو اللہ کا اور حکم مانو رسول کا پھر اگر تم منہ پھیرو تو رسول کے ذمہ وہی ہے جس اس پر لازم کیا گیا اور تم پر وہ ہے جس کا بوجھ تم پر رکھا گیا اور اگر رسول کی فرمانبرداری کرو گے راہ پاؤ گے، اور رسول کے ذمہ نہیں مگر صاف پہنچا دینا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2846, 24, 55, N'اللہ نے وعدہ دیا ان کو جو تم میں سے ایمان لائے اور اچھے کام کیے کہ ضرور انہیں زمین میں خلافت دے گا جیسی ان سے پہلوں کو دی اور ضرور ان کے لیے جمادے گا ان کا وہ دین جو ان کے لیے پسند فرمایا ہے اور ضرور ان کے اگلے خوف کو امن سے بدل دے گا میری عبادت کریں میرا شریک کسی کو نہ ٹھہرائیں، اور جو اس کے بعد ناشکری کرے تو وہی لوگ بے حکم ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2847, 24, 56, N'اور نماز برپا رکھو اور زکوٰة دو اور رسول کی فرمانبرداری کرو اس امید پر کہ تم پر رحم ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2848, 24, 57, N'ہرگز کافروں کو خیال نہ کرنا کہ وہ کہیں ہمارے قابو سے نکل جائیں زمین میں اور ان کا ٹھکانا آ گ ہے، اور ضرور کیا ہی برا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2849, 24, 58, N'اے ایمان والو! چاہیے کہ تم سے اذن لیں تمہارے ہاتھ کے مال غلام اور جو تم میں ابھی جوانی کو نہ پہنچے تین وقت نمازِ صبح سے پہلے اور جب تم اپنے کپڑے اتار رکھتے ہو دوپہر کو اور نماز عشاء کے بعد یہ تین وقت تمہاری شرم کے ہیں ان تین کے بعد کچھ گناہ نہیں تم پر نہ ان پر آمدورفت رکھتے ہیں تمہارے یہاں ایک دوسرے کے پاس اللہ یونہی بیان کرتا ہے تمہارے لیے آیتیں، اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2850, 24, 59, N'اور جب تم میں لڑکے جوانی کو پہنچ جائیں تو وہ بھی اذن مانگیں جیسے ان کے اگلوں نے اذن مانگا، اللہ یونہی بیان فرماتا ہے تم سے اپنی آیتیں، اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2851, 24, 60, N'اور بوڑھی خانہ نشین عورتیں جنہیں نکاح کی آرزو نہیں ان پر کچھ گناہ نہیں کہ اپنے بالائی کپڑے اتار رکھیں جب کہ سنگھار نہ چمکائیں اور ان سے بھی بچنا ان کے لیے اور بہتر ہے، ور اللہ سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2852, 24, 61, N'نہ اندھے پر تنگی اور نہ لنگڑے پر مضائقہ اور نہ بیمار پر روک اور نہ تم میں کسی پر کہ کھاؤ اپنی اولاد کے گھر یا اپنے باپ کے گھر یا اپنی ماں کے گھر یا اپنے بھائیوں کے یہاں یا اپنی بہنوں کے گھر ے یا اپنے چچاؤں کے یہاں یا اپنی پھپیوں کے گھر یا اپنے ماموؤں کے یہاں یا اپنی خالاؤں کے گھر یا جہاں کی کنجیاں تمہارے قبضہ میں ہیں یا اپنے دوست کے یہاں تم پر کوئی الزام نہیں کہ مل کر کھاؤ یا الگ الگ پھر جب کسی گھر میں جاؤ تو اپنوں کو سلام کرو ملتے وقت کی اچھی دعا اللہ کے پاس سے مبارک پاکیزہ، اللہ یونہی بیان فرماتا ہے تم سے آیتیں کہ تمہیں سمجھ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2853, 24, 62, N'ایمان والے تو وہی ہیں جو اللہ اور اس کے رسول پر یقین لائے اور جب رسول کے پاس کسی ایسے کام میں حاضر ہوئے ہوں جس کے لیے جمع کیے گئے ہوں تو نہ جائیں جب تک ان سے اجازت نہ لے لیں وہ جو تم سے اجازت مانگتے ہیں وہی ہیں جو اللہ اور اس کے رسول پر ایمان لاتے ہیں پھر جب وہ تم سے اجازت مانگیں اپنے کسی کام کے لیے تو ان میں جسے تم چاہو اجازت دے دو اور ان کے لیے اللہ سے معافی مانگو بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2854, 24, 63, N'رسول کے پکارنے کو آپس میں ایسا نہ ٹھہرالو جیسا تم میں ایک دوسرے کو پکارتا ہے بیشک اللہ جانتا ہے جو تم میں چپکے نکل جاتے ہیں کسی چیز کی آڑ لے کر تو ڈریں وہ جو رسول کے حکم کے خلاف کرتے ہیں کہ انہیں کوئی فتنہ پہنچے یا ان پر دردناک عذاب پڑے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2855, 24, 64, N'سن لو! بیشک اللہ ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے، بیشک وہ جانتا ہے جس حال پر تم ہو اور اس دن کو جس میں اس کی طرف پھیرے جائیں گے تو وہ انہیں بتادے گا جو کچھ انہوں نے کیا، اور اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2856, 25, 1, N'بڑی برکت والا ہے وہ کہ جس نے اتارا قرآن اپنے بندہ پر جو سارے جہان کو ڈر سنانے والا ہو')
