INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2857, 25, 2, N'وہ جس کے لیے ہے آسمانوں اور زمین کی بادشاہت اور اس نے نہ اختیار فرمایا بچہ اور اس کی سلطنت میں کوئی ساجھی نہیں اس نے ہر چیز پیدا کرکے ٹھیک اندازہ پر رکھی،')
