INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2859, 25, 4, N'اور کافر بولے یہ تو نہیں مگر ایک بہتان جو انہوں نے بنالیا ہے اور اس پر اور لوگوں نے انہیں مدد دی ہے بیشک وہ ظلم اور جھوٹ پر آئے،')
