INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2860, 25, 5, N'اور بولے اگلوں کی کہانیاں ہیں جو انہوں نے لکھ لی ہیں تو وہ ان پر صبح و شام پڑھی جاتی ہیں،')
