INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2862, 25, 7, N'اور بولے اور رسول کو کیا ہوا کھانا کھاتا ہے اور بازاروں میں چلتا ہے (ف۹۱۶ کیوں نہ اتارا گیا ان کے ساتھ کوئی فرشتہ کہ ان کے ساتھ ڈر سناتا')
