INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2863, 25, 8, N'یا غیب سے انہیں کوئی خزانہ مل جاتا یا ان کا کوئی باغ ہوتا جس میں سے کھاتے اور ظالم بولے تم تو پیروی نہیں کرتے مگر ایک ایسے مرد کی جس پر جادو ہوا')
