INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2864, 25, 9, N'اے محبوب دیکھو کیسی کہاوتیں تمہارے لیے بنارہے ہیں تو گمراہ ہوئے کہ اب کوئی راہ نہیں پاتے،')
