INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2865, 25, 10, N'بڑی برکت والا ہے وہ کہ اگر چاہے تو تمہارے لیے بہت بہتر اس سے کردے جنتیں جن کے نیچے نہریں بہیں اور کرے گا تمہارے لیے اونچے اونچے محل،')
