INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2867, 25, 12, N'جب وہ انہیں دور جگہ سے دیکھے گی تو سنیں گے اس کا جوش مارنا اور چنگھاڑنا،')
