INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2868, 25, 13, N'اور جب اس کی کسی تنگ جگہ میں ڈالے جائیں گے زنجیروں میں جکڑے ہوئے تو وہاں موت مانگیں گے')
