INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2872, 25, 17, N'اور جس دن اکٹھا کرے گا انہیں اور جن کوا لله کے سوا پوجتے ہیں پھر ان معبودو ں سے فرمائے گا کیا تم نے گمراہ کردیے یہ میرے بندے یا یہ خود ہی راہ بھولے')
