INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2873, 25, 18, N'وہ عرض کریں گے پاکی ہے تجھ کو ہمیں سزاوار (حق) نہ تھا کہ تیرے سوا کسی اور کو مولیٰ بنائیں لیکن تو نے انہیں اور ان کے باپ داداؤں کو برتنے دیا یہاں تک کہ وہ تیری یاد بھول گئے اور یہ لوگ تھے ہی ہلاک ہونے والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2874, 25, 19, N'تو اب معبودوں نے تمہاری بات جھٹلادی تو اب تم نہ عذاب پھیرسکو نہ اپنی مدد کرسکو اور تم میں جو ظالم ہے ہم اسے بڑا عذاب چکھائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2875, 25, 20, N'اور ہم نے تم سے پہلے جتنے رسول بھیجے سب ایسے ہی تھے کھانا کھاتے اور بازاروں میں چلتے اور ہم نے تم میں ایک کو دوسرے کی جانچ کیا ہے اور اے لوگو! کیا تم صبر کرو گے اور اے محبوب! تمہارا رب دیکھتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2876, 25, 21, N'اور بولے وہ جو ہمارے ملنے کی امید نہیں رکھتے ہم پر فرشتے کیوں نہ اتارے یا ہم اپنے رب کو دیکھتے بیشک اپنے جی میں بہت ہی اونچی کھینچی (سرکشی کی) اور بڑی سرکشی پر آئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2877, 25, 22, N'جس دن فرشتوں کو دیکھیں گے وہ دن مجرموں کی کوئی خوشی کا نہ ہوگا اور کہیں گے الٰہی ہم میں ان میں کوئی آڑ کردے رکی ہوئی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2878, 25, 23, N'اور جو کچھ انہوں نے کام کیے تھے ہم نے قصد فرماکر انہیں باریک باریک غبار، کے بکھرے ہوئے ذرے کردیا کہ روزن کی دھوپ میں نظر آتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2879, 25, 24, N'جنت والوں کا اس دن اچھا ٹھکانا اور حساب کے دوپہر کے بعد اچھی آرام کی جگہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2880, 25, 25, N'اور جس دن پھٹ جائے گا آسمان بادلوں سے اور فرشتے اتارے جائیں گے پوری طرح')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2881, 25, 26, N'اس دن سچی بادشاہی رحمن کی ہے، اور وہ دن کافروں پر سخت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2882, 25, 27, N'اور جس دن ظالم اپنے ہاتھ چبا چبا لے گا کہ ہائے کسی طرح سے میں نے رسول کے ساتھ راہ لی ہوتی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2883, 25, 28, N'وائے خرابی میری ہائے کسی طرح میں نے فلانے کو دوست نہ بنایا ہوتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2884, 25, 29, N'بیشک اس نے مجھے بہکادیا میرے پاس آئی ہوئی نصیحت سے اور شیطان آدمی کو بے مدد چھوڑ دیتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2885, 25, 30, N'اور رسول نے عرض کی کہ اے میرے رب! میری قوم نے اس قرآن کو چھوڑنے کے قابل ٹھہرایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2886, 25, 31, N'اور اسی طرح ہم نے ہر نبی کے لیے دشمن بنادیے تھے مجرم لوگ اور تمہارا رب کافی ہے ہدایت کرنے اور مدد دینے کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2887, 25, 32, N'اور کافر بولے قرآن ان پر ایک ساتھ کیوں نہ اتار دیا ہم نے یونہی بتدریج سے اتارا ہے کہ اس سے تمہارا دل مضبوط کریں اور ہم نے اسے ٹھہر ٹھہر کر پڑھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2888, 25, 33, N'اور وہ کوئی کہاوت تمہارے پاس نہ لائیں گے مگر ہم حق اور اس سے بہتر بیان لے آئیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2889, 25, 34, N'وہ جو جہنم کی طرف ہانکے جائیں گے اپنے منہ کے بل ان کا ٹھکانا سب سے برا اور وہ سب سے گمراہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2890, 25, 35, N'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی اور اس کے بھائی ہارون کو وزیر کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2891, 25, 36, N'تو ہم نے فرمایا تم دونوں جاؤ اس قوم کی طرف جس نے ہماری آیتیں جھٹلائیں پھر ہم نے انہیں تباہ کرکے ہلاک کردیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2892, 25, 37, N'اور نوح کی قوم کو جب انہوں نے رسولوں کو جھٹلایا ہم نے ان کو ڈبو دیا اور انہیں لوگوں کے لیے نشانی کردیا اور ہم نے ظالموں کے لیے دردناک عذاب تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2893, 25, 38, N'اور عاد اور ثمود اور کنوئیں والوں کو اور ان کے بیچ میں بہت سی سنگتیں (قومیں)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2894, 25, 39, N'اور ہم نے سب سے مثالیں بیان فرمائیں اور سب کو تباہ کرکے مٹادیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2895, 25, 40, N'اور ضرور یہ ہو آئے ہیں اس بستی پر جس پر برا برساؤ برسا تھا تو کیا یہ اسے دیکھتے نہ تھے بلکہ انہیں جی اٹھنے کی امید تھی ہی نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2896, 25, 41, N'اور جب تمہیں دیکھتے ہیں تو تمہیں نہیں ٹھہراتے مگر ٹھٹھا کیا یہ ہیں جن کو اللہ نے رسول بناکر بھیجا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2897, 25, 42, N'قریب تھا کہ یہ ہمیں ہمارے خداؤں سے بہکادیں اگر ہم ان پر صبر نہ کرتے اور اب جانا چاہتے ہیں جس دن عذاب دیکھیں گے کہ کون گمراہ تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2898, 25, 43, N'کیا تم نے اسے دیکھا جس نے اپنی جی کی خواہش کو اپنا خدا بنالیا تو کیا تم اس کی نگہبانی کا ذمہ لو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2899, 25, 44, N'یا یہ سمجھتے ہو کہ ان میں بہت کچھ سنتے یا سمجھتے ہیں وہ تو نہیں مگر جیسے چوپائے بلکہ ان سے بھی بدتر گمراہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2900, 25, 45, N'اے محبوب! کیا تم نے اپنے رب کو نہ دیکھا کہ کیسا پھیلا سایہ اور اگر چاہتا تو اسے ٹھہرایا ہوا کردیتا پھر ہم نے سورج کو اس پر دلیل کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2901, 25, 46, N'پھر ہم نے آہستہ آہستہ اسے اپنی طرف سمیٹا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2902, 25, 47, N'اور وہی ہے جس نے رات کو تمہارے لیے پردہ کیا اور نیند کو آرام اور دن بنایا اٹھنے کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2903, 25, 48, N'اور وہی ہے جس نے ہوائیں بھیجیں اپنی رحمت کے آگے مژدہ سنائی ہوئی اور ہم نے آسمان سے پانی اتارا پاک کرنے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2904, 25, 49, N'تاکہ ہم ا سسے زندہ کریں کسی مردہ شہر کو اور اسے پلائیں اپنے بنائے ہوئے بہت سے چوپائے اور آدمیوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2905, 25, 50, N'اور بیشک ہم نے ان میں پانی کے پھیرے رکھے کہ وہ دھیان کریں تو بہت لوگوں نے نہ مانا مگر ناشکری کرنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2906, 25, 51, N'اور ہم چاہتے تو ہر بستی میں ایک ڈر سنانے والا بھیجتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2907, 25, 52, N'تو کافروں کا کہا نہ مان اور اس قرآن سے ان پر جہاد کر بڑا جہاد،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2908, 25, 53, N'اور وہی ہے جس نے ملے ہوئے رواں کیے دو سمندر یہ میٹھا ہے نہایت شیریں اور یہ کھاری ہے نہایت تلخ اور ان کے بیچ میں پردہ رکھا اور روکی ہوئی آڑ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2909, 25, 54, N'اور وہی ہے جس نے پانی سے بنایا آدمی پھر اس کے رشتے اور سسرال مقرر کی اور تمہارا رب قدرت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2910, 25, 55, N'اور اللہ کے سوا ایسوں کو پوجتے ہیں جو ان کا بھلا برا کچھ نہ کریں اور کافر اپنے رب کے مقابل شیطان کو مدد دیتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2911, 25, 56, N'اور ہم نے تمہیں نہ بھیجا مگر خوشی اور ڈر سناتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2912, 25, 57, N'تم فرماؤ میں اس پر تم سے کچھ اجرت نہیں مانگتا مگر جو چاہے کہ اپنے رب کی طرف راہ لے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2913, 25, 58, N'اور بھروسہ کرو اس زندہ پر جو کبھی نہ مرے گا اور اسے سراہتے ہوئے اس کی پاکی بولو اور وہی کافی ہے اپنے بندوں کے گناہوں پر خبردار')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2914, 25, 59, N'جس نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے چھ دن میں بنائے پھر عرش پر استواء فرمایا جیسا کہ اس کی شان کے لائق ہے وہ بڑی مہر والا تو کسی جاننے والے سے اس کی تعریف پوچھ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2915, 25, 60, N'اور جب ان سے کہا جائے رحمن کو سجدہ کرو کہتے ہیں رحمن کیا ہے، کیا ہم سجدہ کرلیں جسے تم کہو اور اس حکم نے انہیں اور بدکنا بڑھایا السجدة ۔۷')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2916, 25, 61, N'بڑی برکت والا ہے وہ جس نے آسمان میں برج بنائے اور ان میں چراغ رکھا اور چمکتا چاند،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2917, 25, 62, N'اور وہی ہے جس نے رات اور دن کی بدلی رکھی اس کے لیے جو دھیان کرنا چاہے یا شکر کا ارادہ کرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2918, 25, 63, N'اور رحمن کے وہ بندے کہ زمین پر آہستہ چلتے ہیں اور جب جاہل ان سے بات کرتے ہیں تو کہتے ہیں بس سلام')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2919, 25, 64, N'اور وہ جو رات کاٹتے ہیں اپنے رب کے لیے سجدے اور قیام میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2920, 25, 65, N'اور وہ جو عرض کرتے ہیں اے ہمارے رب! ہم سے پھیر دے جہنم کا عذاب، بیشک اس کا عذاب گلے کا غل (پھندا) ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2921, 25, 66, N'بیشک وہ بہت ہی بری ٹھہرنے کی جگہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2922, 25, 67, N'اور وہ کہ جب خرچ کرتے ہیں نہ حد سے بڑھیں اور نہ تنگی کریں اور ان دونوں کے بیچ اعتدال پر رہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2923, 25, 68, N'اور وہ جو اللہ کے ساتھ کسی دوسرے معبود کو نہیں پوجتے اور اس جان کو جس کی اللہ نے حرمت رکھی ناحق نہیں مارتے اور بدکاری نہیں کرتے اور جو یہ کام کرے وہ سزا پائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2924, 25, 69, N'بڑھایا جائے گا اس پر عذابِ قیامت کے دن اور ہمیشہ اس میں ذلت سے رہے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2925, 25, 70, N'مگر جو توبہ کرے اور ایمان لائے اور اچھا کام کرے اور اچھا کام کرے تو ایسوں کی برائیوں کو اللہ بھلائیوں سے بدل دے گا اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2926, 25, 71, N'اور جو توبہ کرے اور اچھا کام کرے تو وہ اللہ کی طرف رجوع لایا جیسی چاہیے تھی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2927, 25, 72, N'اور جو جھوٹی گواہی نہیں دیتے اور جب بیہودہ پر گذرتے ہیں اپنی عزت سنبھالے گزر جاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2928, 25, 73, N'اور وہ کہ جب کہ انہیں ان کے رب کی آیتیں یاد د لائی جائیں تو ان پر بہرے اندھے ہوکر نہیں گرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (2929, 25, 74, N'اور وہ جو عرض کرتے ہیں، اے ہمارے رب! ہمیں دے ہماری بیبیوں اور اولاد سے آنکھوں کی ٹھنڈک اور ہمیں پرہیزگاروں کا پیشوا بنا')
GO
