INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3156, 26, 224, N'اور شاعروں کی پیرو ی گمراہ کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3157, 26, 225, N'کیا تم نے نہ دیکھا کہ وہ ہر نالے میں سرگرداں پھرتے ہیں')
