INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3158, 26, 226, N'اور وہ کہتے ہیں جو نہیں کرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3159, 26, 227, N'مگر وہ جو ایمان لائے اور اچھے کام کیے اور بکثرت اللہ کی یاد کی اور بدلہ لیا بعد اس کے کہ ان پر ظلم ہوا اور اب جاننا چاہتے ہیں ظالم کہ کس کروٹ پر پلٹا کھائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3160, 27, 1, N'یہ آیتیں ہیں قرآن اور روشن کتاب کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3161, 27, 2, N'ہدایت اور خوشخبری ایمان والوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3162, 27, 3, N'وہ جو نماز برپا رکھتے ہیں اور زکوٰة دیتے ہیں اور وہ آخرت پر یقین رکھتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3163, 27, 4, N'وہ جو آخرت پر ایمان نہیں لاتے ہم نے ان کے کوتک (برے اعمال) ان کی نگاہ میں بھلے کر دکھائے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3164, 27, 5, N'تو وہ بھٹک رہے ہیں یہ وہ ہیں جن کے لیے برا عذاب ہے اور یہی آخرت میں سب سے بڑھ کر نقصان میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3165, 27, 6, N'اور بیشک تم قرآن سکھائے جاتے اور حکمت والے علم والے کی طرف سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3166, 27, 7, N'جب کہ موسیٰ نے اپنی گھر والی سے کہا مجھے ایک آگ نظر پڑی ہے عنقریب میں تمہارے پاس اس کی کوئی خبر لاتا ہوں یا اس میں سے کوئی چمکتی چنگاری لاؤں گا کہ تم تاپو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3167, 27, 8, N'پھر جب آگ کے پاس آیا ندا کی گئی کہ برکت دیا گیا وہ جو اس آگ کی جلوہ گاہ میں ہے یعنی موسیٰ اور جو اس کے آس پاس میں یعنی فرشتے اور پاکی ہے اللہ کو جو رب ہے سارے جہان کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3168, 27, 9, N'اے موسیٰ بات یہ ہے کہ میں ہی ہوں اللہ عزت والا حکمت والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3169, 27, 10, N'اور اپنا عصا ڈال دے پھر موسیٰ نے اسے دیکھا لہراتا ہوا گویا سانپ ہے پیٹھ پھیر کر چلا اور مڑ کر نہ دیکھا، ہم نے فرمایا اے موسیٰ ڈر نہیں، بیشک میرے حضور رسولوں کو خوف نہیں ہوتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3170, 27, 11, N'ہاں جو کوئی ز یادتی کرے پھر برائی کے بعد بھلائی سے بدلے تو بیشک میں بخشنے والا مہربان ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3171, 27, 12, N'اور اپنا ہاتھ اپنے گریبان میں ڈال نکلے گا سفید چمکتا بے عیب نو نشانیوں میں فرعون اور اس کی قوم کی طرف، بیشک وہ بے حکم لوگ ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3172, 27, 13, N'پھر جب ہماری نشانیاں آنکھیں کھولتی ان کے پاس آئیں بولے یہ تو صریح جادو ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3173, 27, 14, N'اور ان کے منکر ہوئے اور ان کے دلوں میں ان کا یقین تھا ظلم اور تکبر سے تو دیکھو کیسا انجام ہوا فسادیوں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3174, 27, 15, N'اور بیشک ہم نے داؤد اور سلیمان کو بڑا علم عطا فرمایا اور دونوں نے کہا سب خوبیاں اللہ کو جس نے ہمیں اپنے بہت سے ایمان والے بندوں پر فضیلت بخشی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3175, 27, 16, N'اور سلیمان داؤد کا جانشین ہوا اور کہا اے لوگو! ہمیں پرندوں کی بولی سکھائی گئی اور ہر چیز میں سے ہم کو عطا ہوا بیشک یہی ظاہر فضل ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3176, 27, 17, N'اور جمع کیے گئے سلیمان کے لیے اس کے لشکر جنوں اور آدمیوں اور پرندوں سے تو وہ روکے جاتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3177, 27, 18, N'یہاں تک کہ جب چیونٹیوں کے نالے پر آئے ایک چیونٹی بولی اے چیونٹیو! اپنے گھروں میں چلی جاؤ تمہیں کچل نہ ڈالیں سلیمان اور ان کے لشکر بے خبری میں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3178, 27, 19, N'تو اس کی بات مسکرا کر ہنسا اور عرض کی اے میرے رب! مجھے توفیق دے کہ میں شکر کروں تیرے احسان کا جو تو نے مجھ پر اور میرے ماں باپ پر کیے اور یہ کہ میں وہ بھلا کام کرو ں جو تجھے پسند آئے اور مجھے اپنی رحمت سے اپنے ان بندوں میں شامل کر جو تیرے قرب خاص کے سزاوار ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3179, 27, 20, N'اور پرندوں کا جائزہ لیا تو بولا مجھے کیا ہوا کہ میں ہد ہد کو نہیں دیکھتا یا وہ واقعی حاضر نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3180, 27, 21, N'ضرور میں اسے سخت عذاب کرو ں گا یا ذبح کردوں گا یا کوئی روشن سند میرے پاس لائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3181, 27, 22, N'تو ہد ہد کچھ زیادہ دیر نہ ٹھہرا اور آکر عرض کی کہ میں وہ بات دیکھ کر آیا ہوں جو حضور نے نہ دیکھی اور میں شہر سبا سے حضور کے پاس ایک یقینی خبر لایا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3182, 27, 23, N'میں نے ایک عورت دیکھی کہ ان پر بادشاہی کررہی ہے اور اسے ہر چیز میں سے ملا ہے اور اس کا بڑا تخت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3183, 27, 24, N'میں نے اسے اور اس کی قوم کو پایا کہ اللہ کو چھوڑ کر سورج کو سجدہ کرتے ہیں اور شیطان نے ان کے اعمانل ان کی نگاہ میں سنوار کر ان کو سیدھی راہ سے روک دیا تو وہ راہ نہیں پاتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3184, 27, 25, N'کیوں نہیں سجدہ کرتے اللہ کو جو نکالتا ہے آسمانوں اور زمین کی چھپی چیزیں اور جانتا ہے جو کچھ تم چھپاتے ہو اور ظاہر کرتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3185, 27, 26, N'اللہ ہے کہ اس کے سوا کوئی سچا معبود نہیں وہ بڑے عرش کا مالک ہے، السجد ة۔۸)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3186, 27, 27, N'سلیمان نے فرمایا اب ہم دیکھیں گے کہ تو نے سچ کہا یا تو جھوٹوں میں ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3187, 27, 28, N'میرا یہ فرمان لے جان کر ان پر ڈال پھر ان سے الگ ہٹ کر دیکھ کہ وہ کیا جواب دیتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3188, 27, 29, N'وہ عورت بولی اے سردارو! بیشک میری طرف ایک عزت والا خط ڈالا گیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3189, 27, 30, N'بیشک وہ سلیمان کی طرف سے ہے اور بیشک وہ اللہ کے نام سے ہے نہایت مہربان رحم والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3190, 27, 31, N'یہ کہ مجھ پر بلندی نہ چاہو اور گردن رکھتے میرے حضور حاضر ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3191, 27, 32, N'بولی اے سردارو! میرے اس معاملے میں مجھے رائے دو میں کسی معاملے میں کوئی قطعی فیصلہ نہیں کرتی جب تک تم میرے پاس حاضر نہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3192, 27, 33, N'وہ بولے ہم زور والے اور بڑی سخت لڑائی والے ہیں اور اختیار تیرا ہے تو نظر کر کہ کیا حکم دیتی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3193, 27, 34, N'بولی بیشک بادشاہ جب کسی بستی میں داخل ہوتے ہیں اسے تباہ کردیتے ہیں اور اس کے عزت والوں کو ذلیل اور ایسا ہی کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3194, 27, 35, N'اور میں ان کی طرف ایک تحفہ بھیجنے والی ہوں پھر دیکھوں گی کہ ایلچی کیا جواب لے کر پلٹے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3195, 27, 36, N'پھر جب وہ سلیمان کے پاس آیا فرمایا کیا مال سے میری مدد کرتے ہو تو جو مجھے اللہ نے دیا وہ بہتر ہے اس سے جو تمہیں دیا بلکہ تمہیں اپنے تحفہ پر خوش ہوتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3196, 27, 37, N'پلٹ جا ان کی طرف تو ضرور ہم ان پر وہ لشکر لائیں گے جن کی انہیں طاقت نہ ہوگی اور ضرور ہم ان کو اس شہر سے ذلیل کرکے نکال دیں گے یوں کہ وہ پست ہوں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3197, 27, 38, N'سلیمان نے فرمایا، اے درباریو! تم میں کون ہے کہ وہ اس کا تخت میرے پاس لے آئے قبل اس کے کہ وہ میرے حضور مطیع ہوکر حاضر ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3198, 27, 39, N'ایک بڑا خبیث جن بولا کہ میں وہ تخت حضور میں حاضر کردوں گا قبل اس کے کہ حضور اجلاس برخاست کریں اور میں بیشک اس پر قوت والا امانتدار ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3199, 27, 40, N'اس نے عرض کی جس کے پاس کتاب کا علم تھا کہ میں اسے حضور میں حاضر کردوں گا ایک پل مارنے سے پہلے پھر جب سلیمان نے تخت کو اپنے پاس رکھا دیکھا کہ یہ میرے رب کے فضل سے ہے، تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا ناشکری، اور جو شکر کرے وہ اپنے بھلے کو شکر کرتا ہے اور جو ناشکری کرے تو میرا رب بے پرواہ ہے سب خوبیوں والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3200, 27, 41, N'سلیمان نے حکم دیا عورت کا تخت اس کے سامنے وضع بدل کر بیگانہ کردو کہ ہم دیکھیں کہ وہ راہ پاتی ہے یا ان میں ہوتی ہے جو ناواقف رہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3201, 27, 42, N'پھر جب وہ آئی اس سے کہا گیا کیا تیرا تخت ایسا ہی ہے، بولی گویا یہ وہی ہے اور ہم کو اس واقعہ سے پہلے خبر مل چکی اور ہم فرمانبردار ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3202, 27, 43, N'اور اسے روکا اس چیز نے جسے وہ اللہ کے سوا پوجتی تھی، بیشک وہ کافر لوگوں میں سے تھی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3203, 27, 44, N'اس سے کہا گیا صحن میں آ پھر جب اس نے اسے دیکھا گہرا پانی سمجھی اور اپنی ساقیں کھولیں سلیمان نے فرمایا یہ تو ایک چکنا صحن ہے شیشوں جڑا عورت نے عرض کی اے میرے رب! میں نے اپنی جان پر ظلم کیا اور اب سلیمانے کے ساتھ اللہ کے حضور گردن رکھتی ہوں جو رب سارے جہان کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3204, 27, 45, N'اور بیشک ہم نے ثمود کی طرف ان کے ہم قوم صالح کو بھیجا کہ اللہ کو پوجو تو جبھی وہ دو گروہ ہوگئے جھگڑا کرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3205, 27, 46, N'صا لح نے فرمایا اے میری قوم! کیوں برائی کی جلدی کرتے ہو بھلائی سے پہلے اللہ سے بخشش کیوں نہیں مانگتے شاید تم پر رحم ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3206, 27, 47, N'بولے ہم نے برُا شگون کیا تم سے اور تمہارے ساتھیوں سے فرمایا تمہاری بدشگونی اللہ کے پاس ہے بلکہ تم لوگ فتنے میں پڑے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3207, 27, 48, N'اور شہر میں نو شخص تھے کہ زمین میں فساد کرتے اور سنوار نہ چاہتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3208, 27, 49, N'آپس میں اللہ کی قسمیں کھا کر بولے ہم ضرور رات کو چھاپا ماریں گے صا لح اور اس کے گھر والوں پر پھر اس کے وارث سے کہیں گے اس گھر والوں کے قتل کے وقت ہم حاضر نہ تھے اور بیشک ہم سچے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3209, 27, 50, N'او رانہوں نے اپنا سا مکر کیا اور ہم نے اپنی خفیہ تدبیر فرمائی اور وہ غافل رہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3210, 27, 51, N'تو دیکھو کیسا انجام ہوا ان کے مکر کا ہم نے ہلاک کردیا انہیں اور ان کی ساری قوم کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3211, 27, 52, N'تو یہ ہیں ان کے گھر ڈھے پڑے بدلہ ان کے ظلم کا، بیشک اس میں نشانی ہے جاننے والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3212, 27, 53, N'اور ہم نے ان کو بچالیا جو ایمان لائے اور ڈرتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3213, 27, 54, N'اور لوط کو جب اس نے اپنی قوم سے کہا کیا بے حیائی پر آتے ہو اور تم سوجھ رہے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3214, 27, 55, N'کیا تم مردوں کے پاس مستی سے جاتے ہو عورتیں چھوڑ کر بلکہ تم جاہل لوگ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3215, 27, 56, N'تو اس کی قوم کا کچھ جواب نہ تھا مگر یہ کہ بولے لوط کے گھرانے کو اپنی بستی سے نکال دو یہ لوگ تو ستھراپن چاہتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3216, 27, 57, N'تو ہم نے اسے اور اس کے گھر والوں کو نجات دی مگر اس کی عورت کو ہم نے ٹھہرادیا تھا کہ وہ رہ جانے والوں میں ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3217, 27, 58, N'اور ہم نے ان پر ایک برساؤ برسایا تو کیا ہی برا برساؤ تھا ڈرا ئے ہوؤں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3218, 27, 59, N'تم کہو سب خوبیاں اللہ کو اور سلام اس کے چنے ہوئے بندے پر کیا اللہ بہتر یا ان کے ساختہ شریک')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3219, 27, 60, N'ا وہ جس نے آسمان و زمین بنائے اور تمہارے لیے آسمان سے پانی اتارا تو ہم نے اس سے باغ اگائے رونق والے تمہاری طاقت نہ تھی کہ ان کے پیڑ اگاتے کیا اللہ کے ساتھ کوئی اور خدا ہے بلکہ وہ لوگ راہ سے کتراتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3220, 27, 61, N'یا وہ جس نے زمین بسنے کو بنائی اور اس کے بیچ میں نہریں نکالیں اور اس کے لیے لنگر بنائے اور دونوں سمندروں میں آڑ رکھی کیا اللہ کے ساتھ اور خدا ہے، بلکہ ان میں اکثر جاہل ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3221, 27, 62, N'یا وہ جو لاچار کی سنتا ہے جب اسے پکارے اور دور کردیتا ہے برائی اور تمہیں زمین کا وارث کرتا ہے کیا اللہ کے ساتھ اور خدا ہے، بہت ہی کم دھیان کرتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3222, 27, 63, N'یا وہ جو تمہیں راہ دکھاتا ہے اندھیریوں میں خشکی اور تری کی اور وہ کہ ہوائیں بھیجتا ہے، اپنی رحمت کے آگے خوشحبری سناتی کیا اللہ کے ساتھ کوئی اور خدا ہے، برتر ہے اللہ ان کے شرک سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3223, 27, 64, N'یا وہ جو خلق کی ابتداء فرماتا ہے پھر اسے دوبارہ بنائے گا اور وہ جو تمہیں آسمانوں اور زمین سے روزی دیتا ہے کیا اللہ کے ساتھ کوئی اور خدا ہے، تم فرماؤ کہ اپنی دلیل لاؤ اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3224, 27, 65, N'تم فرماؤ غیب نہیں جانتے جو کوئی آسمانوں اور زمین میں ہیں مگر اللہ اور انہیں خبر نہیں کہ کب اٹھا ےٴ جائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3225, 27, 66, N'کیا ان کے علم کا سلسلہ آخرت کے جانے تک پہو نچ گیا کوئی نہیں وہ اس کی طرف سے شک میں ہیں بلکہ وہ اس سے اندھے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3226, 27, 67, N'اور کافر بولے کیا جب ہم اور ہمارے باپ دادا مٹی ہوجائیں گے کیا ہم پھر نکالے جائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3227, 27, 68, N'بیشک اس کا وعدہ دیا گیا ہم کو اور ہم سے پہلے ہمارے باپ داداؤں کو یہ تو نہیں مگر اگلوں کی کہانیاں،')
GO
