INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3267, 28, 15, N'اور اس شہر میں داخل ہوا جس وقت شہر والے دوپہر کے خواب میں بے خبر تھے تو اس میں دو مرد لڑتے پائے، ایک موسیٰ، کے گروہ سے تھا اور دوسرا اس کے دشمنوں سے تو وہ جو اس کے گروہ سے تھا اس نے موسیٰ سے مدد مانگی، اس پر جو اس کے دشمنوں سے تھا، تو موسیٰ نے اس کے گھونسا مارا تو اس کا کام تما م کردیا کہا یہ کام شیطان کی طرف سے ہوا بیشک وہ دشمن ہے کھلا گمراہ کرنے والا،')
