INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3270, 28, 18, N'تو صبح کی، اس شہر میں ڈرتے ہوئے اس انتظار میں کہ کیا ہوتا ہے جبھی دیکھا کہ وہ جس نے کل ان سے مدد چاہی تھی فریاد کررہا ہے موسیٰ نے اس سے فرمایا بیشک تو کھلا گمراہ ہے')
