INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3271, 28, 19, N'تو جب موسیٰ نے چاہا کہ اس پر گرفت کرے جو ان دونوں کا دشمن ہے وہ بولا اے موسیٰ کیا تم مجھے ویسا ہی قتل کرنا چاہتے ہو جیسا تم نے کل ایک شخص کو قتل کردیا، تم تو یہی چاہتے ہو کہ زمین میں سخت گیر بنو اور اصلاح کرنا نہیں چاہتے')
