INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3272, 28, 20, N'اور شہر کے پرلے کنارے سے ایک شخص دوڑ تا آیا، کہا اے موسیٰ! بیشک دربار والے آپ کے قتل کا مشورہ کررہے ہیں تو نکل جایے میں آپ کا خیر خواہ ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3273, 28, 21, N'تو اس شہر سے نکلا ڈرتا ہوا اس انتظار میں کہ اب کیا ہوتا ہے عرض کی، اے میرے رب! مجھے ستمگاروں سے بچالے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3274, 28, 22, N'اور جب مدین کی طرف متوجہ ہوا کہا قریب ہے کہ میرا رب مجھے سیدھی راہ بتائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3275, 28, 23, N'اور جب مدین کے پانی پر آیا وہاں لوگوں کے ایک گروہ کو دیکھا کہ اپنے جانوروں کو پانی پلارہے ہیں، اور ان سے اس طرف دو عورتیں دیکھیں کہ اپنے جانوروں کو روک رہی ہیں موسیٰ نے فرمایا تم دونوں کا کیا حال ہے وہ بولیں ہم پانی نہیں پلاتے جب تک سب چرواہے پلاکر پھیر نہ لے جائیں اور ہمارے باپ بہت بوڑھے ہیں')
