GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3277, 28, 25, N'تو ان دونوں میں سے ایک اس کے پاس آئی شرم سے چلتی ہوئی بولی میرا باپ تمہیں بلاتا ہے کہ تمہیں مزدوری دے اس کی جو تم نے ہمارے جانوروں کو پانی پلایا ہے جب موسیٰ اس کے پاس آیا اور اسے باتیں کہہ سنائیں اس نے کہا ڈریے نہیں، آپ بچ گئے ظالموں سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3278, 28, 26, N'ان میں کی ایک بولی اے میرے باپ! ان کو نوکر رکھ لو بیشک بہتر نوکر وہ جو طاقتور اور امانتدار ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3279, 28, 27, N'کہا میں چاہتا ہوں کہ اپنی دونوں بیٹیوں میں سے ایک تمہیں بیاہ دوں اس مہر پر کہ تم آٹھ برس میری ملازمت کرو پھر اگر پورے دس برس کرلو تو تمہاری طرف سے ہے اور میں تمہیں مشقت میں ڈالنا نہیں چاہتا قریب ہے انشاء اللہ تم مجھے نیکوں میں پاؤ گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3280, 28, 28, N'موسیٰ نے کہا یہ میرے اور آپ کے درمیان اقرار ہوچکا، میں ان دونوں میں جو میعاد پوری کردوں تو مجھ پر کوئی مطالبہ نہیں، اور ہمارے اس کہے پر اللہ کا ذمہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3281, 28, 29, N'پھر جب موسیٰ نے اپنی میعاد پوری کردی اور اپنی بی بی کو لے کر چلا طُور کی طرف سے ایک آگ دیکھی اپنی گھر والی سے کہا تم ٹھہرو مجھے طُور کی طرف سے ایک آگ نظر پڑی ہے شاید میں وہاں سے کچھ خبر لاؤ ں یا تمہارے لیے کوئی آ گ کی چنگاری لاؤں کہ تم تاپو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3282, 28, 30, N'پھر جب آگ کے پاس حاضر ہوا ندا کی گئی میدان کے دہنے کنارے سے برکت والے مقام میں پیڑ سے کہ اے موسیٰ! بیشک میں ہی ہوں اللہ رب سارے جہان کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3283, 28, 31, N'اور یہ کہ ڈال دے اپنا عصا پھر جب موسیٰ نے اسے دیکھا لہراتا ہوا گویا سانپ ہے پیٹھ پھیر کر چلا اور مڑ کر نہ دیکھا اے موسیٰ سامنے آ اور ڈر نہیں، بیشک تجھے امان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3284, 28, 32, N'اپنا ہاتھ گریبان میں ڈال نکلے گا سفید چمکتا بے عیب اور اپنا ہاتھ سینے پر رکھ لے خوف دور کرنے کو تو یہ دو حُجتیں ہیں تیرے رب کی فرعون اور اس کے درباریوں کی طرف، بیشک وہ بے حکم لوگ ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3285, 28, 33, N'عرض کی اے میرے رب! میں نے ان میں ایک جان مار ڈالی ہے تو ڈرتا ہوں کہ مجھے قتل کردیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3286, 28, 34, N'اور میرا بھائی ہارون اس کی زبان مجھ سے زیادہ صاف ہے تو اسے میری مدد کے لیے رسول بنا، کہ میری تصدیق کرے مجھے ڈر ہے کہ وہ مجھے جھٹلائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3287, 28, 35, N'فرمایا، قریب ہے کہ ہم تیرے بازو کو تیرے بھائی سے قوت دیں گے اور تم دونوں کو غلبہ عطا فرمائیں گے تو وہ تم دونوں کا کچھ نقصان نہ کرسکیں گے، ہماری نشانیوں کے سبب تم دونوں اور جو تمہاری پیروی کریں گے غالب آؤ گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3288, 28, 36, N'پھر جب موسیٰ ان کے پاس ہماری روشن نشانیاں لایا بولے یہ تو نہیں مگر بناوٹ کا جادو اور ہم نے اپنے اگلے باپ داداؤں میں ایسا نہ سنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3289, 28, 37, N'اور موسیٰ نے فرمایا میرا رب خوب جانتا ہے جو اس کے پاس سے ہدایت لایا اور جس کے لیے آخرت کا گھر ہوگا بیشک ظالم مراد کو نہیں پہنچتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3290, 28, 38, N'اور فرعون بولا، اے درباریو! میں تمہارے لیے اپنے سوا کوئی خدا نہیں جانتا تو اے ہامان! میرے لیے گارا پکا کر ایک محل بنا کہ شاید میں موسیٰ کے خدا کو جھانک آؤں اور بیشک میرے گمان میں تو وہ جھوٹا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3291, 28, 39, N'اور اس نے اور اس کے لشکریوں نے زمین میں بے جا بڑائی چاہی اور سمجھے کہ انہیں ہماری طرف پھرنا نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3292, 28, 40, N'تو ہم نے اسے اور اس کے لشکر کو پکڑ کر دریا میں پھینک دیا تو دیکھو کیسا انجام ہوا ستمگاروں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3293, 28, 41, N'اور انہیں ہم نے دوزخیوں کا پیشوا بنایا کہ آگ کی طرف بلاتے ہیں اور قیامت کے دن ان کی مدد نہ ہوگی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3294, 28, 42, N'اور اس دنیا میں ہم نے ان کے پیچھے لعنت لگائی اور قیامت کے دن ان کا برا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3295, 28, 43, N'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی بعد اس کے کہ اگلی سنگتیں (قومیں) ہلاک فرمادیں جس میں لوگوں کے دل کی آنکھیں کھولنے والی باتیں اور ہدایت اور رحمت تاکہ وہ نصیحت مانیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3296, 28, 44, N'اور تم طور کی جانت مغرب میں نہ تھے جبکہ ہم نے موسیٰ کو رسالت کا حکم بھیجا اور اس وقت تم حاضر نہ تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3297, 28, 45, N'مگر ہوا یہ کہ ہم نے سنگتیں پیدا کیں کہ ان پر زمانہ دراز گزرا اور نہ تم اہلِ مدین میں مقیم تھے ان پر ہماری آیتیں پڑھتے ہوئے، ہاں ہم رسول بنانے والے ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3298, 28, 46, N'اور نہ تم طور کے کنارے تھے جب ہم نے ندا فرمائی ہاں تمہارے رب کی مہر ہے (کہ تمہیں غیب کے علم دیے) کہ تم ایسی قوم کو ڈر سناؤ جس کے پاس تم سے پہلے کوئی ڈر سنانے والا نہ آیا یہ امید کرتے ہوئے کہ ان کو نصیحت ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3299, 28, 47, N'اور اگر نہ ہوتا کہ کبھی پہنچتی انہیں کوئی مصیبت اس کے سبب جو ان کے ہاتھوں نے آگے بھیجا تو کہتے، اے ہمارے رب! تو نے کیوں نہ بھیجا ہماری طرف کوئی رسول کہ ہم تیری آیتوں کی پیروی کرتے اور ایمان لاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3300, 28, 48, N'پھر جب ان کے پاس حق آیا ہماری طرف سے بولے انہیں کیوں نہ دیا گیا جو موسیٰ کو دیا گیا کیا اس کے منکر نہ ہوئے تھے جو پہلے موسیٰ کو دیا گیا بولے دو جادو ہیں ایک دوسرے کی پشتی (امداد) پر، اور بولے ہم ان دونوں کے منکر ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3301, 28, 49, N'تم فرماؤ تو اللہ کے پاس سے کوئی کتاب لے آؤ جو ان دونوں کتابوں سے زیادہ ہدایت کی ہو میں اس کی پیروی کروں گا اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3302, 28, 50, N'پھر اگر وہ یہ تمہارا فرمانا قبول نہ کریں تو جان لو کہ بس وہ اپنی خواہشو ں ہی کے پیچھے ہیں، اور اس سے بڑھ کر گمراہ کون جو اپنی خواہش کی پیروی کرے اللہ کی ہدایت سے جدا، بیشک اللہ ہدایت ہیں فرماتا ظالم لوگوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3303, 28, 51, N'اور بیشک ہم نے ان کے لیے بات مسلسل اتاری کہ وہ دھیان کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3304, 28, 52, N'جن کو ہم نے اس سے پہلے کتاب دی وہ اس پر ایمان لاتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3305, 28, 53, N'اور جب ان پر یہ آیتیں پڑھی جاتی ہیں کہتے ہیں ہم اس پر ایمان لائے، بیشک یہی حق ہے ہمارے رب کے پا س سے ہم اس سے پہلے ہی گردن رکھ چکے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3306, 28, 54, N'ان کو ان کا اجر دوبالا دیا جائے گا بدلہ ان کے صبر کا اور وہ بھلائی سے برائی کو ٹالتے ہیں اور ہمارے دیے سے کچھ ہماری راہ میں خرچ کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3307, 28, 55, N'اور جب بیہودہ بات سنتے ہیں اس سے تغافل کرتے ہیں اور کہتے ہیں ہمارے لیے ہمارے عمل اور تمہارے لیے تمہارے عمل، بس تم پر سلام ہم جاہلوں کے غرضی (چاہنے والے) نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3308, 28, 56, N'بیشک یہ نہیں کہ تم جسے اپنی طرف سے چاہو ہدایت کردو ہاں اللہ ہدایت فرماتا ہے جسے چاہے، اور وہ خوب جانتا ہے ہدایت والوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3309, 28, 57, N'اور کہتے ہیں اگر ہم تمہارے ساتھ ہدایت کی پیروی کریں تو لوگ ہمارے ملک سے ہمیں اچک لے جائیں گے کیا ہم نے انہیں جگہ نہ دی امان والی حرم میں جس کی طرف ہر چیز کے پھل لائے جاتے ہیں ہمارے پاس کی روزی لیکن ان میں اکثر کو علم نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3310, 28, 58, N'اور کتنے شہر ہم نے ہلاک کردیے جو اپنے عیش پر اترا گئے تھے تو یہ ہیں ان کے مکان کہ ان کے بعد ان میں سکونت نہ ہوئی مگر کم اور ہمیں وارث ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3311, 28, 59, N'اور تمہارا رب شہروں کو ہلاک نہیں کرتا جب تک ان کے اصل مرجع میں رسول نہ بھیجے جو ان پر ہماری آیتیں پڑھے اور ہم شہروں کو ہلاک نہیں کرتے مگر جبکہ ان کے ساکن ستمگار ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3312, 28, 60, N'اور جو کچھ چیز تمہیں دی گئی ہے اور دنیوی زندگی کا برتاوا اور اس کا سنگھارہے اور جواللہ کے پاس ہے اور وہ بہتر اور زیادہ باقی رہنے والا تو کیا تمہیں عقل نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3313, 28, 61, N'تو کیا وہ جسے ہم نے اچھا وعدہ دیا تو وہ اس سے ملے گا اس جیسا ہے جسے ہم نے دنیوی زندگی کا برتاؤ برتنے دیا پھر وہ قیامت کے دن گرفتار کرکے حاضر لایا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3314, 28, 62, N'اور جس دن انہیں ندا کرے گا تو فرمائے گا کہاں ہیں میرے وہ شریک جنہیں تم گمان کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3315, 28, 63, N'کہیں گے وہ جن پر بات ثابت ہوچکی اے ہمارے رب یہ ہیں وہ جنہیں ہم نے گمراہ کیا، ہم نے انہیں گمراہ کیا جیسے خود گمراہ ہوئے تھے ہم ان سے بیزار ہوکر تیری طرف رجوع لاتے ہیں وہ ہم کو نہ پوجتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3316, 28, 64, N'اور ان سے فرمایا جائے گا اپنے شریکوں کو پکارو تو وہ پکاریں گے تو وہ ان کی نہ سنیں گے اور دیکھیں گے عذاب، کیا اچھا ہوتا اگر وہ راہ پاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3317, 28, 65, N'اور جس دن انہیں ندا کرتے گا تو فرمائے گا تم نے رسولوں کو کیا جواب دیا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3318, 28, 66, N'تو اس دن ان پر خبریں اندھی ہوجائیں گی تو وہ کچھ پوجھ گچھ نہ کریں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3319, 28, 67, N'تو وہ جس نے توبہ کی اور ایمان لایا اور اچھا کام کیا قریب ہے کہ وہ راہ یاب ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3320, 28, 68, N'اور تمہارا رب پیدا کرتا ہے جو چاہے اور پسند فرماتا ہے ان کا کچھ اختیار نہیں، پاکی اور برتری ہے اللہ کو ان کے شرک سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3321, 28, 69, N'اور تمہارا رب جانتا ہے جو ان کے سینوں میں چھپا ہے اور جو ظاہر کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3322, 28, 70, N'اور وہی ہے اللہ کہ کوئی خدا نہیں اس کے سوا اسی کی تعریف ہے دنیا اور آخرت میں اور اسی کا حکم ہے اور اسی کی طرف پھر جاؤ گے،')
GO
