INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3371, 29, 31, N'اور جب ہمارے فرشتے ابراہیم کے پاس مژدہ لے کر آئے بولے ہم ضرور اس شہر والوں کو ہلاک کریں گے بیشک اس کے بسنے والے ستمگاروں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3372, 29, 32, N'کہا اس میں تو لوط ہے فرشتے بولے ہمیں خوب معلوم ہے جو کوئی اس میں ہے، ضرور ہم اسے اور اس کے گھر والوں کو نجات دیں گے مگر اس کی عورت کو، وہ رہ جانے والوں میں ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3373, 29, 33, N'اور جب ہمارے فرشتے لوط کے پاس آئے ان کا آنا اسے ناگوار ہوا اور ان کے سبب دل تنگ ہوا اور انہوں نے کہا نہ ڈریے اور نہ غم کیجئے بیشک ہم آپ کو اور آپ کے گھر والوں کو نجات دیں گے مگر آپ کی عورت وہ رہ جانے والوں میں ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3374, 29, 34, N'بیشک ہم اس شہر والوں پر آسمان سے عذاب اتارنے والے ہیں بدلہ ان کی نافرمانیوں کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3375, 29, 35, N'اور بیشک ہم نے اس سے روشن نشانی باقی رکھی عقل والوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3376, 29, 36, N'مدین کی طرف ان کے ہم قوم شعیب کو بھیجا تو اس نے فرمایا، اے میری قوم! اللہ کی بندگی کرو اور پچھلے دن کی امید رکھو اور زمین میں فساد پھیلاتے نہ پھرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3377, 29, 37, N'تو انہوں نے اسے جھٹلایا تو انہیں زلزلے نے آلیا تو صبح اپنے گھروں میں گھٹنوں کے بل پڑے رہ گئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3378, 29, 38, N'اور عاد اور ثمود کو ہلاک فرمایا اور تمہیں ان کی بستیاں معلوم ہوچکی ہیں اور شیطان نے ان کے کوتک ان کی نگاہ میں بھلے کر دکھائے اور انہیں راہ سے روکا اور انہیں سوجھتا تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3379, 29, 39, N'اور قارون اور فرعون اور ہامان کو اور بیشک ان کے پاس موسیٰ روشن نشانیاں لے کر آیا تو انہوں نے زمین میں تکبر کیا اور وہ ہم سے نکل کر جانے والے نہ تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3380, 29, 40, N'تو ان میں ہر ایک کو ہم نے اس کے گناہ پر پکڑا تو ان میں کسی پر ہم نے پتھراؤ بھیجا اور ان میں کسی کو چنگھاڑ نے آلیا اور ان میں کسی کو زمین میں دھنسادیا اور ان میں کسی کو ڈبو دیا اور اللہ کی شان نہ تھی کہ ان پر ظلم کرے ہاں وہ خود ہی اپنی جانوں پر ظلم کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3381, 29, 41, N'ان کی مثال جنہوں نے اللہ کے سوا اور مالک بنالیے ہیں مکڑی کی طرح ہے، اس نے جالے کا گھر بنایا اور بیشک سب گھروں میں کمزور گھر مکڑی کا گھر کیا اچھا ہوتا اگر جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3382, 29, 42, N'اللہ جانتا ہے جس چیز کی اس کے سوا پوجا کرتے ہیں اور وہی عزت و حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3383, 29, 43, N'اور یہ مثالیں ہم لوگوں کے لیے بیان فرماتے ہیں، اور انہیں نہیں سمجھتے مگر علم والے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3384, 29, 44, N'اللہ نے آسمان اور زمین حق بنائے، بیشک اس میں نشانی ہے مسلمانوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3385, 29, 45, N'اے محبوب! پڑھو جو کتاب تمہاری طرف وحی کی گئی اور نماز قائم فرماؤ، بیشک نماز منع کرتی ہے بے حیائی اور بری بات سے اور بیشک اللہ کا ذکر سب سے بڑا اور اللہ جانتا ہے جو تم کرتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3386, 29, 46, N'اور اے مسلمانو! کتابیوں سے نہ جھگڑو مگر بہتر طریقہ پر مگر وہ جنہوں نے ان میں سے ظلم کیا اور کہو ہم ایمان لائے اس پر جو ہماری طرف اترا اور جو تمہاری طرف اترا اور ہمارا تمہارا ایک معبود ہے اور ہم اس کے حضور گردن رکھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3387, 29, 47, N'اور اے محبوب! یونہی تمہاری طرف کتاب اتاری تو وہ جنہیں ہم نے کتا ب عطا فرمائی اس پر ایمان لاتے ہیں، اور کچھ ان میں سے ہیں جو اس پر ایمان لاتے ہیں، اور ہماری آیتوں سے منکر نہیں ہوتے مگر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3388, 29, 48, N'اور اس سے پہلے تم کوئی کتاب نہ پڑھتے تھے اور نہ اپنے ہاتھ سے کچھ لکھتے تھے یوں ہوتا تو باطل ضرور شک لاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3389, 29, 49, N'بلکہ وہ روشن آیتیں ہیں ان کے سینوں میں جن کو علم دیا گیا اور ہماری آیتوں کا انکار نہیں کرتے مگر ظالم')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3390, 29, 50, N'اور بولے کیوں نہ اتریں کچھ نشانیاں ان پر ان کے رب کی طرف سے تم فرماؤ نشانیاں تو اللہ ہی کے پاس ہیں اور میں تو یہی صاف ڈر سنانے والا ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3391, 29, 51, N'اور کیا یہ انہیں بس نہیں کہ ہم نے تم پر کتاب اتاری جو ان پر پڑھی جاتی ہے بیشک اس میں رحمت اور نصیحت ہے ایمان والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3392, 29, 52, N'تم فرماؤ اللہ بس ہے میرے اور تمہارے درمیان گواہ جانتا ہے جو کچھ آسمانوں اور زمین میں ہے، اور وہ جو باطل پر یقین لائے اور اللہ کے منکر ہوئے وہی گھاٹے میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3393, 29, 53, N'اور تم سے عذاب کی جلدی کرتے ہیں اور اگر ایک ٹھہرائی مدت نہ ہوتی تو ضرور ان پر عذاب آجاتا اور ضرور ان پر اچانک آئے گا جب وہ بے خبر ہوں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3394, 29, 54, N'تم سے عذاب کی جلدی مچاتے ہیں، اور بیشک جہنم گھیرے ہوئے ہے کافروں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3395, 29, 55, N'جس دن انہیں ڈھانپے گا عذاب ان کے اوپر اور ان کے پاؤں کے نیچے سے اور فرمائے گا چکھو اپنے کیے کا مزہ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3396, 29, 56, N'اے میرے بندو! جو ایمان لائے بیشک میری زمین وسیع ہے تو میری ہی بندگی کرو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3397, 29, 57, N'ہر جان کو موت کا مز ہ چکھنا ہے پھر ہماری ہی طرف پھروگے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3398, 29, 58, N'اور بیشک جو ایمان لائے اور اچھے کام کیے ضرور ہم انہیں جنت کے بالا خانوں پر جگہ دیں گے جن کے نیچے نہریں بہتی ہوں گی ہمیشہ ان میں رہیں گے، کیا ہی اچھا اجر کام والوں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3399, 29, 59, N'وہ جنہوں نے صبر کیا اور اپنے رب ہی پر بھروسہ رکھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3400, 29, 60, N'اور زمین پر کتنے ہی چلنے والے ہیں کہ اپنی روزی ساتھ نہیں رکھتے اللہ روزی دیتا ہے انہیں اور تمہیں اور وہی سنتا جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3401, 29, 61, N'اور اگر تم ان سے پوچھو کس نے بنائے آسمان اور زمین اور کام میں لگائے سورج اور چاند تو ضرور کہیں گے اللہ نے، تو کہاں اوندھے جاتے ہیں')
