INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3402, 29, 62, N'اللہ کشادہ کرتا ہے رزق اپنے بندوں میں جس کے لیے چاہے اور تنگی فرماتا ہے جس کے لیے چاہے، بیشک اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3403, 29, 63, N'اور جو تم ان سے پوچھو کس نے اتارا آسمان سے پانی تو اس کے سبب زمین زندہ کردی مَرے پیچھے ضرور کہیں گے اللہ نے تم فرماؤ سب خوبیاں اللہ کو، بلکہ ان میں اکثر بے عقل ہیں')
