INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3404, 29, 64, N'اور یہ دنیا کی زندگی تو نہیں مگر کھیل کود اور بیشک آخرت کا گھر ضرور وہی سچی زندگی ہے کیا اچھا تھا اگر جانتے')
