INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3405, 29, 65, N'پھر جب کشتی میں سوار ہوتے ہیں اللہ کو پکارتے ہیں ایک اسی عقیدہ لاکر پھر جب وہ انہیں خشکی کی طرف بچا لاتا ہے جبھی شرک کرنے لگتے ہیں')
