INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3406, 29, 66, N'کہ ناشکری کریں ہماری دی ہوئی نعمت کی اور برتیں۔ تو اب جانا چاہتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3407, 29, 67, N'اور کیا انہوں نے یہ نہ دیکھا کہ ہم نے حرمت والی زمین پناہ بنائی اور ان کے آس پاس والے لوگ اچک لیے جاتے ہیں تو کیا باطل پر یقین لاتے ہیں اور اللہ کی دی ہوئی نعمت سے ناشکری کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3408, 29, 68, N'اور اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے یا حق کو جھٹلائے جب وہ اس کے پاس آئے، کیا جہنم میں کافروں کا ٹھکانا نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3409, 29, 69, N'اور جنہوں نے ہماری راہ میں کوشش کی ضرور ہم انہیں اپنے راستے دکھادیں گے اور بیشک اللہ نیکوں کے ساتھ ہے')
GO
