INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3413, 30, 4, N'چند برس میں حکم اللہ ہی کا ہے آگے اور پیچھے اور اس دن ایمان والے خوش ہوں گے،')
