INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3414, 30, 5, N'اللہ کی مدد سے مدد کرتا ہے جس کی چاہے، اور وہی عزت والا مہربان،')
