INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3415, 30, 6, N'اللہ کا وعدہ اللہ اپنا وعدہ خلاف نہیں کرتا لیکن بہت لوگ نہیں جانتے')
