INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3416, 30, 7, N'جانتے ہیں آنکھوں کے سامنے کی دنیوی زندگی اور وہ آخرت سے پورے بے خبر ہیں،')
