INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3417, 30, 8, N'کیا انہوں نے اپنے جی میں نہ سوچا کہ، اللہ نے پیدا نہ کیے آسمان اور زمین اور جو کچھ ان کے درمیان ہے مگر حق اور ایک مقرر میعاد سے اور بیشک بہت سے لوگ اپنے رب سے ملنے کا انکار رکھتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3418, 30, 9, N'اور کیا انہوں نے زمین میں سفر نہ کیا کہ دیکھتے کہ ان سے اگلوں کا انجام کیسا ہوا وہ ان سے زیادہ زور آور تھے اور زمین جوتی اور آباد کی ان کی آبادی سے زیادہ اور ان کے رسول ان کے پاس روشن نشانیاں لائے تو اللہ کی شان نہ تھی کہ ان پر ظلم کرتا ہاں وہ خود ہی اپنی جانوں پر ظلم کرتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3419, 30, 10, N'پھر جنہوں نے حد بھر کی برائی کی ان کا انجام یہ ہوا کہ اللہ کی آیتیں جھٹلانے لگے اور ان کے ساتھ تمسخر کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3420, 30, 11, N'اللہ پہلے بناتا ہے پھر دوبارہ بنائے گا پھر اس کی طرف پھروگے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3421, 30, 12, N'اور جس دن قیامت قائم ہوگی مجرموں کی آس ٹوٹ جائے گی')
