INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3422, 30, 13, N'اور ان کے شریک ان کے سفارشی نہ ہوں گے اور وہ اپنے شریکوں سے منکر ہوجائیں گے،')
GO
