INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3478, 31, 9, N'ہمیشہ ان میں رہیں گے، اللہ کا وعدہ ہے سچا، اور وہی عزت و حکمت والا ہے،')
