INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3479, 31, 10, N'اس نے آسمان بنائے بے ایسے ستونوں کے جو تمہیں نظر آئیں اور زمین میں ڈالے لنگر کہ تمہیں لے کر نہ کانپے اور اس میں ہر قسم کے جانور پھیلائے، اور ہم نے آسمان سے پانی اتارا تو زمین میں ہر نفیس جوڑا اگایا')
