INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3481, 31, 12, N'اور بیشک ہم نے لقمان کو حکمت عطا فرمائی کہ اللہ کا شکر کر اور جو شکر کرے وہ اپنے بھلے کو شکر کرتا ہے اور جو ناشکری کرے تو بیشک اللہ بے پرواہ ہے سب خوبیاں سراہا،')
