INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3489, 31, 20, N'کیا تم نے نہ دیکھا کہ اللہ نے تمہارے لیے کام میں لگائے جو کچھ آسمانوں اور زمین میں ہیں اور تمہیں بھرپور دیں اپنی نعمتیں ظاہر اور چھپی اور بعضے آدمی اللہ کے بارے میں جھگڑتے ہیں یوں کہ نہ علم نہ عقل نہ کوئی روشن کتاب')
