INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3490, 31, 21, N'اور جب ان سے کہا جائے اس کی پیروی کرو جو اللہ نے اتارا تو کہتے ہیں بلکہ ہم تو اس کی پیروی کریں گے جس پر ہم نے اپنے باپ دادا کوپایا کیا اگرچہ شیطان ان کو عذاب دوزخ کی طرف بلاتا ہو')
