INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3498, 31, 29, N'اے سننے والے کیا تو نے نہ دیکھا کہ اللہ رات لاتا ہے دن کے حصے میں اور دن کرتا ہے رات کے حصے میں اور اس نے سورج اور چاند کام میں لگائے ہر ایک ایک مقرر میعاد تک چلتا ہے اور یہ کہ اللہ تمہارے کاموں سے خبردار ہے،')
