INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3523, 32, 20, N'رہے وہ جو بے حکم ہیں ان کا ٹھکانا آ گ ہے، جب کبھی اس میں سے نکلنا چاہیں گے پھر اسی میں پھیر دیے جائیں گے اور ان سے کہا جائے گا چکھو اس آگ کا عذاب جسے تم جھٹلاتے تھے،')
