INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3524, 32, 21, N'اور ضرور ہم انہیں چکھائیں گے کچھ نزدیک کا عذاب اس بڑے عذاب سے پہلے جسے دیکھنے والا امید کرے کہ ابھی باز آئیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3525, 32, 22, N'اور اس سے بڑھ کر ظالم کون جسے اس کے رب کی آیتوں سے نصیحت کی گئی پھر اس نے ان سے منہ پھیر لیا بیشک ہم مجرموں سے بدلہ لینے والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3526, 32, 23, N'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی تو تم اس کے ملنے میں شک نہ کرو اور ہم نے اسے بنی اسرائیل کے لیے ہدایت کیا،')
