INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3527, 32, 24, N'اور ہم نے ان میں سے کچھ امام بنائے کہ ہمارے حکم سے بناتے جبکہ انہوں نے صبر کیا اور وہ ہماری آیتوں پر یقین لاتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3528, 32, 25, N'بیشک تمہارا رب ان میں فیصلہ کردے گا قیامت کے دن جس بات میں اختلاف کرتے تھے')
