INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3529, 32, 26, N'اور کیا انہیں اس پر ہدایت نہ ہوئی کہ ہم نے ان سے پہلے کتنی سنگتیں (قومیں) ہلاک کردیں کہ آج یہ ان کے گھروں میں چل پھر رہے ہیں بیشک اس میں ضرور نشانیاں ہیں تو کیا سنتے نہیں')
