INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3530, 32, 27, N'اور کیا نہیں دیکھتے کہ ہم پانی بھیجتے ہیں خشک زمین کی طرف پھر اس سے کھیتی نکالتے ہیں کہ اس میں سے ان کے چوپائے اور وہ خود کھاتے ہیں تو کیا انہیں سوجھتانہیں')
