INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3531, 32, 28, N'اور کہتے ہیں یہ فیصلہ کب ہوگا اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3532, 32, 29, N'تم فرماؤ فیصلہ کے دن کافروں کو ان کا ایمان لانا نفع نہ دے گا اور نہ انہیں مہلت ملے')
