INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3533, 32, 30, N'تو ان سے منہ پھیرلو اور انتظار کرو بیشک انہیں بھی انتظار کرنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3534, 33, 1, N'اے غیب کی خبریں بتانے والے (نبی) اللہ کا یوں ہی خوف رکھنا اور کافروں اور منافقوں کی نہ سننا بیشک اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3535, 33, 2, N'اور اس کی پیروی رکھنا جو تمہارے رب کی طرف سے تمہیں وحی ہوتی ہے، اے لوگو! اللہ تمہارے کام دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3536, 33, 3, N'اور اے محبوب! تم اللہ پر بھروسہ رکھو، اور اللہ بس ہے کام بنانے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3537, 33, 4, N'اللہ نے کسی آدمی کے اندر دو دل نہ رکھے اور تمہاری ان عورتوں کو جنہیں تم کے برابر کہہ دو تمہاری ماں نہ بنایا اور نہ تمہارے لے پالکوں کو تمہارا بیٹا بنایا یہ تمہارے اپنے منہ کا کہنا ہے اور اللہ حق فرماتا ہے اور وہی راہ دکھاتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3538, 33, 5, N'انہیں ان کے باپ ہی کا کہہ کر پکارو یہ اللہ کے نزدیک زیادہ ٹھیک ہے پھر اگر تمہیں ان کے باپ معلوم نہ ہوں تو دین میں تمہارے بھائی ہیں اور بشریت میں تمہارے چچا زاد اور تم پر اس میں کچھ گناہ نہیں جو نا دانستہ تم سے صادر ہوا ہاں وہ گناہ ہے جو دل کے قصد سے کرو اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3539, 33, 6, N'یہ نبی مسلمانوں کا ان کی جان سے زیادہ مالک ہے اور اس کی بیبیاں ان کی مائیں ہیں اور رشتہ والے اللہ کی کتاب میں ایک دوسرے سے زیادہ قریب ہیں بہ نسبت اور مسلمانوں اور مہاجروں کے مگر یہ کہ تم اپنے دوستوں پر احسان کرو یہ کتاب میں لکھا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3540, 33, 7, N'اور اے محبوب! یاد کرو جب ہم نے نبیوں سے عہد لیا اور تم سے اور نوح اور ابراہیم اور موسی ٰ اور عیسیٰ بن مریم سے اور ہم نے ان سے گاڑھا عہد لیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3541, 33, 8, N'تاکہ سچوں سے ان کے سچ کا سوال کرے اور اس نے کافروں کے لیے دردناک عذاب تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3542, 33, 9, N'اے ایمان والو! اللہ کا احسان اپنے اوپر یاد کرو جب تم پر کچھ لشکر آئے تو ہم نے ان پر آندھی اور وہ لشکر بھیجے جو تمہیں نظر نہ آئے اور اللہ تمہارے کام دیکھتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3543, 33, 10, N'جب کافر تم پر آئے تمہارے اوپر سے اور تمہارے نیچے سے اور جبکہ ٹھٹک کر رہ گئیں نگاہیں اور دل گلوں کے پاس آگئے اور تم اللہ پر طرح طرح کے گمان کرنے لگے امید و یاس کے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3544, 33, 11, N'وہ جگہ تھی کہ مسلمانوں کی جانچ ہوئی اور خوب سختی سے جھنجھوڑے گئے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3545, 33, 12, N'اور جب کہنے لگے منافق اور جن کے دلوں میں روگ تھا ہمیں اللہ و رسول نے وعدہ نہ دیا تھا مگر فریب کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3546, 33, 13, N'اور جب ان میں سے ایک گروہ نے کہا اے مدینہ والو! یہاں تمہارے ٹھہرنے کی جگہ نہیں تم گھروں کو واپس چلو اور ان میں سے ایک گروہ نبی سے اذن مانگتا تھا یہ کہہ کر ہمارے گھر بے حفاظت ہیں، اور وہ بے حفاظت نہ تھے، وہ تو نہ چاہتے تھے مگر بھاگنا،')
