INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3547, 33, 14, N'اور اگر ان پر فوجیں مدینہ کے اطراف سے آئیں پھر ان سے کفر چاہتیں تو ضرور ان کا مانگا دے بیٹھتے اور اس میں دیر نہ کرتے مگر تھوڑی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3548, 33, 15, N'اور بیشک اس سے پہلے وہ اللہ سے عہد کرچکے تھے کہ پیٹھ نہ پھیریں گے، اور اللہ کا وعدہ پوچھا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3549, 33, 16, N'تم فرماؤ ہرگز تمہیں بھاگنا نفع نہ دے گا اگر موت یا قتل سے بھاگو اور جب بھی دنیا نہ برتنے دیے جاؤ گے مگر تھوڑی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3550, 33, 17, N'تم فرماؤ وہ کون ہے جو اللہ کا حکم تم پر سے ٹال دے اگر وہ تمہارا برا چاہے یا تم پر مہر (رحم) فرمانا چاہے اور وہ اللہ کے سوا کوئی حامی نہ پائیں گے نہ مددگار،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3551, 33, 18, N'بیشک اللہ جانتا ہے تمہارے ان کو جو اوروں کو جہاد سے روکتے ہیں اور اپنے بھائیوں سے کہتے ہیں ہماری طرف چلے آؤ اور لڑائی میں نہیں آتے مگر تھوڑے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3552, 33, 19, N'تمہاری مدد میں گئی کرتے (کمی کرتے) ہیں پھر جب ڈر کا وقت آئے تم انہیں دیکھو گے تمہاری طرف یوں نظر کرتے ہیں کہ ان کی آنکھیں گھوم رہی ہیں جیسے کسی پر موت چھائی ہو پھر جب ڈر کا وقت نکل جائے تمہیں طعنے دینے لگیں تیز زبانوں سے مال غنیمت کے لالچ میں یہ لوگ ایمان لائے ہی نہیں تو اللہ نے ان کے عمل اکارت کردیے اور یہ اللہ کو آسان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3553, 33, 20, N'وہ سمجھ رہے ہیں کہ کافروں کے لشکر ابھی نہ گئے اور اگر لشکر دوبارہ آئیں تو ان کی خواہش ہوگی کہ کسی طرح گا نؤں میں نکل کر تمہاری خبریں پوچھتے اور اگر وہ تم میں رہتے جب بھی نہ لڑتے مگر تھوڑے')
GO
