GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3555, 33, 22, N'اور جب مسلمانوں نے کافروں کے لشکر دیکھے بولے یہ ہے وہ جو ہمیں وعدہ دیا تھا اللہ اور اس کے رسول نے اور سچ فرمایا اللہ اور اس کے رسول نے اور اس سے انہیں نہ بڑھا مگر ایمان اور اللہ کی رضا پر راضی ہونا،')
