GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3557, 33, 24, N'تاکہ اللہ سچوں کو ان کے سچ کا صلہ دے اور منافقوں کو عذاب کرے اگر چاہے، یا انہیں توبہ دے، بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3558, 33, 25, N'اور اللہ نے کافروں کو ان کے دلوں کی جلن کے ساتھ پلٹایا کہ کچھ بھلا نہ پایا اور اللہ نے مسلمانوں کو لڑائی کی کفایت فرمادی اور اللہ زبردست عزت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3559, 33, 26, N'اور جن اہلِ کتاب نے ان کی مدد کی تھی انہیں ان کے قلعوں سے اتارا اور ان کے دلوں میں رُعب ڈالا ان میں ایک گروہ کو تم قتل کرتے ہو اور ایک گروہ کو قید')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3560, 33, 27, N'اور ہم نے تمہارے ہاتھ لگائے ان کی زمین اور ان کی زمین اور ان کے مکان اور ان کے مال اور وہ زمین جس پر تم نے ابھی قدم نہیں رکھا ہے اور اللہ ہر چیز پر قادر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3561, 33, 28, N'اے غیب بتانے والے (نبی)! اپنی بیبیوں سے فرمادے اگر تم دنیا کی زندگی اور اس کی آرائش چاہتی ہو تو آؤ میں تمہیں مال دُوں اور اچھی طرح چھوڑ دُوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3562, 33, 29, N'اور اگر تم اللہ اور اس کے رسول اور آخرت کا گھر چاہتی ہو تو بیشک اللہ نے تمہاری نیکی والیوں کے لیے بڑا اجر تیار کر رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3563, 33, 30, N'اے نبی کی بیبیو! جو تم میں صریح حیا کے خلاف کوئی جرأت کرے اس پر اوروں سے دُونا عذاب ہوگا اور یہ اللہ کو آسان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3564, 33, 31, N'اور جو تم میں فرمانبردار رہے اللہ اور رسول کی اور اچھا کام کرے ہم اسے اوروں سے دُونا ثواب دیں گے اور ہم نے اس کے لیے عزت کی روزی تیار کر رکھی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3565, 33, 32, N'اے نبی کی بیبیو! تم اور عورتوں کی طرح نہیں ہو اگر اللہ سے ڈرو تو بات میں ایسی نرمی نہ کرو کہ دل کا روگی کچھ لالچ کرے ہاں اچھی بات کہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3566, 33, 33, N'اور اپنے گھروں میں ٹھہری رہو اور بے پردہ نہ رہو جیسے اگلی جاہلیت کی بے پردگی اور نماز قائم رکھو اور زکوٰة دو اور اللہ اور اس کے رسول کا حکم مانو ا لله تو یہی چاہتا ہے، اے نبی کے گھر والو! کہ تم سے ہر ناپاکی دور فرما دے اور تمہیں پاک کرکے خوب ستھرا کردے')
GO
