INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3653, 34, 47, N'تم فرماؤ میں نے تم سے اس پر کچھ اجر مانگا ہو تو وہ تمہیں کو میرا اجر تو اللہ ہی پر ہے اور وہ ہر چیز پر گواہ ہے،')
