INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3661, 35, 1, N'سب خوبیاں اللہ کو جو آسمانوں اور زمین کا بنانے والا فرشتوں کو رسول کرنے والا جن کے دو دو تین تین چار چار پر ہیں، بڑھاتا ہے آفرینش (پیدائش) میں جو چاہے بیشک اللہ ہر چیز پر قادر ہے،')
