INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3663, 35, 3, N'اے لوگو! اپنے اوپر اللہ کا احسان یاد کرو کیا اللہ کے سوا اور بھی کوئی خالق ہے کہ آسمان اور زمین سے تمہیں روزی دے، اس کے سوا کوئی معبود نہیں، تو تم کہاں اوندھے جاتے ہو')
