INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3666, 35, 6, N'بیشک شیطان تمہارا دشمن ہے تو تم بھی اسے دشمن سمجھو وہ تو اپنے گروہ کو اسی لیے بلاتا ہے کہ دوزخیوں میں ہوں')
