INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3667, 35, 7, N'کافروں کے لیے سخت عذاب ہے، اور جو ایمان لائے اور اچھے کام کیے ان کے لیے بخشش اور بڑا ثواب ہے،')
