INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3668, 35, 8, N'تو کیا وہ جس کی نگاہ میں اس کا برا کام آراستہ کیا گیا کہ اس نے اسے بھلا سمجھا ہدایت والے کی طرح ہوجائے گا اس لیے اللہ گمراہ کرتا ہے جسے چاہے اور راہ دیتا ہے جسے چاہے، تو تمہاری جان ان پر حسرتوں میں نہ جائے اللہ خوب جانتا ہے جو کچھ وہ کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3669, 35, 9, N'اور اللہ ہے جس نے بھیجیں ہوائیں کہ بادل ابھارتی ہیں، پھر ہم اسے کسی مردہ شہر کی طرف رواں کرتے ہیں تو اس کے سبب ہم زمین کو زندہ فرماتے ہیں اس کے مرے پیچھے یونہی حشر میں اٹھنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3670, 35, 10, N'جسے عزت کی چاہ ہو تو عزت تو سب اللہ کے ہاتھ ہے اسی کی طرف چڑھتا ہے پاکیزہ کلام اور جو نیک کام سے وہ اسے بلند کرتا ہے اور وہ جو برے داؤں (فریب) کرتے ہیں ان کے لیے سخت عذاب ہے اور انہیں کا مکر برباد ہوگا (ف۲۸')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3671, 35, 11, N'اور اللہ نے تمہیں بنایا مٹی سے پھر پانی کی بوند سے پھر تمہیں کیا جوڑے جوڑے اور کسی مادہ کو پیٹ نہیں رہتا اور نہ وہ جتنی ہے مگر اس کے علم سے، اور جس بڑی عمر والے کو عمر دی جائے یا جس کسی کی عمر کم رکھی جائے یہ سب ایک کتاب میں ہے بیشک یہ اللہ کو آسان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3672, 35, 12, N'اور دونوں سمندر ایک سے نہیں یہ میٹھا ہے خوب میٹھا پانی خوشگوار اور یہ کھاری ہے تلخ اور ہر ایک میں سے تم کھاتے ہو تازہ گوشت اور نکالتے ہو پہننے کا ایک گہنا (زیور) اور تو کشتیوں کو اس میں دیکھے کہ پانی چیرتی ہیں تاکہ تم اس کا فضل تلاش کرو اور کسی طرح حق مانو')
