INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3673, 35, 13, N'رات لاتا ہے دن کے حصہ میں اور دن لاتا ہے رات کے حصہ میں اور اس نے کام میں لگائے سورج اور چاند ہر ایک ایک مقرر میعاد تک چلتا ہے یہ ہے اللہ تمہارا رب اسی کی بادشاہی ہے، اور اس کے سوا جنہیں تم پوجتے ہو دانہ خُرما کے چھلکے تک کے مالک نہیں،')
GO
