INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3678, 35, 18, N'اور کوئی بوجھ اٹھانے والی جان دوسرے کا بوجھ نہ اٹھائے گی اور اگر کوئی بوجھ والی اپنا بوجھ بٹانے کو کسی کو بلائے تو اس کے بوجھ میں سے کوئی کچھ نہ اٹھائے گا اگرچہ قریب رشتہ دار ہو اے محبوب! تمہارا ڈر سناتا انہیں کو کام دیتا ہے جو بے دیکھے اپنے رب! سے ڈرتے ہیں اور نماز قائم رکھتے ہیں، اور جو ستھرا ہوا تو اپنے ہی بھلے کو ستھرا ہوا اور اللہ ہی کی طرف پھرنا ہے،')
