INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3685, 35, 25, N'اور اگر یہ تمہیں جھٹلائیں تو ان سے اگلے بھی جھٹلاچکے ہیں ان کے پاس ان کے رسول آئے روشن دلیلیں اور صحیفے اور چمکتی کتاب لے کر،')
