GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3699, 35, 39, N'وہی ہے جس نے تمہیں زمین میں اگلوں کا جانشین کیا تو جو کفر کرے اس کا کفر اسی پر پڑے اور کافروں کو ان کا کفر ان کے رب کے یہاں نہیں بڑھائے گا مگر بیزاری اور کافروں کو ان کا کفر نہ بڑھائے گا مگر نقصان')
