INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3992, 38, 22, N'جب وہ داؤد پر داخل ہوئے تو وہ ان سے گھبرا گیا انہوں نے عرض کی ڈریے نہیں ہم دو فریق ہیں کہ ایک نے دوسرے پر زیادتی کی ہے تو ہم میں سچا فیصلہ فرمادیجئے اور خلافِ حق نہ کیجئے اور ہمیں سیدھی راہ بتایے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3993, 38, 23, N'بیشک یہ میرا بھائی ہے اس کے پاس ننانوے دُنبیاں ہیں اور میرے پاس ایک دُنبی، اب یہ کہتا ہے وہ بھی مجھے حوالے کردے اور بات میں مجھ پر زور ڈالتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3994, 38, 24, N'داؤد نے فرمایا بیشک یہ تجھ پر زیادتی کرتا ہے کہ تیری دُنبی اپنی دُنبیوں میں ملانے کو مانگتا ہے، اور بیشک اکثر ساجھے والے ایک دوسرے پر زیادتی کرتے ہیں مگر جو ایمان لائے اور اچھے کام کیے اور وہ بہت تھوڑے ہیں اب داؤد سمجھا کہ ہم نے یہ اس کی جانچ کی تھی تو اپنے رب سے معافی مانگی اور سجدے میں گر پڑا اور رجوع لایا، (السجدة ۱۰)')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3995, 38, 25, N'تو ہم نے اسے یہ معاف فرمایا، اور بیشک اس کے لیے ہماری بارگاہ میں ضرور قرب اور اچھا ٹھکانا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3996, 38, 26, N'اے داؤد بیشک ہم نے تجھے زمین میں نائب کیا تو لوگوں میں سچا حکم کر اور خواہش کے پیچھے نہ جانا کہ تجھے اللہ کی راہ سے بہکادے گی، بیشک وہ جو اللہ کی راہ سے بہکتے ہیں ان کے لیے سخت عذاب ہے اس پر کہ وہ حساب کے دن کو بھول بیٹھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3997, 38, 27, N'اور ہم نے آسمان اور زمین اور جو کچھ ان کے درمیان ہے بیکار نہ بنائے، یہ کافروں کا گمان ہے تو کافروں کی خرابی ہے آگ سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3998, 38, 28, N'کیا ہم انہیں جو ایمان لائے اور اچھے کام کیے ان جیسا کردیں جو زمین میں فساد پھیلاتے ہیں، یا ہم پرہیزگاروں کو شریر بے حکموں کے برابر ٹھہرادیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (3999, 38, 29, N'یہ ایک کتاب ہے کہ ہم نے تمہاری طرف اتاری برکت والی تاکہ اس کی آیتوں کو سوچیں اور عقلمند نصیحت مانیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4000, 38, 30, N'اور ہم نے داؤد کو سلیمان عطا فرمایا، کیا اچھا بندہ بیشک وہ بہت رجوع لانے والا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4001, 38, 31, N'جبکہ اس پر پیش کیے گئے تیسرے پہر کو کہ روکئے تو تین پاؤں پر کھڑے ہوں چوتھے سم کا کنارہ زمین پر لگائے ہوئے اور چلائے تو ہوا ہوجائیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4002, 38, 32, N'تو سلیمان نے کہا مجھے ان گھوڑوں کی محبت پسند آئی ہے اپنے رب کی یاد کے لیے پھر انہیں چلانے کا حکم دیا یہاں تک کہ نگاہ سے پردے میں چھپ گئے')
