INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4060, 39, 2, N'بیشک ہم نے تمہاری طرف یہ کتاب حق کے ساتھ اتاری تو اللہ کو کو پوجو نرے اس کے بندے ہوکر،')
