INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4061, 39, 3, N'ہاں خالص اللہ ہی کی بندگی ہے اور وہ جنہوں نے اس کے سوا اور والی بنالیے کہتے ہیں ہم تو انہیں صرف اتنی بات کے لیے پوجتے ہیں کہ یہ ہمیں اللہ کے پاس نزدیک کردیں، اللہ ان پر فیصلہ کردے گا اس بات کا جس میں اختلاف کررہے ہیں بیشک اللہ راہ نہیں دیتا اسے جو جھوٹا بڑا ناشکرا ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4062, 39, 4, N'اللہ اپنے لیے بچہ بناتا تو اپنی مخلوق میں سے جسے چاہتا چن لیتا پاکی ہے اسے وہی ہے ایک اللہ سب پر غالب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4063, 39, 5, N'اس نے آسمان اور زمین حق بنائے رات کو دن پر لپیٹتا ہے اور دن کو رات پر لپیٹتا ہے اور اس نے سورج اور چاند کو کام میں لگایا ہر ایک، ایک ٹھہرائی میعاد کے لیے چلتا ہے سنتا ہے وہی صاحب عزت بخشنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4064, 39, 6, N'اس نے تمہیں ایک جان سے بنایا پھر اسی سے اس کا جوڑ پیدا کیا اور تمہارے لیے چوپایوں میں سے آٹھ جوڑے تھے تمہیں تمہاری ماؤں کے پیٹ میں بناتا ہے ایک طرح کے بعد اور طرح تین اندھیریوں میں یہ ہے اللہ تمہارا رب اسی کی بادشاہی ہے، اس کے سوا کسی کی بندگی نہیں، پھر کہیں پھیرے جاتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4065, 39, 7, N'اگر تم ناشکری کرو تو بیشک اللہ بے نیاز ہے تم سے اور اپنے بندوں کی ناشکری اسے پسند نہیں، اور اگر شکر کرو تو اسے تمہارے لیے پسند فرماتا ہے اور کوئی بوجھ اٹھانے والی جان دوسرے کا بوجھ نہیں اٹھائے گی پھر تمہیں اپنے رب ہی کی طرف پھرنا ہے تو وہ تمہیں بتادے گا جو تم کرتے تھے بیشک وہ دلوں کی بات جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4066, 39, 8, N'اور جب آدمی کو کوئی تکلیف پہنچتی ہے اپنے رب کو پکارتا ہے اسی طرف جھکا ہوا پھر جب اللہ نے اسے اپنے پاس سے کوئی نعمت دی تو بھول جاتا ہے جس لیے پہلے پکارا تھا اور اللہ کے برابر والے ٹھہرانے لگتا ہے تاکہ اس کی راہ سے بہکادے تم فرماؤ تھوڑے دن اپنے کفر کے ساتھ برت لے بیشک تو دوزخیوں میں ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4067, 39, 9, N'کیا وہ جسے فرمانبرداری میں رات کی گھڑیاں گزریں سجود میں اور قیام میں آخرت سے ڈرتا اور اپنے رب کی رحمت کی آس لگائے کیا وہ نافرمانوں جیسا ہو جائے گا تم فرماؤ کیا برابر ہیں جاننے والے اور انجان، نصیحت تو وہی مانتے ہیں جو عقل والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4068, 39, 10, N'تم فرماؤ اے میرے بندو! جو ایمان لائے اپنے سے ڈرو، جنہوں نے بھلائی کی ان کے لیے اس دنیا میں بھلائی ہے اور اللہ کی زمین وسیع ہے صابروں ہی کو ان کا ثواب بھرپور دیا جائے گا بے گنتی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4069, 39, 11, N'تم فرماؤ مجھے حکم ہے کہ اللہ کو پوجوں نرا اس کا بندہ ہوکر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4070, 39, 12, N'اور مجھے حکم ہے کہ میں سب سے پہلے گردن رکھوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4071, 39, 13, N'تم فرماؤ بالفرض اگر مجھ سے نافرمانی ہوجائے تو مجھے اپنے رب سے ایک بڑے دن کے عذاب کا ڈر ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4072, 39, 14, N'تم فرماؤ میں اللہ ہی کو پوجتا ہوں نرا اس کا بندہ ہوکر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4073, 39, 15, N'تو تم اس کے سوا جسے چاہو پوجو تم فرماؤ پوری ہار انہیں جو اپنی جان اور اپنے گھر والے قیامت کے دن ہار بیٹھے ہاں ہاں یہی کھلی ہار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4074, 39, 16, N'ان کے اوپر آگ کے پہاڑ ہیں اور ان کے نیچے پہاڑ اس سے اللہ ڈراتا ہے اپنے بندوں اے میرے بندو! تم مجھ سے ڈرو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4075, 39, 17, N'اور وہ جو بتوں کی پوجا سے بچے اور اللہ کی طرف رجوع ہوئے انہیں کے لیے خوشخبری ہے تو خوشی سناؤ میرے ان بندوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4076, 39, 18, N'جو کان لگا کر بات سنیں پھر اس کے بہتر پر چلیں یہ ہیں جن کو اللہ نے ہدایت فرمائی اور یہ ہیں جن کو عقل ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4077, 39, 19, N'تو کیا وہ جس پر عذاب کی بات ثابت ہوچکی نجات والوں کے برابر ہوجائے گا تو کیا تم ہدایت دے کر آگ کے مستحق کو بچالو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4078, 39, 20, N'لیکن جو اپنے رب سے ڈرے ان کے لیے بالا خانے ہیں ان پر بالا خانے بنے ان کے نیچے نہریں بہیں، اللہ کا وعدہ، اللہ وعدہ خلاف نہیں کرتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4079, 39, 21, N'کیا تو نے نہ دیکھا کہ اللہ نے آسمان سے پانی اتارا پھر اس سے زمین میں چشمے بنائے پھر اس سے کھیتی نکالتا ہے کئی رنگت کی پھر سوکھ جاتی ہے تو تُو دیکھے کہ وہ پیلی پڑ گئی پھر اسے ریزہ ریزہ کردیتا ہے، بیشک اس میں دھیان کی بات ہے عقل مندوں کو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4080, 39, 22, N'تو کیا وہ جس کا سینہ اللہ نے اسلام کے لیے کھول دیا تو وہ اپنے رب کی طرف سے نور پر ہے اس جیسا ہوجائے گا جو سنگدل ہے تو خرابی ہے ان کی جن کے دل یادِ خدا کی طرف سے سخت ہوگئے ہیں وہ کھلی گمراہی میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4081, 39, 23, N'اللہ نے اتاری سب سے اچھی کتاب کہ اول سے آخر تک ایک سی ہے دوہرے بیان والی اس سے بال کھڑے ہوتے ہیں ان کے بدن پر جو اپنے رب سے ڈرتے ہیں، پھر ان کی کھالیں اور دل نرم پڑتے ہیں یادِ خدا کی طرف رغبت میں یہ اللہ کی ہدایت ہے راہ دکھائے اس سے جسے چاہے، اور جسے اللہ گمراہ کرے اسے کوئی راہ دکھانے والا نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4082, 39, 24, N'تو کیا وہ جو قیامت کے دن برے عذاب کی ڈھال نہ پائے گا اپنے چہرے کے سوا نجات والے کی طرح ہوجائے گا اور ظالموں سے فرمایا جائے گا اپنا کمایا چکھو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4083, 39, 25, N'ان سے اگلوں نے جھٹلایا تو انہیں عذاب آیا جہاں سے انہیں خبر نہ تھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4084, 39, 26, N'اور اللہ نے انہیں دنیا کی زندگی میں رسوائی کا مز ہ چکھایا اور بیشک آخرت کا عذاب سب سے بڑا، کیا اچھا تھا اگر وہ جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4085, 39, 27, N'اور بیشک ہم نے لوگوں کے لیے اس قرآن میں ہر قسم کی کہاوت بیان فرمائی کہ کسی طرح انہیں دھیان ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4086, 39, 28, N'عربی زبان کا قرآن جس میں اصلاً کجی نہیں کہ کہیں وہ ڈریں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4087, 39, 29, N'اللہ ایک مثال بیان فرماتا ہے ایک غلام میں کئی بدخو آقا شریک اور ایک نرے ایک مولیٰ کا، کیا ان دونوں کا حال ایک سا ہے سب خوبیاں اللہ کو بلکہ ان کے اکثر نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4088, 39, 30, N'بیشک تمہیں انتقال فرمانا ہے اور ان کو بھی مرنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4089, 39, 31, N'پھر تم قیامت کے دن اپنے رب کے پاس جھگڑو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4090, 39, 32, N'تو اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ باندھے اور حق کو جھٹلائے جب اس کے پاس آئے، کیا جہنم میں کافروں کا ٹھکانہ نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4091, 39, 33, N'اور وہ جو یہ سچ لے کر تشریف لائے اور وہ جنہوں نے ان کی تصدیق کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4092, 39, 34, N'یہی ڈر والے ہیں، ان کے لےیے ہے، جو وہ چاہیں اپنے رب کے پاس، نیکوں کا یہی صلہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4093, 39, 35, N'تاکہ اللہ ان سے اتار دے برے سے برا کام جو انہوں نے کیا اور انہیں ان کے ثواب کا صلہ دے اچھے سے اچھے کام پر جو وہ کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4094, 39, 36, N'کیا اللہ اپنے بندے کو کافی نہیں اور تمہیں ڈراتے ہیں اس کے سوا اوروں سے اور جسے اللہ گمراہ کرے اس کی کوئی ہدایت کرنے والا نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4095, 39, 37, N'اور جسے اللہ ہدایت دے اسے کوئی بہکانے والا نہیں، کیا اللہ عزت والا بدلہ لینے والا نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4096, 39, 38, N'اور اگر تم ان سے پوچھو آسمان اور زمین کس نے بنائے تو ضرور کہیں گے اللہ نے تم فرماؤ بھلا بتاؤ تو وہ جنہیں تم اللہ کے سوا پوجتے ہو اگر اللہ مجھے کوئی تکلیف پہنچانا چاہے تو کیا وہ اس کی بھیجی تکلیف ٹال دیں گے یا وہ مجھ پر مہر (رحم) فرمانا چاہے تو کیا وہ اس کی مہر کو روک رکھیں گے تم فرماؤ اللہ مجھے بس ہے بھروسے والے اس پر بھروسہ کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4097, 39, 39, N'تم فرماؤ، اے میری قوم! اپنی جگہ کام کیے جاؤ میں اپنا کام کرتا ہوں تو آگے جان جاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4098, 39, 40, N'کس پر آتا ہے وہ عذاب کہ اسے رسوا کرے گا اور کس پر اترتا ہے عذاب کہ رہ پڑے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4099, 39, 41, N'بیشک ہم نے تم پر یہ کتاب لوگوں کی ہدایت کو حق کے ساتھ اتاری تو جس نے راہ پائی تو اپنے بھلے کو اور جو بہکا وہ اپنے ہی برے کو بہکا اور تم کچھ ان کے ذمہ دار نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4100, 39, 42, N'اللہ جانوں کو وفات دیتا ہے ان کی موت کے وقت اور جو نہ مریں انہیں ان کے سوتے میں پھر جس پر موت کا حکم فرمادیا اسے روک رکھتا ہے اور دوسری ایک میعاد مقرر تک چھوڑ دیتا ہے بیشک اس میں ضرور نشانیاں ہیں سوچنے والوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4101, 39, 43, N'کیا انہوں نے اللہ کے مقابل کچھ سفارشی بنا رکھے ہیں تم فرماؤ کیا اگرچہ وہ کسی چیز کے مالک نہ ہوں اور نہ عقل رکھیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4102, 39, 44, N'تم فرماؤ شفاعت تو سب اللہ کے ہاتھ میں ہے اسی کے لیے ہے آسمانوں اور زمین کی بادشاہی، پھر تمہیں اسی کی طرف پلٹنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4103, 39, 45, N'اور جب ایک اللہ کا ذکر کیا جاتا ہے دل سمٹ جاتے ہیں ان کے جو آخرت پر ایمان نہیں لاتے اور جب اس کے سوا اوروں کا ذکر ہوتا ہے جبھی وہ خوشیاں مناتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4104, 39, 46, N'تم عرض کرو اے اللہ! آسمانوں اور زمین کے پیدا کرنے والے نہاں اور عیاں کے جاننے والے تو اپنے بندوں میں فیصلہ فرمائے گا جس میں وہ اختلاف رکھتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4105, 39, 47, N'اور اگر ظالموں کے لیے ہوتا جو کچھ زمین میں ہے سب اور اس کے ساتھ اس جیسا تو یہ سب چھڑائی (چھڑانے) میں دیتے روز ِ قیامت کے بڑے عذاب سے اور انہیں اللہ کی طرف سے وہ بات ظاہر ہوئی جو ان کے خیال میں نہ تھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4106, 39, 48, N'اور ان پر اپنی کمائی ہوئی برائیاں کھل گئیں اور ان پر آپڑا وہ جس کی ہنسی بناتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4107, 39, 49, N'پھر جب آدمی کو کوئی تکلیف پہنچتی ہے تو ہمیں بلاتا ہے پھر جب اسے ہم اپنے پاس سے کوئی نعمت عطا فرمائیں کہتا ہے یہ تو مجھے ایک علم کی بدولت ملی ہے بلکہ وہ تو آزمائش ہے مگر ان میں بہتوں کو علم نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4108, 39, 50, N'ان سے اگلے بھی ایسے ہی کہہ چکے تو ان کا کمایا ان کے کچھ کام نہ آیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4109, 39, 51, N'تو ان پر پڑ گئیں ان کی کمائیوں کی برائیاں اور وہ جو ان میں ظالم عنقریب ان پر پڑیں گی ان کی کمائیوں کی برائیاں اور وہ قابو سے نہیں نکل سکتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4110, 39, 52, N'کیا انہیں معلوم نہیں کہ اللہ روزی کشادہ کرتا ہے جس کے لیے چاہے اور تنگ فرماتا ہے، بیشک اس میں ضرور نشانیاں ہیں ایمان والوں کے لیے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4111, 39, 53, N'تم فرماؤ اے میرے وہ بندو! جنہوں نے اپنی جانوں پر زیادتی کی اللہ کی رحمت سے ناامید نہ ہو، بیشک اللہ سب گناہ بخش دیتا ہے بیشک وہی بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4112, 39, 54, N'اور اپنے رب کی طرف رجوع لاؤ اور اس کے حضور گردن رکھو قبل اس کے کہ تم پر عذاب آئے پھر تمہاری مدد نہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4113, 39, 55, N'اور اس کی پیروی کرو جو اچھی سے اچھی تمہارے رب سے تمہاری طرف اتاری گئی قبل اس کے کہ عذاب تم پر اچانک آجائے اور تمہیں خبر نہ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4114, 39, 56, N'کہ کہیں کوئی جان یہ نہ کہے کہ ہائے افسوس! ان تقصیروں پر جو میں نے اللہ کے بارے میں کیں اور بیشک میں ہنسی بنایا کرتا تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4115, 39, 57, N'یا کہے اگر اللہ مجھے راہ دکھاتا تو میں ڈر والوں میں ہوتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4116, 39, 58, N'یا کہے جب عذاب دیکھے کسی طرح مجھے واپسی ملے کہ میں نیکیاں کروں')
