INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4129, 39, 71, N'اور کافر جہنم کی طرف ہانکے جائیں گے گروہ گروہ یہاں تک کہ جب وہاں پہنچیں گے اس کے دروازے کھولے جائیں گے اور اس کے داروغہ ان سے کہیں گے کیا تمہارے پاس تمہیں میں سے وہ رسول نہ آئے تھے جو تم پر تمہارے رب کی آیتیں پڑھتے تھے اور تمہیں اس دن سے ملنے سے ڈراتے تھے، کہیں گے کیوں نہیں مگر عذاب کا قول کافروں پر ٹھیک اترا')
