INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4130, 39, 72, N'فرمایا جائے گا جاؤ جہنم کے دروازوں میں اس میں ہمیشہ رہنے، تو کیا ہی برا ٹھکانا متکبروں کا،')
