INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4133, 39, 75, N'اور تم فرشتوں کو دیکھو گے عرش کے آس پاس حلقہ کیے اپنے رب کی تعریف کے ساتھ ا س کی پاکی بولتے اور لوگوں میں سچا فیصلہ فرمادیا جائے گا اور کہا جائے گا کہ سب خوبیاں اللہ کو جو سارے جہاں کا رب')
