INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4137, 40, 4, N'اللہ کی آیتوں میں جھگڑا نہیں کرتے مگر کافر تو اے سننے والے تجھے دھوکا نہ دے ان کا شہروں میں اہل گہلے (اِتراتے) پھرنا')
