INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4138, 40, 5, N'ان سے پہلے نوح کی قوم اور ان کے بعد کے گروہوں نے جھٹلایا، اور ہر امت نے یہ قصد کیا کہ اپنے رسول کو پکڑ لیں اور باطل کے ساتھ جھگڑے کہ اس سے حق کو ٹال دیں تو میں نے انہیں پکڑا، پھر کیسا ہوا میرا عذاب')
