INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4139, 40, 6, N'اور یونہی تمہارے رب کی بات کافروں پر ثابت ہوچکی ہے کہ وہ دوزخی ہیں،')
