INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4140, 40, 7, N'وہ جو عرش اٹھاتے ہیں اور جو اس کے گرد ہیں اپنے کی تعریف کے ساتھ اس کی پاکی بولتے اور اس پر ایمان لاتے اور مسلمانوں کی مغفرت مانگتے ہیں اے رب ہمارے تیرے رحمت و علم میں ہر چیز کی سمائی ہے تو انہیں بخش دے جنہوں نے توبہ کی اور تیری راہ پر چلے اور انہیں دوزخ کے عذاب سے بچالے،')
