INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4141, 40, 8, N'اے ہمارے رب! اور انہیں بسنے کے باغوں میں داخل کر جن کا تو نے ان سے وعدہ فرمایا ہے اور ان کو جو نیک ہوں ان کے باپ دادا اور بیبیوں اور اولاد میں بیشک تو ہی عزت و حکمت والا ہے،')
