INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4142, 40, 9, N'اور انہیں گناہوں کی شامت سے بچالے، اور جسے تو اس دن گناہوں کی شامت سے بچائے تو بیشک تو نے اس پر رحم فرمایا، اور یہی بڑی کامیابی ہے،')
