INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4143, 40, 10, N'بیشک جنہوں نے کفر کیا ان کو ندا کی جائے گی کہ ضرور تم سے اللہ کی بیزاری اس سے بہت زیادہ ہے جیسے تم آج اپنی جان سے بیزار ہو جب کہ تم ایمان کی طرف بلائے جاتے تو تم کفر کرتے،')
