INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4144, 40, 11, N'کہیں گے اے ہمارے رب تو نے ہمیں دوبارہ مردہ کیا اور دوبارہ زندہ کیا اب ہم اپنے گناہوں پر مُقِر ہوئے تو آگ سے نکلنے کی بھی کوئی راہ ہے')
