INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4145, 40, 12, N'یہ اس پر ہوا کہ جب ایک اللہ پکارا جاتا تو تم کفر کرتے اور ان کا شریک ٹھہرایا جاتا تو تم مان لیتے تو حکم اللہ کے لیے ہے جو سب سے بلند بڑا،')
