INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4146, 40, 13, N'وہی ہے کہ تمہیں اپنی نشانیاں دکھاتا ہے اور تمہارے لیے آسمان سے روزی اتارتا ہے اور نصیحت نہیں مانتا مگر جو رجوع لائے')
