INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4147, 40, 14, N'تو اللہ کی بندگی کرو نرے اس کے بندے ہوکر پڑے برا مانیں کافر،')
