INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4149, 40, 16, N'جس دن وہ بالکل ظاہر ہوجائیں گے اللہ پر ان کا کچھ حال چھپا نہ ہوگا آج کسی کی بادشاہی ہے ایک اللہ سب پر غا لب کی، ف۳۷)')
