INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4150, 40, 17, N'آج ہر جان اپنے کےٴ کا بدلہ پاےٴ گی آج کسی پر زیادتی نہیں، بیشک اللہ جلد حساب لینے والا ہے،')
