INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4151, 40, 18, N'اور انہیں ڈراؤ اس نزدیک آنے والی آفت کے دن سے جب دل گلوں کے پاس آجائیں گے غم میں بھرے، اور ظالموں کا نہ کوئی دوست نہ کوئی سفارشی جس کا کہا مانا جائے')
