INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4152, 40, 19, N'اللہ جانتا ہے چوری چھپے کی نگاہ اور جو کچھ سینوں میں چھپا ہے')
