INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4153, 40, 20, N'اور اللہ سچا فیصلہ فرماتا ہے، اور اس کے سوا جن کو پوجتے ہیں وہ کچھ فیصلہ نہیں کرتے بیشک اللہ ہی سنتا اور دیکھتا ہے')
