INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4154, 40, 21, N'تو کیا انہوں نے زمین میں سفر نہ کیا کہ دیکھتے کیسا انجام ہوا ان سے اگلوں کا ان کی قوت اور زمین میں جو نشانیاں چھوڑ گئے ان سے زائد تو اللہ نے انہیں ان کے گناہوں پر پکڑا، اور اللہ سے ان کا کوئی بچانے والا نہ ہوا')
