INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4155, 40, 22, N'یہ اس لیے کہ ان کے پاس ان کے رسول روشن نشانیاں لے کر آئے پھر وہ کفر کرتے تو اللہ نے انہیں پکڑا، بیشک اللہ زبردست عذاب والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4156, 40, 23, N'اور بیشک ہم نے موسیٰ کو اپنی نشانیوں اور روشن سند کے ساتھ بھیجا،')
