INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4157, 40, 24, N'فرعون اور ہامان اور قارون کی طرف تو وہ بولے جادوگر ہے بڑا جھوٹا')
