INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4158, 40, 25, N'پھر جب وہ ان پر ہمارے پاس سے حق لایا بولے جو اس پر ایمان لائے ان کے بیٹے قتل کرو اور عورتیں زندہ رکھو اور کافروں کا داؤ نہیں مگر بھٹکتا پھرتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4159, 40, 26, N'اور فرعون بولا مجھے چھوڑو میں موسیٰ کو قتل کروں اور وہ اپنے رب کو پکارے میں ڈرتا ہوں کہیں وہ تمہارا دین بدل دے یا زمین میں فساد چمکائے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4160, 40, 27, N'اور موسیٰ نے کہا میں تمہارے اور اپنے رب کی پناہ لیتا ہوں ہر متکبر سے کہ حساب کے دن پر یقین نہیں لاتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4161, 40, 28, N'اور بولا فرعون والوں میں سے ایک مرد مسلمان کہ اپنے ایمان کو چھپاتا تھا کیا ایک مرد کو اس پر مارے ڈالتے ہو کہ وہ کہتا ہے کہ میرا رب اللہ ہے اور بیشک وہ روشن نشانیاں تمہارے پاس تمہارے رب کی طرف سے لائے اور اگر بالفرض وہ غلط کہتے ہیں تو ان کی غلط گوئی کا وبال ان پر، اور اگر وہ سچے ہیں تو تمہیں پہنچ جائے گا کچھ وہ جس کا تمہیں وعدہ دیتے ہیں بیشک اللہ راہ نہیں دیتا اسے جو حد سے بڑھنے والا بڑا جھوٹا ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4162, 40, 29, N'اے میری قوم! آج بادشاہی تمہاری ہے اس زمین میں غلبہ رکھتے ہو تو اللہ کے عذاب سے ہمیں کون بچالے گا اگر ہم پر آئے فرعون بولا میں تو تمہیں وہی سمجھاتا ہوں جو میری سوجھ ہے اور میں تمہیں وہی بتاتا ہوں جو بھلائی کی راہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4163, 40, 30, N'اور وہ ایمان والا بولا اے میری قوم! مجھے تم پر اگلے گروہوں کے دن کا سا خوف ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4164, 40, 31, N'جیسا دستور گزرا نوح کی قوم اور عاد اور ثمود اور ان کے بعد اوروں کا اور اللہ بندوں پر ظلم نہیں چاہتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4165, 40, 32, N'اور اے میری قوم میں تم پر اس دن سے ڈراتا ہوں جس دن پکار مچے گی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4166, 40, 33, N'جس دن پیٹھ دے کر بھاگو گے اللہ سے تمہیں کوئی بچانے والا نہیں، اور جسے اللہ گمراہ کرے اس کا کوئی راہ دکھانے والا نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4167, 40, 34, N'اور بیشک اس سے پہلے تمہارے پاس یوسف روشن نشانیاں لے کر آئے تو تم ان کے لائے ہوئے سے شک ہی میں رہے، یہاں تک کہ جب انہوں نے انتقال فرمایا تم بولے ہرگز اب اللہ کوئی رسول نہ بھیجے گا اللہ یونہی گمراہ کرتا ہے اسے جو حد سے بڑھنے والا شک لانے والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4168, 40, 35, N'وہ جو اللہ کی آیتوں میں جھگڑا کرتے ہیں بغیر کسی سند کے، کہ انہیں ملی ہو، کس قدر سخت بیزاری کی بات ہے اللہ کے نزدیک اور ایمان لانے والوں کے نزدیک، اللہ یوں ہی مہر کردیتا ہے متکبر سرکش کے سارے دل پر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4169, 40, 36, N'اور فرعون بولا اے ہامان! میرے لیے اونچا محل بنا شاید میں پہنچ جاؤں راستوں تک،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4170, 40, 37, N'کا ہے کے راستے آسمان کے تو موسیٰ کے خدا کو جھانک کر دیکھوں اور بیشک میرے گمان میں تو وہ جھوٹا ہے اور یونہی فرعون کی نگاہ میں اس کا برا کام بھلا کر دکھا گیا اور وہ راستے میں روکا گیا، اور فرعون کا داؤ ہلاک ہونے ہی کو تھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4171, 40, 38, N'اور وہ ایمان والا بولا، اے میری قوم! میرے پیچھے چلو میں تمہیں بھلائی کی راہ بتاؤں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4172, 40, 39, N'اے میری قوم! یہ دنیا کا جینا تو کچھ برتنا ہی ہے اور بیشک وه پچھلا ہمیشہ رہنے کا گھر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4173, 40, 40, N'جو برُا کام کرے تو اسے بدلہ نہ ملے گا مگر اتنا ہی اور جو اچھا کام کرے مرد خواه عورت اور جو مسلمان تو وہ جنت میں داخل کیے جائیں گے وہاں بے گنتی رزق پائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4174, 40, 41, N'اور اے میری قوم مجھے کیا ہوا میں تمہیں بلاتا ہوں نجات کی طرف اور تم مجھے بلاتے ہو دوزخ کی طرف')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4175, 40, 42, N'مجھے اس طرف بلاتے ہو کہ اللہ کا انکا کروں اور ایسے کو اس کا شریک کروں جو میرے علم میں نہیں، اور میں تمہیں اس عزت والے بہت بخشنے والے کی طرف بلاتا ہوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4176, 40, 43, N'آپ ہی ثابت ہوا کہ جس کی طرف مجھے بلاتے ہو اسے بلانا کہیں کام کا نہیں دنیا میں نہ آخرت میں اور یہ ہمارا پھرنا اللہ کی طرف ہے اور یہ کہ حد سے گزرنے والے ہی دوزخی ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4177, 40, 44, N'تو جلد وہ وقت آتا ہے کہ جو میں تم سے کہہ رہا ہوں، اسے یاد کرو گے اور میں اپنے کام اللہ کو سونپتا ہوں، بیشک اللہ بندوں کو دیکھتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4178, 40, 45, N'تو اللہ نے اسے بچالیا ان کے مکر کی برائیوں سے اور فرعون والوں کو برے عذاب نے آ گھیرا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4179, 40, 46, N'آ گ جس پر صبح و شام پیش کیے جاتے ہیں اور جس دن قیامت قائم ہوگی، حکم ہوگا فرعون والوں کو سخت تر عذاب میں داخل کرو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4180, 40, 47, N'اور جب وہ آگ میں باہم جھگڑیں گے تو کمزور ان سے کہیں گے جو بڑے بنتے تھے ہم تمہارے تابع تھے تو کیا تم ہم سے آگ کا کوئی حصہ گھٹا لوگے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4181, 40, 48, N'وہ تکبر والے بولے ہم سب آگ میں ہیں بیشک اللہ بندوں میں فیصلہ فرماچکا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4182, 40, 49, N'اور جو آگ میں ہیں اس کے داروغوں سے بولے اپنے رب سے دعا کرو ہم پر عذاب کا ایک دن ہلکا کردے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4183, 40, 50, N'انہوں نے کہا کیا تمہارے پاس تمہارے رسول نشانیاں نہ لاتے تھے بولے کیوں نہیں بولے تو تمہیں دعا کرو اور کافروں کی دعا نہیں، مگر بھٹکتے پھرنے کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4184, 40, 51, N'بیشک ضرور ہم اپنے رسولوں کی مدد کریں گے اور ایمان والوں کی دنیا کی زندگی میں اور جس دن گواہ کھڑے ہوں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4185, 40, 52, N'جس دن ظالموں کو ان کے بہانے کچھ کام نہ دیں گے اور ان کے لیے لعنت ہے اور ان کے لیے بُرا گھر')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4186, 40, 53, N'اور بیشک ہم نے موسیٰ کو رہنمائی عطا فرمائی اور بنی اسرائیل کو کتاب کا وارث کیا')
