INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4188, 40, 55, N'تم صبر کرو بیشک اللہ کا وعدہ سچا ہے اور اپنوں کے گناہوں کی معافی چاہو اور اپنے رب کی تعریف کرتے ہوئے صبح اور شام اس کی پاکی بولو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4189, 40, 56, N'وہ جو اللہ کی آیتوں میں جھگڑا کرتے ہیں بغیر کسی سند کے جو انہیں ملی ہو ان کے دلوں میں نہیں مگر ایک بڑائی کی ہوس جسے نہ پہنچیں گے تو تم اللہ کی پناہ مانگو بیشک وہی سنتا دیکھتا ہے،')
