INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4190, 40, 57, N'بیشک آسمانوں اور زمین کی پیدائش آدمیوں کی پیدائش سے بہت بڑی لیکن بہت لوگ نہیں جانتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4191, 40, 58, N'اور اندھا اور انکھیارا برابر نہیں اور نہ وہ جو ایمان لائے اور اچھے کام کیے اور بدکار کتنا کم دھیان کرتے ہو،')
