INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4192, 40, 59, N'بیشک قیامت ضرور آنے والی ہے اس میں کچھ شک نہیں لیکن بہت لوگ ایمان نہیں لاتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4193, 40, 60, N'اور تمہارے رب نے فرمایا مجھ سے دعا کرو میں قبول کروں گا بیشک وہ جو میری عبادت سے اونچے کھینچتے (تکبر کرتے) ہیں عنقریب جہنم میں جائیں گے ذلیل ہوکر،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4194, 40, 61, N'اللہ ہے جس نے تمہارے لیے رات بنائی کہ اس میں آرام پاؤ اور دن بنایا آنکھیں کھولتا بیشک اللہ لوگوں پر فضل والا ہے لیکن بہت آدمی شکر نہیں کرتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4195, 40, 62, N'وہ ہے اللہ تمہارا رب ہر چیز کا بنانے والا اس کے سوا کسی کی بندگی نہیں تو کہاں اوندھے جاتے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4196, 40, 63, N'یونہی اوندھے ہوتے ہیں وہ جو اللہ کی آیتوں کا انکار کرتے ہیں')
