INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4197, 40, 64, N'اللہ ہے جس نے تمہارے لیے زمین ٹھہراؤ بنائی اور آسمان چھت اور تمہاری تصویر کی تو تمہاری صورتیں اچھی بنائیں اور تمہیں ستھری چیزیں روزی دیں یہ ہے اللہ تمہارا رب، تو بڑی برکت والا ہے اللہ رب سارے جہان کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4198, 40, 65, N'وہی زندہ ہے اس کے سوا کسی کی بندگی نہیں تو اسے پوجو نرے اسی کے بندے ہوکر، سب خوبیاں اللہ کو جو سارے جہاں کا رب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4199, 40, 66, N'تم فرماؤ میں منع کیا گیا ہوں کہ انہیں پوجوں جنہیں تم اللہ کے سوا پوجتے ہو جبکہ میرے پاس روشن دلیلیں میرے رب کی طرف سے آئیں اور مجھے حکم ہوا ہے کہ رب العالمین کے حضور گردن رکھوں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4200, 40, 67, N'وہی ہے جس نے تمہیں مٹی سے بنایا پھر پانی کی بوند سے پھر خون کی پھٹک سے پھرتمہیں نکالتا ہے بچہ پھرتمہیں باقی رکھتا ہے کہ اپنی جوانی کو پہنچو پھر اس لیے کہ بوڑھے ہو اور تم میں کوئی پہلے ہی اٹھالیا جاتا ہے اور اس لیے کہ تم ایک مقرر وعدہ تک پہنچو اور اس لیے کہ سمجھو')
