INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4201, 40, 68, N'وہی ہے کہ جِلاتا ہے اور مارتا ہے پھر جب کوئی حکم فرماتا ہے تو اس سے یہی کہتا ہے کہ ہو جا جبھی وہ ہوجاتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4202, 40, 69, N'کیا تم نے انہیں نہ دیکھا جو اللہ کی آیتوں میں جھگڑے ہیں کہاں پھیرے جاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4203, 40, 70, N'وہ جنہوں نے جھٹلائی کتاب اور جو ہم نے اپنے رسولوں کے ساتھ بھیجا، ف۱۵۰) وہ عنقریب جان جائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4204, 40, 71, N'جب ان کی گردنوں میں طوق ہوں گے اور زنجیریں گھسیٹے جائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4205, 40, 72, N'کھولتے پانی میں، پھر آگ میں دہکائے جائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4206, 40, 73, N'پھر ان سے فرمایا جائے گا کہاں گئے وہ جو تم شریک بناتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4207, 40, 74, N'اللہ کے مقابل، کہیں گے وہ تو ہم سے گم گئے بلکہ ہم پہلے کچھ پوجتے ہی نہ تھے اللہ یونہی گمراہ کرتا ہے کافروں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4208, 40, 75, N'یہ اس کا بدلہ ہے جو تم زمین میں باطل پر خوش ہوتے تھے اور اس کا بدلہ ہے جو تم اتراتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4209, 40, 76, N'جاؤ جہنم کے دروازوں میں اس میں ہمیشہ رہنے، تو کیا ہی برا ٹھکانا مغروروں کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4210, 40, 77, N'تو تم صبر کرو بیشک اللہ کا وعدہ سچا ہے، تو اگر ہم تمہیں دکھادیں کچھ وہ چیز جس کا انہیں وعدہ دیا جاتا ہے یا تمہیں پہلے ہی وفات دیں بہرحال انہیں ہماری ہی طرف پھرنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4211, 40, 78, N'اور بیشک ہم نے تم سے پہلے کتنے رسول بھیجے کہ جن میں کسی کا احوال تم سے بیان فرمایا اور کسی کا احوال نہ بیان فرمایا اور کسی رسول کو نہیں پہنچتا کہ کوئی نشانی لے آئے بے حکم خدا کے، پھر جب اللہ کا حکم آئے گا سچا فیصلہ فرمادیا جائے گا اور باطل والوں کا وہاں خسارہ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4212, 40, 79, N'اللہ ہے جس نے تمہارے لیے چوپائے بنائے کہ کسی پر سوار ہو اور کسی کا گوشت کھاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4213, 40, 80, N'اور تمہارے لیے ان میں کتنے ہی فائدے ہیں اور اس لیے کہ تم ان کی پیٹھ پر اپنے دل کی مرادوں کو پہنچو اور ان پر اور کشتیوں پر سوار ہوتے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4214, 40, 81, N'اور وہ تمہیں اپنی نشانیاں دکھاتا ہے تو اللہ کی کونسی نشانی کا انکار کرو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4215, 40, 82, N'کیا انہوں نے زمین میں سفر نہ کیا کہ دیکھتے ان سے اگلوں کا کیسا انجام ہوا، وہ ان سے بہت تھے اور ان کی قوت اور زمین میں نشانیاں ان سے زیادہ تو ان کے کیا کام آیا جو انہوں نے کمایا،')
