INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4223, 41, 5, N'اور بولے ہمارے دل غلاف میں ہیں اس بات سے جس کی طرف تم ہمیں بلاتے ہو اور ہمارے کانوں میں ٹینٹ (روئی) ہے اور ہمارے اور تمہارے درمیان روک ہے تو تم اپنا کام کرو ہم اپنا کام کرتے ہیں')
