INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4228, 41, 10, N'اور اس میں اس کے اوپر سے لنگر ڈالے (بھاری بوجھ رکھے) اور اس میں برکت رکھی اور اس میں اس کے بسنے والوں کی روزیاں مقرر کیں یہ سب ملاکر چار دن میں ٹھیک جواب پوچھنے والوں کو،')
