INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4229, 41, 11, N'پھر آسمان کی طرف قصد فرمایا اور وہ دھواں تھا تو اس سے اور زمین سے فرمایا کہ دونوں حاضر ہو خوشی سے چاہے ناخوشی سے، دونوں نے عرض کی کہ ہم رغبت کے ساتھ حاضر ہوئے،')
