INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4231, 41, 13, N'پھر اگر وہ منہ پھیریں تو تم فرماؤ کہ میں تمہیں ڈراتا ہوں ایک کڑ ک سے جیسی کڑ ک عاد اور ثمود پر آئی تھی')
