INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4232, 41, 14, N'جب رسول ان کے آگے پیچھے پھرتے تھے کہ اللہ کے سوا کسی کو نہ پوجو، بولے ہمارا رب چاہتا تو فرشتے اتارتا تو جو کچھ تم لے کر بھیجے گئے ہم اسے نہیں مانتے')
