INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4233, 41, 15, N'تو وہ جو عاد تھے انہیں نے زمین میں ناحق تکبر کیا اور بولے ہم سے زیادہ کس کا زور، اور کیا انہوں نے نہ جانا کہ اللہ جس نے انہیں بنایا ان سے زیادہ قوی ہے، اور ہماری آیتوں کا انکار کرتے تھے،')
