INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4235, 41, 17, N'اور رہے ثمود انہیں ہم نے راہ دکھائی تو انہوں نے سوجھنے پر اندھے ہونے کو پسند کیا تو انہیں ذلت کے عذاب کی کڑ ک نے آ لیا سزا ان کے کیے کی')
