INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4238, 41, 20, N'یہاں تک کہ پچھلے آ ملیں یہاں تک کہ جب وہاں پہنچیں گے ان کے کان اور ان کی آنکھیں اور ان کے چمڑے سب ان پر ان کے کیے کی گواہی دیں گے')
