INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4243, 41, 25, N'اور ہم نے ان پر کچھ ساتھی تعینات کیے انہوں نے انہیں بھلا کردیا جو ان کے آگے ہے اور جو ان کے پیچھے اور ان پر بات پوری ہوئی ان گروہوں کے ساتھ جو ان سے پہلے گزر چکے جن اور آدمیوں کے، بیشک وہ زیاں کار تھے،')
