INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4247, 41, 29, N'اور کافر بولے اے ہمارے رب ہمیں دکھا وہ دونوں جن اور آدمی جنہوں نے ہمیں گمراہ کیا کہ ہم انہیں اپنے پاؤں تلے ڈالیں کہ وہ ہر نیچے سے نیچے رہیں')
