INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4252, 41, 34, N'اور نیکی اور بدی برابر نہ ہوجائیں گی، اے سننے والے برائی کو بھلائی سے ٹال جبھی وہ کہ تجھ میں اور اس میں دشمنی تھی ایسا ہوجائے گا جیسا کہ گہرا دوست')
