INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4254, 41, 36, N'اور اگر تجھے شیطان کا کوئی کونچا (تکلیف) پہنچے تو اللہ کی پناہ مانگ بیشک وہی سنتا جانتا ہے،')
