INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4255, 41, 37, N'اور اس کی نشانیوں میں سے ہیں رات اور دن اور سورج اور چاند سجدہ نہ کرو سورج کو اور نہ چاند کو اور اللہ کو سجدہ کرو جس نے انہیں پیدا کیا اگر تم اس کے بندے ہو،')
