INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4256, 41, 38, N'تو اگر یہ تکبر کریں تو وہ جو تمہارے رب کے پاس ہیں رات دن اس کی پاکی بولتے ہیں اور اکتاتے نہیں، السجدة ۔۱۱)')
