INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4257, 41, 39, N'اور اس کی نشانیوں سے ہے کہ تو زمین کو دیکھے بے قدر پڑی پھر جب ہم نے اس پر پانی اتارا تر و تازہ ہوئی اور بڑھ چلی، بیشک جس نے اسے جِلایا ضرور مردے جِلائے گا، بیشک وہ سب کچھ کرسکتا ہے،')
