INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4258, 41, 40, N'بیشک وہ جو ہماری آیتوں میں ٹیڑھے چلتے ہیں ہم سے چھپے نہیں تو کیا جو آ گ میں ڈالا جائے گا وہ بھلا، یا جو قیامت میں امان سے آئے گا جو جی میں آئے کرو بیشک وہ تمہارے کام دیکھ رہا ہے،')
