INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4259, 41, 41, N'بیشک جو ذکر سے منکر ہوئے جب وہ ان کے پاس آیا ان کی خرابی کا کچھ حال نہ پوچھ، اور بیشک وہ عزت والی کتاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4260, 41, 42, N'باطل کو اس کی طرف راہ نہیں نہ اس کے آگے سے نہ اس کے پیچھے سے اتارا ہوا ہے حکمت والے سب خوبیوں سراہے کا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4261, 41, 43, N'تم سے نہ فرمایا جائے مگر وہی جو تم سے اگلے رسولوں کو فرمایا، کہ بیشک تمہارا رب بخشش والا اور دردناک عذاب والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4262, 41, 44, N'اور اگر ہم اسے عجمی زبان کا قرآن کرتے تو ضرور کہتے کہ اس کی آیتیں کیوں نہ کھولی گئیں کیا کتاب عجمی اور نبی عربی تم فرماؤ وہ ایمان والوں کے لیے ہدایت اور شفا ہے اور وہ جو ایمان نہیں لاتے ان کے کانوں میں ٹینٹ (روئی) ہے اور وہ ان پر اندھا پن ہے گویا وہ دور جگہ سے پکارے جاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4263, 41, 45, N'اور بیشک ہم نے موسیٰ کو کتاب عطا فرمائی تو اس میں اختلاف کیا گیا اور اگر ایک بات تمہارے رب کی طرف سے گزر نہ چکی ہوتی تو جبھی ان کا فیصلہ ہوجاتا اور بیشک وہ ضرور اس کی طرف سے ایک دھوکا ڈالنے والے شک میں ہیں،')
