INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4265, 41, 47, N'قیامت کے علم کا اسی پر حوالہ ہے اور کوئی پھل اپنے غلاف سے نہیں نکلتا اور نہ کسی مادہ کو پیٹ رہے اور نہ جنے مگر اس کے علم سے اور جس دن انہیں ندا فرمائے گا کہاں ہیں میرے شریک کہیں گے ہم تجھ سے کہہ چکے ہیں کہ ہم میں کوئی گواہ نہیں')
