INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4284, 42, 12, N'اسی کے لیے ہیں آسمانوں اور زمین کی کنجیاں روزی وسیع کرتا ہے جس کے لیے چاہے اور تنگ فرماتا ہے بیشک وہ سب کچھ جانتا ہے،')
