INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4285, 42, 13, N'تمہارے لیے دین کی وہ راہ ڈالی جس کا حکم اس نے نوح کو دیا اور جو ہم نے تمہاری طرف وحی کی اور جس کا حکم ہم نے ابراہیم اور موسیٰ اور عیسیٰ کو دیا کہ دین ٹھیک رکھو اور اس میں پھوٹ نہ ڈالو مشرکوں پر بہت ہی گراں ہے وہ جس کی طرف تم انہیں بلاتے ہو، اور اللہ اپنے قریب کے لیے چن لیتا ہے جسے چاہے اور اپنی طرف راہ دیتا ہے اسے جو رجوع لائے')
