INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4286, 42, 14, N'اور انہوں نے پھوٹ نہ ڈالی مگر بعد اس کے کہ انہیں علم آچکا تھا آپس کے حسد سے اور اگر تمہارے رب کی ایک بات گزر نہ چکی ہوتی ایک مقرر میعاد تک تو کب کا ان میں فیصلہ کردیا ہوتا اور بیشک وہ جو ان کے بعد کتاب کے وارث ہوئے وہ اس سے ایک دھوکا ڈالنے والے شک میں ہیں')
