INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4287, 42, 15, N'تو اسی لیے بلاؤ اور ثابت قدم رہو جیسا تمہیں حکم ہوا ہے اور ان کی خواہشوں پر نہ چلو اور کہو کہ میں ایمان لایا اس پر جو کوئی کتاب اللہ نے اتاری اور مجھے حکم ہے کہ میں تم میں انصاف کروں اللہ ہمارا اور تمہارا سب کا رب ہے ہمارے لیے ہمارا عمل اور تمہارے لیے تمہارا کیا کوئی حجت نہیں ہم میں اور تم میں اللہ ہم سب کو جمع کرے گا اور اسی کی طرف پھرنا ہے،')
