INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4288, 42, 16, N'اور وہ جو اللہ کے بارے میں جھگڑتے ہیں بعد اس کے کہ مسلمان اس کی دعوت قبول کرچکے ہیں ان کی دلیل محض بے ثبات ہے ان کے رب کے پاس اور ان پر غضب ہے اور ان کے لیے سخت عذاب ہے')
