INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4290, 42, 18, N'اس کی جلدی مچارہے ہیں وہ جو اس پر ایمان نہیں رکھتے اور جنہیں اس پر ایمان ہے وہ اس سے ڈر رہے ہیں اورجانتے ہیں کہ بیشک وہ حق ہے، سنتے ہو بیشک جو قیامت میں شک کرتے ہیں ضرور دُور کی گمراہی میں ہیں،')
