INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4292, 42, 20, N'جو آخرت کی کھیتی چاہے ہم اس کے لیے اس کی کھیتی بڑھائیں اور جو دنیا کی کھیتی چاہے ہم اسے اس میں سے کچھ دیں گے اور آخرت میں اس کا کچھ حصہ نہیں')
