INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4293, 42, 21, N'یا ان کے لیے کچھ شریک ہیں جنہوں نے ان کے لیے وہ دین نکال دیا ہے کہ اللہ نے اس کی اجازت نہ دی اور اگر ایک فیصلہ کا وعدہ نہ ہوتا تو یہیں ان میں فیصلہ کردیا جاتا اور بیشک ظالموں کے لیے دردناک عذاب ہے')
