INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4294, 42, 22, N'تم ظالموں کو دیکھو گے کہ اپنی کمائیوں سے سہمے ہوئے ہوں گے اور وہ ان پر پڑ کر رہیں گی اور جو ایمان لائے اور اچھے کام کیے وہ جنت کی پھلواریوں میں ہیں، ان کے لیے ان کے رب کے پاس ہے جو چاہیں، یہی بڑا فضل ہے،')
