INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4296, 42, 24, N'یا یہ کہتے ہیں کہ انہوں نے اللہ پر جھوٹ باندھ لیا اور اللہ چاہے تو تمہارے اوپر اپنی رحمت و حفاظت کی مہر فرمادے اور مٹا تا ہے باطل کو اور حق کو ثابت فرماتا ہے اپنی باتوں سے بیشک وہ دلوں کی باتیں جانتا ہے،')
