INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4297, 42, 25, N'اور وہی ہے جو اپنے بندوں کی توبہ قبول فرماتا اور گناہوں سے درگزر فرماتا ہے اور جانتا ہے جو کچھ تم کرتے ہو،')
