INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4299, 42, 27, N'اور اگر اللہ اپنے سب بندوں کا رزق وسیع کردیتا تو ضرور زمین میں فساد پھیلاتے لیکن وہ اندازہ سے اتارتا ہے جتنا چاہے، بیشک وہ بندوں سے خبردار ہے انہیں دیکھتا ہے،')
