INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4300, 42, 28, N'اور وہی ہے کہ مینہ اتارتا ہے ان کے نا امید ہونے پر اور اپنی رحمت پھیلاتا ہے اور وہی کام بنانے والا ہے سب خوبیوں سراہا،')
