INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4301, 42, 29, N'اور اس کی نشانیوں سے ہے آسمانوں اور زمین کی پیدائش اور جو چلنے والے ان میں پھیلائے، اور وہ ان کے اکٹھا کرنے پر جب چاہے قادر ہے،')
