INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4302, 42, 30, N'اور تمہیں جو مصیبت پہنچی وہ اس کے سبب سے ہے جو تمہارے ہاتھوں نے کمایا اور بہت کچھ تو معاف فرمادیتا ہے،')
