INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4303, 42, 31, N'اور تم زمین میں قابو سے نہیں نکل سکتے اور نہ اللہ کے مقابل تمہارا کوئی دوست نہ مددگار')
