INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4304, 42, 32, N'اور اس کی نشانیوں سے ہیں دریا میں چلنے والیاں جیسے پہاڑیاں،')
