INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4305, 42, 33, N'وہ چاہے تو ہوا تھما دے اس کی پیٹھ پر ٹھہری رہ جائیں بیشک اس میں ضرور نشانیاں ہیں ہر بڑے صابر شاکر کو')
