INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4306, 42, 34, N'یا انہیں تباہ کردے لوگوں کے گناہوں کے سبب اور بہت معاف فرمادے')
