INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4315, 42, 43, N'اور بیشک جس نے صبر کیا اور بخش دیا تو یہ ضرور ہمت کے کام ہیں،')
