INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4363, 43, 38, N'یہاں تک کہ جب کافر ہمارے پاس آئے گا اپنے شیطان سے کہے گا ہائے کسی طرح مجھ میں تجھ میں پورب پچھم کا فاصلہ ہوتا تو کیا ہی برا ساتھی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4364, 43, 39, N'اور ہرگز تمہارا اس سے بھلا نہ ہوگا آج جبکہ تم نے ظلم کیا کہ تم سب عذاب میں شریک ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4365, 43, 40, N'تو کیا تم بہروں کو سناؤ گے یا اندھوں کو راہ دکھاؤ گے اور انہیں جو کھلی گمراہی میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4366, 43, 41, N'تو اگر ہم تمہیں لے جائیں تو ان سے ہم ضرور بدلہ لیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4367, 43, 42, N'یا تمہیں دکھادیں جس کا انہیں ہم نے وعدہ دیا ہے تو ہم ان پر بڑی قدرت والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4368, 43, 43, N'تو مضبوط تھامے رہو اسے جو تمہاری طرف وحی کی گئی بیشک تم سیدھی راہ پر ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4369, 43, 44, N'اور بیشک وہ شرف ہے تمہارے لیے اور تمہاری قوم کے لیے اور عنقریب تم سے پوچھا جائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4370, 43, 45, N'اور ان سے پوچھو جو ہم نے تم سے پہلے رسول بھیجے کیا ہم نے رحمان کے سوا کچھ اور خدا ٹھہرائے جن کو پوجا ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4371, 43, 46, N'اور بیشک ہم نے موسیٰ کو اپنی نشایوں کے ساتھ فرعون اور اس کے سرداروں کی طرف بھیجا تو اس نے فرمایا بیشک میں اس کا رسول ہوں جو سارے جہاں کا مالک ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4372, 43, 47, N'پھر جب وہ ان کے پاس ہماری نشانیاں لایا جبھی وہ ان پر ہنسنے لگے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4373, 43, 48, N'اور ہم انہیں جو نشانی دکھاتے وہ پہلے سے بڑی ہوتی اور ہم نے انہیں مصیبت میں گرفتار کیا کہ وہ بام آئیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4374, 43, 49, N'اور بولے کہ اے جادوگر ہمارے لیے اپنے رب سے دعا کر کہ اس عہد کے سبب جو اس کا تیرے پاس ہے بیشک ہم ہدایت پر آئیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4375, 43, 50, N'پھر جب ہم نے ان سے وہ مصیبت ٹال دی جبھی وہ عہد توڑ گئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4376, 43, 51, N'اور فرعون اپنی قوم میں پکارا کہ اے میری قوم! کیا میرے لیے مصر کی سلطنت نہیں اور یہ نہریں کہ میرے نیچے بہتی ہیں تو کیا تم دیکھتے نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4377, 43, 52, N'یا میں بہتر ہوں اس سے کہ ذلیل ہے اور بات صاف کرتا معلوم نہیں ہوتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4378, 43, 53, N'تو اس پر کیوں نہ ڈالے گئے سونے کے کنگن یا اس کے ساتھ فرشتے آتے کہ اس کے پاس رہتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4379, 43, 54, N'پھر اس نے اپنی قوم کو کم عقل کرلیا تو وہ اس کے کہنے پر چلے بیشک وہ بے حکم لوگ تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4380, 43, 55, N'پھر جب انہوں نے وہ کیا جس پر ہمارا غضب ان پر آیا ہم نے ان سے بدلہ لیا تو ہم نے ان سب کو ڈبودیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4381, 43, 56, N'انہیں ہم نے کردیا اگلی داستان اور کہاوت پچھلوں کے لیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4382, 43, 57, N'اور جب ابنِ مریم کی مثال بیان کی جائے، جبھی تمہاری قوم اس سے ہنسنے لگتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4383, 43, 58, N'اور کہتے ہیں کیا ہمارے معبود بہتر ہیں یا وہ انہوں نے تم سے یہ نہ کہی مگر ناحق جھگڑے کو بلکہ وہ ہیں جھگڑالو لوگ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4384, 43, 59, N'وہ تو نہیں مگر ایک بندہ جس پر ہم نے احسان فرمایا اور اسے ہم نے بنی اسرائیل کے لیے عجیب نمونہ بنایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4385, 43, 60, N'اور اگر ہم چاہتے تو زمین میں تمہارے بدلے فرشتے بساتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4386, 43, 61, N'اور بیشک عیسی ٰ قیامت کی خبر ہے تو ہرگز قیامت میں شک نہ کرنا اور میرے پیرو ہونا یہ سیدھی راہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4387, 43, 62, N'اور ہرگز شیطان تمہیں نہ روک دے بیشک وہ تمہارا کھلا دشمن ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4388, 43, 63, N'اور جب عیسیٰ روشن نشانیاں لایا اس نے فرمایا میں تمہارے پاس حکمت لے کر آیا اور اس لیے میں تم سے بیان کردوں بعض وہ باتیں جن میں تم اختلاف رکھتے ہو تو اللہ سے ڈرو اور میرا حکم مانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4389, 43, 64, N'بیشک اللہ میرا رب اور تمہارا رب تو اسے پوجو، یہ سیدھی راہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4390, 43, 65, N'پھر وہ گروہ آپس میں مختلف ہوگئے تو ظالموں کی خرابی ہے ایک درد ناک دن کے عذاب سے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4391, 43, 66, N'کاہے کے انتظار میں ہیں مگر قیامت کے کہ ان پر اچانک آجائے اور انہیں خبر نہ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4392, 43, 67, N'گہرے دوست اس دن ایک دوسرے کے دشمن ہوں گے مگر پرہیزگار')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4393, 43, 68, N'ان سے فرمایا جائے گا اے میرے بندو آج نہ تم پر خوف نہ تم کو غم ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4394, 43, 69, N'وہ جو ہماری آیتوں پر ایمان لائے اور مسلمان تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4395, 43, 70, N'داخل ہو جنت میں تم اور تمہاری بیبیاں اور تمہاری خاطریں ہوتیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4396, 43, 71, N'ان پر دورہ ہوگا سونے کے پیالوں اور جاموں کا اور اس میں جو جی چاہے اور جس سے آنکھ کو لذت پہنچے اور تم اس میں ہمیشہ رہو گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4397, 43, 72, N'اور یہ ہے وہ جنت جس کے تم وارث کیے گئے اپنے اعمال سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4398, 43, 73, N'تمہارے لیے اس میں بہت میوے ہیں کہ ان میں سے کھاؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4399, 43, 74, N'بیشک مجرم جہنم کے عذاب میں ہمیشہ رہنے والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4400, 43, 75, N'وہ کبھی ان پر سے ہلکا نہ پڑے گا اور وہ اس میں بے آ س رہیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4401, 43, 76, N'اور ہم نے ان پر کچھ ظلم نہ کیا، ہاں وہ خود ہی ظالم تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4402, 43, 77, N'اور وہ پکاریں گے اے مالک تیرا رب ہمیں تمام کرچکے وہ فرمائے گا تمہیں تو ٹھہرنا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4403, 43, 78, N'بیشک ہم تمہارے پاس حق لائے مگر تم میں اکثر کو حق ناگوار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4404, 43, 79, N'کیا انہوں نے اپنے خیال میں کوئی کام پکا کرلیا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4405, 43, 80, N'تو ہم اپنا کام پکا کرنے والے ہیں کیا اس گھمنڈ میں ہیں کہ ہم ان کی آہستہ بات اور ان کی مشورت نہیں سنتے، ہاں کیوں نہیں اور ہمارے فرشتے ان کے پاس لکھ رہے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4406, 43, 81, N'تم فرماؤ بفرض محال رحمٰن کے کوئی بچہ ہوتا، تو سب سے پہلے میں پوجتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4407, 43, 82, N'پاکی ہے آسمانوں اور زمین کے رب کو، عرش کے رب کو ان باتوں سے جو یہ بناتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4408, 43, 83, N'تو تم انہیں چھوڑو کہ بیہودہ باتیں کریں اور کھیلیں یہاں تک کہ اپنے اس دن کو پائیں جس کا ان سے وعدہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4409, 43, 84, N'اور وہی آسمان والوں کا خدا اور زمین والوں کا خدا اور وہی حکمت و علم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4410, 43, 85, N'اور بڑی برکت والا ہے وہ کہ اسی کے لیے ہے سلطنت آسمانوں اور زمین کی اور جو کچھ ان کے درمیان ہے اور اسی کے پاس ہے قیامت کا علم، اور تمہیں اس کی طرف پھرنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4411, 43, 86, N'اور جن کو یہ اللہ کے سوا پوجتے ہیں شفاعت کا اختیار نہیں رکھتے، ہاں شفاعت کا اختیار انہیں ہے جو حق کی گواہی دیں اور علم رکھیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4412, 43, 87, N'اور اگر تم ان سے پوچھو انہیں کس نے پیدا کیا تو ضرور کہیں گے اللہ نے تو کہاں اوندھے جاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4413, 43, 88, N'مجھے رسول کے اس کہنے کی قسم کہ اے میرے رب! یہ لوگ ایمان نہیں لاتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4414, 43, 89, N'تو ان سے درگزر کرو اور فرماؤ بس سلام ہے کہ آگے جان جائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4415, 44, 1, N'حٰمٓ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4416, 44, 2, N'قسم اس روشن کتاب کی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4417, 44, 3, N'بیشک ہم نے اسے برکت والی رات میں اتارا بیشک ہم ڈر سنانے والے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4418, 44, 4, N'اس میں بانٹ دیا جاتا ہے ہر حکمت والا کام')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4419, 44, 5, N'ہمارے پاس کے حکم سے، بیشک ہم بھیجنے والے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4420, 44, 6, N'تمہارے رب کی طرف سے رحمت، بیشک وہی سنتا جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4421, 44, 7, N'وہ جو رب ہے آسمانوں اور زمین کا اور جو کچھ ان کے درمیان ہے، اگر تمہیں یقین ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4422, 44, 8, N'اس کے سوا کسی کی بندگی نہیں وہ جِلائے اور مارے، تمہارا رب اور تمہارے اگلے باپ دادا کا رب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4423, 44, 9, N'بلکہ وہ شک میں پڑے کھیل رہے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4424, 44, 10, N'تو تم اس دن کے منتظر رہو جب آسمان ایک ظاہر دھواں لائے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4425, 44, 11, N'کہ لوگوں کو ڈھانپ لے گا یہ ہے دردناک عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4426, 44, 12, N'اس دن کہیں گے، اے ہمارے رب! ہم پر سے عذاب کھول دے ہم ایمان لاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4427, 44, 13, N'کہاں سے ہو انہیں نصیحت ماننا حالانکہ ان کے پاس صاف بیان فرمانے والا رسول تشریف لاچکا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4428, 44, 14, N'اس سے روگرداں ہوئے اور بولے سکھایا ہوا دیوانہ ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4429, 44, 15, N'ہم کچھ دنوں کو عذاب کھولے دیتے ہیں تم پھر وہی کرو گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4430, 44, 16, N'جس دن ہم سب سے بڑی پکڑ پکڑیں گے بیشک ہم بدلہ لینے والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4431, 44, 17, N'اور بیشک ہم نے ان سے پہلے فرعون کی قوم کو جانچا اور ان کے پاس ایک معزز رسول تشریف لایا')
GO
