INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4502, 45, 29, N'ہمارا یہ نوشتہ تم پر حق بولتا ہے، ہم لکھتے رہے تھے جو تم نے کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4503, 45, 30, N'تو وہ جو ایمان لائے اور اچھے کام کیے ان کا رب انہیں اپنی رحمت میں لے گا یہی کھلی کامیابی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4504, 45, 31, N'اور جو کافر ہوئے ان سے فرمایا جائے گا، کیا نہ تھا کہ میری آیتیں تم پر پڑھی جاتی تھیں تو تم تکبر کرتے تھے اور تم مجرم لوگ تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4505, 45, 32, N'اور جب کہا جاتا بیشک اللہ کا وعدہ سچا ہے اور قیامت میں شک نہیں تم کہتے ہم نہیں جانتے قیامت کیا چیز ہے ہمیں تو یونہی کچھ گمان سا ہوتا ہے اور ہمیں یقین نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4506, 45, 33, N'اور ان پر کھل گئیں ان کے کاموں کی برائیاں اور انہیں گھیرلیا اس عذاب نے جس کی ہنسی بناتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4507, 45, 34, N'اور فرمایا جائے گا آج ہم تمہیں چھوڑدیں گے جیسے تم اپنے اس دن کے ملنے کو بھولے ہوئے تھے اور تمہارا ٹھکانا آ گ ہے اور تمہارا کوئی مددگار نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4508, 45, 35, N'یہ اس لیے کہ تم نے اللہ کی آیتوں کا ٹھٹھا (مذاق) بنایا اور دنیا کی زندگی نے تمہیں فریب دیا تو آج نہ وہ آگ سے نکالے جائیں اور نہ ان سے کوئی منانا چاہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4509, 45, 36, N'تو اللہ ہی کے لیے سب خوبیاں ہیں آسمانوں کا رب اور زمین کا رب اور سارے جہاں کا رب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4510, 45, 37, N'اور اسی کے لیے بڑائی ہے آسمانوں اور زمین میں، اور وہی عزت و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4511, 46, 1, N'حٰمٓ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4512, 46, 2, N'یہ کتاب اتارنا ہے اللہ عزت و حکمت والے کی طرف سے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4513, 46, 3, N'ہم نے نہ بنائے آسمان اور زمین اور جو کچھ ان کے درمیان ہے مگر حق کے ساتھ اور ایک مقرر میعاد پر اور کافر اس چیز سے کہ ڈرائے گئے منہ پھیرے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4514, 46, 4, N'تم فرماؤ بھلا بتاؤ تو وہ جو تم اللہ کے سوا پوجتے ہو مجھے دکھاؤ انہوں نے زمین کا کون سا ذرہ بنایا یا آسمان میں ان کا کوئی حصہ ہے، میرے پاس لاؤ اس سے پہلی کوئی کتاب یا کچھ بچا کھچا علم اگر تم سچے ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4515, 46, 5, N'اور اس سے بڑھ کر گمراہ کون جو اللہ کے سوا ایسوں کو پوجے جو قیامت تک اس کی نہ سنیں اور انہیں ان کی پوجا کی خبر تک نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4516, 46, 6, N'اور جب لوگوں کا حشر ہوگا وہ ان کے دشمن ہوں گے اور ان سے منکر ہوجائیں گے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4517, 46, 7, N'اور جب ان پر پڑھی جائیں ہماری روشن آیتیں تو کافر اپنے پاس آئے ہوئے حق کو کہتے ہیں یہ کھلا جادو ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4518, 46, 8, N'کیا کہتے ہیں انہوں نے اسے جی سے بنایا تم فرماؤ اگر میں نے اسے جی سے بنالیا ہوگا تو تم اللہ کے سامنے میرا کچھ اختیار نہیں رکھتے وہ خوب جانتا ہے جن باتوں میں تم مشغول ہو اور وہ کافی ہے میرے اور تمہارے درمیان گواہ، اور وہی بخشنے والا مہربان ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4519, 46, 9, N'تم فرماؤ میں کوئی انوکھا رسول نہیں اور میں نہیں جانتا میرے ساتھ کیا کیا جائے گا اور تمہارے ساتھ کیا میں تو اسی کا تابع ہوں جو مجھے وحی ہوتی ہے اور میں نہیں مگر صاف ڈر سنانے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4520, 46, 10, N'تم فرماؤ بھلا دیکھو تو اگر وہ قرآن اللہ کے پاس سے ہو اور تم نے اس کا انکار کیا اور بنی اسرائیل کا ایک گواہ اس پر گواہی دے چکا تو وہ ایمان لایا اور تم نے تکبر کیا بیشک اللہ راہ نہیں دیتا ظالموں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4521, 46, 11, N'اور کافروں نے مسلمانوں کو کہا اگر اس میں کچھ بھلائی ہو تو یہ ہم سے آگے اس تک نہ پہنچ جاتے اور جب انہیں اس کی ہدایت نہ ہوئی تو اب کہیں گے کہ یہ پرانا بہتان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4522, 46, 12, N'اور اس سے پہلے موسیٰ کی کتاب سے پیشوا اور مہربانی، اور یہ کتاب ہے تصدیق فرماتی عربی زبان میں کہ ظالموں کو ڈر سنائے، اور نیکوں کو بشارت،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4523, 46, 13, N'بیشک وہ جنہوں نے کہا ہمارا رب اللہ ہے پھر ثابت قدم رہے نہ ان پر خوف نہ ان کو غم')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4524, 46, 14, N'وہ جنت والے ہیں ہمیشہ اس میں رہیں گے ان کے اعمال کا انعام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4525, 46, 15, N'اور ہم نے آدمی کو حکم کیا اپنے ماں باپ سے بھلائی کرے، ا س کی ماں نے اسے پیٹ میں رکھا تکلیف سے اور جنا اس کو تکلیف سے، اور اسے اٹھائے پھرنا اور اس کا دودھ چھڑانا تیس مہینے میں ہے یہاں تک کہ جب اپنے زور کو پہنچا اور چالیس برس کا ہوا عرض کی اے میرے رب! میرے دل میں ڈال کہ میں تیری نعمت کا شکر کروں جو تو نے مجھ پر اور میرے ماں باپ پر کی اور میں وہ کام کروں جو تجھے پسند آئے اور میرے لیے میری اولاد میں صلاح (نیکی) رکھ میں تیری طرف رجوع لایا اور میں مسلمان ہوں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4526, 46, 16, N'یہ ہیں وہ جن کی نیکیاں ہم قبول فرمائیں گے اور ان کی تقصیروں سے درگزر فرمائیں گے جنت والوں میں، سچا وعدہ جو انہیں دیا جاتا تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4527, 46, 17, N'اور وہ جس نے اپنے ماں باپ سے کہا اُف تم سے دل پک گیا (بیزار ہے) کیا مجھے یہ وعدہ دیتے ہو کہ پھر زندہ کیا جاؤں گا حالانکہ مجھ پر سے پہلے سنگتیں گزر چکیں اور وہ دونوں اللہ سے فریاد کرتے ہیں تیری خرابی ہو ایمان لا، بیشک اللہ کا وعدہ سچا ہے تو کہتا ہے یہ تو نہیں مگر اگلوں کی کہانیاں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4528, 46, 18, N'یہ وہ ہیں جن پر بات ثابت ہوچکی ان گروہوں میں جو ان سے پلے گزرے جن اور آدمی، بیشک وہ زیاں کار تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4529, 46, 19, N'اور ہر ایک کے لیے اپنے اپنے عمل کے درجے ہیں اور تاکہ اللہ ان کے کام انہیں پورے بھردے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4530, 46, 20, N'اور ان پر ظلم نہ ہوگا، اور جس دن کافر آگ پر پیش کیے جائیں گے، ان سے فرمایا جائے گا تم اپنے حصہ کی پاک چیزیں اپنی دنیا ہی کی زندگی میں فنا کرچکے اور انہیں برت چکے تو آج تمہیں ذلت کا عذاب بدلہ دیا جائے گا سزا اس کی کہ تم زمین میں ناحق تکبر کرتے تھے اور سزا اس کی کہ حکم عدولی کرتے تھے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4531, 46, 21, N'اور یاد کرو عاد کے ہم قوم کو جب اس نے ان کو سرزمینِ احقاف میں ڈرایا اور بیشک اس سے پہلے ڈر سنانے والے گزر چکے اور اس کے بعد آئے کہ اللہ کے سوا کسی کو نہ پُوجو، بیشک مجھے تم پر ایک بڑے دن کے عذاب کا اندیشہ ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4532, 46, 22, N'بولے کیا تم اس لیے آئے کہ ہمیں ہمارے معبودوں سے پھیر دو، تو ہم پر لاؤ جس کا ہمیں وعدہ دیتے ہو اگر تم سچے ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4533, 46, 23, N'اس نے فرمایا اس کی خبر تو اللہ ہی کے پاس ہے میں تو تمہیں اپنے رب کے پیام پہنچاتا ہوں ہاں میری دانست میں تم نرے جاہل لوگ ہو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4534, 46, 24, N'پھر جب انہوں نے عذاب کو دیکھا بادل کی طرح آسمان کے کنارے میں پھیلا ہوا ان کی وادیوں کی طرف آتا بولے یہ بادل ہے کہ ہم پر برسے گا بلکہ یہ تو وہ ہے جس کی تم جلدی مچاتے تھے، ایک آندھی ہے جس میں دردناک عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4535, 46, 25, N'ہر چیز کو تباہ کر ڈالتی ہے اپنے رب کے حکم سے تو صبح رہ گئے کہ نظر نہ آتے تھے مگر ان کے سُونے مکان، ہم ایسی ہی سزا دیتے ہیں مجرموں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4536, 46, 26, N'اور بیشک ہم نے انہیں وہ مقدور دیے تھے جو تم کو نہ دیے اور ان کے لیے کان اور آنکھ اور دل بنائے تو ان کے کام کان اور آنکھیں اور دل کچھ کام نہ آئے جبکہ وہ اللہ کی آیتوں کا انکار کرتے تھے اور انہیں گھیرلیا اس عذاب نے جس کی ہنسی بناتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4537, 46, 27, N'اور بیشک ہم نے ہلاک کردیں تمہارے آس پاس کی بستیاں اور طرح طرح کی نشانیاں لائے کہ وہ باز آئیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4538, 46, 28, N'تو کیوں نہ مدد کی ان کی جن کو انہوں نے اللہ کے سوا قرب حاصل کرنے کو خدا ٹھہرا رکھا تھا بلکہ وہ ان سے گم گئے اور یہ ان کا بہتان و افتراء ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4539, 46, 29, N'اور جبکہ ہم نے تمہاری طرف کتنے جن پھیرے کان لگا کر قرآن سنتے، پھر جب وہاں حاضر ہوئے آپس میں بولے خاموش رہو پھر جب پڑھنا ہوچکا اپنی قوم کی طرف ڈر سناتے پلٹے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4540, 46, 30, N'بولے اے ہماری قوم ہم نے ایک کتاب سنی کہ موسیٰ کے بعد اتاری گئی اگلی کتابوں کی تصدیق فرمائی حق اور سیدھی راہ دکھائی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4541, 46, 31, N'اے ہماری قوم! اللہ کے منادی کی بات مانو اور اس پر ایمان لاؤ کہ وہ تمہارے کچھ گناہ بخش دے اور تمہیں دردناک عذاب سے بچالے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4542, 46, 32, N'اور جو اللہ کے منادی کی بات نہ مانے وہ زمین میں قابو سے نکل کر جانے والا نہیں اور اللہ کے سامنے اس کا کوئی مددگار نہیں وہ کھلی گمراہی میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4543, 46, 33, N'کیا انہوں نے نہ جانا کہ وہ اللہ جس نے آسمان اور زمین بنائے اور ان کے بنانے میں نہ تھکا قادر ہے کہ مردے جِلائے، کیوں نہیں بیشک وہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4544, 46, 34, N'اور جس دن کافر آگ پر پیش کیے جائیں گے، ان سے فرمایا جائے گا کیا یہ حق نہیں کہیں گے کیوں نہیں ہمارے رب کی قسم، فرمایا جائے گا تو عذاب چکھو بدلہ اپنے کفر کا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4545, 46, 35, N'تو تم صبر کرو جیسا ہمت والے رسولوں نے صبر کیا اور ان کے لیے جلدی نہ کرو گویا وہ جس دن دیکھیں گے جو انہیں وعدہ دیا جاتا ہے دنیا میں نہ ٹھہرے تھے مگر دن کی ایک گھڑی بھر یہ پہنچانا ہے تو کون ہلاک کیے جائیں گے مگر بے حکم لوگ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4546, 47, 1, N'جنہوں نے کفر کیا اور اللہ کی راہ سے روکا اللہ نے ان کے عمل برباد کیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4547, 47, 2, N'اور ایمان لائے اور اچھے کام کیے اور اس پر ایمان لائے جو محمد پر اتارا گیا اور وہی ان کے رب کے پاس سے حق ہے اللہ نے ان کی برائیاں اتار دیں اور ان کی حالتیں سنوار دیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4548, 47, 3, N'یہ اس لیے کہ کافر باطل کے پیرو ہوئے اور ایمان والوں نے حق کی پیروی کی جو ان کے رب کی طرف سے ہے اللہ لوگوں سے ان کے احوال یونہی بیان فرماتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4549, 47, 4, N'تو جب کافروں سے تمہارا سامناہو تو گردنیں مارنا ہے یہاں تک کہ جب انہیں خوب قتل کرلو تو مضبوط باندھو، پھر اس کے بعد چاہے احسان کرکے چھوڑ دو چاہے فدیہ لے لو یہاں تک کہ لڑائی اپنابوجھ رکھ دے بات یہ ہے اوراللہ چاہتا تو آپ ہی اُن سے بدلہ لیتا مگر اس لئے تم میں ایک کو دوسرے سے جانچے اور جو اللہ کی راہ میں مارے گئے اللہ ہرگز ان کے عمل ضائع نہ فرمائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4550, 47, 5, N'جلد انہیں راہ دے گا اور ان کا کام بنادے گا،')
