INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4551, 47, 6, N'اور انہیں جنت میں لے جائے گا انہیں اس کی پہچان کرادی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4552, 47, 7, N'اے ایمان والو اگر تم دین خدا کی مدد کرو گے اللہ تمہاری مدد کرے گا اور تمہارے قدم جمادے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4553, 47, 8, N'اور جنہوں نے کفر کیا تو ان پر تباہی پڑے اور اللہ ان کے اعمال برباد کرے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4554, 47, 9, N'یہ اس لیے کہ انہیں ناگوار ہوا جو اللہ نے اتارا تو اللہ نے ان کا کیا دھرا اِکارت کیا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4555, 47, 10, N'تو کیا انہوں نے زمین میں سفر نہ کیا کہ دیکھتے ان سے اگلوں کا کیسا انجام ہوا، اللہ نے ان پر تباہی ڈالی اور ان کافروں کے لیے بھی ویسی کتنی ہی ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4556, 47, 11, N'یہ اس لیے کہ مسلمانوں کا مولیٰ اللہ ہے اور کافروں کا کوئی مولیٰ نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4557, 47, 12, N'بیشک اللہ داخل فرمائے گا انہیں جو ایمان لائے اور اچھے کام کیے باغوں میں جن کے نیچے نہریں رواں، اور کافر برتتے ہیں اور کھاتے ہیں جیسے چوپائے کھائیں اور آگ میں ان کا ٹھکانا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4558, 47, 13, N'اور کتنے ہی شہر کہ اس شہر سے قوت میں زیادہ تھے جس نے تمہیں تمہارے شہر سے باہر کیا، ہم نے انہیں ہلاک فرمایا تو ان کا کوئی مددگار نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4559, 47, 14, N'تو کیا جو اپنے رب کی طرف سے روشن دلیل پر ہو اُس جیسا ہوگا جس کے برے عمل اسے بھلے دکھائے گئے اور وہ اپنی خواہشوں کے پیچھے چلے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4560, 47, 15, N'احوال اس جنت کا جس کا وعدہ پرہیزگاروں سے ہے، اس میں ایسی پانی کی نہریں ہیں جو کبھی نہ بگڑے اور ایسے دودھ کی نہریں ہیں جس کا مزہ نہ بدلا اور ایسی شراب کی نہریں ہیں جس کے پینے میں لذت ہے اور ایسی شہد کی نہریں ہیں جو صاف کیا گیا اور ان کے لیے اس میں ہر قسم کے پھل ہیں، اور اپنے رب کی مغفرت کیا ایسے چین والے ان کی برابر ہوجائیں گے جنہیں ہمیشہ آگ میں رہنا اور انہیں کھولتا پانی پلایا جائے گا کہ آنتوں کے ٹکڑے ٹکڑے کردے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4561, 47, 16, N'اور ان میں سے بعض تمہارے ارشاد سنتے ہیں یہاں تک کہ جب تمہارے پاس سے نکل کر جائیں علم والوں سے کہتے ہیں ابھی انہوں نے کیا فرمایا یہ ہیں وہ جن کے دلوں پر اللہ نے مہر کردی اور اپنی خواہشوں کے تابع ہوئے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4562, 47, 17, N'اور جنہوں نے راہ پائی اللہ نے ان کی ہدایت اور زیادہ فرمائی اور ان کی پرہیزگاری انہیں عطا فرمائی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4563, 47, 18, N'تو کاہے کے انتظار میں ہیں مگر قیامت کے کہ ان پر اچانک آجائے، کہ اس کی علامتیں تو آہی چکی ہیں پھر جب آجائے گی تو کہاں وہ اور کہاں ان کا سمجھنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4564, 47, 19, N'تو جان لو کہ اللہ کے سوا کسی کی بندگی نہیں اور اے محبوب! اپنے خاصوں اور عام مسلمان مردوں اور عورتوں کے گناہوں کی معافی مانگو اور اللہ جانتا ہے دن کو تمہارا پھرنا اور رات کو تمہارا آرام لینا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4565, 47, 20, N'اور مسلمان کہتے ہیں کوئی سورت کیوں نہ اتاری گئی پھر جب کوئی پختہ سورت اتاری گئی اور اس میں جہاد کا حکم فرمایا گیا تو تم دیکھو گے انہیں جن کے دلوں میں بیماری ہے کہ تمہاری طرف اس کا دیکھنا دیکھتے ہیں جس پر مُرونی چھائی ہو، تو ان کے حق میں بہتر یہ تھا کہ فرمانبرداری کرتے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4566, 47, 21, N'اور اچھی بات کہتے پھر جب حکم ناطق ہوچکا تو اگر اللہ سے سچے رہتے تو ان کا بھلا تھا،')
GO
