INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4569, 47, 24, N'تو کیا وہ قرآن کو سوچتے نہیں یا بعضے دلوں پر ان کے قفل لگے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4570, 47, 25, N'بیشک وہ جو اپنے پیچھے پلٹ گئے بعد اس کے کہ ہدایت ان پر کھل چکی تھی شیطان نے انہیں فریب دیا اور انہیں دنیا میں مدتوں رہنے کی امید دلائی')
