INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4571, 47, 26, N'یہ اس لیے کہ انہوں نے کہا ان لوگوں سے جنہیں اللہ کا اتارا ہوا ناگوار ہے ایک کام میں ہم تمہاری مانیں گے اور اللہ ان کی چھپی ہوئی جانتا ہے،')
