INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4574, 47, 29, N'کیا جن کے دلوں میں بیماری ہے اس گھمنڈ میں ہیں کہ اللہ ان کے چھپے بَیر ظاہر نہ فرمائے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4575, 47, 30, N'اور اگر ہم چاہیں تو تمہیں ان کو دکھادیں کہ تم ان کی صورت سے پہچان لو اور ضرور تم انہیں بات کے اسلوب میں پہچان لو گے اور اللہ تمہارے عمل جانتا ہے')
