INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4577, 47, 32, N'بیشک وہ جنہوں نے کفر کیا اور اللہ کی راہ سے روکا اور رسول کی مخالفت کی بعد اس کے کہ ہدایت ان پر ظاہر ہوچکی تھی وہ ہرگز اللہ کو کچھ نقصان نہ پہچائیں گے، اور بہت جلد اللہ ان کا کیا دھرا اَکارت کردے گا')
