INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4578, 47, 33, N'اے ایمان والو اللہ کا حکم مانو اور رسول کا حکم مانو اور اپنے عمل باطل نہ کرو')
