INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4580, 47, 35, N'تو تم سستی نہ کرو اور آپ صلح کی طرف نہ بلاؤ اور تم ہی غالب آؤ گے، اور اللہ تمہارے ساتھ ہے اور وہ ہرگز تمہارے اعمال میں تمہیں نقصان نہ دے گا')
