INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4581, 47, 36, N'دنیا کی زندگی تو یہی کھیل کود ہے اور اگر تم ایمان لاؤ اور پرہیزگاری کرو تو وہ تم کو تمہارے ثواب عطا فرمائے گا اور کچھ تم سے تمہارے مال نہ مانگے گا')
