INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4585, 48, 2, N'تاکہ اللہ تمہارے سبب سے گناہ بخشے تمہارے اگلوں کے اور تمہارے پچھلوں کے اور اپنی نعمتیں تم پر تمام کردے اور تمہیں سیدھی راہ دکھادے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4586, 48, 3, N'اور اللہ تمہاری زبردست مدد فرمائے')
