GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4588, 48, 5, N'تاکہ ایمان والے مردوں اور ایمان والی عورتوں کو باغوں میں لے جائے جن کے نیچے نہریں رواں ہمیشہ ان میں رہیں اور انکی برائیاں ان سے اتار دے، اور یہ اللہ کے یہاں بڑی کامیابی ہے،')
