INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4589, 48, 6, N'اور عذاب دے منافق مَردوں اور منافق عورتوں اور مشرک مَردوں اور مشرک عورتوں کو جو اللہ پر گمان رکھتے ہیں انہیں پر ہے بری گردش اور اللہ نے اُن پر غضب فرمایا اور انہیں لعنت کی اور ان کے لیے جہنم تیار فرمایا، اور وہ کیا ہی برا انجام ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4590, 48, 7, N'اور اللہ ہی کی ملک ہیں آسمانوں اور زمین کے سب لشکر، اور اللہ عزت و حکمت والا ہے،')
