INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4591, 48, 8, N'بیشک ہم نے تمہیں بھیجا حاضر و ناظر اور خوشی اور ڈر سناتا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4592, 48, 9, N'تاکہ اے لوگو تم اللہ اور اس کے رسول پر ایمان لاؤ اور رسول کی تعظیم و توقیر کرو اور صبح و شام اللہ کی پاکی بولو')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4593, 48, 10, N'وہ جو تمہاری بیعت کرتے ہیں وہ تو اللہ ہی سے بیعت کرتے ہیں ان کے ہاتھوں پر اللہ کا ہاتھ ہے، تو جس نے عہد توڑا اس نے اپنے بڑے عہد کو توڑا اور جس نے پورا کیا وہ عہد جو اس نے اللہ سے کیا تھا تو بہت جلد اللہ اسے بڑا ثواب دے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4594, 48, 11, N'اب تم سے کہیں گے جو گنوار (اعرابی) پیچھے رہ گئے تھے کہ ہمیں ہمارے مال اور ہمارے گھر والوں نے مشغول رکھا اب حضور ہماری مغفرت چاہیں اپنی زبانوں سے وہ بات کہتے ہیں جو ان کے دلوں میں نہیں تم فرماؤ تو اللہ کے سامنے کسے تمہارا کچھ اختیار ہے اگر وہ تمہارا برا چاہے یا تمہاری بھلائی کا ارادہ فرمائے، بلکہ اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4595, 48, 12, N'بلکہ تم تو یہ سمجھے ہوئے تھے کہ رسول اور مسلمان ہرگز گھروں کو واپس نہ آئیں گے اور اسی کو اپنے دلوں میں بھلا سمجھیں ہوئے تھے اور تم نے برا گمان کیا اور تم ہلاک ہونے والے لوگ تھے')
