INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4598, 48, 15, N'اب کہیں گے پیچھے بیٹھ رہنے والے جب تم غنیمتیں لینے چلو تو ہمیں بھی اپنے پیچھے آنے دو وہ چاہتے ہیں اللہ کا کلام بدل دیں تم فرماؤ ہرگز ہمارے ساتھ نہ آؤ اللہ نے پہلے سے یونہی فرمادیا تو اب کہیں گے بلکہ تم ہم سے جلتے ہو بلکہ وہ بات نہ سمجھتے تھے مگر تھوڑی')
