INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4601, 48, 18, N'بیشک اللہ راضی ہوا ایمان والوں سے جب وہ اس پیڑ کے نیچے تمہاری بیعت کرتے تھے تو اللہ نے جانا جو ان کے دلوں میں ہے تو ان پر اطمینان اتارا اور انہیں جلد آنے والی فتح کا انعام دیا')
