INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4607, 48, 24, N'اور وہی ہے جس نے ان کے ہاتھ تم سے روک دیے اور تمہارے ہاتھ ان سے روک دیے وادی مکہ میں بعد اس کے کہ تمہیں ان پر قابو دے دیا تھا، اور اللہ تمہارے کام دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4608, 48, 25, N'وہ وہ ہیں جنہوں نے کفر کیا اور تمہیں مسجدِ حرام سے روکا اور قربانی کے جانور رُکے پڑے اپنی جگہ پہنچنے سے اور اگر یہ نہ ہوتا کچھ مسلمان مرد اور کچھ مسلمان عورتیں جن کی تمہیں خبر نہیں کہیں تم انہیں روند ڈالو تو تمہیں ان کی طرف سے انجانی میں کوئی مکروہ پہنچے تو ہم تمہیں ان کی قتال کی اجازت دیتے ان کا یہ بچاؤ اس لیے ہے کہ اللہ اپنی رحمت میں داخل کرے جسے چاہے، اگر وہ جدا ہوجاتے تو ہم ضرور ان میں کے کافروں کو دردناک عذاب دیتے')
