INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4610, 48, 27, N'بیشک اللہ نے سچ کردیا اپنے رسول کا سچا خواب بیشک تم ضرور مسجد حرام میں داخل ہوگے اگر اللہ چاہے امن و امان سے اپنے سروں کے بال منڈاتے یا ترشواتے بے خوف، تو اس نے جانا جو تمہیں معلوم نیں تو اس سے پہلے ایک نزدیک آنے والی فتح رکھی')
