GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4612, 48, 29, N'محمد اللہ کے رسول ہیں، اور ان کے ساتھ والے کافروں پر سخت ہیں اور آپس میں نرم دل تو انہیں دیکھے گا رکوع کرتے سجدے میں گرتے اللہ کا فضل و رضا چاہتے، ان کی علامت ان کے چہروں میں ہے سجدوں کے نشان سے یہ ان کی صفت توریت میں ہے، اور ان کی صفت انجیل میں جیسے ایک کھیتی اس نے اپنا پٹھا نکالا پھر اسے طاقت دی پھر دبیز ہوئی پھر اپنی ساق پر سیدھی کھڑی ہوئی کسانوں کو بھلی لگتی ہے تاکہ ان سے کافروں کے دل جلیں، اللہ نے وعدہ کیا ان سے جو ان میں ایمان اور اچھے کاموں والے ہیں بخشش اور بڑے ثواب کا،')
GO
