INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4623, 49, 11, N'اے ایمان والو نہ مَرد مَردوں سے ہنسیں عجب نہیں کہ وہ ان ہنسنے والوں سے بہتر ہوں اور نہ عورتیں عورتوں سے، دور نہیں کہ وہ ان ہنسے والیوں سے بہتر ہوں اور آپس میں طعنہ نہ کرو اور ایک دوسرے کے برے نام نہ رکھو کیا ہی برا نام ہے مسلمان ہوکر فاسق کہلانا اور جو توبہ نہ کریں تو وہی ظالم ہیں،')
