INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4624, 49, 12, N'اے ایمان والو بہت گمانوں سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور عیب نہ ڈھونڈھو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں کوئی پسند رکھے گا کہ اپنے مرے بھائی کا گوشت کھائے تو یہ تمہیں گوارا نہ ہوگا اور اللہ سے ڈرو بیشک اللہ بہت توبہ قبول کرنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4625, 49, 13, N'اے لوگو! ہم نے تمہیں ایک مرد اورایک عورت سے پیدا کیا اور تمہیں شاخیں اور قبیلے کیا کہ آپس میں پہچان رکھو بیشک اللہ کے یہاں تم میں زیادہ عزت والا وہ جو تم میں زیادہ پرہیزگارہے بیشک اللہ جاننے والا خبردار ہے،')
