INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4626, 49, 14, N'گنوار بولے ہم ایمان لائے تم فرماؤ تم ایمان تو نہ لائے ہاں یوں کہوں کہ ہم مطیع ہوئے اور ابھی ایمان تمہارے دلوں میں کہاں داخل ہوا اور اگر تم اللہ اور اس کے رسول کی فرمانبرداری کرو گے تو تمہارے کسی عمل کا تمہیں نقصان نہ دے گا بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4627, 49, 15, N'ایمان والے تو وہی ہیں جو اللہ اور اس کے رسول پر ایمان لائے پھر شک نہ کیا اور اپنی جان اور مال سے اللہ کی راہ میں جہاد کیا وہی سچے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4628, 49, 16, N'تم فرماؤ کیا تم اللہ کو اپنا دین بتاتے ہو، اور اللہ جانتا ہے جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے اور اللہ سب کچھ جانتا ہے')
