INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4629, 49, 17, N'اے محبوب وہ تم پر احسان جتاتے ہیں کہ مسلمان ہوگئے، تم فرماؤ اپنے اسلام کا احسان مجھ پر نہ رکھو بلکہ اللہ تم پر احسان رکھتا ہے کہ اس نے تمہیں اسلام کی ہدایت کی اگر تم سچے ہو')
