INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (4630, 49, 18, N'بیشک اللہ جانتا ہے آسمانوں اور زمین کے سب غیب، اور اللہ تمہارے کام دیکھ رہا ہے')
