INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5078, 57, 3, N'وہی اول وہی آخر وہی ظاہر وہی باطن اور وہی سب کچھ جانتا ہے،')
