INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5079, 57, 4, N'وہی ہے جس نے آسمان اور زمین چھ دن میں پیدا کیے پھر عرش پر استوا فرمایا جیسا کہ اس کی شان کے لائق ہے، جانتا ہے جو زمین کے اندر جا تا ہے اور جو اس سے باہر نکلتا ہے اور جو آسمان سے اترتا ہے اور جو اس میں چڑھتا ہے اور وہ تمہارے ساتھ ہے تم کہیں ہو، اور اللہ تمہارے کام دیکھ رہا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5080, 57, 5, N'اسی کی ہے آسمانوں اور زمین کی سلطنت، اور اللہ ہی کی طرف، سب کاموں کی رجوع،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5081, 57, 6, N'رات کو دن کے حصے میں لاتا ہے اور دن کو رات کے حصے میں لاتا ہے اور وہ دلوں کی بات جانتا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5082, 57, 7, N'اللہ اور اس کے رسول پر ایمان لاؤ اور اس کی راہ میں کچھ وہ خرچ کرو جس میں تمہیں اَوروں کا جانشین کیا تو جو تم میں ایمان لائے اور اس کی راہ میں خرچ کیا ان کے لیے بڑا ثواب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5083, 57, 8, N'اور تمہیں کیا ہے کہ اللہ پر ایمان نہ لاؤ، حالانکہ یہ رسول تمہیں بلارہے ہیں کہ اپنے ر ب پر ایمان لاؤ اور بیشک وہ تم سے پہلے سے عہد لے چکا ہے اگر تمہیں یقین ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5084, 57, 9, N'وہی ہے کہ اپنے بندہ پر روشن آیتیں اتارتا ہے تاکہ تمہیں اندھیریوں سے اجالے کی طرف لے جائے اور بیشک ا لله تم پر ضرور مہربان رحم والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5085, 57, 10, N'اور تمہیں کیا ہے کہ اللہ کی راہ میں خرچ نہ کرو حالانکہ آسمانوں اور زمین میں سب کا وارث اللہ ہی ہے تم میں برابر نہیں وہ جنہوں نے فتحِ مکہ سے قبل خرچ اور جہاد کیا وہ مرتبہ میں ان سے بڑے ہیں جنہوں نے بعد فتح کے خرچ اور جہاد کیا، اور ان سب سے اللہ جنت کا وعدہ فرماچکا اور اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5086, 57, 11, N'کون ہے جو اللہ کو قرض دے اچھا قرض تو وہ اس کے لیے دونے کرے اور اللہ کو عزت کا ثواب دے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5087, 57, 12, N'جس دن تم ایمان والے مردوں اور ایمان والی عورتوں کو دیکھو گے کہ ان کا نور ہے ان کے آگے اور ان کے دہنے دوڑتا ہے ان سے فرمایا جارہا ہے کہ آج تمہاری سب سے زیادہ خوشی کی بات وہ جنتیں ہیں جن کے نیچے نہریں بہیں تم ان میں ہمیشہ رہو، یہی بڑی کامیابی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5088, 57, 13, N'جس دن منافق مرد اور منافق عورتیں مسلمانوں سے کہیں گے کہ ہمیں یک نگاہ دیکھو کہ ہم تمہارے نور سے کچھ حصہ لیں، کہا جائے گا اپنے پیچھے لوٹو (ُ۳۴) وہاں نور ڈھونڈو وہ لوٹیں گے، جبھی ان کے درمیان ایک دیوار کھڑی کردی جائے گی جس میں ایک دروازہ ہے اس کے اندر کی طرف رحمت اور اس کے باہر کی طرف عذاب،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5089, 57, 14, N'منافق مسلمانوں کو پکاریں گے کیا ہم تمہارے ساتھ نہ تھے وہ کہیں گے کیوں نہیں مگر تم نے تو اپنی جانیں فتنہ میں ڈالیں اور مسلمانوں کی برائی تکتے اور شک رکھتے اور جھوٹی طمع نے تمھیں فریب دیا یہاں تک کہ اللہ کا حکم آگیا اور تمہیں اللہ کے حکم پر اس بڑے فریبی نے مغرور رکھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5090, 57, 15, N'تو آج نہ تم سے کوئی فدیہ لیا جائے اور نہ کھلے کافروں سے، تمہارا ٹھکانا آگ ہے، وہ تمہاری رفیق ہے، اور کیا ہی برا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5091, 57, 16, N'کیا ایمان والوں کو ابھی وہ وقت نہ آیا کہ ان کے دل جھک جائیں اللہ کی یاد اور اس حق کے لیے جو اترا اور ان جیسے نہ ہوں جن کو پہلے کتاب دی گئی پھر ان پر مدت دراز ہوئی تو ان کے دل سخت ہوگئے اور ان میں بہت فاسق ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5092, 57, 17, N'جان لو کہ اللہ زمین کو زندہ کرتا ہے اس کے مرے پیچھے بیشک ہم نے تمہارے لیے نشانیاں بیان فرمادیں کہ تمہیں سمجھ ہو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5093, 57, 18, N'بیشک صدقہ دینے والے مرد اور صدقہ دینے والی عورتیں اور وہ جنہوں نے اللہ کو اچھا قرض دیا ان کے دونے ہیں اور ان کے لیے عزت کا ثواب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5094, 57, 19, N'اور وہ جو اللہ اور اس کے سب رسولوں پر ایمان لائیں وہی ہیں کامل سچے، اور اَوروں پر گواہ اپنے رب کے یہاں، ان کے لیے ان کا ثواب اور ان کا نور ہے اور جنہوں نے کفر کیا اور ہماری آیتیں جھٹلائیں وہ دوزخی ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5095, 57, 20, N'جان لو کہ دنیا کی زندگی تو نہیں مگر کھیل کود اور آرائش اور تمہارا آپس میں بڑائی مارنا اور مال اور اولاد میں ایک دوسرے پر زیادتی چاہنا اس مینھ کی طرح جس کا اُگایاسبزہ کسانوں کو بھایا پھر سوکھا کہ تو اسے زرد دیکھے پھر روندن (پامال کیا ہوا) ہوگیا اور آخرت میں سخت عذاب ہے اور اللہ کی طرف سے بخشش اور اس کی رضا اور دنیا کا جینا تو نہیں مگر دھوکے کا مال')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5096, 57, 21, N'بڑھ کر چلو اپنے رب کی بخشش اور اس جنت کی طرف جس کی چوڑائی جیسے آسمان اور زمین کا پھیلاؤ تیار ہوئی ہے ان کے لیے جو اللہ اور اس کے سب رسولوں پر ایمان لائے، یہ اللہ کا فضل ہے جسے چاہے دے، اور اللہ بڑا فضل والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5097, 57, 22, N'نہیں پہنچتی کوئی مصیبت زمین میں اور نہ تمہاری جانوں میں مگر وہ ایک کتاب میں ہے قبل اس کے کہ ہم اسے پیدا کریں بیشک یہ اللہ کو آسان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5098, 57, 23, N'اس لیے کہ غم نہ کھاؤ اس پر جو ہاتھ سے جائے اور خوش نہ ہو اس پر جو تم کو دیا اور اللہ کو نہیں کوئی اترونا (شیخی بگھارنے والا) بڑائی مارنے والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5099, 57, 24, N'وہ جو آپ بخل کریں اور اوروں سے بخل کو کہیں اور جو منہ پھیرے تو بیشک اللہ ہی بے نیاز ہے سب خوبیوں سراہا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5100, 57, 25, N'بیشک ہم نے اپنے رسولوں کو دلیلوں کے ساتھ بھیجا اور ان کے ساتھ کتاب اور عدل کی ترازو اتاری کہ لوگ انصاف پر قائم ہوں اور ہم نے لوہا اتارا اس میں سخت آنچ (نقصان) اور لوگوں کے فائدے اور اس لیے کہ اللہ دیکھے اس کو جو بے دیکھے اس کی اور اس کے رسولوں کی مدد کرتا ہے، بیشک اللہ قورت والا غالب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5101, 57, 26, N'اور بیشک ہم نے نوح اور ابراہیم کو بھیجا اور ان کی اولاد میں نبوت اور کتاب رکھی تو ان میں کوئی راہ پر آیا اور ان میں بہتیرے فاسق ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5102, 57, 27, N'پھر ہم نے ان کے پیچھے اسی راہ پر اپنے اور رسول بھیجے اور ان کے پیچھے عیسیٰ بن مریم کو بھیجا اور اسے انجیل عطا فرمائی اور اس کے پیروں کے دل میں نرمی اور رحمت رکھی اور راہب بننا تو یہ بات انہوں نے دین میں اپنی طرف سے نکالی ہم نے ان پر مقرر نہ کی تھی ہاں یہ بدعت انہوں نے ا لله کی رضا چاہنے کو پیدا کی پھر اسے نہ نباہا جیسا اس کے نباہنے کا حق تھا تو ان کے ایمان والوں کو ہم نے ان کا ثواب عطا کیا، اور ان میں سے بہتیرے فاسق ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5103, 57, 28, N'اے ایمان والو! اللہ سے ڈرو اور اس کے رسول پر ایمان لاؤ وہ اپنی رحمت کے دو حصے تمہیں عطا فرمائے گا اور تمہارے لیے نور کردے گا جس میں چلو اور تمہیں بخش دے گا، اور اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5104, 57, 29, N'یہ اس لیے کہ کتاب والے کافر جان جائیں کہ اللہ کے فضل پر ان کا کچھ قابو نہیں اور یہ کہ فضل اللہ کے ہاتھ ہے دیتا ہے جسے چاہے، اور اللہ بڑے فضل والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5105, 58, 1, N'بیشک اللہ نے سنی اس کی بات جو تم سے اپنے شوہر کے معاملہ میں بحث کرتی ہے اور اللہ سے شکایت کرتی ہے، اور اللہ تم دونوں کی گفتگو سن رہا ہے، بیشک اللہ سنتا دیکھتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5106, 58, 2, N'وہ جو تم میں اپنی بیبیوں کو اپنی ماں کی جگہ کہہ بیٹھتے ہیں وہ ان کی مائیں نہیں ان کی مائیں تو وہی ہیں جن سے وہ پیدا ہیں اور وہ بیشک بری اور نری جھوٹ بات کہتے ہیں اور بیشک اللہ ضرور معاف کرنے والا اور بخشنے والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5107, 58, 3, N'اور وہ جو اپنی بیبیوں کو اپنی ماں کی جگہ کہیں پھر وہی کرنا چاہیں جس پر اتنی بری بات کہہ چکے تو ان پر لازم ہے ایک بردہ آزاد کرنا قبل اس کے کہ ایک دوسرے کو ہاتھ لگائیں یہ ہے جو نصیحت تمہیں کی جاتی ہے، اور اللہ تمہارے کاموں سے خبردار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5108, 58, 4, N'پھر جسے بردہ نہ ملے تو لگاتار دو مہینے کے روزے قبل اس کے کہ ایک دوسرے کو ہاتھ لگائیں پھر جس سے روزے بھی نہ ہوسکیں تو ساٹھ مسکینوں کا پیٹ بھرنا یہ اس لیے کہ تم اللہ اور اس کے رسول پر ایمان رکھو اور یہ اللہ کی حدیں ہیں اور کافروں کے لیے دردناک عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5109, 58, 5, N'بیشک وہ جو مخالفت کرتے ہیں اللہ اور اس کے رسول کی ذلیل کیے گئے جیسے ان سے اگلوں کو ذلت دی گئی اور بیشک ہم نے روشن آیتیں اتاریں اور کافروں کے لیے خواری کا عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5110, 58, 6, N'جس دن اللہ ان سب کو اٹھائے گا پھر انہیں ان کے کو تک جتادے گا اللہ نے انہیں گن رکھا ہے اور وہ بھول گئے اور ہر چیز اللہ کے سامنے ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5111, 58, 7, N'اے سننے والے کیا تو نے نہ دیکھا کہ اللہ جانتا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں جہاں کہیں تین شخصوں کی سرگوشی ہو تو چوتھا وہ موجود ہے اور پانچ کی تو چھٹا وہ اور نہ اس سے کم اور نہ اس سے زیادہ کی مگر یہ کہ وہ ان کے ساتھ ہے جہاں کہیں ہوں پھر انہیں قیامت کے دن بتادے گا جو کچھ انہوں نے کیا، بیشک اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5112, 58, 8, N'کیا تم نے انہیں نہ دیکھا جنہیں بری مشورت سے منع فرمایا گیا تھا پھر وہی کرتے ہیں جس کی ممانعت ہوئی تھی اور آپس میں گناہ اور حد سے بڑھنے اور رسول کی نافرمانی کے مشورے کرتے ہیں اور جب تمہارے حضور حاضر ہوتے ہیں تو ان لفظوں سے تمہیں مجرا کرتے ہیں جو لفظ اللہ نے تمہارے اعزاز میں نہ کہے اور اپنے دلوں میں کہتے ہیں ہمیں اللہ عذاب کیوں نہیں کرتا ہمارے اس کہنے پر انہیں جہنم بس ہے، اس میں دھنسیں گے، تو کیا ہی برا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5113, 58, 9, N'اے ایمان والو تم جب آپس میں مشورت کرو تو گناہ اور حد سے بڑھنے اور رسول کی نافرمانی کی مشورت نہ کرو اور نیکی اورپرہیزگاری کی مشورت کرو، اور اللہ سے ڈرو جس کی طرف اٹھائے جاؤ گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5114, 58, 10, N'وہ مشورت تو شیطان ہی کی طرف سے ہے اس لیے کہ ایمان والوں کو رنج دے اور وہ اس کا کچھ نہیں بگاڑ سکتا بے حکم خدا کے، اور مسلمانوں کو اللہ ہی پر بھروسہ چاہیے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5115, 58, 11, N'اے ایمان والو جب تم سے کہا جائے مجلسوں میں جگہ دو تو جگہ دو اللہ تمہیں جگہ دے گا اور جب کہا جائے اٹھ کھڑے ہو تو اٹھ کھڑے ہو اللہ تمہارے ایمان والوں کے اور ان کے جن کو علم دیا گیا درجے بلند فرمائے گا، اور اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5116, 58, 12, N'اے ایمان والو جب تم رسول سے کوئی بات آہستہ عرض کرنا چاہو تو اپنی عرض سے پہلے کچھ صدقہ دے لو یہ تمہارے لیے بہت بہتر اور بہت ستھرا ہے، پھر اگر تمہیں مقدور نہ ہو تو اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5117, 58, 13, N'کیا تم اس سے ڈرے کہ تم اپنی عرض سے پہلے کچھ صدقے دو پھر جب تم نے یہ نہ کیا، اور اللہ نے اپنی مہر سے تم پر رجوع فرمائی تو نماز قائم رکھو اور زکوٰة دو اور اللہ اور اس کے رسول کے فرمانبردار رہو، اور اللہ تمہارے کاموں کو جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5118, 58, 14, N'کیا تم نے انہیں نہ دیکھا جو ایسوں کے دوست ہوئے جن پر اللہ کا غضب ہے وہ نہ تم میں سے نہ ان میں سے وہ دانستہ جھوٹی قسم کھاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5119, 58, 15, N'اللہ نے ان کے لیے سخت عذاب تیار کر رکھا ہے، بیشک وہ بہت ہی برے کام کرتے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5120, 58, 16, N'انہوں نے اپنی قسموں کو ڈھال بنالیا ہے تو اللہ کی راہ سے روکا تو ان کے لیے خواری کا عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5121, 58, 17, N'ان کے مال اور ان کی اولاد اللہ کے سامنے انہیں کچھ کام نہ دیں گے وہ دوزخی ہیں، انہیں اس میں ہمیشہ رہنا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5122, 58, 18, N'جس دن اللہ ان سب کو اٹھائے گا تو اس کے حضور بھی ایسے ہی قسمیں کھائیں گے جیسی تمہارے سامنے کھارہے ہیں اور وہ یہ سمجھتے ہیں کہ انہوں نے کچھ کیا سنتے ہو بیشک وہی جھوٹے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5123, 58, 19, N'ان پر شیطان غالب آگیا تو انہیں اللہ کی یاد بھلا دی، وہ شیطان کے گروہ ہیں، سنتا ہے بیشک شیطان ہی کا گروہ ہار میں ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5124, 58, 20, N'بیشک وہ جو اللہ اور اس کے رسول کی مخالفت کرتے ہیں وہ سب سے زیادہ ذلیلوں میں ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5125, 58, 21, N'اللہ لکھ چکا کہ ضرور میں غالب آؤں گا اور میرے رسول بیشک اللہ قوت والا عزت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5126, 58, 22, N'تم نہ پاؤ گے ان لوگوں کو جو یقین رکھتے ہیں اللہ اور پچھلے دن پر کہ دوستی کریں ان سے جنہوں نے اللہ اور اس کے رسول سے مخالفت کی اگرچہ وہ ان کے باپ یا بیٹے یا بھائی یا کنبے والے ہوں یہ ہیں جن کے دلوں میں اللہ نے ایمان نقش فرمادیا اور اپنی طرف کی روح سے ان کی مدد کی اور انہیں باغوں میں لے جائے گا جن کے نیچے نہریں بہیں ان میں ہمیشہ رہیں، اللہ ان سے راضی اور وہ اللہ سے راضی یہ اللہ کی جماعت ہے، سنتا ہے اللہ ہی کی جماعت کامیاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5127, 59, 1, N'اللہ کی پاکی بولتا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اور وہ وہی عزت و حکمت والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5128, 59, 2, N'وہی ہے جس نے ان کافر کتابیوں کو ان کے گھروں سے نکالا ان کے پہلے حشر کے لیے تمہیں گمان نہ تھا کہ وہ نکلیں گے اور وہ سمجھتے تھے کہ ان کے قلعے انہیں اللہ سے بچالیں گے تو اللہ کا حکم ان کے پاس آیا جہاں سے ان کا گمان بھی نہ تھا اور اس نے ان کے دلوں میں رُعب ڈالا کہ اپنے گھر ویران کرتے ہیں اپنے ہاتھوں اور مسلمانوں کے ہاتھوں تو عبرت لو اے نگاہ والو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5129, 59, 3, N'اور اگر نہ ہوتا کہ اللہ نے ان پر گھر سے اجڑنا لکھ دیا تھا تو دنیا ہی میں ان پر عذاب فرماتا اور ان کے لیے آخرت میں آگ کا عذاب ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5130, 59, 4, N'یہ اس لیے کہ وہ اللہ سے اور اس کے رسول سے پھٹے (جدا) رہے اور جو اللہ اور اس کے رسول سے پھٹا رہے تو بیشک اللہ کا عذاب سخت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5131, 59, 5, N'جو درخت تم نے کاٹے یا ان کی جڑوں پر قائم چھوڑ دیے یہ سب اللہ کی اجازت سے تھا اور اس لیے کہ فاسقوں کو رسوا کرے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5132, 59, 6, N'اور جو غنیمت دلائی اللہ نے اپنے رسول کو ان سے تو تم نے ان پر نہ اپنے گھوڑے دوڑائے تھے اور نہ اونٹ ہاں اللہ اپنے رسولوں کے قابو میں دے دیتا ہے جسے چاہے اور اللہ سب کچھ کرسکتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5133, 59, 7, N'جو غنیمت دلائی اللہ نے اپنے رسول کو شہر والوں سے وہ اللہ اور رسول کی ہے اور رشتہ داروں اور یتیموں اور مسکینوں اور مسافروں کے لیے کہ تمہارے اغنیا کا مال نہ جائے (ف۹۲۱ اور جو کچھ تمہیں رسول عطا فرمائیں وہ لو اور جس سے منع فرمائیں باز رہو، اور اللہ سے ڈرو بیشک اللہ کا عذاب سخت ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5134, 59, 8, N'ان فقیر ہجرت کرنے والوں کے لیے جو اپنے گھروں اور مالوں سے نکالے گئے اللہ کا فضل اور اس کی رضا چاہتے اور اللہ و رسول کی مدد کرتے وہی سچے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5135, 59, 9, N'اور جنہوں نے پہلے سے اس شہر اور ایمان میں گھر بنالیا دوست رکھتے ہیں انہیں جو ان کی طرف ہجرت کرکے گئے اور اپنے دلوں میں کوئی حاجت نہیں پاتے اس چیز کو جو دیے گئے اور اپنی جانوں پر ان کو ترجیح دیتے ہیں اگرچہ انہیں شدید محتاجی ہو اور جو اپنے نفس کے لالچ سے بچایا گیا تو وہی کامیاب ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5136, 59, 10, N'اور وہ جو ان کے بعد آئے عرض کرتے ہیں اے ہمارے رب ہمیں بخش دے اور ہمارے بھائیوں کو جو ہم سے پہلے ایمان لائے اور ہمارے دل میں ایمان والوں کی طرف سے کینہ نہ رکھ اے ہمارے رب بیشک تو ہی نہایت مہربان رحم والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5137, 59, 11, N'کیا تم نے منافقوں کو نہ دیکھا کہ اپنے بھائیوں کافر کتابیوں سے کہتے ہیں کہ اگر تم نکالے گئے تو ضرور ہم تمہارے ساتھ جائیں گے اور ہرگز تمہارے بارے میں کسی کی نہ مانیں گے اور اگر تم سے لڑائی ہوئی تو ہم ضرور تمہاری مدد کریں گے، اور اللہ گواہ ہے کہ وہ جھوٹے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5138, 59, 12, N'اگر وہ نکالے گئے تو یہ ان کے ساتھ نہ نکلیں گے، اور ان سے لڑائی ہوئی تو یہ ان کی مدد نہ کریں گے اگر ان کی مدد کی بھی تو ضرور پیٹھ پھیر کر بھاگیں گے، پھر مدد نہ پائیں گے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5139, 59, 13, N'بیشک ان کے دلوں میں اللہ سے زیادہ تمہارا ڈر ہے یہ اس لیے کہ وہ ناسمجھ لوگ ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5140, 59, 14, N'یہ سب مل کر بھی تم سے نہ لڑیں گے مگر قلعہ بند شہروں میں یا دُھسّوں (شہر پناہ) کے پیچھے، آپس میں ان کی آنچ (جنگ) سخت ہے تم انہیں ایک جتھا سمجھو گے اور ان کے دل الگ الگ ہیں، یہ اس لیے کہ وہ بے عقل لوگ ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5141, 59, 15, N'ان کی سی کہاوت جو ابھی قریب زمانہ میں ان سے پہلے تھے انہوں نے اپنے کام کا وبال چکھا اور ان کے لیے دردناک عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5142, 59, 16, N'شیطان کی کہاوت جب اس نے آدمی سے کہا کفر کر پھر جب اس نے کفر کرلیا بولا میں تجھ سے الگ ہوں میں اللہ سے ڈرتا ہوں جو سارے جہان کا رب')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5143, 59, 17, N'تو ان دونوں کا انجام یہ ہوا کہ وہ دونوں آگ میں ہیں ہمیشہ اس میں رہے، اور ظالموں کو یہی سزا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5144, 59, 18, N'اے ایمان والو اللہ سے ڈرو اور ہر جان دیکھے کہ کل کے لیے آگے کیا بھیجا اور اللہ سے ڈرو بیشک اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5145, 59, 19, N'اور ان جیسے نہ ہو جو اللہ کو بھول بیٹھے تو اللہ نے انہیں بلا میں ڈالا کہ اپنی جانیں یاد نہ رہیں وہی فاسق ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5146, 59, 20, N'دوزخ والے اور جنت والے برابر نہیں جنت والے ہی مراد کو پہنچے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5147, 59, 21, N'اگر ہم یہ قرآن کسی پہاڑ پر اتارتے تو ضرور تو اسے دیکھتا جھکا ہوا پاش پاش ہوتا اللہ کے خوف سے اور یہ مثالیں لوگوں کے لیے ہم بیان فرماتے ہیں کہ وہ سوچیں،')
