INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5149, 59, 23, N'وہی ہے اللہ جس کے سوا کوئی معبود نہیں بادشاہ نہایت پاک سلامتی دینے والا امان بخشنے والا حفاظت فرمانے والا عزت والا عظمت والا تکبر والا اللہ کو پاکی ہے ان کے شرک سے،')
