INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5150, 59, 24, N'وہی ہے اللہ بنانے والا پیدا کرنے والا ہر ایک کو صورت دینے والا اسی کے ہیں سب اچھے نام اس کی پاکی بولتا ہے جو کچھ آسمانوں اور زمین میں ہے اور وہی عزت و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5151, 60, 1, N'اے ایمان والو میرے اور اپنے دشمنوں کو دوست نہ بناؤ تم انہیں خبریں پہنچاتے ہو دوستی سے حالانکہ وہ منکر ہیں اس حق کے جو تمہارے پاس آیا گھر سے جدا کرتے ہیں رسول کو اور تمہیں اس پر کہ تم اپنے رب پر ایمان لائے، اگر تم نکلے ہو میری راہ میں جہاد کرنے اور میری رضا چاہنے کو تو ان سے دوستی نہ کرو تم انہیں خفیہ پیامِ محبت بھیجتے ہو، اور میں خوب جانتا ہوں جو تم چھپاؤ اور جو ظاہر کرو، اور تم میں جو ایسا کرے بیشک وہ سیدھی راہ سے بہکا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5152, 60, 2, N'اگر تمہیں پائیں تو تمہارے دشمن ہوں گے اور تمہاری طرف اپنے ہاتھ اور اپنی زبانیں برائی کے ساتھ دراز کریں گے اور ان کی تمنا ہے کہ کسی طرح تم کافر ہوجاؤ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5153, 60, 3, N'ہرگز کام نہ آئیں گے تمہیں تمہارے رشتے اور نہ تمہاری اولاد قیامت کے دن، تمہیں ان سے الگ کردے گا اور اللہ تمہارے کام دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5154, 60, 4, N'بیشک تمہارے لیے اچھی پیروی تھی ابراہیم اور اس کے ساتھ والوں میں جب انہوں نے اپنی قوم سے کہا بیشک ہم بیزار ہیں تم سے اور ان سے جنہیں اللہ کے سوا پوجتے ہو، ہم تمہارے منکر ہوئے اور ہم میں اور تم میں دشمنی اور عداوت ظاہر ہوگئی ہمیشہ کے لیے جب تک تم ایک اللہ پر ایمان نہ لاؤ مگر ابراہیم کا اپنے باپ سے کہنا کہ میں ضرور تیری مغفرت چاہوں گا اور میں اللہ کے سامنے تیر ے کسی نفع کا مالک نہیں اے ہمارے رب ہم نے تجھی پر بھروسہ کیا اور تیری ہی طرف رجوع لائے اور تیری ہی طرف پھرنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5155, 60, 5, N'اے ہمارے رب ہمیں کافروں کی آزمائش میں نہ ڈال اور ہمیں بخش دے، اے ہمارے رب بیشک تو ہی عزت و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5156, 60, 6, N'بیشک تمہارے لیے ان میں اچھی پیروی تھی اسے جو اللہ اور پچھلے دن کا امیدوار ہو اور جو منہ پھیرے تو بیشک اللہ ہی بے نیاز ہے سب خوبیوں سراہا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5157, 60, 7, N'قریب ہے کہ اللہ تم میں اور ان میں جو ان میں سے تمہارے دشمن ہیں دوستی کردے اور اللہ قادر ہے اور بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5158, 60, 8, N'اللہ تمہیں ان سے منع نہیں کرتا جو تم سے دین میں نہ لڑے اور تمہیں تمہارے گھروں سے نہ نکالا کہ ان کے ساتھ احسان کرو اور ان سے انصاف کا برتاؤ برتو، بیشک انصاف والے اللہ کو محبوب ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5159, 60, 9, N'اللہ تمہیں انہی سے منع کرتا ہے جو تم سے دین میں لڑے یا تمہیں تمہارے گھروں سے نکالا یا تمہارے نکالنے پر مدد کی کہ ان سے دوستی کرو اور جو ان سے دوستی کرے تو وہی ستمگار ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5160, 60, 10, N'اے ایمان والو جب تمہارے پاس مسلمان عورتیں کفرستان سے اپنے گھر چھوڑ کر آئیں تو ان کا امتحان کرو اللہ ان کے ایمان کا حال بہتر جانتا ہے، پھر اگر تمہیں ایمان والیاں معلوم ہوں تو انہیں کافروں کو واپس نہ دو، نہ یہ انہیں حلال نہ وہ انہیں حلال اور ان کے کافر شوہروں کو دے دو جو ان کا خرچ ہوا اور تم پر کچھ گناہ نہیں کہ ان سے نکاح کرلو جب ان کے مہر انہیں دو اور کافرنیوں کے نکاح پر جمے نہ رہو اور مانگ لو جو تمہارا خرچ ہوا اور کافر مانگ لیں جو انہوں نے خرچ کیا یہ اللہ کا حکم ہے، وہ تم میں فیصلہ فرماتا ہے، اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5161, 60, 11, N'اور اگر مسلمانوں کے ہاتھ سے کچھ عورتیں کافروں کی طرف نکل جائیں پھر تم کافروں کو سزا دو تو جن کی عورتیں جاتی رہی تھیں غنیمت میں سے انہیں اتنا دیدو جو ان کا خرچ ہوا تھا اور اللہ سے ڈرو جس پر تمہیں ایمان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5162, 60, 12, N'اے نبی جب تمہارے حضور مسلمان عورتیں حاضر ہوں اس پر بیعت کرنے کو کہ اللہ کا کچھ شریک نہ ٹھہرائیں گی اور نہ چوری کریں گی اور نہ بدکاری اور نہ اپنی اولاد کو قتل کریں گی اور نہ وہ بہتان لائیں گی جسے اپنے ہاتھوں اور پاؤں کے درمیان یعنی موضع ولادت میں اٹھائیں اور کسی نیک بات میں تمہاری نافرانی نہ کریں گی تو ان سے بیعت لو اور اللہ سے ان کی مغفرت چاہو بیشک اللہ بخشنے والا مہربان ہے،')
GO
