INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5168, 61, 5, N'اور یاد کرو جب موسیٰ نے اپنی قوم سے کہا، اے میری قوم مجھے کیوں ستاتے ہو حالانکہ تم جانتے ہو کہ میں تمہاری طرف اللہ کا رسول ہوں پھر جب وہ ٹیڑھے ہوئے اللہ نے ان کے دل ٹیڑھے کردیے اور اللہ فاسق لوگوں کو راہ نہیں دیتا')
