INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5175, 61, 12, N'وہ تمہارے گناہ بخش دے گا اور تمہیں باغوں میں لے جائے گا جن کے نیچے نہریں رواں اور پاکیزہ محلوں میں جو بسنے کے باغوں میں ہیں، یہی بڑی کامیابی ہے،')
