INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5177, 61, 14, N'اے ایمان والو دین خدا کے مددگار ہو جیسے عیسیٰ بن مریم نے حواریوں سے کہا تھا کون ہے جو اللہ کی طرف ہو کر میری مدد کریں حواری بولے ہم دینِ خدا کے مددگار ہیں تو بنی اسرائیل سے ایک گروہ ایمان لایا اور ایک گروہ نے کفر کیا تو ہم نے ایمان والوں کو ان کے دشمنوں پر مدد دی تو غالب ہوگئے')
