INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5179, 62, 2, N'وہی ہے جس نے اَن پڑھوں میں انہی میں سے ایک رسول بھیجا کہ ان پر اس کی آیتیں پڑھتے ہیں اور انہیں پاک کرتے ہیں اور انہیں کتاب و حکمت کا علم عطا فرماتے ہیں اور بیشک وہ اس سے پہلے ضرور کھلی گمراہی میں تھے')
