INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5180, 62, 3, N'اور ان میں سے اوروں کو پاک کرتے اور علم عطا فرماتے ہیں، جو ان اگلوں سے نہ ملے اور وہی عزت و حکمت والا ہے،')
