INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5181, 62, 4, N'یہ اللہ کا فضل ہے جسے چاہے دے، اور اللہ بڑے فضل والا ہے')
