INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5182, 62, 5, N'ان کی مثال جن پر توریت رکھی گئی تھی پھر انہوں نے اس کی حکم برداری نہ کی گدھے کی مثال ہے جو پیٹھ پر کتابیں اٹھائے کیا ہی بری مثال ہے ان لوگوں کی جنہوں نے اللہ کی آیتیں جھٹلائیں، اور اللہ ظالموں کو راہ نہیں دیتا،')
