INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5186, 62, 9, N'اے ایمان والو جب نماز کی اذان ہو جمعہ کے دن تو اللہ کے ذکر کی طرف دوڑو اور خرید و فروخت چھوڑ دو یہ تمہارے لیے بہتر ہے اگر تم جانو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5187, 62, 10, N'پھر جب نماز ہوچکے تو زمین میں پھیل جاؤ اور اللہ کا فضل تلاش کرو اور اللہ کو بہت یاد کرو اس امید پر کہ فلاح پاؤ،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5188, 62, 11, N'اور جب انہوں نے کوئی تجارت یا کھیل دیکھا اس کی طرف چل دیے اور تمہیں خطبے میں کھڑا چھوڑ گئے تم فرماؤ وہ جو اللہ کے پاس ہے کھیل سے اور تجارت سے بہتر ہے، اور اللہ کا رزق سب سے اچھا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5189, 63, 1, N'جب منافق تمہارے حضور حاضر ہوتے ہیں کہتے ہیں کہ ہم گواہی دیتے ہیں کہ حضور بیشک یقیناً اللہ کے رسول ہیں اور اللہ جانتا ہے کہ تم اس کے رسول ہو، اور اللہ گواہی دیتا ہے کہ منافق ضرور جھوٹے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5190, 63, 2, N'اور انہوں نے اپنی قسموں کو ڈھال ٹھہرالیا تو اللہ کی راہ سے روکا بیشک وہ بہت ہی برے کام کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5191, 63, 3, N'یہ اس لیے کہ وہ زبان سے ایمان لائے پھر دل سے کافر ہوئے تو ان کے دلوں پر مہر کردی گئی تو اب وہ کچھ نہیں سمجھتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5192, 63, 4, N'اور جب تو انہیں دیکھے ان کے جسم تجھے بھلے معلوم ہوں، اور اگر بات کریں تو تُو ان کی بات غور سے سنے گویا وہ کڑیاں ہیں دیوار سے ٹکائی ہوئی ہر بلند آواز اپنے ہی اوپر لے جاتے ہیں وہ دشمن ہیں تو ان سے بچتے رہو اللہ انہیں مارے کہاں اوندھے جاتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5193, 63, 5, N'اور جب ان سے کہا جائے کہ آؤ رسول اللہ تمہارے لیے معافی چاہیں تو اپنے سر گھماتے ہیں اور تم انہیں دیکھو کہ غور کرتے ہوئے منہ پھیر لیتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5194, 63, 6, N'ان پر ایک سا ہے تم ان کی معافی چاہو یا نہ چاہو، اللہ انہیں ہر گز نہ بخشے گا بیشک اللہ فاسقوں کو راہ نہیں دیتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5195, 63, 7, N'وہی ہیں جو کہتے ہیں کہ ان پر خرچ نہ کرو جو رسول اللہ کے پاس ہیں یہاں تک کہ پریشان ہوجائیں، اور اللہ ہی کے لیے ہیں آسمانوں اور زمین کے خزانے مگر منافقوں کو سمجھ نہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5196, 63, 8, N'کہتے ہیں ہم مدینہ پھر کر گئے تو ضرور جو بڑی عزت والا ہے وہ اس میں سے نکال دے گا اسے جو نہایت ذلت والا ہے اور عزت تو اللہ اور اس کے رسول اور مسلمانوں ہی کے لیے ہے مگر منافقوں کو خبر نہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5197, 63, 9, N'اے ایمان والو تمہارے مال نہ تمہاری اولاد کوئی چیز تمہیں اللہ کے ذکر سے غافل نہ کرے اور جو ایسا کرے تو وہی لوگ نقصان میں ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5198, 63, 10, N'اور ہمارے دیے میں سے کچھ ہماری راہ میں خرچ کرو قبل اس کے کہ تم میں کسی کو موت آئے پھر کہنے لگے، اے میرے رب تو نے مجھے تھوڑی مدت تک کیوں مہلت نہ دی کہ میں صدقہ دیتا اور نیکوں میں ہوتا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5199, 63, 11, N'اور ہرگز اللہ کسی جان کو مہلت نہ دے گا جب اس کا وعدہ آجائے اور اللہ کو تمہارے کاموں کی خبر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5200, 64, 1, N'اللہ کی پاکی بولتا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں، اسی کا ملک ہے اور اسی کی تعریف اور وہ ہر چیز پر قادر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5201, 64, 2, N'وہی ہے جس نے تمہیں پیدا کیا تو تم میں کوئی کافر اور تم میں کوئی مسلمان اور اللہ تمہارے کام دیکھ رہا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5202, 64, 3, N'اس نے آسمان اور زمین حق کے ساتھ بنائے اور تمہاری تصویر کی تو تمہاری اچھی صورت بنائی اور اسی کی طرف پھرنا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5203, 64, 4, N'جانتا ہے جو کچھ آسمانوں اور زمین میں ہے اور جانتا ہے جو تم چھپاتے اور ظاہر کرتے ہو، اور اللہ دلوں کی بات جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5204, 64, 5, N'کیا تمہیں ان کی خبر نہ آئی جنہوں نے تم سے پہلے کفر کیا اور اپنے کام کا وبال چکھا اور ان کے لیے دردناک عذاب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5205, 64, 6, N'یہ اس لیے کہ ان کے پاس ان کے رسول روشن دلیلیں لاتے تو بولے، کیا آدمی ہمیں راہ بتائیں گے تو کافر ہوئے اور پھر گئے اور اللہ نے بے نیازی کو کام فرمایا، اور اللہ بے نیاز ہے سب خوبیوں سراہا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5206, 64, 7, N'کافروں نے بکا کہ وہ ہرگز نہ اٹھائے جائیں گے، تم فرماؤ کیوں نہیں میرے رب کی قسم تم ضرور اٹھائے جاؤ گے پھر تمہارے کوتک تمہیں جتا دیے جائیں گے، اور یہ اللہ کو آسان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5207, 64, 8, N'تو ایمان لاؤ اللہ اور اس کے رسول اور اس نور پر جو ہم نے اتارا، اور اللہ تمہارے کاموں سے خبردار ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5208, 64, 9, N'جس دن تمہیں اکٹھا کرے گا سب جمع ہونے کے دن وہ دن ہے ہار والوں کی ہار کھلنے کا اور جو اللہ پر ایمان لائے اور اچھا کام کرے اللہ اس کی برائیاں اتاردے گا اور اسے باغوں میں لے جائے گا جن کے نیچے نہریں بہیں کہ وہ ہمیشہ ان میں رہیں، یہی بڑی کامیابی ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5209, 64, 10, N'اور جنہوں نے کفر کیا اور ہماری آیتیں جھٹلائیں وہ آگ والے ہیں ہمیشہ اس میں رہیں، اور کیا ہی برا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5210, 64, 11, N'کوئی مصیبت نہیں پہنچتی مگر اللہ کے حکم سے، اور جو اللہ پر ایمان لائے اللہ اس کے دل کو ہدایت فرمادے گا اور اللہ سب کچھ جانتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5211, 64, 12, N'اور اللہ کا حکم مانو اور رسول کا حکم مانو، پھر اگر تم منہ پھیرو تو جان لو کہ ہمارے رسول پر صرف صریح پہنچا دینا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5212, 64, 13, N'اللہ ہے جس کے سوا کسی کی بندگی نہیں اور اللہ ہی پر ایمان والے بھروسہ کریں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5213, 64, 14, N'اے ایمان والو تمہاری کچھ بی بیا ں اور بچے تمہارے دشمن ہیں تو ان سے احتیاط رکھو اور اگر معاف کرو اور درگزرو اور بخش دو تو بیشک اللہ بخشنے والا مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5214, 64, 15, N'تمہارے مال اور تمہارے بچے جانچ ہی ہیں اور اللہ کے پاس بڑا ثواب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5215, 64, 16, N'تو اللہ سے ڈرو جہاں تک ہوسکے اور فرمان سنو اور حکم مانو اور اللہ کی راہ میں خرچ کرو اپنے بھلے کو، اور جو اپنی جان کے لالچ سے بچایا گیا تو وہی فلاح پانے والے ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5216, 64, 17, N'اگر تم اللہ کو اچھا قرض دو گے وہ تمہارے لیے اس کے دونے کردے گا اور تمہیں بخش دے گا اور اللہ قدر فرمانے والے حلم والا ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5217, 64, 18, N'ہر نہاں اور عیاں کا جاننے والا عزت والا حکمت والا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5218, 65, 1, N'اے نبی جب تم لوگ عورتوں کو طلاق دو تو ان کی عدت کے وقت پر انہیں طلاق دو اور عدت کا شمار رکھو اور اپنے رب اللہ سے ڈرو، عدت میں انہیں ان کے گھروں سے نہ نکالو اور نہ وہ آپ نکلیں مگر یہ کہ کوئی صریح بے حیائی کی بات لائیں اور یہ اللہ کی حدیں ہیں، اور جو اللہ کی حدوں سے آگے بڑھا بیشک اس نے اپنی جان پر ظلم کیا، تمہیں نہیں معلوم شاید اللہ اس کے بعد کوئی نیا حکم بھیجے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5219, 65, 2, N'تو جب وہ اپنی میعاد تک پہنچنے کو ہوں تو انہیں بھلائی کے ساتھ روک لو یا بھلائی کے ساتھ جدا کرو اور اپنے میں دو ثقہ کو گواہ کرلو اور اللہ کے لیے گواہی قائم کرو اس سے نصیحت فرمائی جاتی ہے اسے جو اللہ اور پچھلے دن پر ایمان رکھتا ہو اور جو اللہ سے ڈرے اللہ اس کے لیے نجات کی راہ نکال دے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5220, 65, 3, N'اور اسے وہاں سے روزی دے گا جہاں اس کا گمان نہ ہو، اور جو اللہ پر بھروسہ کرے تو وہ اسے کافی ہے بیشک اللہ اپنا کام پورا کرنے والا ہے، بیشک اللہ نے ہر چیز کا ایک اندازہ رکھا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5221, 65, 4, N'اور تمہاری عورتوں میں جنہیں حیض کی امید نہ رہی اگر تمہیں کچھ شک ہو تو ان کی عدت تین مہینے ہے اور ان کی جنہیں ابھی حیض نہ آیا اور حمل والیوں کی میعاد یہ ہے کہ وہ اپنا حمل جَن لیں اور جو اللہ سے ڈرے اللہ اس کے کام میں آسانی فرمادے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5222, 65, 5, N'یہ اللہ کا حکم ہے کہ اس نے تمہاری طرف اتارا، اور جو اللہ سے ڈرے اللہ اس کی برائیاں اتار دے گا اور اسے بڑا ثواب دے گا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5223, 65, 6, N'عورتوں کو وہاں رکھو جہاں خود رہتے ہو اپنی طاقت بھر اور انہیں ضرر نہ دو کہ ان پر تنگی کرو اور اگر حمل والیاں ہوں تو انہیں نان و نفقہ دو یہاں تک کہ ان کے بچہ پیدا ہو پھر اگر وہ تمہارے لیے بچہ کو دودھ پلائیں تو انہیں اس کی اجرت دو اور آپس میں معقول طور پر مشورہ کرو پھر اگر باہم مضائقہ کرو (دشوار سمجھو) تو قریب ہے کہ اسے اور دودھ پلانے والی مل جائے گی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5224, 65, 7, N'مقدور والا اپنے مقدور کے قابل نفقہ دے، اور جس پر اس کا رزق تنگ کیا گیا وہ اس میں سے نفقہ دے جو اسے اللہ نے دیا، اللہ کسی جان پر بوجھ نہیں رکھتا مگر اسی قابل جتنا اسے دیا ہے، قریب ہے اللہ دشواری کے بعد آسانی فرمادے گا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5225, 65, 8, N'اور کتنے ہی شہر تھے جنہوں نے اپنے رب کے حکم اور اس کے رسولوں سے سرکشی کی تو ہم نے ان سے سخت حسا ب لیا اور انہیں بری مار دی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5226, 65, 9, N'تو انہوں نے اپنے کیے کا وبال چکھا اور ان کے کام انجام گھاٹا ہوا،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5227, 65, 10, N'اللہ نے ان کے لیے سخت عذاب تیار کر رکھا ہے تو اللہ سے ڈرو اے عقل والو! وہ جو ایمان لائے ہو، بیشک اللہ نے تمہارے لیے عزت اتاری ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5228, 65, 11, N'وہ رسول کہ تم پر اللہ کی روشن آیتیں پڑھتا ہے تاکہ انہیں جو ایمان لائے اور اچھے کام کیے اندھیریوں سے اجالے کی طرف لے جائے، اور جو اللہ پر ایمان لائے اور اچھا کام کرے وہ اسے باغوں میں لے جائے گا جن کے نیچے نہریں بہیں جن میں ہمیشہ ہمیشہ رہیں، بیشک اللہ نے اس کے لیے اچھی روزی رکھی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5229, 65, 12, N'اللہ ہے جس نے سات آسمان بنائے اور انہی کی برابر زمینیں حکم ان کے درمیان اترتا ہے تاکہ تم جان لو کہ اللہ سب کچھ کرسکتا ہے، اللہ کا علم ہر چیز کو محیط ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5230, 66, 1, N'اے غیب بتا نے والے (نبی) تم اپنے اوپر کیوں حرام کئے لیتے ہو وه چیز جو اللہ نے تمھارے لئے حلال کی اپنی بیبیوں کی مرضی چاہتے ہو اور اللہ بخشنے والا ٴ مہربان ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5231, 66, 2, N'بیشک اللہ نے تمہارے لیے تمہاری قسموں کا اتار مقرر فرمادیا اور اللہ تمہارا مولیٰ ہے، اور اللہ علم و حکمت والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5232, 66, 3, N'اور جب نبی نے اپنی ایک بی بی سے ایک راز کی بات فرمائی پھر جب وہ اس کا ذکر کر بیٹھی اور اللہ نے اسے نبی پر ظاہر کردیا تو نبی نے اسے کچھ جتایا اور کچھ سے چشم پوشی فرمائی پھر جب نبی نے اسے اس کی خبر دی بولی حضور کو کس نے بتایا، فرمایا مجھے علم والے خبردار نے بتایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5233, 66, 4, N'نبی کی دونوں بیبیو! اگر اللہ کی طرف تم رجوع کرو تو ضرور تمہارے دل راہ سے کچھ ہٹ گئے ہیں اور اگر ان پر زور باندھو تو بیشک اللہ ان کا مددگار ہے اور جبریل اور نیک ایمان والے، اور اس کے بعد فرشتے مدد پر ہیں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5234, 66, 5, N'ان کا رب قریب ہے اگر وہ تمہیں طلاق دے دیں کہ انہیں تم سے بہتر بیبیاں بدل دے اطاعت والیاں ایمان والیاں ادب والیاں توبہ والیاں بندگی والیاں روزہ داریں بیاہیاں اور کنواریاں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5235, 66, 6, N'اے ایمان والو! اپنی جانوں اور اپنے گھر والوں کو آگ سے بچاؤ جس کے ایندھن آدمی اور پتھر ہیں اس پر سخت کرّے (طاقتور) فرشتے مقرر ہیں جو اللہ کا حکم نہیں ٹالتے اور جو انہیں حکم ہو وہی کرتے ہیں')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5236, 66, 7, N'اے کافرو! آج بہانے نہ بناؤ تمہیں وہی بدلہ ملے گا جو تم کرتے تھے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5237, 66, 8, N'اے ایمان والو! اللہ کی طرف ایسی توبہ کرو جو آگے کو نصیحت ہوجائے قریب ہے تمہارا رب تمہاری برائیاں تم سے اتار دے اور تمہیں باغوں میں لے جائے جن کے نیچے نہریں بہیں جس دن اللہ رسوا نہ کرے گا نبی اور ان کے ساتھ کے ایمان والوں کو ان کا نور دوڑتا ہوگا ان کے آگے اور ان کے دہنے عرض کریں گے، اے ہمارے رب! ہمارے لیے ہمارا نور پورا کردے اور ہمیں بخش دے، بیشک تجھے ہر چیز پر قدرت ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5238, 66, 9, N'اے غیب بتانے والے! (نبی) کافروں پر اور منافقوں پر جہاد کرو اور ان پر سختی فرماؤ، اور ان کا ٹھکانا جہنم ہے، اور کیا ہی برا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5239, 66, 10, N'اللہ کافروں کی مثال دیتا ہے نوح کی عورت اور لوط کی عورت، وہ ہمارے بندوں میں دو سزا وارِ (لائق) قرب بندوں کے نکاح میں تمہیں پھر انہوں نے ان سے دغا کی تو وہ اللہ کے سامنے انہیں کچھ کام نہ آئے اور فرما دیا گیا کے تم دونوں عورتیں جہنم میں جاؤ جانے والوں کے ساتھ')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5240, 66, 11, N'اور اللہ مسلمانو ں کی مثال بیان فر ماتا ہے فرعون کی بی بی جب اس نے عرض کی، اے میرے رب! میرے لیے اپنے پاس جنت میں گھر بنا اور مجھے فرعون اور اس کے کام سے نجات دے اور مجھے ظالم لوگوں سے نجات بخش')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5241, 66, 12, N'اور عمران کی بیٹی مریم جس نے اپنی پارسائی کی حفاظت کی تو ہم نے اس میں اپنی طرف کی روح پھونکی اور اس نے اپنے رب کی باتوں اور اس کی کتابوں کی تصدیق کی اور فرمانبرداروں میں ہوئی،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5242, 67, 1, N'بڑی برکت والا ہے وہ جس کے قبضہ میں سارا ملک اور وہ ہر چیز پر قادر ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5243, 67, 2, N'وہ جس نے موت اور زندگی پیدا کی کہ تمہاری جانچ ہو تم میں کس کا کام زیادہ اچھا ہے اور وہی عزت والا بخشش والا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5244, 67, 3, N'جس نے سات آسمان بنائے ایک کے اوپر دوسرا، تو رحمٰن کے بنانے میں کیا فرق دیکھتا ہے تو نگاہ اٹھا کر دیکھ تجھے کوئی رخنہ نظر آتا ہے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5245, 67, 4, N'پھر دوبارہ نگاہ اٹھا نظر تیری طرف ناکام پلٹ آئے گی تھکی ماندی')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5246, 67, 5, N'اور بیشک ہم نے نیچے کے آسمان کو چراغوں سے آراستہ کیا اور انہیں شیطانوں کے لیے مار کیا اور ان کے لیے بھڑکتی آگ کا عذاب تیار فرمایا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5247, 67, 6, N'اور جنہوں نے اپنے رب کے ساتھ کفر کیا ان کے لیے جہنم کا عذاب ہے، اور کیا ہی برا انجام،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5248, 67, 7, N'جب اس میں ڈالے جائیں گے اس کا رینکنا (چنگھاڑنا) سنیں گے کہ جوش مارتی ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5249, 67, 8, N'معلوم ہوتا ہے کہ شدت غضب میں پھٹ جائے گی، جب کبھی کوئی گروہ اس میں ڈالا جائے گا اس کے داروغہ ان سے پوچھیں گے کیا تمہارے پاس کوئی ڈر سنانے والا نہ آیا تھا')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5250, 67, 9, N'کہیں گے کیوں نہیں بیشک ہمارے پاس ڈر سنانے والے تشریف لائے پھر ہم نے جھٹلایا اور کہا اللہ نے کچھ نہیں اُتارا، تم تو نہیں مگر بڑی گمراہی میں،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5251, 67, 10, N'اور کہیں گے اگر ہم سنتے یا سمجھتے تو دوزخ والوں میں نہ ہوتے،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5252, 67, 11, N'اب اپنے گناہ کا اقرار کیا تو پھٹکار ہو دوزخیوں کو،')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5253, 67, 12, N'بیشک جو بے دیکھے اپنے رب سے ڈرتے ہیں ان کے لیے بخشش اور بڑا ثواب ہے')
GO
INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5254, 67, 13, N'اور تم اپنی بات آہستہ کہو یا آواز سے، وہ تو دلوں کی جانتا ہے')
