INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5280, 68, 9, N'وہ تو اس آرزو میں ہیں کہ کسی طرح تم نرمی کرو تو وہ بھی نرم پڑجائیں،')
