INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5449, 72, 2, N'کہ بھلائی کی راہ بتا تا ہے تو ہم اس پر ایمان لائے، اور ہم ہرگز کسی کو اپنے رب کا شریک نہ کریں گے،')
