INSERT [dbo].[ur_kanzuliman] ([ID], [sura], [aya], [tran_text]) VALUES (5495, 73, 20, N'بیشک تمہارا رب جانتا ہے کہ تم قیام کرتے ہو کبھی دو تہائی رات کے قریب، کبھی آدمی رات، کبھی تہائی اور ایک جماعت تمہارے ساتھ والی اور اللہ رات اور دن کا اندازہ فرماتا ہے، اسے معلوم ہے کہ اے مسلمانو! تم سے رات کا شمار نہ ہوسکے گا تو اس نے اپنی مہر سے تم پر رجوع فرمائی اب قرآن میں سے جتنا تم پر آسان ہو اتنا پڑھو اسے معلوم ہے کہ عنقریب کچھ تم میں سے بیمار ہوں گے اور کچھ زمین میں سفر کریں گے اللہ کا فضل تلاش کرنے اور کچھ اللہ کی راہ میں لڑتے ہوں گے تو جتنا قرآن میسر ہو پڑھو اور نماز قائم رکھو اور زکوٰة دو اور اللہ کو اچھا قرض دو اور اپنے لیے جو بھلائی آگے بھیجو گے اسے اللہ کے پاس بہتر اور بڑے ثواب کی پاؤ گے، اور اللہ سے بخشش مانگو، بیشک اللہ بخشنے والا مہربان ہے،')
GO
