/****** Object:  StoredProcedure [dbo].[ChangeSchedule]    Script Date: 11/6/2023 10:31:00 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ChangeSchedule]
@StudentID varchar(50),
@Classes int,
@DaysName varchar(max),
@ClassTime varchar(30),
@TutorName varchar(50),
@Discription varchar(max)
AS
BEGIN
    UPDATE Schedule
	SET Classes=@Classes,DaysName=@DaysName,ClassTime=@ClassTime,TutorName=@TutorName,Description=@Discription
	where StudentID=@StudentID
	select StudentID FROM Schedule where StudentID=@StudentID
END
GO
