CREATE PROCEDURE [dbo].[GetScheduledStudents]
AS
BEGIN
	SELECT r.StudentID,r.Name,r.PhoneNumber,r.SkypeID,r.Gender,r.Country,s.Classes,s.DaysName,s.ClassTime,s.TutorName,S.Description from Registration r
	inner join Schedule s on s.StudentID=r.StudentID
	 where r.IsScheduled=1
	SELECT COUNT(*) as TotalRecords FROM Schedule
END

