/****** Object:  StoredProcedure [dbo].[GetTodaySchedule]    Script Date: 11/6/2023 10:31:00 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetTodaySchedule]
AS
BEGIN
	SELECT r.StudentID,r.Name,r.PhoneNumber,r.SkypeID,r.Gender,r.Country,s.Classes,s.DaysName,s.ClassTime,s.TutorName,S.Description from Registration r
	inner join Schedule s on s.StudentID=r.StudentID
	where s.DaysName like '%'+datename(dw,getdate())+'%' or s.DaysName='All'
	SELECT COUNT(*) as TotalRecords FROM Registration r
    inner join Schedule s on s.StudentID=r.StudentID
	where s.DaysName like '%'+datename(dw,getdate())+'%' or s.DaysName='All'
END

GO
