CREATE PROCEDURE [dbo].[SaveRegistration] 
@StudentName varchar(100),
@FatherName varchar(100),
@PhoneNumber varchar(50),
@Email varchar(30),
@SkypeID varchar(50),
@Gender varchar(10),
@DateOfBirth varchar(20),
@Country varchar(50),
@City varchar(50),
@Classes int,
@DaysName varchar(300),
@FeasibleTime varchar(50),
@FirstLanguage varchar(50)
AS
BEGIN
	INSERT INTO Registration (Name,FatherName,PhoneNumber,Email,SkypeID,Gender,DateOfBirth,Country,City,Classes,DaysName,FeasibleTime,FirstLanguage)
	OUTPUT INSERTED.StudentID,INSERTED.Name,INSERTED.Email,INSERTED.SkypeID
	VALUES (@StudentName,@FatherName,@PhoneNumber,@Email,@SkypeID,@Gender,@DateOfBirth,@Country,@City,@Classes,@DaysName,@FeasibleTime,@FirstLanguage)
END

