CREATE PROCEDURE [dbo].[SaveSchedule]
@StudentID varchar(50),
@Classes int,
@DaysName varchar(max),
@ClassTime varchar(30),
@TutorName varchar(50),
@Discription varchar(max)
AS
BEGIN
    UPDATE Registration
	SET IsScheduled=1
	where StudentID=@StudentID

	INSERT INTO Schedule(StudentID,Classes,DaysName,ClassTime,TutorName,Description)
	OUTPUT INSERTED.ScheduleID
	VALUES (@StudentID,@Classes,@DaysName,@ClassTime,@TutorName,@Discription)
END

