CREATE PROCEDURE [dbo].[SaveUpdatedRecord] 
@StudentID varchar(100),
@StudentName varchar(100),
@FatherName varchar(100),
@PhoneNumber varchar(50),
@Email varchar(30),
@SkypeID varchar(50),
@Gender varchar(10),
@DateOfBirth varchar(20),
@Country varchar(50),
@City varchar(50),
@Classes int,
@DaysName varchar(300),
@FeasibleTime varchar(50),
@FirstLanguage varchar(50)
AS
BEGIN
	UPDATE Registration 
	SET Name=@StudentName,FatherName=@FatherName,PhoneNumber=@PhoneNumber,Email=@Email,SkypeID=@SkypeID,Gender=@Gender,DateOfBirth=@DateOfBirth,
	Country=@Country,City=@City,Classes=@Classes,DaysName=@DaysName,FeasibleTime=@FeasibleTime,FirstLanguage=@FirstLanguage,UpdatedRecord=GETDATE()
	WHERE StudentID= @StudentID
END

