GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[StudentPreviewByID]
@StudentID varchar(18)
AS
BEGIN
	SELECT r.StudentID,r.Name,r.FatherName,r.PhoneNumber,r.Email,r.SkypeID,r.Gender,r.DateOfBirth,r.Country,r.City,r.Classes,r.DaysName,r.FeasibleTime,r.FirstLanguage,r.UpdatedRecord,r.RegistrationDate,r.IsScheduled,s.Classes as scheduledClasses,s.DaysName as scheduledDays,s.ClassTime as scheduledClassTime,s.TutorName,S.Description from Registration r
	LEFT join Schedule s on s.StudentID=r.StudentID
	where r.StudentID=@StudentID
END

