/****** Object:  StoredProcedure [dbo].[VerifyUser]    Script Date: 11/6/2023 10:31:00 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[VerifyUser]   
@Email varchar(50),    
@Pass varchar(50)    
AS    
BEGIN    
 SELECT top 1 U.ID,U.UNAME,U.EMAIL,B.LASTID FROM USERS U
 LEFT JOIN USERBOOKMARK B ON B.Email = U.Email
 WHERE U.Email = @Email AND Pass = @Pass
 ORDER BY B.ID DESC
END
